# === Shader-based atom point-sprite prototype (T3.19) ===
# A minimal GLSL 1.20 (compatible with the fixed-function pipeline) shader
# path for rendering atoms as round, smoothly antialiased point sprites at
# higher quality and lower CPU overhead than `glPointSmooth + glDrawArrays`.
# ON by default (step 5) — set SIM_USE_SHADER_POINTS=0 to force the legacy
# fixed-function GL_POINTS path.
# This prototype is intentionally narrow: it ONLY replaces the batched atom
# point draw at `glDrawArrays(GL_POINTS, ...)` (see §E in on_draw). The rest
# of the pipeline keeps using fixed-function paths so the simulation stays
# fully functional even if the GLSL compile fails.
class _PointSpriteShader:
    """One-time compile of a vertex+fragment shader that draws each input
    position as a disc-shaped point sprite. Falls back to no-op on compile
    failure — caller checks `.ok` before drawing and routes to the legacy
    GL_POINTS path otherwise. Lazy-init: only compiles on first .ensure()."""
    _VERTEX_SRC = """
        #version 120
        uniform float u_point_size;
        attribute vec3 a_pos;
        attribute vec4 a_col;
        attribute float a_size;
        varying vec4 v_col;
        void main() {
            gl_Position = gl_ModelViewProjectionMatrix * vec4(a_pos, 1.0);
            // Per-element visual radius (atomic_weight^(1/3), ~0.8-1.3) times
            // the shared zoom-scaled base size → atoms read as distinct sizes.
            gl_PointSize = u_point_size * a_size;
            v_col = a_col;
        }
    """
    _FRAGMENT_SRC = """
        #version 120
        varying vec4 v_col;
        void main() {
            // Radial-gradient point sprite, step-6 "atom" look: a white-hot
            // nucleus, a bright element-colored core, and a wide soft halo —
            // reads as a shaded glowing atom rather than a flat square dot.
            vec2 d = gl_PointCoord - vec2(0.5);
            float r2 = dot(d, d) * 4.0;          // 0 at center → 1 at sprite edge
            if (r2 > 1.0) discard;
            float core = smoothstep(1.0, 0.10, r2);   // solid inner disc
            float halo = smoothstep(1.0, 0.0,  r2);    // soft outer falloff
            float hot  = smoothstep(0.38, 0.0, r2);    // white-hot nucleus
            vec3 col = v_col.rgb * (0.70 + 0.90 * core + 0.30 * hot);
            col = mix(col, vec3(1.0), hot * 0.22);     // subtle white center
            float alpha = clamp(v_col.a * (core * 0.82 + halo * halo * 0.50 + hot * 0.12), 0.0, 1.0);
            gl_FragColor = vec4(col, alpha);
        }
    """

    def __init__(self):
        self.ok = False
        self.program = None
        self.attempted = False
        self._a_pos = -1
        self._a_col = -1
        self._a_size = -1
        self._u_point_size = -1

    def ensure(self):
        """Compile + link the shader. Idempotent. Returns True on success.
        Failure modes (driver lacks GLSL 1.20, GL context not current, etc.)
        leave `.ok=False` and the caller falls back to fixed-function GL_POINTS."""
        if self.attempted:
            return self.ok
        self.attempted = True
        try:
            from OpenGL.GL import (
                glCreateShader, glShaderSource, glCompileShader,
                glGetShaderiv, GL_COMPILE_STATUS, GL_VERTEX_SHADER, GL_FRAGMENT_SHADER,
                glCreateProgram, glAttachShader, glLinkProgram,
                glGetProgramiv, GL_LINK_STATUS,
                glGetAttribLocation, glGetUniformLocation,
            )
        except Exception:
            return False
        try:
            vs = glCreateShader(GL_VERTEX_SHADER)
            glShaderSource(vs, self._VERTEX_SRC)
            glCompileShader(vs)
            if not glGetShaderiv(vs, GL_COMPILE_STATUS):
                return False
            fs = glCreateShader(GL_FRAGMENT_SHADER)
            glShaderSource(fs, self._FRAGMENT_SRC)
            glCompileShader(fs)
            if not glGetShaderiv(fs, GL_COMPILE_STATUS):
                return False
            self.program = glCreateProgram()
            glAttachShader(self.program, vs)
            glAttachShader(self.program, fs)
            glLinkProgram(self.program)
            if not glGetProgramiv(self.program, GL_LINK_STATUS):
                return False
            self._a_pos = glGetAttribLocation(self.program, 'a_pos')
            self._a_col = glGetAttribLocation(self.program, 'a_col')
            self._a_size = glGetAttribLocation(self.program, 'a_size')
            self._u_point_size = glGetUniformLocation(self.program, 'u_point_size')
            self.ok = True
        except Exception:
            self.ok = False
        return self.ok


_point_sprite_shader = _PointSpriteShader()
# Shader point-sprites are ON by default (step 5): round glowing atoms read far
# better than flat GL_POINTS squares. Falls back to fixed-function GL_POINTS
# automatically if GLSL compile fails. SIM_USE_SHADER_POINTS=0 forces legacy.
_SHADER_POINTS_ENABLED = bool(int(os.environ.get('SIM_USE_SHADER_POINTS', '1') or '0'))


def _atomic_write_json(filepath, data, indent=2, ensure_ascii=False, default=None):
    """Atomic JSON write: writes to a sibling .tmp file, then os.replace() into
    place. Ensures readers never see a half-written file even if the process
    crashes mid-write or another process is reading concurrently. Falls back
    to direct write only if the tmp+rename pattern fails for some reason."""
    import json as _aj
    _tmp = filepath + '.tmp'
    try:
        with open(_tmp, 'w', encoding='utf-8') as _fh:
            if default is not None:
                _aj.dump(data, _fh, indent=indent, ensure_ascii=ensure_ascii, default=default)
            else:
                _aj.dump(data, _fh, indent=indent, ensure_ascii=ensure_ascii)
        os.replace(_tmp, filepath)
        return True
    except Exception as _ex:
        # Best-effort cleanup of stale tmp; fall back to a non-atomic write.
        try:
            if os.path.exists(_tmp):
                os.remove(_tmp)
        except Exception:
            pass
        try:
            with open(filepath, 'w', encoding='utf-8') as _fh:
                if default is not None:
                    _aj.dump(data, _fh, indent=indent, ensure_ascii=ensure_ascii, default=default)
                else:
                    _aj.dump(data, _fh, indent=indent, ensure_ascii=ensure_ascii)
            return True
        except Exception:
            return False

def _reexec_into_project_venv():
    """Last-resort portability path: when the system Python refuses pip
    installs entirely (PEP 668 externally-managed env, read-only
    site-packages, broken pip), create `.venv` beside this script and
    re-exec the same command line through the venv interpreter so every
    later auto-install lands in a writable environment.

    Returns True only if the process was replaced (os.execv never returns
    on success); False means 'give up' — callers should keep their normal
    error path. The sys.prefix guard prevents infinite re-exec loops."""
    try:
        if getattr(sys, 'base_prefix', sys.prefix) != sys.prefix:
            return False  # already inside a venv/conda env — don't recurse
        try:
            _script = os.path.abspath(__file__)
        except NameError:
            return False  # -c / interactive — __file__ undefined
        if not os.path.isfile(_script):
            return False
        _here = os.path.dirname(os.path.abspath(__file__))
        _vdir = os.path.join(_here, '.venv')
        _vpy = os.path.join(_vdir, 'bin', 'python')
        if not os.path.exists(_vpy):
            _vpy = os.path.join(_vdir, 'Scripts', 'python.exe')
        if not os.path.exists(_vpy):
            import venv as _venv_mod
            print("[AUTO-INSTALL] Creating project virtualenv (.venv) ...")
            _venv_mod.EnvBuilder(with_pip=True).create(_vdir)
        if not os.path.exists(_vpy):
            return False
        print(f"[AUTO-INSTALL] Re-launching via {_vpy}")
        os.execv(_vpy, [_vpy, _script] + list(sys.argv[1:]))
        return True  # unreachable on success
    except Exception as _vx:
        print(f"[AUTO-INSTALL] Virtualenv fallback failed: {_vx}")
        return False


# --- Auto-install core dependencies before importing them ---
for _pkg_import, _pkg_pip in [('numpy', 'numpy'), ('OpenGL', 'PyOpenGL'),
                               ('pyglet', 'pyglet'), ('networkx', 'networkx')]:
    try:
        __import__(_pkg_import)
    except ImportError:
        print(f"[AUTO-INSTALL] {_pkg_pip} not found. Installing...")
        if not _auto_install(_pkg_pip):
            if _reexec_into_project_venv():
                pass  # unreachable — process image replaced by venv python
            else:
                print(f"[ERROR] Failed to install {_pkg_pip}. "
                      f"Please install manually: pip install {_pkg_pip}")
                sys.exit(1)

