def _ensure(pkg, pip_names=None, required=True, timeout=180):
    """Try to import `pkg`; if missing, attempt a quiet pip install using each
    name in `pip_names` until one succeeds.

    Returns True when the package is importable, False otherwise.
    With required=True the original hard-exit behaviour is kept; with
    required=False the caller is expected to degrade gracefully.
    """
    try:
        __import__(pkg)
        return True
    except ImportError:
        pass
    names = pip_names if pip_names else [pkg]
    for name in names:
        try:
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install",
                 "--quiet", "--disable-pip-version-check",
                 "--no-input", name],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                timeout=timeout,
            )
            __import__(pkg)
            return True
        except Exception:
            continue
    msg = (f"\n[ERROR] Could not install '{pkg}'. Please run one of:\n"
           f"  pip install {names[0]}\n"
           f"  conda install -c conda-forge {pkg}\n")
    if required:
        print(msg, file=sys.stderr)
        sys.exit(1)
    print(msg + "  -> continuing without it (chemistry features disabled)\n",
          file=sys.stderr)
    return False


