# rdkit-pypi was abandoned after Python 3.10; the package is now just 'rdkit'.
# Chemistry degrades gracefully when RDKit cannot be installed (e.g. offline,
# restricted site-packages, or an unsupported interpreter) instead of exiting.
# The availability check uses find_spec (microseconds); the heavy rdkit.Chem
# import is deferred to the first chemistry call via _ensure_rdkit(), so
# CLI modes that never build molecules (--help, --no-gui, genome-only work)
# don't pay ~0.3-1.2 s of import time, and spawned eval workers defer it
# to their first organism.
def _rdkit_importable() -> bool:
    try:
        import importlib.util as _ilu
        return (_ilu.find_spec('rdkit') is not None
                and _ilu.find_spec('rdkit.Chem') is not None)
    except Exception:
        return False


RDKIT_AVAILABLE = _rdkit_importable()
if not RDKIT_AVAILABLE:
    # Monolith embed: route through Simulation.py's persistent-cache
    # auto-installer (.install_attempts.json) so a failed pip probe is
    # not re-attempted on every launch.
    RDKIT_AVAILABLE = bool(_auto_install('rdkit') and _rdkit_importable())

Chem = Descriptors = AllChem = rdMolDescriptors = RDLogger = None
RDKIT_VERSION = None
_RDKIT_LOADED = False

if not RDKIT_AVAILABLE and sys.version_info >= (3, 13):
    print("[WARNING] Python 3.13 + missing RDKit — conda is the reliable route:\n"
          "  conda install -c conda-forge rdkit", file=sys.stderr)


def _ensure_rdkit() -> bool:
    """Perform the real rdkit.Chem import on first chemistry use.
    Returns True when the chemistry backend is usable.  Idempotent."""
    global Chem, Descriptors, AllChem, rdMolDescriptors, RDLogger
    global RDKIT_AVAILABLE, RDKIT_VERSION, _RDKIT_LOADED
    if _RDKIT_LOADED:
        return RDKIT_AVAILABLE
    _RDKIT_LOADED = True
    if not RDKIT_AVAILABLE:
        return False
    try:
        import rdkit as _rdkit_pkg
        from rdkit import Chem as _Chem
        from rdkit.Chem import (Descriptors as _Desc, AllChem as _AC,
                                rdMolDescriptors as _RMD)
        from rdkit import RDLogger as _RL
        _RL.logger().setLevel(_RL.ERROR)
        Chem, Descriptors = _Chem, _Desc
        AllChem, rdMolDescriptors, RDLogger = _AC, _RMD, _RL
        RDKIT_VERSION = getattr(_rdkit_pkg, '_LANG_VERSION', '?')
        # rdkit.Chem lazily pulls submodule code (Lipinski, QED, MolSurf…)
        # on first attribute access.  If that first access happens inside
        # the threaded build_organism_mol warm-up, every worker serializes
        # on the import lock — resolve the descriptor functions we use
        # now, in the main thread, so the pool stage is pure compute.
        for _fn in ('MolWt', 'NumHAcceptors', 'NumHDonors'):
            getattr(Descriptors, _fn, None)
        getattr(rdMolDescriptors, 'CalcNumRings', None)
        getattr(AllChem, 'ETKDGv3', None)
        return True
    except Exception:  # partial/broken install — treat as unavailable
        RDKIT_AVAILABLE = False
        return False

