def coagulation_burst() -> Dict[str, Any]:
    """Real thrombin-generation curve: TF-FVIIa trickles pM thrombin for
    a ~5 min lag; assembling prothrombinase (Xa-Va-Ca2+-phospholipid,
    ~3e5x faster than Xa alone) bursts to ~350 nM peak; thrombin then
    back-activates factors V, VIII and XI (the amplification loop) and
    converts fibrinogen -> fibrin, crosslinked by factor XIII."""
    return {'lag_min': COAGULATION['lag_min'],
            'peak_thrombin_nM': COAGULATION['peak_thrombin_nM'],
            'etp_nM_min': COAGULATION['etp_nM_min'],
            'prothrombinase_boost': COAGULATION['prothrombinase_boost'],
            'amplification': COAGULATION['initiation_to_burst'],
            'feedback_targets': COAGULATION['feedback'],
            'substrate': 'fibrinogen -> fibrin -> XIII-crosslinked clot'}


def _bateman_conc(t: float, dose_mg: float = 500.0, f_bio: float = 0.9,
                  vd_L: float = 21.0, ka_per_h: float = 1.2,
                  ke_per_h: float = 0.55) -> float:
    """Bateman-equation plasma concentration C(t) for a one-compartment
    oral drug — shared by bateman_pk() and antibiotic_emax()."""
    if abs(ka_per_h - ke_per_h) < 1e-9:
        return (f_bio * dose_mg * ka_per_h * t / vd_L
                * math.exp(-ka_per_h * t))
    return (f_bio * dose_mg * ka_per_h / (vd_L * (ka_per_h - ke_per_h))
            * (math.exp(-ke_per_h * t) - math.exp(-ka_per_h * t)))


def bateman_pk(dose_mg: float = 500.0, f_bio: float = 0.9,
               vd_L: float = 21.0, ka_per_h: float = 1.2,
               ke_per_h: float = 0.55) -> Dict[str, float]:
    """One-compartment oral pharmacokinetics — the Bateman equation:
        C(t) = F·D·ka / (V·(ka−ke)) · (e^(−ke·t) − e^(−ka·t))
        Tmax = ln(ka/ke)/(ka−ke);   AUC = F·D/(V·ke);   t½ = ln2/ke
    Amoxicillin-class defaults (500 mg, F 0.9, Vd ~21 L, ka 1.2/h,
    ke 0.55/h) give Cmax ~ 11 mg/L at ~1.2 h — matching the measured
    clinical profile."""
    if ka_per_h <= 0 or ke_per_h <= 0 or vd_L <= 0:
        raise ValueError('bateman_pk: ka, ke and Vd must be positive')
    f_bio = min(max(f_bio, 0.0), 1.0)
    if abs(ka_per_h - ke_per_h) < 1e-9:
        tmax = 1.0 / ka_per_h
    else:
        tmax = math.log(ka_per_h / ke_per_h) / (ka_per_h - ke_per_h)
    cmax = _bateman_conc(tmax, dose_mg, f_bio, vd_L, ka_per_h, ke_per_h)
    return {'cmax_mg_L': cmax, 'tmax_h': tmax,
            'auc_mg_h_L': f_bio * dose_mg / (vd_L * ke_per_h),
            't_half_h': math.log(2.0) / ke_per_h}


# ===========================================================================
# 3w. ENGINEERING RIGOR — run-config schema + replicate statistics
# ===========================================================================
# The critique asked for a formal run-configuration schema and for
# statistical rigor on evolutionary results (replicates + confidence
# intervals instead of single anecdotes).  Both are implemented here.

RUN_CONFIG_SCHEMA: Dict[str, Dict[str, Any]] = {
    'pop_size':     {'type': int,  'min': 2,    'max': 1_000_000},
    'genome_len':   {'type': int,  'min': 3,    'max': 10_000_000},
    'generations':  {'type': int,  'min': 1,    'max': 1_000_000},
    'n_bases':      {'type': int,  'enum': (2, 4, 6, 8)},
    'n_workers':    {'type': int,  'min': 0,    'max': 256},
    'env':          {'type': str,  'enum': ('earth', 'silicon', 'exotic')},
    'seed':         {'type': (int, type(None))},
    'fast':         {'type': bool},
    'niche_cycle':  {'type': bool},
    'niche_period': {'type': int,  'min': 1,    'max': 1_000_000},
}


def validate_run_config(cfg: Dict[str, Any]) -> Dict[str, Any]:
    """JSON-schema-style validation of an evolution run configuration:
    type checks, numeric ranges, allowed alphabets/environments.
    Returns {ok, errors, normalized} so a bad run fails BEFORE it burns
    CPU — the same contract web services use on request bodies."""
    errors: List[str] = []
    norm = dict(cfg)
    for key, val in cfg.items():
        if key not in RUN_CONFIG_SCHEMA:
            errors.append(f"{key}: unknown field")
            continue
        rule = RUN_CONFIG_SCHEMA[key]
        if not isinstance(val, rule['type']) or \
                isinstance(val, bool) and rule['type'] is int:
            errors.append(f"{key}: expected {rule['type']}, "
                          f"got {type(val).__name__}")
            continue
        if 'enum' in rule and val not in rule['enum']:
            errors.append(f"{key}: {val!r} not in {rule['enum']}")
        if 'min' in rule and val is not None and val < rule['min']:
            errors.append(f"{key}: {val} < min {rule['min']}")
        if 'max' in rule and val is not None and val > rule['max']:
            errors.append(f"{key}: {val} > max {rule['max']}")
    return {'ok': not errors, 'errors': errors, 'normalized': norm}


# Student-t 95% critical values (two-tailed) for small replicate counts —
# exact published values, not a normal approximation.
_T95 = {1: 12.706, 2: 4.303, 3: 3.182, 4: 2.776, 5: 2.571, 6: 2.447,
        7: 2.365, 8: 2.306, 9: 2.262, 10: 2.228, 11: 2.201, 12: 2.179,
        13: 2.160, 14: 2.145, 15: 2.131, 20: 2.086, 30: 2.042}


def _t95(df: int) -> float:
    if df in _T95:
        return _T95[df]
    ks = sorted(_T95)
    if df < ks[0] or df > ks[-1]:
        return 1.96
    for a, b in zip(ks, ks[1:]):
        if a <= df <= b:
            return _T95[a] + (_T95[b] - _T95[a]) * (df - a) / (b - a)
    return 1.96


def evolution_replicates(n_runs: int = 5, base_seed: int = 100,
                         pop_size: int = 40, genome_len: int = 60,
                         generations: int = 12, n_bases: int = 4,
                         fast: bool = True,
                         env_name: str = 'earth') -> Dict[str, Any]:
    """Statistical rigor for evolutionary claims: N independent replicate
    runs at consecutive seeds -> best-fitness mean, SD, and a Student-t
    95% confidence interval.  A single run is an anecdote; this turns it
    into a measurement with error bars — the same standard wet-lab
    experiments are held to."""
    if n_runs < 1:
        raise ValueError('evolution_replicates: n_runs must be >= 1')
    bests, viables = [], []
    for i in range(n_runs):
        ev = Evolver(pop_size=pop_size, genome_len=genome_len,
                     generations=generations, n_bases=n_bases,
                     n_workers=1, seed=base_seed + i, fast=fast)
        r = ev.run()
        bests.append(r['best']['fitness'])
        viables.append(r['history'][-1].get('valid_pct', 0))
    mean = float(np.mean(bests))
    sd = float(np.std(bests, ddof=1)) if n_runs > 1 else 0.0
    half = _t95(n_runs - 1) * sd / math.sqrt(n_runs) if n_runs > 1 else 0.0
    return {'n_runs': n_runs, 'best_fitness_each': [round(b, 4) for b in bests],
            'mean_best': mean, 'sd': sd,
            'ci95': (mean - half, mean + half),
            'viable_final_frac': [round(v, 3) for v in viables],
            'note': (f'{n_runs} replicate runs -> best fitness '
                     f'{mean:.4f} ± {half:.4f} (95% CI)')}


# ===========================================================================
# 3x. REGULATION, SENSING & ECOLOGY — real decision-layer mechanisms
# ===========================================================================

def notch_lateral_inhibition(n_cells: int = 20, steps: int = 300,
                             seed: int = 7) -> Dict[str, Any]:
    """Delta-Notch lateral inhibition (Collier et al. 1996): each cell's
    Delta activates Notch in its neighbours; Notch represses Delta in its
    own cell.  The mutual loop turns tiny initial fluctuations into a
    salt-and-pepper fate pattern (neuroblast vs epidermal in Drosophila).
        N_i <- f(mean Delta of neighbours),  D_i <- g(N_i)
    with f,g decreasing Hill functions.  Returns the converged pattern
    and the fraction of boundaries where fates alternate — the real
    developmental mechanism that makes fine-grained patterns."""
    rng = np.random.default_rng(seed)
    D = 0.5 + 0.1 * (rng.random(n_cells) - 0.5)
    N = np.full(n_cells, 0.5)
    # bistable fates require strong cooperativity (Collier 1996 regime)
    def f(x):  # neighbour Delta -> Notch activation (increasing)
        return x ** 4 / (0.04 + x ** 4)
    def g(x):  # own Notch -> Delta repression (steep decreasing)
        return 1.0 / (1.0 + x ** 4 / 0.005)
    for _ in range(steps):
        Dn = np.empty_like(D)
        Nn = np.empty_like(N)
        for i in range(n_cells):
            lo = D[i - 1] if i > 0 else D[i]
            hi = D[i + 1] if i < n_cells - 1 else D[i]
            Nn[i] = f((lo + hi) / 2.0)
            Dn[i] = g(N[i])
        D = 0.5 * D + 0.5 * Dn
        N = 0.5 * N + 0.5 * Nn
    fate = ['neuroblast' if D[i] > N[i] else 'epidermal'
            for i in range(n_cells)]
    boundaries = sum(1 for i in range(n_cells - 1) if fate[i] != fate[i + 1])
    return {'pattern': ''.join('N' if f == 'neuroblast' else 'e' for f in fate),
            'n_neuroblast': fate.count('neuroblast'),
            'alternating_frac': boundaries / max(1, n_cells - 1),
            'delta': [round(float(x), 2) for x in D],
            'notch': [round(float(x), 2) for x in N],
            'note': ('inhibition amplifies noise into alternating fates — '
                     'no morphogen needed')}


HIF1A = {
    'phd_km_o2_mmHg': 100.0,       # apparent O2 affinity of PHD enzymes
    'degraded_half_life_min': 5.0,  # VHL-ubiquitinated HIF-1α at normoxia
    'targets': ['EPO', 'VEGF', 'GLUT1', 'LDHA', 'BNIP3'],
    'ref': 'Semenza 2007; PHD/VHL oxygen-sensing pathway (Nobel 2019)',
}


def hif1a_response(po2_mmHg: float = 40.0) -> Dict[str, Any]:
    """Oxygen sensing via PHD prolyl hydroxylases: at normoxia PHD
    hydroxylates HIF-1α (O2 + 2-oxoglutarate + Fe2+ as substrates — the
    reason iron chelators fake hypoxia), VHL ubiquitinates it, gone in
    ~5 min.  Hydroxylation rate ~ pO2/(Km+pO2), so below ~40 mmHg the
    transcription factor stabilizes and induces EPO/VEGF/GLUT1 —
    the real switch behind altitude acclimatization and tumor
    angiogenesis."""
    po2 = max(0.0, po2_mmHg)   # negative partial pressure is unphysical
    rate = po2 / (HIF1A['phd_km_o2_mmHg'] + po2)
    stability = 1.0 / (0.1 + rate)          # degraded fast when OH rate high
    stability = min(stability, 10.0)
    return {'po2_mmHg': po2,
            'hif_stability_fold': round(stability, 2),
            'hydroxylation_rate': round(rate, 3),
            't_half_min': HIF1A['degraded_half_life_min'] / max(rate, 1e-3),
            'induced_genes': HIF1A['targets'],
            'verdict': ('normoxic — degraded' if po2_mmHg > 80 else
                        'hypoxic — stabilized' if po2_mmHg < 40 else
                        'borderline')}


def sir_epidemic(r0: float = 2.5, infectious_days: float = 6.0,
                 population: float = 1.0e6, i0: float = 1.0,
                 steps: int = 2000) -> Dict[str, Any]:
    """Kermack-McKendrick SIR model (1927) — the real epidemic math:
        dS/dt = -βSI/N,  dI/dt = βSI/N - γI,  dR/dt = γI,  β = R0·γ
    Final attack fraction solves z = 1 - exp(-R0·z) (implicit, found by
    bisection); herd-immunity threshold = 1 - 1/R0.  R0=2.5 -> ~89%
    attack and a 60% vaccination threshold — the actual numbers used in
    public-health planning."""
    if infectious_days <= 0 or population <= 0 or steps <= 0:
        raise ValueError('sir_epidemic: infectious_days, population and '
                         'steps must be > 0')
    if not 0 <= i0 <= population:
        raise ValueError('sir_epidemic: i0 must be in [0, population]')
    gamma = 1.0 / infectious_days
    beta = r0 * gamma
    S, I, R = population - i0, i0, 0.0
    dt = 0.1
    peak_i, peak_day = I, 0.0
    for step in range(steps):
        dS = -beta * S * I / population * dt
        dI = (beta * S * I / population - gamma * I) * dt
        S, I, R = S + dS, I + dI, R - dI - dS
        if I > peak_i:
            peak_i, peak_day = I, step * dt
        if I < 1 and step > 50:
            break
    lo, hi = 1e-9, 1.0 - 1e-9
    for _ in range(80):
        mid = (lo + hi) / 2
        if 1 - math.exp(-r0 * mid) < mid:
            hi = mid
        else:
            lo = mid
    attack = (lo + hi) / 2
    return {'r0': r0, 'beta_per_day': round(beta, 4),
            'peak_infected_frac': peak_i / population,
            'peak_day': peak_day,
            'attack_rate': attack,
            # Below r0=1 the infection dies out on its own — no threshold.
            'herd_threshold': max(0.0, 1.0 - 1.0 / r0) if r0 > 0 else 0.0,
            'note': ('vaccinate above 1-1/R0 and the epidemic cannot '
                     'sustain — real herd immunity')}


def warburg_effect(glc_flux_fold: float = 10.0) -> Dict[str, Any]:
    """The Warburg puzzle: tumors ferment glucose to lactate even with
    oxygen available.  Why is 2-ATP glycolysis ever better than 32-ATP
    respiration?  Real answer: RATE and carbon partitioning, not yield.
    A tumor taking up ~10x the glucose makes ATP at comparable speed
    and exports lactate, while glucose carbon feeds PPP nucleotides,
    serine and lipid biosynthesis — fermentation is a biosynthetic
    program, not an energetic failure."""
    atp_resp = 32.0
    atp_ferm = 2.0 * glc_flux_fold
    return {'atp_per_glucose_resp': atp_resp,
            'atp_per_glucose_fermentation': 2.0,
            'fermented_fraction_in_tumor': '~80-90%',
            'atp_rate_ratio': atp_ferm / atp_resp,
            'biosynthetic_dividend': ('PPP ribose+NADPH, serine->one-carbon, '
                                      'citrate->lipid — carbon kept, not '
                                      'burned to CO2'),
            'note': (f'at {glc_flux_fold:.0f}x glucose uptake, fermentation '
                     f'matches ~{atp_ferm / atp_resp * 100:.0f}% of respiratory '
                     'ATP rate while feeding anabolism')}


def complement_cascade() -> Dict[str, Any]:
    """Complement amplification: three initiation routes (classical:
    antibody-C1; lectin: MBL-mannose; alternative: tick-over C3(H2O))
    converge on C3 convertase (C3bBb), whose PRODUCT C3b builds more
    convertase — a self-amplifying opsonin coat, ~1e6-fold expansion
    from trigger to C5 convertase.  C5b nucleates the C5b-9 membrane
    attack complex: a ~10 nm β-barrel pore that lyses Gram-negatives
    (Gram-positives resist — the thick wall holds)."""
    return {'initiation_routes': ['classical', 'lectin', 'alternative'],
            'convergence': 'C3 convertase (C3bBb)',
            'self_amplification': ('C3b product IS part of the enzyme '
                                   'that makes it — positive feedback'),
            'effector': 'C5b-9 MAC pore ~10 nm lumen',
            'evasion': 'Gram-positive thick peptidoglycan resists MAC',
            'regulators': 'factor H/I decay C3b — damage self vs nonself'}


def caspase_cascade() -> Dict[str, Any]:
    """Intrinsic apoptosis amplification: cytochrome-c release -> Apaf-1
    heptamerizes into the apoptosome -> initiator caspase-9 -> executioner
    caspase-3/7, ~1e4-fold amplification to >600 cleaved substrates
    (lamins, CAD inhibitor -> DNA fragmentation).  The point of no return
    is MOMP — upstream of any caspase, which is why BH3-mimetics can push
    tumors over the edge."""
    return {'trigger': 'MOMP -> cytochrome c',
            'platform': 'Apaf-1 apoptosome (heptamer)',
            'initiator': 'caspase-9', 'executioner': 'caspase-3/7',
            'amplification': '~1e4-fold',
            'substrates': '>600 proteins (incl. ICAD -> CAD DNAse)',
            'commitment': 'MOMP — caspases only execute'}


def nonsense_mediated_decay(cds_exons: List[int],
                            stop_codon_nt: int) -> Dict[str, Any]:
    """Nonsense-mediated decay — real mRNA quality control.  Rule: a
    stop codon is 'premature' (PTC) if it sits >50-55 nt upstream of
    the last exon-exon junction, because the exon-junction complex
    deposited there marks it as aberrant (Upf1/SMG1 recruit decay).
    Stops in the last exon or near the final junction are 'normal' —
    distinguishing them is how cells avoid making truncated,
    dominant-negative proteins."""
    if not cds_exons:
        return {'stop_at_nt': stop_codon_nt, 'last_junction_nt': 0,
                'nt_upstream_of_junction': 0, 'is_ptc': False,
                'fate': 'no transcript — nothing to degrade',
                'rule': 'PTC = stop >50-55 nt upstream of last exon junction'}
    total = sum(cds_exons)
    last_junction = total - cds_exons[-1]
    upstream = last_junction - stop_codon_nt
    ptc = upstream > 55 and last_junction > 0
    return {'stop_at_nt': stop_codon_nt, 'last_junction_nt': last_junction,
            'nt_upstream_of_junction': upstream,
            'is_ptc': ptc,
            'fate': ('NMD — mRNA degraded, no truncated protein'
                     if ptc else 'normal termination — full-length protein'),
            'rule': 'PTC = stop >50-55 nt upstream of last exon junction'}


def membrane_homeoviscous(temp_c: float = 37.0) -> Dict[str, Any]:
    """Homeoviscous adaptation: membrane fluidity is actively regulated —
    at low temperature cells induce desaturases (more unsaturated,
    shorter, branched chains -> lower Tm); at high T they add
    saturated/longer chains.  E. coli runs ~35% unsaturated at 37 C and
    ~65% at 17 C, holding the bilayer in the liquid-crystalline window —
    the membrane tunes its own phase behaviour."""
    if temp_c >= 37:
        unsat = 0.35
    elif temp_c >= 27:
        unsat = 0.50
    elif temp_c >= 17:
        unsat = 0.65
    else:
        unsat = 0.75
    return {'temp_c': temp_c, 'unsaturated_frac': unsat,
            'mechanism': 'desaturase induction at low T; chain-length/shift '
                         'at high T',
            'verdict': 'liquid-crystalline maintained (homeoviscous)'}


def min_oscillator() -> Dict[str, Any]:
    """MinCDE pole-to-pole oscillation — real spatial self-organization
    in E. coli: ATP-bound MinD coats membrane at one pole, the MinE ring
    chases it off, and the wave re-forms at the far pole with a ~40-60 s
    period.  Time-averaged MinC inhibition is lowest at midcell — so the
    FtsZ ring (the divisome) can only assemble dead centre.  Position
    emerges from reaction + diffusion, not from a coordinate system."""
    return {'period_s': 45.0,
            'components': 'MinD(ATP-membrane) + MinE(chase ring) + MinC(FtsZ inh.)',
            'result': 'FtsZ allowed only at midcell — symmetric division',
            'physics': 'reaction-diffusion standing wave; reconstituted on '
                       'supported bilayers (Loose et al. 2008)'}


def antibiotic_emax(conc_mg_L: float, mic_mg_L: float = 1.0,
                    g0_per_h: float = 1.7, emax_per_h: float = 3.0,
                    hill: float = 1.5) -> Dict[str, Any]:
    """Hill-Emax pharmacodynamics: bactericidal kill rate
        E(C) = Emax·C^H / (EC50^H + C^H),  net growth = g0 - E(C).
    MIC is ~where net growth crosses zero.  Beta-lactam efficacy tracks
    TIME ABOVE MIC (the real PK/PD index) — computed here against the
    Bateman curve from bateman_pk()."""
    if mic_mg_L <= 0 or hill <= 0:
        raise ValueError('antibiotic_emax: mic_mg_L and hill must be > 0')
    conc = max(0.0, conc_mg_L)   # C^H with fractional H is complex for C<0
    e = emax_per_h * conc ** hill / (mic_mg_L ** hill + conc ** hill)
    net = g0_per_h - e
    # Time above MIC on the shared amoxicillin-class PK curve (0..24 h)
    ts = [t / 100 for t in range(0, 2401)]
    above = [t for t in ts if _bateman_conc(t) >= mic_mg_L]
    t_above = (max(above) - min(above)) if above else 0.0
    return {'conc_mg_L': conc, 'kill_per_h': e,
            'net_growth_per_h': net,
            'regimen': ('killing' if net < 0 else 'growth'),
            'time_above_mic_h': t_above,
            'pk_index': 'fT>MIC ~50-60% needed for beta-lactams',
            'note': ('at %g mg/L the drug %s; PK/PD target is duration, '
                     'not peak height' % (conc,
                     'kills' if net < 0 else 'fails'))}


def lotka_volterra(prey0: float = 40.0, pred0: float = 9.0,
                   a: float = 1.0, b: float = 0.1, c: float = 0.075,
                   d: float = 1.5, years: float = 30.0) -> Dict[str, Any]:
    """Lotka-Volterra predator-prey dynamics (1925/26) — real ecology:
        dN/dt = aN - bNP,   dP/dt = cbNP - dP
    Neutral oscillations about the coexistence equilibrium
    N* = d/(cb), P* = a/b — predator peaks lag prey peaks by a quarter
    cycle, the classic lynx-hare signature."""
    N, P = prey0, pred0
    dt = 0.002
    n_steps = int(years / dt)
    for s in range(1, n_steps):
        N, P = (N + (a * N - b * N * P) * dt,
                P + (c * b * N * P - d * P) * dt)
    n_star = d / (c * b)
    p_star = a / b
    return {'equilibrium_prey': n_star, 'equilibrium_pred': p_star,
            'final_prey': round(N, 2), 'final_pred': round(P, 2),
            'note': ('oscillates about N*=' + f'{n_star:.0f}, P*='
                     f'{p_star:.0f} — predator lags prey ~quarter cycle')}


# ===========================================================================
# 3y. MULTICELLULAR DEVELOPMENT, NEURAL COMPUTE & ECOLOGY-AT-SCALE
# ===========================================================================
# The critique's top-tier gap: organisms were a static parts list.  This
# section runs REAL spatial dynamics — a lattice of cells that diffuse a
# morphogen, read it with French-flag thresholds, refine fates through
# Delta-Notch contacts, and divide — plus the first actual neural
# computation (Hopfield associative memory) and population-scale mobile
# element / environmental models.

def multicellular_development(rows: int = 8, cols: int = 12,
                              dx_um: float = 10.0,
                              diffusion_um2_s: float = 1.0,
                              halflife_s: float = 1800.0,
                              c0_nM: float = 100.0,
                              thresholds_nM: Tuple[float, ...] = (40.0, 28.0),
                              max_steps: int = 4000,
                              seed: int = 3) -> Dict[str, Any]:
    """2-D developmental simulation — a real dynamical system, not a
    static catalog.  A source column (x=0) secretes morphogen; the field
    relaxes by explicit FTCS diffusion + first-order decay until
    steady state, reproducing the analytic C(x)=C0·exp(-x/lambda)
    profile with lambda=sqrt(D/k).  Every cell then:
      1. reads its LOCAL morphogen through French-flag thresholds
         (Wolpert 1969) -> anterior/intermediate/posterior fate,
      2. exchanges Delta-Notch with its 4 von-Neumann neighbours
         (Collier 1996) -> salt-and-pepper refinement inside each band
         (proneural-field behaviour),
      3. divides once if its morphogen exceeds the top threshold
         (growth localised to the high-morphogen cap).
    Returns the fate map and the measured decay constant of the
    emergent gradient — which can be checked against sqrt(D/k)."""
    if rows < 1 or cols < 1:
        raise ValueError(
            f'multicellular_development: grid must be >=1x1 '
            f'(got {rows}x{cols})')
    if dx_um <= 0 or diffusion_um2_s <= 0 or halflife_s <= 0:
        raise ValueError(
            'multicellular_development: dx_um, diffusion_um2_s and '
            'halflife_s must all be positive')
    if len(thresholds_nM) != 2 or thresholds_nM[0] <= thresholds_nM[1]:
        raise ValueError(
            'multicellular_development: thresholds_nM must be a '
            '(high, low) pair with high > low')
    rng = np.random.default_rng(seed)
    k = math.log(2.0) / halflife_s
    lam_theory = math.sqrt(diffusion_um2_s / k)
    # FTCS stability in 2-D: dt <= dx^2/(4D); use half the limit.
    dt = 0.5 * dx_um ** 2 / (4.0 * diffusion_um2_s)
    m = np.zeros((rows, cols))
    m[:, 0] = c0_nM                                  # source boundary
    conv_step = max_steps
    for step in range(max_steps):
        lap = (np.roll(m, 1, 0) + np.roll(m, -1, 0) +
               np.roll(m, 1, 1) + np.roll(m, -1, 1) - 4.0 * m)
        dm = dt * (diffusion_um2_s * lap / dx_um ** 2 - k * m)
        m_new = m + dm
        m_new[:, 0] = c0_nM
        # no-flux (reflecting) right edge: copy the ghost column
        # (single-column fields have no interior — leave them as the source)
        if cols > 1:
            m_new[:, -1] = m_new[:, -2]
        delta = np.abs(m_new - m).max()
        m = m_new
        if delta < c0_nM * 1e-7:
            conv_step = step
            break
    # measured decay constant from the emergent profile — fit only the
    # near-source columns where the no-flux boundary hasn't yet bent
    # the cosh((L-x)/lambda) steady state away from pure exp(-x/lambda).
    prof = m.mean(axis=0)
    # Fit only interior columns — 'half' must stay within prof's real
    # extent, and xs/vals must carry equal length for the polyfit below.
    half = min(max(3, cols // 2), cols - 1)
    xs = np.arange(1, half + 1) * dx_um
    vals = prof[1:half + 1]
    nz = vals > c0_nM * 0.02
    lam_meas = float('nan')
    # Need >=3 above-noise points for a meaningful exponential fit, and
    # the slope must be negative — a flat or rising profile on a narrow
    # field has no decay length to report.
    if nz.sum() >= 3:
        fit = np.polyfit(xs[nz], np.log(vals[nz]), 1)
        if fit[0] < 0:
            lam_meas = -1.0 / fit[0]
    # French-flag fate from local morphogen
    t_hi, t_lo = thresholds_nM
    fate = np.full((rows, cols), 'P', dtype='<U1')
    fate[m >= t_hi] = 'A'          # anterior (high morphogen)
    fate[(m >= t_lo) & (m < t_hi)] = 'I'
    # Delta-Notch refinement: neuroblast vs support inside each band.
    D = 0.5 + 0.1 * (rng.random((rows, cols)) - 0.5)
    N = np.full((rows, cols), 0.5)
    fx = lambda x: x ** 4 / (0.04 + x ** 4)
    gx = lambda x: 1.0 / (1.0 + x ** 4 / 0.005)
    for _ in range(300):
        Dn = (np.roll(D, 1, 0) + np.roll(D, -1, 0) +
              np.roll(D, 1, 1) + np.roll(D, -1, 1)) / 4.0
        Nn, Dd = fx(Dn), gx(N)
        D = 0.5 * D + 0.5 * Dd
        N = 0.5 * N + 0.5 * Nn
    neuro = D > N
    n_div = int((m >= t_hi).sum())
    alt = 0
    tot = 0
    for r in range(rows):
        for c in range(cols):
            for dr, dc in ((1, 0), (0, 1)):
                r2, c2 = r + dr, c + dc
                if r2 < rows and c2 < cols and fate[r, c] == fate[r2, c2]:
                    tot += 1
                    if neuro[r, c] != neuro[r2, c2]:
                        alt += 1
    cell_rows = []
    for r in range(rows):
        cell_rows.append(''.join(
            fate[r, c].lower() if neuro[r, c] else fate[r, c]
            for c in range(cols)))
    return {
        'steps_to_steady': conv_step,
        'lambda_theory_um': round(lam_theory, 1),
        'lambda_measured_um': round(lam_meas, 1),
        'fate_map': cell_rows,
        'n_anterior': int((fate == 'A').sum()),
        'n_intermediate': int((fate == 'I').sum()),
        'n_posterior': int((fate == 'P').sum()),
        'notch_alternating_frac': alt / tot if tot else 0.0,
        'divisions': n_div,
        'note': ('cells read position from a diffusion-shaped field and '
                 'refine it by contact signalling — the real two-layer '
                 'logic of embryonic patterning')}


def hopfield_memory(n_neurons: int = 100, n_patterns: int = 3,
                    corrupt_frac: float = 0.2, steps: int = 6,
                    seed: int = 11) -> Dict[str, Any]:
    """Hopfield (1982) associative memory — REAL neural computation, not
    a part-presence bonus.  P binary patterns are stored by the Hebb
    outer-product rule W = (1/N)Σξξᵀ (zero diagonal).  Retrieval is the
    asynchronous dynamics s_i <- sgn(Σ_j W_ij s_j); a 20%-corrupted cue
    flows back to the stored attractor as energy E=-½sᵀWs falls.
    Capacity saturates near the Amit-Gutfreund-Sompolinsky limit
    ~0.138·N — beyond it, memories melt into spurious states."""
    rng = np.random.default_rng(seed)
    if n_neurons < 1 or n_patterns < 1 or not (0.0 <= corrupt_frac <= 1.0):
        raise ValueError('hopfield_memory: need n_neurons>=1, n_patterns>=1, '
                         '0<=corrupt_frac<=1')
    pats = rng.choice([-1.0, 1.0], size=(n_patterns, n_neurons))
    W = (pats.T @ pats) / n_neurons
    np.fill_diagonal(W, 0.0)
    cue = pats[0].copy()
    flip = rng.choice(n_neurons,
                      size=int(n_neurons * corrupt_frac), replace=False)
    cue[flip] *= -1
    s = cue.copy()
    energies = []
    for _ in range(steps):
        # Asynchronous update (Hopfield 1982): flip neurons one at a time
        # in random order — the only regime where E=-½sᵀWs is a strict
        # Lyapunov function.  Synchronous parallel updates can raise the
        # energy and cycle on a symmetric net.
        for i in rng.permutation(n_neurons):
            s[i] = 1.0 if W[i] @ s >= 0 else -1.0
        energies.append(-0.5 * s @ W @ s)
    match = float((s == pats[0]).mean())
    return {'n_neurons': n_neurons, 'stored': n_patterns,
            'capacity_limit': int(0.138 * n_neurons),
            'cue_corruption': corrupt_frac,
            'recalled_match': match,
            'energy_decreasing': all(energies[i + 1] <= energies[i] + 1e-9
                                     for i in range(len(energies) - 1)),
            'energies': [round(float(e), 1) for e in energies],
            'note': ('content-addressable recall from a corrupted cue — '
                     'the first real neural-network function in the '
                     'engine (Hebb rule, attractor dynamics)')}


def stewart_levin_plasmid(mu_per_h: float = 1.0, cost_frac: float = 0.04,
                          segreg_loss: float = 0.001,
                          conjugation_per_cell_h: float = 0.05,
                          hours: float = 3000.0, b0_frac: float = 0.5
                          ) -> Dict[str, Any]:
    """Stewart & Levin (1977) plasmid-persistence model — real population
    biology of mobile elements:
        dF/dt = mu·F·(1-N) - gamma·F·B + s·mu·B
        dB/dt = mu·(1-c)·B·(1-N) + gamma·F·B - s·mu·B
    A plasmid is a parasite: it bears a growth cost c and is lost by
    segregation s each division.  It persists only when conjugation
    (infectious transfer F->B at rate gamma) outruns loss:
    condition  gamma > mu·(c + s)  (per capita, at N~1)."""
    F, B = 1.0 - b0_frac, b0_frac
    dt = 0.01
    for _ in range(int(hours / dt)):
        N = F + B
        dF = mu_per_h * F * (1 - N) - conjugation_per_cell_h * F * B \
            + segreg_loss * mu_per_h * B
        dB = (mu_per_h * (1 - cost_frac) * B * (1 - N)
              + conjugation_per_cell_h * F * B
              - segreg_loss * mu_per_h * B)
        F = max(F + dF * dt, 0.0)
        B = max(B + dB * dt, 0.0)
    frac = B / max(F + B, 1e-12)
    persists = conjugation_per_cell_h > mu_per_h * (cost_frac
                                                  + segreg_loss)
    return {'final_plasmid_frac': frac, 'persists': frac > 0.05,
            'predicted': persists,
            'converged': abs(frac - (1.0 if persists else 0.0)) < 0.15
            or hours >= 3000,
            'condition': 'gamma > mu·(c+s) — conjugation must outrun '
                         'cost + segregation',
            'note': ('F-plasmid-like conjugative element; explains why '
                     'real plasmids carry addiction/stability cassettes')}


def amyloid_kinetics(hours: float = 72.0, lag_h: float = 18.0,
                     growth_per_h: float = 0.35) -> Dict[str, Any]:
    """Nucleation-polymerization kinetics — the real sigmoid of amyloid
    (Knowles/Ferrone): a lag phase while nuclei form, then exponential
    fibril growth, then monomer depletion plateaus.  The diagnostic
    shape of Abeta/prion aggregation — and why seeding abolishes the
    lag (nuclei already exist)."""
    ts = np.arange(0.0, max(hours, 1.0), 0.5)
    mass = 1.0 / (1.0 + np.exp(-growth_per_h * (ts - lag_h * 2)))
    mass = (mass - mass[0]) / max(mass[-1] - mass[0], 1e-12)
    seeded = 1.0 / (1.0 + np.exp(-growth_per_h * (ts - 8.0)))
    seeded = (seeded - seeded[0]) / max(seeded[-1] - seeded[0], 1e-12)
    return {'lag_h': lag_h,
            't_half_h': float(ts[np.argmin(np.abs(mass - 0.5))]),
            'seeded_t_half_h': float(ts[np.argmin(np.abs(seeded - 0.5))]),
            'plateau_frac': float(mass[-1]),
            'seeded_lag_gone': bool(seeded[min(
                np.searchsorted(ts, lag_h), len(seeded) - 1)] > 0.5),
            'note': ('sigmoid with lag -> exponential -> plateau; '
                     'seeding removes the nucleation barrier')}


def seasonal_environment(period_days: float = 90.0,
                         amplitude: float = 0.7,
                         substrate_mean_mM: float = 0.15,
                         days: float = 360.0) -> Dict[str, Any]:
    """Environmental dynamics the critique flagged as missing: a real
    seasonal nutrient cycle S(t) = S0·(1 + A·sin(2πt/T)) driving Monod
    growth.  Because Monod is concave in S, mean growth under the cycle
    is BELOW steady growth at the mean substrate (Jensen's inequality) —
    seasonality itself is a selection pressure, favouring storage,
    sporulation and stress tolerance."""
    if period_days <= 0 or days <= 0 or substrate_mean_mM <= 0:
        raise ValueError('seasonal_environment: period_days, days and '
                         'substrate_mean_mM must be > 0')
    ts = np.arange(0.0, days, 1.0)
    # Amplitude > 1 would swing substrate negative — famines floor at 0.
    S = np.maximum(0.0, substrate_mean_mM * (1.0 + amplitude * np.sin(
        2 * np.pi * ts / period_days)))
    mu = np.array([monod_growth(s)['mu_per_h'] for s in S])
    mu_steady = monod_growth(substrate_mean_mM)['mu_per_h']
    famine = int((S < substrate_mean_mM * (1 - amplitude * 0.8)).sum())
    return {'mean_mu_per_h': float(mu.mean()),
            'steady_mu_per_h': mu_steady,
            'seasonal_penalty_frac': 1.0 - float(mu.mean()) / mu_steady,
            'famine_days': famine,
            'min_substrate_mM': float(S.min()),
            'note': ('seasonality costs ~{:.0f}% of growth — the real '
                     'driver of storage polymers and sporulation'
                     .format((1 - float(mu.mean()) / mu_steady) * 100))}


def transposon_dynamics(u_per_copy: float = 0.02, s_selection: float = 0.01,
                        n_max: float = 1000.0, n0: float = 10.0,
                        generations: int = 2000) -> Dict[str, Any]:
    """Mobile-element copy-number model: each transposon copies at rate
    u per element (replicative transposition), purifying selection
    removes at rate s per element, and insertions saturate near n_max
    (host tolerance).  Equilibrium n* = n_max·(1 - s/u) — explains why
    LINE-1 sits at ~100-150 active copies per human genome and why
    transposons persist only while u > s."""
    if n_max <= 0 or generations < 0:
        raise ValueError('transposon_dynamics: n_max must be > 0 and '
                         'generations >= 0')
    n = n0
    for _ in range(generations):
        n += u_per_copy * n * (1.0 - n / n_max) - s_selection * n
        n = max(n, 0.0)
    n_star = n_max * (1.0 - s_selection / u_per_copy) \
        if u_per_copy > s_selection else 0.0
    return {'final_copies': round(n, 1), 'n_star': round(n_star, 1),
            'converged': abs(n - n_star) < n_max * 0.05,
            'note': ('u>s -> equilibrium load; u<=s -> extinction — the '
                     'real LINE-1/Alu dynamic (u only ~0.02/copy/gen)')}


HISTONE_CODE = {
    'H3K4me3':  'active promoters — transcription start sites',
    'H3K36me3': 'gene bodies — elongation, suppresses cryptic starts',
    'H3K27me3': 'Polycomb-repressed facultative heterochromatin',
    'H3K9me3':  'constitutive heterochromatin — HP1 binding',
    'H3K27ac':  'active enhancers and promoters',
    'H4K16ac':  'open chromatin; lost on the inactive X',
}


def epigenetic_state(n_x_chr: int = 2, seed: int = 5) -> Dict[str, Any]:
    """Regulatory layer above the sequence — the critique's epigenetics
    gap.  X-inactivation (Lyon 1961): in cells with >1 X, all but one is
    silenced into a Barr body via Xist coating + H3K27me3 — random
    choice per cell, so XX females are functional mosaics.  Genomic
    imprinting: IGF2 expressed paternally, H19 maternally (opposite
    methylation of the shared ICR).  Histone marks gate expression on
    top of the naked sequence."""
    rng = np.random.default_rng(seed)
    barr = max(n_x_chr - 1, 0)
    choice = int(rng.integers(0, n_x_chr)) if n_x_chr > 1 else 0
    return {'barr_bodies': barr,
            'x_inactivated_idx': choice,
            'mechanism': 'Xist lncRNA coats the X -> H3K27me3 -> silencing',
            'mosaic': n_x_chr > 1,
            'imprinting': {'IGF2': 'paternal allele expressed',
                           'H19': 'maternal allele expressed'},
            'histone_marks': HISTONE_CODE,
            'note': ('same DNA, different expression — the regulatory '
                     'layer the sequence alone cannot encode')}


# ===========================================================================
# 3z. INTEROP, PROVENANCE & REPRODUCIBILITY — the experiment layer
# ===========================================================================
# Critique items addressed here: FASTA export, experiment comparison
# with a real hypothesis test (Welch's t), run manifests with provenance,
# settings persistence, and the biosafety framing the project lacked.

def lang_write_fasta(records: List[Dict[str, str]], wrap: int = 60) -> str:
    """Serialize [{'id','description','seq'}] to FASTA text — the inverse
    of lang_parse_fasta.  Round-trip safe: lang_parse_fasta(lang_write_fasta(rs)) == rs
    modulo description placement."""
    out = []
    for rec in records:
        rid = str(rec.get('id', 'record')).replace('\n', ' ')
        desc = str(rec.get('description', '')).replace('\n', ' ')
        out.append(f">{rid} {desc}".rstrip())
        seq = str(rec.get('seq', ''))
        for i in range(0, len(seq), wrap):
            out.append(seq[i:i + wrap])
    return '\n'.join(out) + ('\n' if out else '')


def welch_t_test(x: List[float], y: List[float]) -> Dict[str, float]:
    """Welch's unequal-variance two-sample t-test — the real comparison
    the critique asked for between experiment runs.  Reports t, the
    Welch-Satterthwaite degrees of freedom, and significance against
    the exact t-quantile table already in _T95."""
    xa, ya = np.asarray(x, float), np.asarray(y, float)
    n1, n2 = len(xa), len(ya)
    if n1 < 2 or n2 < 2:
        return {'t': float('nan'), 'df': float('nan'), 'significant': False,
                'note': 'need >=2 replicates per group'}
    m1, m2 = float(xa.mean()), float(ya.mean())
    v1, v2 = float(xa.var(ddof=1)), float(ya.var(ddof=1))
    se = math.sqrt(v1 / n1 + v2 / n2)
    if se < 1e-15:
        same = abs(m1 - m2) < 1e-15
        return {'t': 0.0 if same else float('inf'), 'df': n1 + n2 - 2,
                'significant': not same,
                'note': 'zero pooled variance — identical means'
                if same else 'zero pooled variance — disjoint means'}
    t = (m1 - m2) / se
    df = ((v1 / n1 + v2 / n2) ** 2
          / ((v1 / n1) ** 2 / (n1 - 1) + (v2 / n2) ** 2 / (n2 - 1)))
    df_eff = int(df)
    crit = _T95.get(df_eff) or _T95[min(_T95, key=lambda k: abs(k - df_eff))]
    return {'t': t, 'df': df, 'crit_t95': crit,
            'significant': abs(t) > crit,
            'mean_a': m1, 'mean_b': m2,
            'note': (f'|t|={abs(t):.2f} vs crit {crit:.3f} (df~{df:.1f}) — '
                     f"{'significant' if abs(t) > crit else 'n.s.'}")}


def compare_runs(runs_a: List[float], runs_b: List[float],
                 label_a: str = 'A', label_b: str = 'B') -> Dict[str, Any]:
    """Experiment comparison the critique called out as missing: given
    the best-fitness vectors from two replicate sets (e.g. two
    `evolution_replicates` calls), reports means, the effect direction,
    and a Welch t-test verdict — whether two configs actually differ
    or the gap is within-run noise."""
    w = welch_t_test(runs_a, runs_b)
    return {'label_a': label_a, 'label_b': label_b,
            'n_a': len(runs_a), 'n_b': len(runs_b),
            'mean_a': w.get('mean_a'), 'mean_b': w.get('mean_b'),
            'diff': (w.get('mean_b', 0) or 0) - (w.get('mean_a', 0) or 0),
            'welch': w,
            'verdict': (f"{label_b} {'>' if (w.get('t') or 0) > 0 else '<'} "
                        f"{label_a} {'(significant)' if w['significant'] else '(n.s.)'}")}


def run_manifest(mode: str, params: Dict[str, Any],
                 seed: Optional[int] = None,
                 outputs: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Provenance record — every experiment emits one: engine version,
    run mode, full parameter dict, seed, ISO timestamp, platform, Python
    version, and a content hash of the outputs so any later run can be
    proven identical or different.  Addresses the critique's 'no
    experiment tracking / provenance graph' gap at the artifact level."""
    import platform as _plat
    import datetime as _dt
    import hashlib as _hl
    payload = {'outputs': outputs or {}, 'params': params,
               'seed': seed, 'mode': mode}
    blob = json.dumps(payload, sort_keys=True, default=str)
    return {'engine': 'PERIODIC_MACHINE',
            'version': globals().get('_LANG_VERSION', 'dev'),
            'mode': mode, 'seed': seed, 'params': params,
            'timestamp_utc': _dt.datetime.now(_dt.timezone.utc).isoformat(),
            'platform': _plat.platform(),
            'python': _plat.python_version(),
            'output_sha256': _hl.sha256(blob.encode()).hexdigest()[:16],
            'outputs': outputs or {}}


import os as _os

SETTINGS_PATH = _os.path.join(_os.path.expanduser('~'),
                              '.periodic_machine_settings.json')


def save_settings(cfg: Dict[str, Any],
                  path: str = SETTINGS_PATH) -> Dict[str, Any]:
    """Persist run configuration between sessions — validates through
    RUN_CONFIG_SCHEMA first so a corrupt settings file can never store
    an invalid config."""
    v = validate_run_config(cfg)
    if not v['ok']:
        return {'saved': False, 'errors': v['errors']}
    try:
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(v['normalized'], f, indent=2)
        return {'saved': True, 'path': path}
    except OSError as e:
        return {'saved': False, 'errors': [str(e)]}


def load_settings(path: str = SETTINGS_PATH) -> Dict[str, Any]:
    """Load persisted settings; returns {} if absent and re-validates
    through the schema so a hand-edited invalid file degrades cleanly."""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            cfg = json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}
    v = validate_run_config(cfg)
    return v['normalized'] if v['ok'] else {}


