# Total protein mass calculation
# Real cell dry-mass composition (Neidhardt, E. coli physiology —
# mammalian cytosol is similar): protein ~55%, RNA ~20%, DNA ~3%,
# lipid ~9%, carbohydrate ~5%, metabolites/other ~8% of dry mass.
CELL_COMPOSITION = {
    'protein':      0.55,
    'rna':          0.20,
    'dna':          0.03,
    'lipid':        0.09,
    'carbohydrate': 0.05,
    'other':        0.08,
    'dry_fraction_of_wet': 0.30,   # cells are ~70% water
}

# Body-protein scaling (Bianconi 2013 cell census; ICRP Reference Man):
#   erythrocytes ~25e12 of ~37e12 cells but tiny (~30 pg protein each,
#   ~90% haemoglobin); nucleated cells average ~90 pg protein; roughly
#   45% of total body protein is extracellular matrix (collagen etc.)
#   so intracellular protein is ~55% of the total.
BODY_PROTEIN_SCALING = {
    'erythrocytes':        25e12,
    'rbc_protein_pg':      30.0,
    # Mass-weighted mean for nucleated cells: arithmetic means are
    # dominated by tiny lymphocytes, but body MASS is dominated by
    # large cells — hepatocytes ~1-2 ng protein, adipocytes ~0.5-1 ng,
    # syncytial myocytes much more.  ~280 pg is the defensible
    # mass-weighted figure, not the per-cell-type median.
    'nucleated_protein_pg': 280.0,
    'intracellular_share': 0.55,   # rest is ECM/plasma protein
    'icrp_total_protein_kg': 11.0, # ICRP 70 kg reference man
}


def cell_composition(dry_mass_pg: float) -> Dict[str, float]:
    """Break a cell's dry mass (pg) into real macromolecular fractions."""
    return {k: dry_mass_pg * v for k, v in CELL_COMPOSITION.items()
            if k != 'dry_fraction_of_wet'}


def calculate_body_protein_mass(n_cells: float) -> Dict[str, float]:
    """Real body-protein estimate from cell census + composition —
    NOT the catalog sum (which only covers ~29 modeled protein types).
    Split erythrocytes (tiny, haemoglobin-rich) from nucleated cells,
    then scale intracellular protein to total incl. extracellular
    matrix (collagen ~1/3 of all body protein)."""
    s = BODY_PROTEIN_SCALING
    rbc = min(s['erythrocytes'], n_cells)
    nuc = max(0.0, n_cells - rbc)
    intra_g = (rbc * s['rbc_protein_pg'] + nuc * s['nucleated_protein_pg']) / 1e12
    intra_kg = intra_g / 1000.0
    total_kg = intra_kg / s['intracellular_share']
    return {
        'intracellular_protein_kg': intra_kg,
        'extracellular_protein_kg': total_kg - intra_kg,
        'total_protein_kg':         total_kg,
        'icrp_reference_kg':        s['icrp_total_protein_kg'],
        'within_icrp_factor':       total_kg / s['icrp_total_protein_kg'],
    }


def calculate_proteome_mass() -> Dict[str, Any]:
    """Calculate total effective mass of the human proteome using multipliers."""
    total_mass_da = 0
    total_copies = 0
    by_system: Dict[str, float] = {}
    
    for name, data in HUMAN_PROTEOME.items():
        # Handle proteins with copies_per_cell or ribosomes with rRNA_bases
        copies = data.get('copies_per_cell', 0)
        if copies == 0 and 'proteins' in data:
            # Ribosome: estimate copies from proteins count * typical stoichiometry
            copies = data['proteins'] * 1000  # rough estimate for ribosomes
        multiplier = data.get('multiplier', 1)
        mw = data.get('mw', 50000)  # default ~50 kDa if not specified

        # Secreted proteins (albumin, IgG, insulin...) carry copies_per_cell=0
        # because they aren't cell-bound — for those, `multiplier` is the
        # whole-body copy count, not a cell multiplier.
        total_copies_protein = (copies * multiplier if copies > 0
                                else multiplier)
        mass = total_copies_protein * mw
        total_mass_da += mass
        total_copies += total_copies_protein
        
        systems = data.get('organ_systems', ['other'])
        for system in systems:
            by_system[system] = by_system.get(system, 0) + mass
    
    # Convert to kg (1 Da = 1.66e-27 kg)
    total_kg = total_mass_da * 1.660539e-27

    return {
        'total_mass_daltons': total_mass_da,
        'total_mass_kg': total_kg,
        'total_protein_copies': total_copies,
        'by_organ_system': {k: v * 1.660539e-27 for k, v in by_system.items()},
        'n_protein_types': len(HUMAN_PROTEOME),
    }


def format_mass(kg: float) -> str:
    """Format a mass in kg with adaptive units so small values don't render
    as '0.00 kg'."""
    if kg >= 0.1:
        return f"{kg:.2f} kg"
    if kg >= 1e-4:
        return f"{kg * 1e3:.2f} g"
    if kg >= 1e-7:
        return f"{kg * 1e6:.2f} mg"
    return f"{kg:.2e} kg"

