    assert g1['expected_indel_per_break'] > g2['expected_indel_per_break']
    assert p53_dna_damage_decision(30)['decision'] == 'APOPTOSIS'
    assert p53_dna_damage_decision(2)['decision'] == 'ARREST+REPAIR'
    assert p53_dna_damage_decision(0)['decision'] == 'NORMAL CYCLE'
    print(f"  [89] dsb/p53 OK (G1->NHEJ indel {g1['expected_indel_per_break']:.2f}, "
          f"G2->HR, 30 breaks->APOPTOSIS)")

    # 90. LIF neuron + STDP — actual neural computation.  The simulated
    # firing rate must match the closed-form f-I curve, and STDP must
    # show real LTP/LTD asymmetry (Bi & Poo).
    r_sim = lif_simulate(4.0, T_ms=2000)
    r_ana = lif_rate_analytic(4.0)
    assert abs(r_sim['rate_hz'] - r_ana) / r_ana < 0.15, \
        f"sim {r_sim['rate_hz']} vs analytic {r_ana}"
    assert lif_rate_analytic(1.0) == 0.0          # below rheobase
    assert lif_rate_analytic(10.0) > lif_rate_analytic(4.0) > 0
    assert stdp_window(+10) > 0 > stdp_window(-10)
    sp90 = stdp_pair_demo()
    assert sp90['w_after_LTP_pairing'] > 1.0 > sp90['w_after_LTD_pairing']
    print(f"  [90] LIF/STDP OK (sim {r_sim['rate_hz']:.0f} Hz ~ analytic "
          f"{r_ana:.0f} Hz; LTP x{sp90['w_after_LTP_pairing']:.1f}, "
          f"LTD x{sp90['w_after_LTD_pairing']:.2f})")

    # 91. Thermodynamic feasibility — real ΔG = ΔG' + RT ln Q on the
    # glycolytic chain.  Textbook result: exactly hexokinase, PFK and
    # pyruvate kinase are the irreversible regulated steps; the rest
    # sit near equilibrium.  Cellular ATP hydrolysis ~ -50 kJ/mol.
    gl = glycolysis_feasibility()
    irrev = {s['step'] for s in gl if 'irreversible' in s['class']}
    assert irrev == {'hexokinase', 'PFK-1', 'pyr_kinase'}, irrev
    assert all(s['class'] != 'forward-infeasible' for s in gl)
    assert -55 < atp_hydrolysis_dg() < -45
    print(f"  [91] thermodynamics OK (irreversible={sorted(irrev)}, "
          f"aldolase dG={gl[3]['dG_kj']:+.1f}, ATP->ADP {atp_hydrolysis_dg():.0f} kJ/mol)")

    # 92. Metabolic breadth — real stoichiometric yields.
    assert beta_oxidation()['atp_net'] == 106.0            # palmitate C16
    assert beta_oxidation(8)['acetyl_coa'] == 4
    assert urea_cycle()['high_energy_bonds'] == 4          # ATP->AMP counts 2
    ppp = pentose_phosphate()
    assert ppp['complete_oxidation']['nadph'] == 12
    s1 = sglt_concentration(na_per_glucose=1)
    s2 = sglt_concentration(na_per_glucose=2)
    assert s2['max_glucose_ratio'] > s1['max_glucose_ratio'] > 1
    assert nitrogenase_cost()['atp_per_n2'] == 16
    assert methanogenesis_dg()['dG0_kjmol'] == -131.0
    print(f"  [92] metab-breadth OK (palmitate 106 ATP, urea 4 bonds, "
          f"PPP 12 NADPH, SGLT1 {s2['max_glucose_ratio']:.0f}x > SGLT2 "
          f"{s1['max_glucose_ratio']:.0f}x, N2ase 16 ATP)")

    # 93. Cytoskeletal machines — real mechanochemistry.
    k93 = kinesin_run()
    assert 700 < k93['velocity_nm_s'] < 900               # ~800 nm/s unloaded
    assert 0.4 < k93['efficiency'] < 0.9                  # real ~60-80%
    assert 100 < k93['processivity_steps'] < 200
    assert sarcomere_force(2.1) == 1.0 > sarcomere_force(3.0)
    assert sarcomere_force(3.7) == 0.0                    # no overlap
    assert sarcomere_force(1.0) < sarcomere_force(1.6)    # collision zone
    mt93 = microtubule_dynamics()
    assert mt93['bounded'] and 0.5 < mt93['mean_length_um'] < 5
    print(f"  [93] machines OK (kinesin {k93['velocity_nm_s']:.0f} nm/s eff "
          f"{k93['efficiency']:.0%}, sarcomere peak 2.1 um, MT L="
          f"{mt93['mean_length_um']:.1f} um)")

    # 94. Classic evolution experiments — real falsifiable signatures.
    ld94 = luria_delbruck()
    assert ld94['fano_fluctuation'] > 5 * ld94['fano_postselection']
    mr94 = mullers_ratchet(1e5, 1.0)
    assert mr94['ratchet_active']                          # U/s >> ln Ne
    assert not mullers_ratchet(1e9, 0.001)['ratchet_active']
    kn94 = knudson_two_hit()
    assert kn94['p_hereditary_tumour'] > 100 * kn94['p_sporadic_tumour']
    tb94 = telegraph_bursting()
    assert tb94['fano'] > 1.0                              # bursty
    print(f"  [94] evo-experiments OK (LD Fano {ld94['fano_fluctuation']:.0f} vs "
          f"{ld94['fano_postselection']:.2f}, ratchet n0={mr94['n0_least_loaded']:.0e}, "
          f"Knudson {kn94['p_hereditary_tumour']:.2f}>{kn94['p_sporadic_tumour']:.3f}, "
          f"burst Fano {tb94['fano']:.1f})")

    # 95. Organ-system physiology — real clinical physics.
    assert 30 < bohr_effect(7.2)['p50_mmHg'] < 35          # muscle
    assert 20 < bohr_effect(7.6)['p50_mmHg'] < 24          # lung
    q_small = poiseuille_flow(25, 2.5); q_big = poiseuille_flow(25, 5.0)
    assert abs(q_big['Q_mL_s'] / q_small['Q_mL_s'] - 16.0) < 0.1   # r^4
    alv = alveolar_pressure(75, 72); alv_s = alveolar_pressure(75, 5)
    assert alv['P_kPa'] / alv_s['P_kPa'] > 10              # surfactant
    q95 = quantal_release()
    assert abs(q95['mean_quanta'] - 50) < 1e-9 and q95['cv'] < 0.2
    rc95 = renal_countercurrent()
    assert rc95['daily_filtrate_L'] == 180 and rc95['reabsorbed_pct'] == 99.0
    print(f"  [95] physiology OK (Bohr p50 {bohr_effect(7.2)['p50_mmHg']:.0f}@"
          f"pH7.2, Poiseuille r^4=16x, alveolus {alv['P_kPa']:.1f}->"
          f"{alv_s['P_kPa']:.2f} kPa, quantal m={q95['mean_quanta']:.0f})")

    # 96. Kinetic proofreading + bacterial stress regulons — the real
    # mechanisms biology uses to buy fidelity and survive starvation.
    hp96 = hopfield_proofreading()
    assert abs(hp96['error_per_event'] - 1e-4) < 1e-9        # ribosome ~1e-4
    assert hopfield_proofreading(system='polymerase')['error_per_event'] < 1e-7
    sr96 = stringent_response(1.0)
    assert 0.05 < sr96['rrna_transcription_fold'] < 0.5      # rRNA crushed
    assert stringent_response(0.0)['rrna_transcription_fold'] == 1.0
    assert sos_response(10)['tls_polV_active']               # persistent -> Pol V
    assert not sos_response(2)['tls_polV_active']            # light -> error-free
    assert splicing_isoforms(3)['theoretical_isoforms'] == 8
    assert splicing_isoforms()['alt_spliced_pct'] == 95.0
    print(f"  [96] fidelity/regulons OK (proofread {hp96['error_per_event']:.0e}, "
          f"ppGpp rRNA x{sr96['rrna_transcription_fold']:.2f}, SOS Pol V, "
          f"splicing 95%)")

    # 97. Biosynthetic network — real precursor families and costs.
    aa97 = amino_acid_biosynthesis()
    assert aa97['most_expensive'] == 'W' and aa97['cheapest'] == 'A'
    assert len(aa97['essential_human']) == 9                 # PVT TIM HALL
    assert aa97['cost_atp_equiv']['W'] > 2 * aa97['cost_atp_equiv']['V']
    na97 = nitrogen_assimilation(0.1)
    assert 'GS/GOGAT' in na97['pathway'] and na97['atp_per_n'] == 1.0
    assert 'GDH' in nitrogen_assimilation(5.0)['pathway']    # high-NH4 fallback
    nb97 = nucleotide_biosynthesis()
    assert nb97['imp_atp_equiv'] == 6.0 > nb97['salvage_atp_equiv'] == 2.0
    assert nb97['purine_folate_carbons'] == 2 and nb97['rnr_nadph_per_dntp'] == 1.0
    print(f"  [97] biosynthesis OK (Trp {aa97['cost_atp_equiv']['W']:.0f} vs Ala "
          f"{aa97['cost_atp_equiv']['A']:.0f} ATP-equiv, IMP 6 vs salvage 2, "
          f"GS/GOGAT 3.5/N)")

    # 98. Transport + cytoskeletal mechanics — real physical constraints.
    bp98 = bilayer_permeability(10.0)
    g_t = bp98['permeability']['glucose']['t_half_s']
    na_t = bp98['permeability']['Na+/K+']['t_half_s']
    assert 60 < g_t < 7200 and na_t > 1e4 * g_t              # min vs ~years
    cm98 = cytoskeleton_mechanics()
    assert 3 < cm98['stall_pN_per_filament'] < 12            # kT/d·ln(c/cc)
    assert 0.1 < cm98['protrusive_um_s'] < 0.6               # keratocyte pace
    cap98 = cardiac_ap()
    assert cap98['apd_ms'] == 300.0 > 100 * cap98['neuronal_apd_ms']
    assert 2e9 < cap98['lifetime_beats_80y'] < 4e9
    assert ucp1_thermogenesis(1)['atp_forgone'] == 2.5
    print(f"  [98] transport/mechanics OK (glucose t1/2 {g_t/60:.0f} min vs "
          f"Na+ {na_t/3.15e7:.1f} yr, ratchet {cm98['stall_pN_per_filament']:.0f} pN, "
          f"cardiac 300 ms plateau)")

    # 99. Homeostatic control + biological clocks — real ODEs, real
    # thresholds.  ADA criteria classify the simulated 2-h value.
    gi99 = glucose_insulin_response()
    assert 130 < gi99['peak_glucose_mgdl'] < 200 and gi99['ada_class'] == 'normal'
    assert gi99['g_at_120min'] < 140
    gi99b = glucose_insulin_response(phenotype='igt')
    assert 140 <= gi99b['g_at_120min'] < 200
    gi99c = glucose_insulin_response(phenotype='diabetic')
    assert gi99c['g_at_120min'] >= 200
    kc99 = kai_clock()
    assert 23 < kc99['period_h'] < 25 and kc99['q10'] < 1.5  # temp-compensated
    rp99 = repressilator()
    assert rp99['oscillating'] and 100 < rp99['period_min'] < 250
    print(f"  [99] homeostasis/clocks OK (OGTT peak {gi99['peak_glucose_mgdl']:.0f}->"
          f"{gi99['g_at_120min']:.0f}@120 min={gi99['ada_class']}, KaiC {kc99['period_h']} h "
          f"Q10={kc99['q10']}, repressilator {rp99['period_min']:.0f} min)")

    # 100. Molecular + population evolution — real distance corrections.
    jc100 = jukes_cantor_distance(0.1)
    assert abs(jc100['d_sub_per_site'] - 0.1073) < 1e-3      # standard value
    assert jukes_cantor_distance(0.8)['saturated']
    k2_100 = kimura_2p_distance(0.08, 0.02)
    assert k2_100['d_sub_per_site'] > jc100['d_sub_per_site'] > 0.1
    co100 = coalescent_tmrca(2, 10_000)
    assert abs(co100['tmrca_generations'] - 20_000) < 1      # 4Ne(1-1/2)=2Ne
    co_mt = coalescent_tmrca(100, 8_000, 25, 'haploid')
    assert 100_000 < co_mt['tmrca_years'] < 500_000          # mt-Eve scale
    ml100 = mutation_load(2.0)
    assert abs(ml100['load'] - 0.865) < 0.01                 # 1-e^-2 (Haldane)
    shm100 = somatic_hypermutation()
    assert shm100['fold_over_germline'] == 1e6
    assert 5 < shm100['mutations_per_clone'] < 20
    assert meiosis_recombination()['crossovers_per_meiosis'] == 55
    print(f"  [100] mol-evolution OK (JC {jc100['d_sub_per_site']:.3f}, "
          f"coalescent 2Ne={co100['tmrca_generations']:.0f} gen, "
          f"SHM 1e6x, load 0.87)")

    # 101. Energetics breadth — uncoupling, brain budget, tau-leaping.
    be101 = brain_energy_budget()
    assert 1e9 < be101['atp_per_neuron_s'] < 1e10
    assert be101['signaling_share_pct'] == 80.0
    rxns101 = central_dogma_reactions()
    tl101 = [tau_leap({'gene': 1}, rxns101, t_max=200.0, tau=0.5, seed=s)
             for s in (1, 2, 3, 4, 5)]
    tl_mean = sum(r['final'].get('protein', 0) for r in tl101) / len(tl101)
    ssa101 = simulate_gene_expression(t_max=200.0, seed=7)
    ssa_mean = ssa101['final'].get('protein', 0)
    assert 0.5 < tl_mean / max(ssa_mean, 1) < 2.0            # same regime
    assert tl101[0]['n_leaps'] < ssa101['n_reactions_fired'] / 10
    print(f"  [101] energetics OK (brain {be101['atp_per_neuron_s']:.1e} ATP/n/s, "
          f"tau-leap mean {tl_mean:.0f} vs SSA {ssa_mean} in "
          f"{tl101[0]['n_leaps']} leaps)")

    # 102. GenBank round-trip — real annotation import.
    gb102 = ("LOCUS       TESTGENE        300 bp    DNA   linear   12-NOV-2026\n"
             "DEFINITION  synthetic test locus with two CDS features\n"
             "ACCESSION   TEST001\n"
             "FEATURES             Location/Qualifiers\n"
             "     CDS             10..90\n"
             "                     /gene=\"gfaA\"\n"
             "                     /product=\"test protein A\"\n"
             "     CDS             complement(join(100..140,160..190))\n"
             "                     /gene=\"gfbB\"\n"
             "ORIGIN\n"
             "        1 atggctaaaa tggctaaaa tggctaaaa tggctaaaa tggctaaaa tggctaaaa tggctaaaa\n"
             "       71 tggctaaaa tggctaaaa atgggaaaa tttggctaa agctttggc taaagctttg gctaaagctt\n"
             "      141 tggctaaagc tttggctaaa agctttggct aaagctttgg ctaaagcttt ggctaaagct\n"
             "//\n")
    rec102 = parse_genbank(gb102)
    assert rec102['locus'] == 'TESTGENE' and rec102['accession'] == 'TEST001'
    assert len(rec102['features']) == 2
    spans102 = _parse_genbank_location('complement(join(100..140,160..190))')
    assert spans102 == [(99, 140, -1), (159, 190, -1)]
    import tempfile, os as _os
    _p102 = _os.path.join(tempfile.gettempdir(),
                          f'pm_test_{_os.getpid()}.gb')
    with open(_p102, 'w') as _f102:
        _f102.write(gb102)
    imp102 = import_genbank_genome(_p102)
    _os.unlink(_p102)
    assert imp102['n_cds'] == 2 and [c['gene'] for c in imp102['cds']] == ['gfaA', 'gfbB']
    assert imp102['cds'][1]['spans'] == 2                    # join resolved
    print(f"  [102] genbank OK ({imp102['n_cds']} CDS from join/complement, "
          f"genes {[c['gene'] for c in imp102['cds']]})")

    # 103. SBML export — real standard-format interop.
    import xml.dom.minidom as _md
    sbml103 = export_sbml()
    doc103 = _md.parseString(sbml103)
    assert len(doc103.getElementsByTagName('species')) == len(FBA_SPECIES)
    assert len(doc103.getElementsByTagName('reaction')) == len(FBA_REACTIONS)
    glyc103 = [r for r in doc103.getElementsByTagName('reaction')
               if r.getAttribute('id') == 'glycolysis'][0]
    glc_ref = [s for s in glyc103.getElementsByTagName('speciesReference')
               if s.getAttribute('species') == 'glc'][0]
    assert glc_ref.getAttribute('stoichiometry') == '1'
    print(f"  [103] SBML OK ({len(FBA_SPECIES)} species x {len(FBA_REACTIONS)} "
          f"reactions, well-formed L3V1 XML)")

    # 104. Morris sensitivity — the SA ranking must reproduce the LP dual.
    mo104 = morris_sensitivity()
    assert mo104['binding_nutrient'] == 'glucose_uptake'
    assert abs(mo104['elementary_effects']['glucose_uptake'] - 32.0) < 1.0
    assert abs(mo104['elementary_effects']['o2_uptake']) < 1e-9
    print(f"  [104] sensitivity OK (glc effect {mo104['elementary_effects']['glucose_uptake']:.0f} "
          f"= shadow price; O2 effect 0 at glc-limited vertex)")

    # 105. Checkpoint/resume — a crashed run continues bit-for-bit.
    # Unique filename: a second test process on the same machine must not
    # overwrite this checkpoint between save and load.
    _ck = _os.path.join(tempfile.gettempdir(),
                        f'pm_ckpt_test_{_os.getpid()}.json')
    ev_full = Evolver(pop_size=20, genome_len=40, generations=4, n_bases=4,
                      n_workers=1, seed=99, fast=True)
    r_full = ev_full.run()
    ev_half = Evolver(pop_size=20, genome_len=40, generations=2, n_bases=4,
                      n_workers=1, seed=99, fast=True, checkpoint_every=1,
                      checkpoint_path=_ck)
    ev_half.run()
    ev_res = Evolver(pop_size=20, genome_len=40, generations=4, n_bases=4,
                     n_workers=1, seed=99, fast=True)
    ev_res.load_checkpoint(_ck)
    r_res = ev_res.run()
    _os.unlink(_ck)
    assert abs(r_full['best']['fitness'] - r_res['best']['fitness']) < 1e-9
    assert len(r_res['history']) == len(r_full['history'])
    print(f"  [105] checkpoint/resume OK (interrupted+resumed best "
          f"{r_res['best']['fitness']:.4f} = uninterrupted "
          f"{r_full['best']['fitness']:.4f})")

    # 106. SBML round-trip — the exported standard file parses back into
    # the identical network and re-solves to the same LP optimum.
    sb106 = import_sbml(export_sbml())
    assert sb106['species'] == FBA_SPECIES
    assert sb106['reactions'] == FBA_REACTIONS          # lossless stoich
    rt106 = fba_core_carbon(1.0, 6.0, species=sb106['species'],
                            reactions=sb106['reactions'])
    assert abs(rt106['atp_per_glucose'] - 32.0) < 1e-6
    assert abs(rt106['atp_flux'] - fba_core_carbon(1.0, 6.0)['atp_flux']) < 1e-6
    print(f"  [106] SBML round-trip OK ({sb106['n_species']} species/"
          f"{sb106['n_reactions']} reactions lossless; re-solved "
          f"{rt106['atp_per_glucose']:.0f} ATP/glc)")

    # 107. Alignment + BLAST statistics + composition — the real
    # bioinformatics primitives on engine sequences.
    nw107 = needleman_wunsch('ATCGATCG', 'ATCGATCG')
    assert nw107['score'] == 16 and nw107['identity'] == 1.0
    nw107b = needleman_wunsch('ATCGATCG', 'ATGGATCG')
    assert nw107b['score'] < nw107['score']             # mismatch costs
    sw107 = smith_waterman('TTTTACGTACGTAAAA', 'GGGACGTACGTCCC')
    assert sw107['score'] == 16 and 'ACGTACGT' in sw107['aligned_a']
    ka107 = karlin_altschul_evalue(50, 1000, 1000)
    ka107b = karlin_altschul_evalue(30, 1000, 1000)
    assert ka107['significant'] and ka107['evalue'] < 0.05
    assert not ka107b['significant']                    # real BLAST boundary
    assert ka107b['evalue'] > ka107['evalue'] > 0
    assert abs(gc_content('ATCGGCGC') - 0.75) < 1e-9
    oe107 = dinucleotide_oe('ATCGATCG', 'CG')
    assert oe107 > 2.0                                  # CpG-island-like
    oe107b = dinucleotide_oe('ATATATATCCCCGGGG', 'CG')
    assert oe107b < 1.5
    print(f"  [107] alignment/BLAST OK (NW={nw107['score']}, SW found "
          f"'{sw107['aligned_a']}', E(S=50)={ka107['evalue']:.2e} sig, "
          f"CpG O/E {oe107:.1f})")

    # 108. Selection tests + logo + Wright-Fisher — real population /
    # molecular-evolution machinery.
    dsyn = dn_ds_ratio('ATGGCTAAATGG', 'ATGGCCAAATGG')   # GCT->GCC synonymous
    assert dsyn['dnds'] == 0.0 and dsyn['syn_subs'] == 1
    dnon = dn_ds_ratio('ATGGCTAAATGG', 'ATGGATAAATGG')   # Ala->Asp nonsyn
    assert dnon['dnds'] == float('inf') and dnon['nonsyn_subs'] == 1
    did  = dn_ds_ratio('ATGGCTAAATGG', 'ATGGCTAAATGG')
    assert did['syn_subs'] == 0 and did['nonsyn_subs'] == 0
    td108 = tajimas_d(10, 10, 3.5)
    assert abs(td108['D'] - (-0.03)) < 0.05              # worked example ~0
    td108b = tajimas_d(10, 10, 0.5)
    assert td108b['D'] < -1.0                            # rare-allele excess
    lg108 = sequence_logo(['ATCG', 'ATCG', 'ATCG'])
    assert abs(lg108[0]['R_bits'] - 2.0) < 1e-9          # conserved = 2 bits
    lg108b = sequence_logo(['AAAA', 'CCCC', 'GGGG', 'TTTT'])
    assert abs(lg108b[0]['R_bits']) < 1e-9               # uniform = 0 bits
    wf108 = wright_fisher(0.5, 100, 500, seed=7)
    wf108b = wright_fisher(0.5, 100, 500, seed=7)
    assert wf108['final_p'] == wf108b['final_p']         # deterministic
    assert wf108['fixed'] or wf108['lost'] or wf108['gens_run'] == 500
    print(f"  [108] selection OK (dN/dS syn={dsyn['dnds']:.1f} vs "
          f"nonsyn={dnon['verdict']}, Tajima {td108['D']:.2f}, logo "
          f"{lg108[0]['R_bits']:.1f} bits, WF p={wf108['final_p']:.2f})")

    # 109. Mechanism breadth — CRISPR, FAS, signal peptide, PCR,
    # heat shock, coagulation, Bateman PK.
    cr109 = crispr_scan('A' * 20 + 'AGG' + 'TTTCCCGGG', guide='A' * 20)
    assert cr109['on_target'] is not None
    assert cr109['repair_prediction']['pathway'] == 'NHEJ'   # G1 default
    assert cr109['on_target']['cut_idx'] == 17               # 3 bp 5' of PAM
    cr109b = crispr_scan('TTTTTTTTT', guide='A' * 20)
    assert cr109b['on_target'] is None
    fa109 = fatty_acid_synthesis(16)
    assert fa109['malonyl_coa'] == 7 and fa109['nadph'] == 14 \
        and fa109['atp_acc'] == 7 and fa109['oxidation_yield_atp'] == 106
    sp109 = signal_peptide_analysis('MK' + 'F' * 12 + 'AAGT' + 'D' * 20)
    sp109b = signal_peptide_analysis('M' + 'D' * 25)
    assert sp109['is_signal'] and not sp109b['is_signal']
    pcr109 = pcr_amplification(30)
    pcr109b = pcr_amplification(30, pol_error_per_bp=1e-6)
    assert pcr109['yield_fold'] > 1e7 < pcr109['ideal_fold']
    assert pcr109['error_free_fraction'] < 0.10 \
        < pcr109b['error_free_fraction']                 # Taq vs proofreading
    hs109 = heat_shock_response(42)
    hs109b = heat_shock_response(30)
    assert 5 < hs109['sigma32_fold_peak'] <= 15 and hs109b['sigma32_fold_peak'] == 1
    assert heat_shock_response(47)['lethal']
    cg109 = coagulation_burst()
    assert cg109['peak_thrombin_nM'] == 350 and cg109['prothrombinase_boost'] == 3e5
    pk109 = bateman_pk()
    assert 8 < pk109['cmax_mg_L'] < 14 and 0.8 < pk109['tmax_h'] < 1.6 \
        and 1.0 < pk109['t_half_h'] < 1.6                # amoxicillin profile
    print(f"  [109] mechanisms OK (CRISPR->NHEJ cut@17, FAS 7+14NADPH, "
          f"PCR {pcr109['error_free_fraction']*100:.0f}% clean, "
          f"PK Cmax {pk109['cmax_mg_L']:.1f} mg/L)")

    # 110. Config schema + replicate statistics — engineering rigor.
    v110 = validate_run_config({'pop_size': 40, 'genome_len': 60,
                                'generations': 10, 'n_bases': 4})
    assert v110['ok']
    v110b = validate_run_config({'pop_size': -5, 'n_bases': 5, 'bogus': 1})
    assert not v110b['ok'] and len(v110b['errors']) == 3
