    nmd111a = nonsense_mediated_decay([200, 150, 100], 250)
    nmd111b = nonsense_mediated_decay([200, 150, 100], 430)
    assert nmd111a['is_ptc'] and not nmd111b['is_ptc']    # EJC 50-55 nt rule
    mh111 = membrane_homeoviscous(17)
    assert mh111['unsaturated_frac'] == 0.65
