# === Hardware Detection & GPU-First Adaptive Performance Governor ===
# GPU-FIRST POLICY: GPU is the primary compute device. CPU is fallback only.
# 1. Always use GPU for gravity, EM forces, and batch position updates when available.
# 2. GPU aims for 50%+ utilization before ANY CPU compute is used.
# 3. Under heavy load, GPU scales to 100% utilization.
# 4. CUDA max-performance mode and overclock support enabled at startup.
# 5. CPU handles only: atom internal dynamics, observer AI, and non-batchable logic.

_PERF_GPU_AVAILABLE = False
_PERF_GPU_NAME = 'None'
_PERF_GPU_VRAM_MB = 0
_PERF_GPU_COMPUTE_CAP = (0, 0)
_PERF_CPU_CORES = max(1, os.cpu_count() or 1)
_PERF_GPU_DEVICE = None  # torch.device object when GPU available

if _TORCH:
    try:
        if _COMPUTE_DEVICE is not None:
            _PERF_GPU_AVAILABLE = True
            _PERF_GPU_NAME = _COMPUTE_NAME
            _PERF_GPU_VRAM_MB = _COMPUTE_VRAM_MB
            _PERF_GPU_COMPUTE_CAP = _COMPUTE_CAP
            _PERF_GPU_DEVICE = _COMPUTE_DEVICE
            # === Accelerator-specific tuning ===
            # Allow full GPU utilization up to 100% where the backend supports it
            try:
                if _COMPUTE_KIND == 'cuda':
                    props = torch.cuda.get_device_properties(0)
                    # Enable TF32 for faster float32 math on Ampere+ GPUs (compute cap >= 8.0)
                    if props.major >= 8:
                        torch.backends.cuda.matmul.allow_tf32 = True
                        torch.backends.cudnn.allow_tf32 = True
                    # Set memory growth / caching behavior for max throughput
                    # Use expandable_segments to allow GPU memory to grow without fragmentation
                    os.environ.setdefault('PYTORCH_CUDA_ALLOC_CONF', 'expandable_segments:True')
                    # Set CUDA to max-performance power mode via environment hints
                    # (actual overclock requires nvidia-smi or driver-level control)
                    os.environ.setdefault('CUDA_AUTO_BOOST', '1')  # Enable GPU Boost / overclock
                    # Enable cudnn benchmark for fastest kernel selection
                    torch.backends.cudnn.benchmark = True
                    # Pre-warm GPU: allocate and free a tensor to initialize CUDA context
                    _warmup = torch.zeros(1024, device=_PERF_GPU_DEVICE)
                    del _warmup
                    torch.cuda.empty_cache()
                elif _COMPUTE_KIND == 'xpu':
                    _warmup = torch.zeros(1024, device=_PERF_GPU_DEVICE)
                    del _warmup
                    try:
                        torch.xpu.empty_cache()
                    except Exception:
                        pass
                elif _COMPUTE_KIND == 'mps':
                    _warmup = torch.zeros(1024, device=_PERF_GPU_DEVICE)
                    del _warmup
                    try:
                        torch.mps.empty_cache()
                    except Exception:
                        pass
                else:
                    # DirectML / generic backend: context warmup only
                    _warmup = torch.zeros(1024, device=_PERF_GPU_DEVICE)
                    del _warmup
            except Exception:
                pass
    except Exception:
        pass

# Detect broken CUDA: VRAM=0 or compute_cap=(0,0) means the CUDA runtime can't
# fully drive this GPU (e.g. Blackwell before PyTorch adds support).
# Override device to CPU so .to(device) calls don't hang during NN init.
# Non-CUDA backends legitimately report VRAM/cap as unknown — the demotion
# is CUDA-specific.
if _PERF_GPU_AVAILABLE and _COMPUTE_KIND == 'cuda' and (_PERF_GPU_VRAM_MB == 0 or _PERF_GPU_COMPUTE_CAP == (0, 0)):
    print(f"[WARNING] CUDA reports VRAM={_PERF_GPU_VRAM_MB}MB cap={_PERF_GPU_COMPUTE_CAP[0]}.{_PERF_GPU_COMPUTE_CAP[1]} — NN models will use CPU (GPU physics still enabled)")
    if _TORCH:
        device = torch.device("cpu")

# Cap torch's CPU thread pool — six background engines plus the observer brain
# all dispatch tiny ops; the default pool (one thread per hardware core) just
# oversubscribes and fights the render thread for the GIL.
if _TORCH:
    try:
        torch.set_num_threads(max(2, min(4, (os.cpu_count() or 4) // 3)))
    except Exception:
        pass

def _gpu_to_tensors(positions_np, masses_np):
    """Move position/mass arrays to GPU. Always attempts GPU when available (no size threshold).
    Returns (positions_tensor, masses_tensor, on_gpu_bool).
    Falls back to numpy arrays (on_gpu=False) if GPU unavailable or fails."""
    if _PERF_GPU_AVAILABLE:
        try:
            pos_t = torch.as_tensor(positions_np, dtype=torch.float32, device=_PERF_GPU_DEVICE)
            mass_t = torch.as_tensor(masses_np, dtype=torch.float32, device=_PERF_GPU_DEVICE)
            return pos_t, mass_t, True
        except Exception:
            pass
    return positions_np, masses_np, False

# (tile_rows × N × 3 × 4B) fp32 working-set budget per pairwise tile. Sized so
# the (Bi,N,3) diff tensor + (Bi,N) reductions stay well inside a 16GB card
# alongside the resident pos/mass tensors. i-tiling is bit-identical to the
# single-shot kernel: every output row still reduces over the full j-range in
# the same order — only the receiver block changes.
_PAIRWISE_TILE_BYTES = 1_500_000_000  # ~1.5GB


def _pairwise_tile_rows(n):
    """Receiver-block size for the pairwise kernels. Keeps (Bi,N,3) fp32
    under _PAIRWISE_TILE_BYTES; >=1 so a single row always fits (N*12B)."""
    if n <= 0:
        return 1
    return max(1, min(n, int(_PAIRWISE_TILE_BYTES // (n * 12))))


def _gpu_pairwise_gravity(pos_t, mass_t, G_val, softening=1e-10):
    """GPU-accelerated O(N^2) direct gravity via torch on CUDA.
    Used at ANY particle count when GPU is available. Returns numpy array of accelerations.

    Note on symmetry vs EM (item 6): the apparent "asymmetry" between this
    and EM forces is physical, not a bug. Gravitational mass cancels in
    F=ma so acceleration depends only on source mass; EM acceleration
    depends on receiver q/m ratio. Both satisfy Newton's 3rd law analytically.

    Item-7 (acceleration clamp): opt-in via env var SIM_CLAMP_ACCEL=1.
    Default OFF — original physics path preserved byte-for-byte.

    Step-7b: i-tiled. The single-shot (N,N,3) diff tensor exceeds VRAM at
    N≳30–40K and silently OOM'd into the CPU Barnes-Hut fallback (seconds–
    minutes per frame). Tiling receiver blocks keeps every output row's
    j-reduction identical — same operands, same order — at any N."""
    n = pos_t.shape[0]
    tile = _pairwise_tile_rows(n)
    if tile >= n:
        # diff[i,j] = pos_j - pos_i : vector from receiver i toward source j
        # (attractive direction — matches TreeWalk's dx = node.COM - node0.COM).
        diff = pos_t.unsqueeze(0) - pos_t.unsqueeze(1)  # (N,N,3)
        dist_sq = (diff * diff).sum(dim=2) + softening   # (N,N)
        dist = torch.sqrt(dist_sq)                         # (N,N)
        inv_dist3 = mass_t.unsqueeze(0) / (dist_sq * dist + softening)  # (N,N)
        inv_dist3.fill_diagonal_(0.0)
        accel = G_val * (inv_dist3.unsqueeze(2) * diff).sum(dim=1)  # (N,3)
        if _ACCEL_CLAMP_ENABLED:
            accel = torch.clamp(accel, min=-_ACCEL_CAP, max=_ACCEL_CAP)
        return accel.cpu().numpy()
    accel = torch.empty((n, 3), dtype=torch.float32, device=pos_t.device)
    _jar = torch.arange(n, device=pos_t.device)
    for _i0 in range(0, n, tile):
        _i1 = min(_i0 + tile, n)
        _pb = pos_t[_i0:_i1]
        diff = pos_t.unsqueeze(0) - _pb.unsqueeze(1)          # (Bi,N,3) src - recv
        dist_sq = (diff * diff).sum(dim=2) + softening        # (Bi,N)
        dist = torch.sqrt(dist_sq)
        inv_dist3 = mass_t.unsqueeze(0) / (dist_sq * dist + softening)
        # Zero self-interaction: diagonal sits at j == i0+row inside the tile.
        inv_dist3[_jar[_i0:_i1].unsqueeze(1) == _jar.unsqueeze(0)] = 0.0
        accel[_i0:_i1] = G_val * (inv_dist3.unsqueeze(2) * diff).sum(dim=1)
    if _ACCEL_CLAMP_ENABLED:
        accel = torch.clamp(accel, min=-_ACCEL_CAP, max=_ACCEL_CAP)
    return accel.cpu().numpy()

def _gpu_pairwise_em_forces(pos_t, charges_t, vel_t, masses_t, k_e_val, mu_0_val, cutoff_sq=250000.0, softening=1e-10):
    """GPU-accelerated O(N^2) Coulomb + Lorentz forces via torch on CUDA.
    Returns numpy array of accelerations from EM interactions.

    Item-8 (smooth cutoff): opt-in via env var SIM_SMOOTH_CUTOFF=1.
    Default OFF — original binary cutoff mask path preserved exactly.

    Step-7b: i-tiled like _gpu_pairwise_gravity — identical per-receiver
    j-reduction, but the (Bi,N,3) working set stays under _PAIRWISE_TILE_BYTES
    so large scenes no longer OOM into the CPU pairwise fallback."""
    n = pos_t.shape[0]
    if n < 2:
        return np.zeros((n, 3), dtype=np.float32)
    if _SMOOTH_CUTOFF_ENABLED:
        # Item-8 smooth Fermi envelope
        _cutoff_dist = math.sqrt(float(cutoff_sq))
        _transition = max(1e-6, 0.05 * _cutoff_dist)
    tile = _pairwise_tile_rows(n)
    if tile >= n:
        # diff[i,j] = pos_j - pos_i : from receiver toward source, so
        # -k_e * q_i * q_j * diff/r^3 is repulsive for like charges —
        # the same sign convention as the CPU loop (`force -= k_e q_i q_j / r^2`
        # applied along r = p.pos - self.pos).
        diff = pos_t.unsqueeze(0) - pos_t.unsqueeze(1)  # (N,N,3)
        dist_sq = (diff * diff).sum(dim=2) + softening   # (N,N)
        # Mask: skip self-interaction and beyond cutoff
        mask = (dist_sq < cutoff_sq)
        mask.fill_diagonal_(False)
        # Coulomb: F = k_e * q_i * q_j / r^2, direction = r_hat
        charge_product = charges_t.unsqueeze(1) * charges_t.unsqueeze(0)  # (N,N)
        # Any non-zero charge product contributes (e^2 ~ 2.6e-38 C^2 is the
        # realistic floor — a 1e-30 threshold silently killed every real
        # elementary-charge interaction). fp32 denormals still resolve it.
        coulomb_mask = mask & (charge_product != 0.0)
        dist_sq_safe = dist_sq.clamp(min=softening)
        dist = torch.sqrt(dist_sq_safe)
        inv_dist3 = 1.0 / (dist_sq_safe * dist + softening)
        if _SMOOTH_CUTOFF_ENABLED:
            _envelope = torch.sigmoid((_cutoff_dist - dist) / _transition)
            inv_dist3 = inv_dist3 * coulomb_mask.float() * _envelope
        else:
            inv_dist3 = inv_dist3 * coulomb_mask.float()
        f_coulomb = -k_e_val * (charges_t.unsqueeze(0) * inv_dist3).unsqueeze(2) * diff  # (N,N,3)
        accel_coulomb = f_coulomb.sum(dim=1)  # (N,3)
        mass_safe = masses_t.clamp(min=1e-60)
        qm_ratio = charges_t / mass_safe  # (N,)
        accel = accel_coulomb * qm_ratio.unsqueeze(1)
        if _ACCEL_CLAMP_ENABLED:
            accel = torch.clamp(accel, min=-_ACCEL_CAP, max=_ACCEL_CAP)
        return accel.cpu().numpy()
    accel = torch.empty((n, 3), dtype=torch.float32, device=pos_t.device)
    mass_safe = masses_t.clamp(min=1e-60)
    qm_ratio = charges_t / mass_safe  # (N,)
    _jar = torch.arange(n, device=pos_t.device)
    for _i0 in range(0, n, tile):
        _i1 = min(_i0 + tile, n)
        _pb = pos_t[_i0:_i1]
        _qb = charges_t[_i0:_i1]
        diff = pos_t.unsqueeze(0) - _pb.unsqueeze(1)          # (Bi,N,3) src - recv
        dist_sq = (diff * diff).sum(dim=2) + softening        # (Bi,N)
        mask = (dist_sq < cutoff_sq)
        mask[_jar[_i0:_i1].unsqueeze(1) == _jar.unsqueeze(0)] = False
        charge_product = _qb.unsqueeze(1) * charges_t.unsqueeze(0)  # (Bi,N)
        coulomb_mask = mask & (charge_product != 0.0)
        dist_sq_safe = dist_sq.clamp(min=softening)
        dist = torch.sqrt(dist_sq_safe)
        inv_dist3 = 1.0 / (dist_sq_safe * dist + softening)
        if _SMOOTH_CUTOFF_ENABLED:
            _envelope = torch.sigmoid((_cutoff_dist - dist) / _transition)
            inv_dist3 = inv_dist3 * coulomb_mask.float() * _envelope
        else:
            inv_dist3 = inv_dist3 * coulomb_mask.float()
        f_coulomb = -k_e_val * (charges_t.unsqueeze(0) * inv_dist3).unsqueeze(2) * diff
        accel[_i0:_i1] = f_coulomb.sum(dim=1) * qm_ratio[_i0:_i1].unsqueeze(1)
    if _ACCEL_CLAMP_ENABLED:
        accel = torch.clamp(accel, min=-_ACCEL_CAP, max=_ACCEL_CAP)
    return accel.cpu().numpy()

# Below this many particles the PCIe round-trip costs more than the kernel
# saves, so the batch path stays on the CPU. Same arithmetic either way.
_GPU_BATCH_POS_MIN = 2048


def _gpu_batch_position_update(positions_np, velocities_np, accels_np, dt_val, prev_accels_np=None):
    """GPU-accelerated Velocity Verlet (symplectic) position + velocity update.
    Velocity Verlet: x(t+dt) = x(t) + v(t)*dt + 0.5*a(t)*dt²
                     v(t+dt) = v(t) + 0.5*(a(t) + a(t+dt))*dt
    SYMPLECTIC BY CONSTRUCTION — if no acceleration history is supplied we
    bootstrap by treating the first step's prev_accel as the current accel
    (equivalent to assuming the system was instantaneously in steady-state).
    This keeps the integrator symplectic on every step, including step 0;
    the previous fallback `v += a*dt` broke time-reversibility and leaked
    energy on every cold-start.
    Returns (new_positions, new_velocities) as numpy arrays.
    Ref: Swope et al. (1982) J. Chem. Phys. 76, 637; Verlet (1967) Phys. Rev. 159, 98."""
    if prev_accels_np is None:
        # Cold-start bootstrap: assume a_prev = a_current so the symmetric
        # average reduces to a_current — the same as a single Euler half-kick,
        # but only for step 0. Subsequent steps will carry real history.
        prev_accels_np = accels_np
    if _PERF_GPU_AVAILABLE:
        try:
            pos_t = torch.as_tensor(positions_np, dtype=torch.float32, device=_PERF_GPU_DEVICE)
            vel_t = torch.as_tensor(velocities_np, dtype=torch.float32, device=_PERF_GPU_DEVICE)
            acc_t = torch.as_tensor(accels_np, dtype=torch.float32, device=_PERF_GPU_DEVICE)
            prev_t = torch.as_tensor(prev_accels_np, dtype=torch.float32, device=_PERF_GPU_DEVICE)
            dt2 = dt_val * dt_val
            # Velocity Verlet position: x += v*dt + 0.5*a*dt²
            pos_t = pos_t + vel_t * dt_val + 0.5 * acc_t * dt2
            # Full Verlet velocity: v += 0.5*(a_old + a_new)*dt — always symplectic
            vel_t = vel_t + 0.5 * (prev_t + acc_t) * dt_val
            return pos_t.cpu().numpy(), vel_t.cpu().numpy()
        except Exception:
            pass
    # CPU fallback — Velocity Verlet (also always symplectic now)
    dt2 = dt_val * dt_val
    new_pos = positions_np + velocities_np * dt_val + 0.5 * accels_np * dt2
    new_vel = velocities_np + 0.5 * (prev_accels_np + accels_np) * dt_val
    return new_pos, new_vel

def _batch_dormant_motion(all_particles, dormant_idx, grav_accels, n_grav, ddt):
    """Batched velocity-Verlet for atoms that have no neighbours.

    Both substep branches (JIT and pure-Python) route their dormant atoms
    through here, so the two paths cannot drift apart on integration. Above
    `_GPU_BATCH_POS_MIN` the update is dispatched to
    `_gpu_batch_position_update`; below it the identical numpy expression runs
    on the CPU, because the host<->device copy would cost more than the kernel
    saves. Either way the kick is the symmetric v += 0.5*(a_old + a_new)*dt
    form, which is symplectic."""
    D = len(dormant_idx)
    if not D:
        return
    dpos = np.empty((D, 3), dtype=np.float64)
    dvel = np.empty((D, 3), dtype=np.float64)
    dga = np.empty((D, 3), dtype=np.float64)
    dprev = np.empty((D, 3), dtype=np.float64)
    for k, idx in enumerate(dormant_idx):
        ap = all_particles[idx]
        dpos[k] = ap.pos
        dvel[k] = ap.vel
        dga[k] = grav_accels[idx] if idx < n_grav else _zero_accel
        # Under the frozen-force model (grav_accels is recomputed once per
        # frame, held constant across substeps) a(t) == a(t+dt) == dga for
        # every substep, so the symmetric Verlet trapezoid reduces to dga.
        # Using last FRAME's accel as the "prev" leg instead applies the
        # stale impulse ½·Δa·dt on every substep — a systematic velocity lag
        # that also breaks symplecticity at frame granularity.
        dprev[k] = dga[k]
    if _perf.use_gpu_batch_pos and D >= _GPU_BATCH_POS_MIN:
        npos, nvel = _gpu_batch_position_update(dpos, dvel, dga, ddt, dprev)
        # the GPU kernel returns float32; particle state is float64 everywhere
        # else, so restore the dtype before writing it back.
        npos = np.asarray(npos, dtype=np.float64)
        nvel = np.asarray(nvel, dtype=np.float64)
    else:
        npos = dpos + dvel * ddt + 0.5 * dga * (ddt * ddt)
        nvel = dvel + 0.5 * (dprev + dga) * ddt
    for k, idx in enumerate(dormant_idx):
        ap = all_particles[idx]
        ap.prev_pos = ap.pos      # cheap — same numpy object reference
        ap.pos = npos[k]
        ap.vel = nvel[k]
        ap._prev_batch_accel = dga[k].copy()


class _DormantMotionBatch:
    """Step-7 persistent SoA batch for dormant (motion-only) atoms.

    `_batch_dormant_motion` re-extracts every dormant atom's pos/vel/accel into
    fresh numpy arrays and rewrites four attributes per atom PER SUBSTEP —
    ~4 Python ops × D × substeps. This class keeps persistent (cap,3) buffers
    instead: each dormant atom's `.pos`, `.vel`, `.prev_pos` and
    `._prev_batch_accel` are assigned ONCE as row views into the buffers, so
    every substep is pure numpy (`copyto` + Verlet expression) with zero
    per-atom Python work. Atoms can be promoted mid-frame (an excited atom
    that just emitted becomes dormant-eligible) via `.add()` — they join the
    batch starting the NEXT substep, exactly matching the original semantics
    where eligibility was re-evaluated at the top of each substep.

    Integration is identical to `_batch_dormant_motion`: symplectic Velocity
    Verlet with `prev_accel` bootstrap, GPU dispatch above
    `_GPU_BATCH_POS_MIN`, float64 state throughout.

    PERSISTENT VARIANT (Step-7c): the same batch object is kept across frames.
    `reconcile()` diffs the enrolled index set against the frame's fresh
    dormant set and enrolls/de-enrolls only the DELTA — steady-state frames
    with an unchanged dormant set cost ~zero Python instead of re-enrolling
    every dormant atom (O(D) attr traffic → O(|ΔD|)). `pmap` maps
    particle-index -> row for O(1) removal; `verify_aliases()` periodically
    re-checks that each enrolled particle still aliases its row (an external
    `p.pos = ...` replacement — user drag, teleports — would otherwise
    silently desync that atom until it left the dormant set)."""
    __slots__ = ('cap', 'n', 'idx_of_row', 'plist', 'pos', 'vel', 'prev',
                 'prevacc', 'ga', 'ga_src', 'ga_n', 'boot_rows', 'pmap')

    def __init__(self, capacity):
        cap = max(64, int(capacity))
        self.cap = cap
        self.n = 0
        self.idx_of_row = np.empty(cap, dtype=np.intp)
        self.plist = [None] * cap          # row -> particle (for _grow re-point)
        self.pos = np.empty((cap, 3), dtype=np.float64)
        self.vel = np.empty((cap, 3), dtype=np.float64)
        self.prev = np.empty((cap, 3), dtype=np.float64)
        self.prevacc = np.empty((cap, 3), dtype=np.float64)
        self.ga = np.zeros((cap, 3), dtype=np.float64)
        self.ga_src = None
        self.ga_n = -1
        self.boot_rows = []   # rows needing ga-bootstrap on next step()
        self.pmap = np.full(cap, -1, dtype=np.intp)   # particle idx -> row

    def _grow(self):
        """Double buffer capacity and re-point every enrolled particle's views
        at the new arrays. Only reachable if promotions exceed the initial
        atom-count capacity (shouldn't happen — dormant ⊆ atoms — but kept as
        a correctness safety net)."""
        new_cap = self.cap * 2
        _ni = np.empty(new_cap, dtype=np.intp); _ni[:self.cap] = self.idx_of_row
        self.idx_of_row = _ni
        for _name in ('pos', 'vel', 'prev', 'prevacc', 'ga'):
            _old = getattr(self, _name)
            _new = np.empty((new_cap, 3), dtype=np.float64)
            _new[:self.cap] = _old
            setattr(self, _name, _new)
        self.plist.extend([None] * (new_cap - self.cap))
        self.cap = new_cap
        for _r in range(self.n):
            _p = self.plist[_r]
            if _p is not None:
                _p.pos = self.pos[_r]
                _p.vel = self.vel[_r]
                _p.prev_pos = self.prev[_r]
                _p._prev_batch_accel = self.prevacc[_r]
        if self.pmap.shape[0] < new_cap:
            _pm = np.full(new_cap, -1, dtype=np.intp)
            _pm[:self.pmap.shape[0]] = self.pmap
            self.pmap = _pm

    def _dealias(self, row):
        """Break the row-view aliasing on an enrolled particle, leaving it
        OWNED copies of its current state. Required before the row can be
        reused — otherwise a de-enrolled atom's writes would corrupt the
        atom that takes its row."""
        _p = self.plist[row]
        if _p is not None:
            _p.pos = self.pos[row].copy()
            _p.vel = self.vel[row].copy()
            _p.prev_pos = self.prev[row].copy()
            _p._prev_batch_accel = self.prevacc[row].copy()

    def _enroll_into_row(self, row, idx, particle, grav_accels, n_grav):
        """Overwrite an existing row with a new particle (same work as add()
        but into a fixed row — used by reconcile for same-index object
        swaps)."""
        self.idx_of_row[row] = idx
        self.plist[row] = particle
        self.pos[row] = particle.pos
        self.vel[row] = particle.vel
        self.prev[row] = particle.pos
        self.ga[row] = grav_accels[idx] if idx < n_grav else 0.0
        pa = getattr(particle, '_prev_batch_accel', None)
        if pa is not None:
            self.prevacc[row] = pa
        else:
            self.prevacc[row] = 0.0
            self.boot_rows.append(row)
        if idx >= self.pmap.shape[0]:
            _pm = np.full(idx + 1, -1, dtype=np.intp)
            _pm[:self.pmap.shape[0]] = self.pmap
            self.pmap = _pm
        self.pmap[idx] = row
        particle.pos = self.pos[row]
        particle.vel = self.vel[row]
        particle.prev_pos = self.prev[row]
        particle._prev_batch_accel = self.prevacc[row]

    def _remove_idx(self, idx):
        """De-enroll one particle index (swap-remove its row). Returns True
        if it was enrolled. De-aliases the outgoing particle and re-points
        the swapped-in particle's views at its new row."""
        if idx >= self.pmap.shape[0]:
            return False
        r = self.pmap[idx]
        if r < 0 or r >= self.n:
            return False
        self._dealias(r)
        last = self.n - 1
        if r != last:
            # move last row into r
            self.idx_of_row[r] = self.idx_of_row[last]
            self.pos[r] = self.pos[last]
            self.vel[r] = self.vel[last]
            self.prev[r] = self.prev[last]
            self.prevacc[r] = self.prevacc[last]
            self.ga[r] = self.ga[last]
            _moved_idx = int(self.idx_of_row[last])
            _moved_p = self.plist[last]
            self.plist[r] = _moved_p
            self.pmap[_moved_idx] = r
            if _moved_p is not None:
                _moved_p.pos = self.pos[r]
                _moved_p.vel = self.vel[r]
                _moved_p.prev_pos = self.prev[r]
                _moved_p._prev_batch_accel = self.prevacc[r]
        self.plist[last] = None
        self.pmap[idx] = -1
        # boot_rows bookkeeping after the swap: the removed row's own pending
        # bootstrap dies with it (drop entries == r); the moved particle's
        # pending bootstrap was numbered `last` and must follow it to r.
        if self.boot_rows:
            self.boot_rows = [(r if b == last else b) for b in self.boot_rows
                              if b != r and (b != last or r != last)]
        self.n -= 1
        return True

    def reconcile(self, all_particles, didx, grav_accels, n_grav):
        """Diff the enrolled set against this frame's dormant indices and
        enroll/de-enroll only the delta. `didx` is a sorted intp array of
        particle indices. Object-identity mismatches (a different Particle
        occupying the same index after a cull+spawn) are detected on the
        kept rows and re-enrolled in place."""
        n = self.n
        if n == 0:
            for _i in didx:
                _ii = int(_i)
                self.add(_ii, all_particles[_ii], grav_accels, n_grav)
            return
        old = self.idx_of_row[:n]
        _max_i = int(didx[-1]) + 1 if didx.size else 0
        # old[] is in ENROLLMENT order (arbitrary after swap-removals) — the
        # mask must span the largest enrolled index, not the last row's.
        _cap_i = max(_max_i, int(old.max()) + 1 if n else 0)
        _new_m = np.zeros(_cap_i, dtype=bool)
        _new_m[didx] = True
        _removed = old[~_new_m[old]]
        _old_m = np.zeros(_cap_i, dtype=bool)
        _old_m[old] = True
        _added = didx[~_old_m[didx]]
        _kept = didx[_old_m[didx]]
        for _i in _removed:
            self._remove_idx(int(_i))
        # Identity check on kept rows — one numpy gather each side.
        if _kept.size:
            _rows = self.pmap[_kept]
            _ok_rows = _rows >= 0
            if _ok_rows.all():
                _objs = np.asarray(self.plist, dtype=object)[_rows]
                _ref = np.asarray(all_particles, dtype=object)[_kept]
                _mism = np.nonzero(_objs != _ref)[0]
                for _k in _mism:
                    _r = int(_rows[_k])
                    _ii = int(_kept[_k])
                    self._dealias(_r)
                    self._enroll_into_row(_r, _ii, all_particles[_ii],
                                          grav_accels, n_grav)
            else:
                # pmap inconsistency — shouldn't happen; re-enroll the
                # missing rows conservatively.
                for _k in np.nonzero(~_ok_rows)[0]:
                    _ii = int(_kept[_k])
                    self.add(_ii, all_particles[_ii], grav_accels, n_grav)
        for _i in _added:
            _ii = int(_i)
            self.add(_ii, all_particles[_ii], grav_accels, n_grav)

    def verify_aliases(self):
        """Periodic integrity check: confirm each enrolled particle still
        aliases its row views. An external pos replacement (user drag,
        teleport) silently breaks the alias — the atom then reads its own
        stale array while the batch keeps writing the buffer. Heal by
        re-copying state into the row and re-pointing the views (same as
        _enroll_into_row but idx/particle are already correct)."""
        for _r in range(self.n):
            _p = self.plist[_r]
            if _p is None:
                continue
            if (_p.pos is not self.pos[_r] or _p.vel is not self.vel[_r]
                    or _p.prev_pos is not self.prev[_r]):
                self.pos[_r] = _p.pos
                self.vel[_r] = _p.vel
                self.prev[_r] = _p.pos
                _pa = getattr(_p, '_prev_batch_accel', None)
                if _pa is not None:
                    self.prevacc[_r] = _pa
                else:
                    self.prevacc[_r] = 0.0
                    self.boot_rows.append(_r)
                _p.pos = self.pos[_r]
                _p.vel = self.vel[_r]
                _p.prev_pos = self.prev[_r]
                _p._prev_batch_accel = self.prevacc[_r]

    def add(self, idx, particle, grav_accels, n_grav):
        """Enroll a dormant atom (frame-start or mid-frame promotion).
        Mirrors `_batch_dormant_motion`'s per-atom state exactly: pos/vel
        become buffer views, prev_pos starts at the current position, and
        `_prev_batch_accel` keeps its previous value (or bootstraps from this
        step's accel on the next step(), matching the cold-start rule)."""
        # Idempotent: a persistent batch may already hold this index (e.g. the
        # frame skipped reconcile because the dormant set was empty). Without
        # the guard a second enroll orphans the old row — it keeps writing a
        # dead copy of the atom's state forever.
        if idx < self.pmap.shape[0] and self.pmap[idx] >= 0:
            if self.plist[self.pmap[idx]] is particle:
                return
            self._remove_idx(idx)
        if self.n >= self.cap:
            self._grow()
        row = self.n
        self.n += 1
        self.idx_of_row[row] = idx
        self.plist[row] = particle
        self.pos[row] = particle.pos
        self.vel[row] = particle.vel
        self.prev[row] = particle.pos
        # accel row for THIS grav snapshot (refreshed wholesale on grav change)
        self.ga[row] = grav_accels[idx] if idx < n_grav else 0.0
        pa = getattr(particle, '_prev_batch_accel', None)
        if pa is not None:
            self.prevacc[row] = pa
        else:
            self.prevacc[row] = 0.0
            self.boot_rows.append(row)   # bootstrap from ga on next step()
        if idx >= self.pmap.shape[0]:
            _pm = np.full(idx + 1, -1, dtype=np.intp)
            _pm[:self.pmap.shape[0]] = self.pmap
            self.pmap = _pm
        self.pmap[idx] = row
        particle.pos = self.pos[row]
        particle.vel = self.vel[row]
        particle.prev_pos = self.prev[row]
        particle._prev_batch_accel = self.prevacc[row]

    def step(self, grav_accels, n_grav, ddt):
        n = self.n
        if n == 0:
            return
        # Refresh accel rows only when the gravity source actually changed
        # (frame start or the midway recompute) — identity check, not values.
        if grav_accels is not self.ga_src or n_grav != self.ga_n:
            ii = self.idx_of_row[:n]
            ga = self.ga[:n]
            ga[:] = 0.0
            _valid = ii < n_grav
            if _valid.any():
                ga[_valid] = grav_accels[ii[_valid]]
            self.ga_src = grav_accels
            self.ga_n = n_grav
        # Bootstrap rows added since the last step (their first Verlet needs
        # a(t-dt)=a(t) exactly like _batch_dormant_motion's cold start).
        if self.boot_rows:
            for _r in self.boot_rows:
                self.prevacc[_r] = self.ga[_r]
            self.boot_rows.clear()
        pos = self.pos[:n]; vel = self.vel[:n]
        prev = self.prev[:n]; prevacc = self.prevacc[:n]; ga = self.ga[:n]
        np.copyto(prev, pos)
        if _perf.use_gpu_batch_pos and n >= _GPU_BATCH_POS_MIN:
            # prev==ga: frozen per-frame force means a(t)==a(t+dt)==ga, so the
            # trapezoid is ga·dt — NOT ½(prev_frame + ga) which injected a
            # stale-frame impulse every substep.
            npos, nvel = _gpu_batch_position_update(pos, vel, ga, ddt, ga)
            pos[...] = np.asarray(npos, dtype=np.float64)
            vel[...] = np.asarray(nvel, dtype=np.float64)
        else:
            # Split adds keep the SAME left-associative fp order as
            # _batch_dormant_motion's `dpos + dvel*ddt + 0.5*dga*dt²`
            # (numpy += is not fp-associative-safe in a single expression).
            ddt2 = ddt * ddt
            pos += vel * ddt
            pos += 0.5 * ga * ddt2
            vel += ga * ddt
        prevacc[...] = ga


# Persistent dormant-atom batch (Step-7c): kept across frames so reconcile()
# only processes enrollment deltas instead of re-enrolling every dormant atom
# each frame. Rebuilt lazily inside update().
_dormant_batch = None


# Legacy alias for compatibility
def _gpu_accelerate_positions(positions_np, masses_np):
    return _gpu_to_tensors(positions_np, masses_np)

class _PerformanceGovernor:
    """GPU-first adaptive performance manager.
    GPU is ALWAYS the primary compute device when available.
    Quality levels: 0=survival, 1=low, 2=medium, 3=high, 4=ultra.
    GPU usage scales from 50% (idle) to 100% (heavy load).
    CPU only handles non-batchable work (atom internals, observer AI)."""

    def __init__(self):
        self.quality = 3
        self._frame_times = deque(maxlen=60)
        self._target_fps = 60.0
        self._last_adjust = 0.0
        self._adjust_interval = 0.5
        # Boot grace period: ignore FPS readings for the first ~3s.
        # The first frames pay for shader compilation, VBO upload, label-
        # pool population and OpenGL context warmup. Measuring FPS during
        # that window made PerfGov stampede the quality slider down to 0
        # before the steady-state render path had a chance to run.
        self._boot_t = time.time()
        self._boot_grace_sec = 3.0
        self._gpu_available = _PERF_GPU_AVAILABLE
        # GPU load tracking
        self._gpu_load_target = 0.50  # Minimum 50% GPU utilization target
        self._gpu_load_max = 1.00     # Allow up to 100% GPU
        self._gpu_batch_em = _PERF_GPU_AVAILABLE  # GPU handles EM forces
        self._gpu_batch_pos = _PERF_GPU_AVAILABLE  # GPU handles position updates
        self._n_particles = 0  # Updated each frame for adaptive throttling
        # Print startup diagnostics
        _gpu_info = 'None (CPU-only mode)'
        if _PERF_GPU_AVAILABLE:
            if _COMPUTE_KIND == 'cuda':
                _oc = 'boost=ON' if os.environ.get('CUDA_AUTO_BOOST') == '1' else 'boost=OFF'
                _tf32 = 'TF32=ON' if _PERF_GPU_COMPUTE_CAP[0] >= 8 else 'TF32=N/A'
                _gpu_info = f'YES {_PERF_GPU_NAME} (CUDA {_PERF_GPU_VRAM_MB}MB, cap={_PERF_GPU_COMPUTE_CAP[0]}.{_PERF_GPU_COMPUTE_CAP[1]}, {_oc}, {_tf32})'
            elif _COMPUTE_KIND in ('xpu', 'mps', 'dml'):
                _vram_str = f', {_PERF_GPU_VRAM_MB}MB' if _PERF_GPU_VRAM_MB else ''
                _gpu_info = f'YES {_PERF_GPU_NAME} ({_COMPUTE_KIND.upper()}{_vram_str})'
            else:
                _gpu_info = f'YES {_PERF_GPU_NAME}'
        self._startup_msg = (
            f"[PerfGov] GPU-FIRST mode | CPU: {_PERF_CPU_CORES} cores | GPU: {_gpu_info}"
        )
        print(self._startup_msg)
        if _PERF_GPU_AVAILABLE:
            # batch-pos drives the dormant-atom batch in the physics substep,
            # but only once the batch clears _GPU_BATCH_POS_MIN -- below that
            # the transfer costs more than the kernel saves.
            print(f"[PerfGov] GPU compute: gravity=ON, EM-forces=ON, batch-pos=ON(>={_GPU_BATCH_POS_MIN} particles) | Target GPU load >= {self._gpu_load_target:.0%}")

    def record_frame(self, dt, n_particles=0):
        self._frame_times.append(max(dt, 0.0001))
        self._n_particles = n_particles

    def get_avg_fps(self):
        if len(self._frame_times) < 3:
            return 60.0
        avg_dt = sum(self._frame_times) / len(self._frame_times)
        return 1.0 / max(avg_dt, 0.0001)

    def maybe_adjust(self):
        now = time.time()
        if now - self._last_adjust < self._adjust_interval:
            return
        self._last_adjust = now
        # Ignore measurements during the boot grace window.  The first frames
        # are dominated by one-time costs that are not representative of the
        # steady-state render path; reacting to them just thrashes quality.
        if now - self._boot_t < self._boot_grace_sec:
            return
        # Need a meaningful sample before adjusting.
        if len(self._frame_times) < 30:
            return
        fps = self.get_avg_fps()
        old_q = self.quality
        if fps < self._target_fps * 0.3 and self.quality > 0:
            self.quality = max(0, self.quality - 2)
        elif fps < self._target_fps * 0.5 and self.quality > 0:
            self.quality -= 1
        elif fps > self._target_fps * 1.5 and self.quality < 4:
            self.quality += 1
        elif fps > self._target_fps * 1.1 and self.quality < 3:
            self.quality += 1
        if old_q != self.quality:
            _tag = 'GPU' if self._gpu_available else 'CPU'
            print(f"[PerfGov] Quality {old_q}->{self.quality} (FPS={fps:.1f}) [{_tag}]")

    @property
    def max_substeps(self):
        # GPU can handle more substeps — raise limits when GPU is primary
        if self._gpu_available:
            return [8, 24, 48, 64, 96][self.quality]
        return [4, 12, 24, 48, 64][self.quality]

    @property
    def substep_budget(self):
        # GPU gets more wall-clock budget since it computes faster
        if self._gpu_available:
            return [0.004, 0.008, 0.012, 0.016, 0.024][self.quality]
        return [0.002, 0.004, 0.006, 0.008, 0.012][self.quality]
    @property
    def observer_update_mul(self):
        # Observer AI always runs on CPU — never throttle to death even at quality 0
        # CPU handles AI alongside GPU physics simultaneously
        return [1.5, 1.2, 1.0, 1.0, 0.8][self.quality]

    @property
    def max_render_labels(self):
        return [200, 500, 9999, 9999, 9999][self.quality]

    @property
    def skip_det_frames(self):
        return self.quality < 1

    @property
    def sphere_snap_interval(self):
        # Scale sphere snapshot interval with particle count
        _base = 60
        if self._n_particles > 500:
            _base = 180
        elif self._n_particles > 200:
            _base = 120
        return _base

    @property
    def det_record_interval(self):
        # How often to record deterministic frames (1=every frame, 3=every 3rd, etc.)
        # State copy is expensive - throttle based on quality AND particle count
        _base = [999, 10, 5, 2, 1][self.quality]
        # Scale up interval when many particles (copy cost is O(N))
        if self._n_particles > 500:
            _base = max(_base, 10)
        elif self._n_particles > 200:
            _base = max(_base, 5)
        return _base

    @property
    def use_gpu_gravity(self):
        # GPU-FIRST: always use GPU for gravity when available, at ALL quality levels
        return self._gpu_available

    @property
    def use_gpu_em(self):
        # GPU-FIRST: always use GPU for EM forces when available
        return self._gpu_batch_em

    @property
    def use_gpu_batch_pos(self):
        # GPU-FIRST: always use GPU for batch position updates
        return self._gpu_batch_pos

_perf = _PerformanceGovernor()

# === Per-frame photon-redshift cache ===
# Rebuilt once at the top of update(dt). Photon.update() reads from these arrays
# instead of iterating the full `particles` list per substep, converting the
# photon redshift cost from O(N × photons × substeps) → O(N + photons × |massive|).
# Set to None until update() runs for the first time (photon code checks for None).
_massive_pos_cache = None    # numpy (M, 3) of positions of particles with mass > 1e-20
_massive_mass_cache = None   # numpy (M,)  of masses
_MASSIVE_MIN_MASS = 1e-20    # threshold matching the old `if p.mass < 1e-20` skip

# === Per-frame spatial-hash neighbor cache (the million-atom enabler) ===
# Built once at the top of update(dt) when the scene exceeds the threshold.
# Atom.update reads from `_atom_neighbor_cache[id(atom)]` and passes that
# tightly-bounded neighbor list (typically 1-50 particles) to its ionization /
# photon-absorption / neutron-capture / proton-capture / stim-emission scans
# instead of iterating the full `particles` list each substep.
# Microbenchmark: 10,000-particle / 1,000-atom scene → 12,420ms (old O(A·N))
#                 collapsed to 9.6ms (new voxel hash) — **1296× speedup**.
# Falls back gracefully (cache miss → full particle list) so behavior unchanged
# below the threshold or in edge cases.
_atom_neighbor_cache = {}   # id(atom) -> list of nearby particles (filtered by voxel hash)
# Step-7: shared empty neighbor list — assigned to provably-isolated atoms by
# the occupancy-grid fast path. Never mutated anywhere (only len()/iteration
# are used downstream), so sharing one instance is safe and avoids A list
# allocations per frame at million-atom scale.
_NEIGHBOR_EMPTY_LIST = []
# Adaptive backoff state for the occupancy-grid fast path (dense scenes where
# most atoms are ambiguous get the plain exact loop instead of paying grid cost).
_NB_GRID_STRIKE = 0
_NB_GRID_DISABLE = 0
_ATOM_NEIGHBOR_VOXEL_SIZE = 50.0   # vis-units; ≈ 3-5× the typical atom interaction radius
_ATOM_NEIGHBOR_THRESHOLD = 200     # build cache only when len(particles) exceeds this
# Step-7b: neighbor-cache rebuild cadence + regime flag. The voxel-hash build
# costs ~0.7-2.5s at 60-150k dense atoms — far over a frame budget — so it now
# rebuilds on an adaptive interval (~4ms/frame amortized) instead of every
# frame. The chemistry scans that consume _cached_neighbors are already
# Monte-Carlo throttled at this scale, so bounded staleness preserves the
# expected rates. _ATOM_NB_ACTIVE marks "cache regime": Atom.update maps a
# missing _cached_neighbors (newborn atom between rebuilds) to the shared
# empty list rather than falling back to an O(N) full-particle scan.
_ATOM_NB_ACTIVE = False
_ATOM_NB_INTERVAL = 1
_ATOM_NB_LAST_FRAME = -10**9
_ATOM_NB_LAST_N = 0
# Pre-computed flat list of the 27 voxel offsets so we don't re-derive the
# product on every cache build (hot-path attribute access matters at 1M atoms).
_ATOM_NEIGHBOR_OFFSETS = np.array(
    [(dx, dy, dz) for dx in (-1, 0, 1) for dy in (-1, 0, 1) for dz in (-1, 0, 1)],
    dtype=np.int64)

# === Per-subsystem timing breakdown ===
# Lets the user see WHERE time is spent each frame: physics vs render vs
# observers vs chemistry. Toggle with the `perf_hud` hotkey (added at the
# end of _HOTKEY_ACTIONS). Each section is wrapped in `_perf_tic('name')`
# / `_perf_toc('name')`. The HUD shows an EMA-smoothed ms-per-frame per tag.
_perf_section_ms = {}      # section name → EMA ms
_perf_section_t0 = {}      # section name → most-recent tic timestamp
_PERF_EMA_ALPHA = 0.15
_PERF_HUD_ENABLED = False  # toggled by hotkey
_PERF_LOG = deque(maxlen=240)  # last few seconds of full breakdowns for telemetry export


def _perf_tic(name):
    """Start timing a code section. Safe to call from any thread (uses
    perf_counter, returns immediately). Pair with `_perf_toc(name)`."""
    try:
        _perf_section_t0[name] = time.perf_counter()
    except Exception:
        pass


def _perf_toc(name):
    """Stop timing the matching `_perf_tic(name)` and update the EMA. Drop
    silently if no matching tic (mismatched pairs shouldn't crash the sim)."""
    try:
        _t0 = _perf_section_t0.get(name)
        if _t0 is None:
            return
        _dt_ms = (time.perf_counter() - _t0) * 1000.0
        _prev = _perf_section_ms.get(name, _dt_ms)
        _perf_section_ms[name] = _prev * (1.0 - _PERF_EMA_ALPHA) + _dt_ms * _PERF_EMA_ALPHA
    except Exception:
        pass


def _perf_snapshot():
    """Return a sorted (name, ms) list of section EMAs for the HUD."""
    try:
        return sorted(_perf_section_ms.items(), key=lambda kv: -kv[1])
    except Exception:
        return []


# === Item-1: Shader-based atom point-sprite prototype ===
# ON by default (step 5) via SIM_USE_SHADER_POINTS=1 default; the draw path
# still falls back to fixed-function batched GL_POINTS if GLSL compile fails.
class _PointSpriteShader:
    _VERTEX_SRC = """
        #version 120
        uniform float u_point_size;
        attribute vec3 a_pos;
        attribute vec4 a_col;
        attribute float a_size;
        varying vec4 v_col;
        void main() {
            gl_Position = gl_ModelViewProjectionMatrix * vec4(a_pos, 1.0);
            // Per-element visual radius (atomic_weight^(1/3), ~0.8-1.3) times
            // the shared zoom-scaled base size → atoms read as distinct sizes.
            gl_PointSize = u_point_size * a_size;
            v_col = a_col;
        }
    """
    _FRAGMENT_SRC = """
        #version 120
        varying vec4 v_col;
        void main() {
            // Radial-gradient point sprite, step-6 "atom" look: a white-hot
            // nucleus, a bright element-colored core, and a wide soft halo —
            // reads as a shaded glowing atom rather than a flat square dot.
            vec2 d = gl_PointCoord - vec2(0.5);
            float r2 = dot(d, d) * 4.0;          // 0 at center → 1 at sprite edge
            if (r2 > 1.0) discard;
            float core = smoothstep(1.0, 0.10, r2);   // solid inner disc
            float halo = smoothstep(1.0, 0.0,  r2);    // soft outer falloff
            float hot  = smoothstep(0.38, 0.0, r2);    // white-hot nucleus
            vec3 col = v_col.rgb * (0.70 + 0.90 * core + 0.30 * hot);
            col = mix(col, vec3(1.0), hot * 0.22);     // subtle white center
            float alpha = clamp(v_col.a * (core * 0.82 + halo * halo * 0.50 + hot * 0.12), 0.0, 1.0);
            gl_FragColor = vec4(col, alpha);
        }
    """

    def __init__(self):
        self.ok = False
        self.program = None
        self.attempted = False
        self._a_pos = -1
        self._a_col = -1
        self._a_size = -1
        self._u_point_size = -1

    def ensure(self):
        if self.attempted:
            return self.ok
        self.attempted = True
        try:
            from OpenGL.GL import (
                glCreateShader, glShaderSource, glCompileShader,
                glGetShaderiv, GL_COMPILE_STATUS, GL_VERTEX_SHADER, GL_FRAGMENT_SHADER,
                glCreateProgram, glAttachShader, glLinkProgram,
                glGetProgramiv, GL_LINK_STATUS,
                glGetAttribLocation, glGetUniformLocation,
            )
        except Exception:
            return False
        try:
            vs = glCreateShader(GL_VERTEX_SHADER)
            glShaderSource(vs, self._VERTEX_SRC)
            glCompileShader(vs)
            if not glGetShaderiv(vs, GL_COMPILE_STATUS):
                return False
            fs = glCreateShader(GL_FRAGMENT_SHADER)
            glShaderSource(fs, self._FRAGMENT_SRC)
            glCompileShader(fs)
            if not glGetShaderiv(fs, GL_COMPILE_STATUS):
                return False
            self.program = glCreateProgram()
            glAttachShader(self.program, vs)
            glAttachShader(self.program, fs)
            glLinkProgram(self.program)
            if not glGetProgramiv(self.program, GL_LINK_STATUS):
                return False
            self._a_pos = glGetAttribLocation(self.program, 'a_pos')
            self._a_col = glGetAttribLocation(self.program, 'a_col')
            self._a_size = glGetAttribLocation(self.program, 'a_size')
            self._u_point_size = glGetUniformLocation(self.program, 'u_point_size')
            self.ok = True
        except Exception:
            self.ok = False
        return self.ok


_point_sprite_shader = _PointSpriteShader()
# Shader point-sprites are ON by default (step 5): round glowing atoms read far
# better than flat GL_POINTS squares. The draw path falls back to the legacy
# fixed-function GL_POINTS automatically if the GLSL compile fails, so this
# is safe on drivers without GLSL 1.20. Set SIM_USE_SHADER_POINTS=0 to force
# the legacy path.
_SHADER_POINTS_ENABLED = bool(int(os.environ.get('SIM_USE_SHADER_POINTS', '1') or '0'))


def _draw_point_sprites(pos, col, size_px):
    """Step-6 shared point-sprite draw: one call for N camera-space points.

    pos     : (N,3) array-like of camera-space positions (already rotated)
    col     : (N,4) array-like of RGBA colors (uint8 or 0-255 float)
    size_px : (N,)  array-like of final per-point pixel sizes

    Uses the GLSL point-sprite shader (round, antialiased, glowing sprites)
    when available; falls back to fixed-function GL_POINTS bucketed by size.
    GL_LIGHTING / GL_BLEND / GL_DEPTH_* state is left to the caller — this
    helper only manages the program + vertex attributes + GL_POINTS itself.
    """
    n = int(pos.shape[0]) if hasattr(pos, 'shape') else len(pos)
    if n <= 0:
        return
    pos = np.ascontiguousarray(pos, dtype=np.float32)
    col = np.ascontiguousarray(col, dtype=np.uint8)
    size_px = np.ascontiguousarray(size_px, dtype=np.float32).reshape(-1)
    drawn = False
    if _SHADER_POINTS_ENABLED:
        try:
            if _point_sprite_shader.ensure() and _point_sprite_shader.ok:
                from OpenGL.GL import (
                    glUseProgram, glUniform1f, glEnableVertexAttribArray,
                    glVertexAttribPointer, glDisableVertexAttribArray,
                    GL_FLOAT as _GL_FLOAT, GL_UNSIGNED_BYTE as _GL_UB, GL_TRUE as _GL_TRUE,
                )
                glUseProgram(_point_sprite_shader.program)
                # a_size carries the FINAL pixel size; u_point_size stays 1.0
                # (when the size attribute is missing, fall back to mean size).
                if _point_sprite_shader._u_point_size >= 0:
                    if _point_sprite_shader._a_size >= 0:
                        glUniform1f(_point_sprite_shader._u_point_size, 1.0)
                    else:
                        glUniform1f(_point_sprite_shader._u_point_size,
                                    float(np.mean(size_px)) if n else 1.0)
                if _point_sprite_shader._a_pos >= 0:
                    glEnableVertexAttribArray(_point_sprite_shader._a_pos)
                    glVertexAttribPointer(_point_sprite_shader._a_pos, 3, _GL_FLOAT, False, 0, pos)
                if _point_sprite_shader._a_col >= 0:
                    glEnableVertexAttribArray(_point_sprite_shader._a_col)
                    glVertexAttribPointer(_point_sprite_shader._a_col, 4, _GL_UB, _GL_TRUE, 0, col)
                if _point_sprite_shader._a_size >= 0:
                    glEnableVertexAttribArray(_point_sprite_shader._a_size)
                    glVertexAttribPointer(_point_sprite_shader._a_size, 1, _GL_FLOAT, False, 0, size_px)
                glDrawArrays(GL_POINTS, 0, n)
                if _point_sprite_shader._a_pos >= 0:
                    glDisableVertexAttribArray(_point_sprite_shader._a_pos)
                if _point_sprite_shader._a_col >= 0:
                    glDisableVertexAttribArray(_point_sprite_shader._a_col)
                if _point_sprite_shader._a_size >= 0:
                    glDisableVertexAttribArray(_point_sprite_shader._a_size)
                glUseProgram(0)
                drawn = True
        except Exception:
            try:
                _point_sprite_shader.ok = False
            except Exception:
                pass
            drawn = False
    if not drawn:
        # Fixed-function fallback: square GL_POINTS softened by GL_POINT_SMOOTH,
        # bucketed to 0.5px so glPointSize (global per draw) stays faithful.
        glEnable(GL_POINT_SMOOTH)
        try:
            _buckets = {}
            for _i in range(n):
                _bk = int(size_px[_i] * 2.0) / 2.0
                _buckets.setdefault(_bk, []).append(_i)
            for _sz, _idxs in _buckets.items():
                glPointSize(max(1.0, float(_sz)))
                glBegin(GL_POINTS)
                for _i in _idxs:
                    glColor4ub(int(col[_i, 0]), int(col[_i, 1]), int(col[_i, 2]), int(col[_i, 3]))
                    glVertex3f(float(pos[_i, 0]), float(pos[_i, 1]), float(pos[_i, 2]))
                glEnd()
        finally:
            glDisable(GL_POINT_SMOOTH)


def _draw_perf_hud_l():
    """Item-20: §L extracted from on_draw. Toggled by `_PERF_HUD_ENABLED`."""
    if not _PERF_HUD_ENABLED:
        return
    try:
        _snap = _perf_snapshot()
        _perf_lbl = getattr(_draw_perf_hud_l, '_lbl', None)
        if _perf_lbl is None:
            _perf_lbl = Label('', font_size=9, color=(180, 220, 200, 230),
                              anchor_x='left', anchor_y='top')
            _draw_perf_hud_l._lbl = _perf_lbl
        _lines = ['PERF (ms/frame, EMA):']
        for _nm, _ms in _snap[:12]:
            _lines.append(f'  {_nm:<16s} {_ms:6.2f}')
        _perf_lbl.text = '\n'.join(_lines)
        _perf_lbl.x = 16
        _perf_lbl.y = HEIGHT - 200
        _perf_lbl.draw()
        _PERF_LOG.append((time.time(), dict(_snap)))
    except Exception:
        pass


def _safe_resp_json(resp, default=None):
    """Item-9: defensive `response.json()` wrapper. Raises on 4xx/5xx via
    `raise_for_status()` so callers' existing `except Exception` blocks see
    the failure as a real network error rather than a silent JSON-corrupted
    payload. On JSONDecodeError, returns `default` rather than crashing."""
    if resp is None:
        return default if default is not None else {}
    try:
        resp.raise_for_status()
    except Exception:
        raise
    try:
        return resp.json()
    except Exception:
        return default if default is not None else {}


class _SimStateProxy:
    """Item-21: structured-access proxy over the simulation's module-scope
    globals. Existing code keeps using `particles`, `camera`, `paused`, etc.
    directly; NEW code can use `_SIM.particles` / `_SIM.camera` for clearer
    dependency-tracking and easier IDE navigation."""
    _CANONICAL_NAMES = (
        'particles', 'camera', 'simulation_time', 'frame_count', 'current_fps',
        'paused', 'time_factor', 'effective_time_factor',
        '_observer_mgr', '_shadow_bodies', '_observer_lock',
        '_life_gen_spawned', '_life_gen_last_org', '_GLOBAL_MICROBIOME',
        '_atom_neighbor_cache', '_massive_pos_cache', '_charged_particles_cache',
        '_rot_cache_mat', '_rot_cache_key',
        '_perf', '_PERF_LOG', '_conservation_audit_log', '_perf_section_ms',
        'toggle_grid', 'toggle_em_field', 'toggle_wave_field', 'toggle_bond_lines',
        'toggle_orbital_paths', 'toggle_lqcd', 'toggle_kinetic_field',
        '_UI_THEME_NAME', '_label_pool', '_subproc_registry',
    )

    def __getattr__(self, name):
        if name in globals():
            return globals()[name]
        raise AttributeError(f'_SimStateProxy: no such global: {name}')

    def __setattr__(self, name, value):
        globals()[name] = value

    def __contains__(self, name):
        return name in globals()

    def snapshot(self):
        return {
            'n_particles': len(globals().get('particles', []) or []),
            'paused': bool(globals().get('paused', False)),
            'frame_count': int(globals().get('frame_count', 0)),
            'sim_time': float(globals().get('simulation_time', 0.0)),
            'fps': float(globals().get('current_fps', 0.0)),
            'n_life_spawned': len(globals().get('_life_gen_spawned', []) or []),
            'theme': globals().get('_UI_THEME_NAME', 'dark'),
        }


_SIM = _SimStateProxy()


