    def _load_hardcoded_artifacts():
        """100% inclusion: each artifact's full bytes are embedded above as zlib +
        base64 constants, so the knowledge lives inside CS.py itself — nothing is
        lost if the sidecar files are absent. Falls back to reading the file next
        to CS.py when a blob is missing. Images keep raw bytes in meta['data'];
        the markdown keeps decoded text in meta['text']."""
        import base64 as _b64, zlib as _z
        _embedded_blobs = {
            'user1_png': globals().get('_USER1_PNG_B64', ''),
            'user2_png': globals().get('_USER2_PNG_B64', ''),
            'as_png': globals().get('_AS_PNG_B64', ''),
            'multiverse_bubble_md': globals().get('_MULTIVERSE_MD_B64', ''),
            'cs_formula_refined_md': globals().get('_CS_FORMULA_REFINED_MD_B64', ''),
            'total_project_info_md': globals().get('_TOTAL_PROJECT_INFO_MD_B64', ''),
        }
        root = os.path.dirname(os.path.abspath(__file__))
        for name, meta in HARDCODED_ARTIFACTS.items():
            blob = None
            try:
                blob = _z.decompress(_b64.b64decode(_embedded_blobs.get(name, '')))
            except Exception:
                blob = None
            meta['embedded'] = blob is not None
            if blob is None:
                try:
                    with open(os.path.join(root, meta['file']), 'rb') as f:
                        blob = f.read()
                except OSError:
                    continue
            meta['present'] = True
            meta['bytes'] = len(blob)
            meta['sha256'] = hashlib.sha256(blob).hexdigest()
            if meta['kind'] == 'markdown':
                meta['text'] = blob.decode('utf-8', errors='ignore')
            else:
                meta['data'] = blob
        return HARDCODED_ARTIFACTS

    def hardcoded_artifact_image(name):
        """Return an embedded PNG artifact as a zero-loss PIL Image for any
        vision/ingestion path (e.g. ingest_real_visual); None if unavailable."""
        try:
            data = HARDCODED_ARTIFACTS.get(name, {}).get('data')
            if data is None:
                return None
            return Image.open(io.BytesIO(data))
        except Exception:
            return None

