    def regenerate_user2_png(path=None):
        """Re-render user2.png from USER2_PNG_SPEC — the corrected formal system —
        and refresh its HARDCODED_ARTIFACTS metadata. Deterministic layout: white
        sheet, monospace spec text, same structure as user1.png. Returns the path
        written, or None if matplotlib is unavailable."""
        try:
            import matplotlib
            matplotlib.use('Agg')
            import matplotlib.pyplot as plt
        except Exception:
            return None
        if path is None:
            path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                HARDCODED_ARTIFACTS['user2_png']['file'])
        fig = plt.figure(figsize=(13.5, 16), dpi=200)
        ax = fig.add_axes([0, 0, 1, 1])
        ax.set_xlim(0, 1); ax.set_ylim(0, 1); ax.axis('off')
        fig.patch.set_facecolor('white')
        y, dy = 0.985, 0.975 / len(USER2_PNG_SPEC)
        for text, kind in USER2_PNG_SPEC:
            kw = dict(family='DejaVu Sans Mono', va='top')
            if kind == 't':
                kw.update(fontsize=13.5, fontweight='bold', color='#7a0019')
            elif kind == 's':
                kw.update(fontsize=9.5, style='italic', color='#333333')
            elif kind == 'h':
                kw.update(fontsize=10.5, fontweight='bold', color='#0a3d91')
            else:
                kw.update(fontsize=9.5, color='#111111')
            ax.text(0.045, y, text, **kw)
            y -= dy
        fig.savefig(path, dpi=200, facecolor='white')
        plt.close(fig)
        try:
            with open(path, 'rb') as f:
                blob = f.read()
            meta = HARDCODED_ARTIFACTS['user2_png']
            meta.update(present=True, bytes=len(blob),
                        sha256=hashlib.sha256(blob).hexdigest(), data=blob)
        except Exception:
            pass
        return path

    _load_hardcoded_artifacts()
