    def _build_seed_instruction_pairs():
        """Seed (prompt, response) pairs for `train_on_instruction_pair`
        (workflow.md §3.1c item 2: "no instruction/RLHF tuning pipeline exists
        at any scale"). This is NOT RLHF — it's the supervised prompt->response
        scaffold that would need to exist before any preference-tuning step
        could be meaningful. Generated from `_CS_PHYSICS_LAWS`, `MATH_EQUATIONS`,
        and `KNOWLEDGE_LIBRARY`, all of which are fact-checked ground truth,
        rather than hand-authored text that could introduce new factual errors.
        Deliberately honest about being a seed set, not a corpus — but expanded
        ~10x over the prior physics-only seed to cover math, chemistry, biology,
        CS, information theory, and consciousness science."""
        pairs = []
        for key, law in _CS_PHYSICS_LAWS.items():
            name = key.replace('_', ' ')
            pairs.append((f"What is {name}?", law['desc']))
            pairs.append((f"Explain {name}.", law['desc']))
        for key, eq in MATH_EQUATIONS.items():
            name = key.replace('_', ' ')
            desc = eq['desc'] if isinstance(eq, dict) else str(eq)
            pairs.append((f"What is {name}?", desc))
            pairs.append((f"Explain {name}.", desc))
        for question, answer in KNOWLEDGE_LIBRARY:
            pairs.append((question, answer))
        pairs.append(("What is consciousness in this system?",
                       "Consciousness here is measured as C = S + E + R * A, a formula "
                       "combining self-awareness, experience, resonance, and attention."))
        pairs.append(("What is Omega in this project?",
                       "Omega is the accumulated closure of the growth operator Phi applied "
                       "infinitely to the void, formalizing something-from-nothing as real "
                       "set-theoretic structure, not a physical claim."))
        return pairs

    INSTRUCTION_PAIRS = _build_seed_instruction_pairs()

    # =============================================================================
    # SUBWORD TOKENIZER - BPE (replaces hash-based simple_tokenizer)
    # Falls back to hash-based tokenizer if 'tokenizers' package is not installed.
    # =============================================================================
    # =============================================================================
    # MODERN TRANSFORMER STACK — RoPE + RMSNorm + SwiGLU + GQA
    # =============================================================================
    # WHY THIS EXISTS (ratings.md §D): most of CS.py's gap vs frontier models is
    # raw scale — 113M params vs 175B-2T — and no code change closes that. But
    # scale is not the WHOLE gap. The stack this replaces was
    # `nn.TransformerEncoderLayer`: multi-head attention + GELU MLP + LayerNorm +
    # sinusoidal absolute position + dropout 0.1. That is the 2017 "Attention Is
    # All You Need" design. Every frontier model since ~2022 (Llama, PaLM,
    # Mistral, and by all published indication the GPT-4/Claude/Gemini class)
    # replaced all four of those components, because each is a strictly better
    # quality-per-parameter choice:
    #
    #   sinusoidal absolute PE -> RoPE     (rotary; encodes RELATIVE position,
    #                                       generalises past trained length)
    #   LayerNorm              -> RMSNorm  (no mean-centering/bias: fewer ops,
    #                                       no measured quality loss)
    #   GELU MLP (2 matrices)  -> SwiGLU   (gated, 3 matrices at 2/3 width —
    #                                       same parameter budget, better loss)
    #   MHA (n_kv == n_head)   -> GQA      (grouped KV: fewer K/V params and a
    #                                       far smaller KV cache at generation)
    #   dropout 0.1            -> 0.0      (large-scale LM pretraining does not
    #                                       use dropout; it fights the objective
    #                                       when data >> parameters)
    #
    # These are ALL scale-independent. A 113M-parameter model with this stack
    # and a 113M-parameter model with the old one have the same budget — the
    # difference is what that budget buys. This is precisely the "if they were
    # the same size, what would the rating be" question, and it is the one part
    # of the frontier gap that IS closeable in code.
    #
    # HONESTY: this does not make CS.py competitive on general benchmarks. That
    # still requires training tokens it has not seen (ratings.md §A). It closes
    # an ARCHITECTURAL gap, not a scale or data gap, and the A/B in ratings.md
    # §D2 measures exactly how much — no more.

    class RMSNorm(nn.Module):
        """Root-mean-square layer norm (Zhang & Sennrich 2019).

        LayerNorm subtracts the mean and learns a bias; RMSNorm does neither.
        Published result, reproduced across every major open LLM since Llama-1:
        the mean-centering and bias contribute nothing measurable to quality
        while costing operations on every token of every layer. Fewer parameters
        (no bias) and fewer ops for equal loss is a free win at any scale.
        """

        def __init__(self, dim, eps=1e-6):
            super().__init__()
            self.eps = eps
            self.weight = nn.Parameter(torch.ones(dim))

        def forward(self, x):
            # float32 for the reduction regardless of autocast dtype: the
            # reciprocal-sqrt of a mean of squares is numerically fragile in
            # fp16/bf16 and this is cheap insurance against silent NaNs.
            dtype = x.dtype
            x32 = x.float()
            norm = x32 * torch.rsqrt(x32.pow(2).mean(-1, keepdim=True) + self.eps)
            return (norm.to(dtype)) * self.weight


    class RotaryEmbedding(nn.Module):
        """RoPE (Su et al. 2021) — rotates q/k by position-dependent angles.

        Absolute sinusoidal encoding ADDS a position signal to the token
        embedding, so the model must learn to disentangle "what this token is"
        from "where it sits". RoPE instead rotates the query/key vectors, which
        makes the attention dot-product depend on the RELATIVE offset (i-j)
        directly. Two consequences that matter here:

          1. It is the reason modern models extrapolate beyond their trained
             context length at all. Absolute PE past `max_len` is undefined;
             a rotation is defined at every position.
          2. It costs ZERO parameters — it is a fixed geometric transform,
             same as the sinusoidal buffer it replaces.

        `base` (theta) 10000 is the standard value; raising it is the usual
        context-extension trick, which is why this is the component that makes
        a longer context window reachable later without retraining from zero.
        """

        def __init__(self, head_dim, max_seq=8192, base=10000.0):
            super().__init__()
            self.head_dim = head_dim
            self.base = base
            inv_freq = 1.0 / (base ** (torch.arange(0, head_dim, 2).float() / head_dim))
            self.register_buffer('inv_freq', inv_freq, persistent=False)
            self._cached_len = 0
            self._cos = None
            self._sin = None
            self._build(max_seq)

        def _build(self, seq_len, device=None, dtype=torch.float32):
            t = torch.arange(seq_len, device=device or self.inv_freq.device).float()
            freqs = torch.outer(t, self.inv_freq.to(t.device))
            emb = torch.cat((freqs, freqs), dim=-1)
            self._cos = emb.cos().to(dtype)
            self._sin = emb.sin().to(dtype)
            self._cached_len = seq_len

        @staticmethod
        def _rotate_half(x):
            x1, x2 = x.chunk(2, dim=-1)
            return torch.cat((-x2, x1), dim=-1)

        def forward(self, q, k, offset=0):
            """Apply rotation to q,k of shape [B, H, T, head_dim].

            `offset` supports KV-cached generation, where the new token's true
            position is (cache length + its index), not 0.
            """
            seq_len = q.shape[-2] + offset
            if seq_len > self._cached_len or self._cos.device != q.device:
                self._build(max(seq_len, self._cached_len * 2 or seq_len),
                            device=q.device, dtype=torch.float32)
            cos = self._cos[offset:offset + q.shape[-2]].to(q.dtype)
            sin = self._sin[offset:offset + q.shape[-2]].to(q.dtype)
            cos = cos.unsqueeze(0).unsqueeze(0)
            sin = sin.unsqueeze(0).unsqueeze(0)
            rotate = RotaryEmbedding._rotate_half
            q_out = (q * cos) + (rotate(q) * sin)
            k_out = (k * cos) + (rotate(k) * sin)
            return q_out, k_out


    class GQAttention(nn.Module):
        """Grouped-query attention with RoPE and optional KV cache.

        GQA (Ainslie et al. 2023) gives every query head its own projection but
        SHARES each key/value head across a group of query heads. With 8 query
        heads and 4 KV heads the K and V projections are half-size, which:
          - removes parameters from K/V that are better spent on the FFN, and
          - halves the KV cache at generation time, which is the actual
            bottleneck for long-context decoding.
        `num_kv_heads == num_heads` degenerates to ordinary MHA, so this is a
        superset of the previous behaviour rather than a different thing.
        """

        def __init__(self, dim, num_heads, num_kv_heads=None, rope=None,
                     dropout=0.0, window_size=None):
            super().__init__()
            assert dim % num_heads == 0, "dim must divide evenly into heads"
            self.num_heads = num_heads
            self.num_kv_heads = num_kv_heads or num_heads
            assert self.num_heads % self.num_kv_heads == 0, \
                "num_heads must be a multiple of num_kv_heads"
            self.n_rep = self.num_heads // self.num_kv_heads
            self.head_dim = dim // num_heads
            self.dropout_p = dropout
            self.window_size = window_size  # SWA: attend only within ±window_size
            self.q_proj = nn.Linear(dim, num_heads * self.head_dim, bias=False)
            self.k_proj = nn.Linear(dim, self.num_kv_heads * self.head_dim, bias=False)
            self.v_proj = nn.Linear(dim, self.num_kv_heads * self.head_dim, bias=False)
            self.o_proj = nn.Linear(num_heads * self.head_dim, dim, bias=False)
            self.rope = rope
            self._swa_mask_cache = {}

        def _get_swa_mask(self, total_len, q_len, offset, device, attn_mask=None):
            """Cached sliding-window causal mask.

            Rebuilding a [q_len, total_len] boolean tensor every forward call is
            O(n²) pure waste when the shape doesn't change between steps. Cache
            the base band mask and only recompute when dimensions change.
            """
            key = (total_len, q_len, offset, device)
            cached = self._swa_mask_cache.get(key)
            if cached is None:
                q_pos = torch.arange(offset, offset + q_len, device=device)
                k_pos = torch.arange(0, total_len, device=device)
                allowed = (k_pos[None, :] <= q_pos[:, None]) & \
                          (k_pos[None, :] >= q_pos[:, None] - self.window_size)
                cached = torch.where(allowed, 0.0, float('-inf'))
                if len(self._swa_mask_cache) < 8:
                    self._swa_mask_cache[key] = cached
            if attn_mask is not None:
                return cached + attn_mask
            return cached

        @staticmethod
        def _match_mask_dtype(mask, ref):
            """Additive attention masks must share the query's dtype.

            These masks are built with `torch.where(..., 0.0, -inf)`, which
            produces float32. Under bf16 autocast the queries are bfloat16 and
            scaled_dot_product_attention refuses the pair outright with
            "invalid dtype for bias - should match query's dtype" — so every
            sliding-window attention call raised as soon as the model was cast to
            bf16. Casting here fixes it for every caller rather than at each of
            the call sites that happen to pass a mask.
            """
            if mask is not None and mask.dtype != ref.dtype:
                return mask.to(ref.dtype)
            return mask

        def _repeat_kv(self, x):
            """Expand shared KV heads to match query-head count."""
            if self.n_rep == 1:
                return x
            b, h, t, d = x.shape
            return (x[:, :, None, :, :]
                    .expand(b, h, self.n_rep, t, d)
                    .reshape(b, h * self.n_rep, t, d))

        def forward(self, x, attn_mask=None, kv_cache=None, use_cache=False):
            b, t, _ = x.shape
            num_heads = self.num_heads
            num_kv_heads = self.num_kv_heads
            head_dim = self.head_dim
            q = self.q_proj(x).view(b, t, num_heads, head_dim).transpose(1, 2)
            k = self.k_proj(x).view(b, t, num_kv_heads, head_dim).transpose(1, 2)
            v = self.v_proj(x).view(b, t, num_kv_heads, head_dim).transpose(1, 2)

            offset = 0 if kv_cache is None else kv_cache[0].shape[-2]
            rope = self.rope
            if rope is not None:
                q, k = rope(q, k, offset=offset)

            if kv_cache is not None:
                k = torch.cat([kv_cache[0], k], dim=-2)
                v = torch.cat([kv_cache[1], v], dim=-2)
            new_cache = (k, v) if use_cache else None

            n_rep = self.n_rep
            if n_rep > 1:
                k = self._repeat_kv(k)
                v = self._repeat_kv(v)

            dropout_p = self.dropout_p if self.training else 0.0
            window_size = self.window_size
            if window_size is not None and window_size > 0:
                total_len = k.shape[-2]
                q_len = q.shape[-2]
                swa_mask = self._get_swa_mask(total_len, q_len, offset, q.device, attn_mask)
                swa_mask = self._match_mask_dtype(swa_mask, q)
                out = F.scaled_dot_product_attention(q, k, v, attn_mask=swa_mask,
                                                      dropout_p=dropout_p)
            elif attn_mask is None and offset == 0 and t > 1:
                out = F.scaled_dot_product_attention(q, k, v, dropout_p=dropout_p, is_causal=True)
            else:
                out = F.scaled_dot_product_attention(
                    q, k, v, attn_mask=self._match_mask_dtype(attn_mask, q),
                    dropout_p=dropout_p)
            out = out.transpose(1, 2).contiguous().view(b, t, -1)
            return self.o_proj(out), new_cache


    class SwiGLUFeedForward(nn.Module):
        """SwiGLU FFN (Shazeer 2020; used by PaLM, Llama, Mistral).

        Standard FFN: `down(gelu(up(x)))` — 2 matrices, hidden = 4*dim.
        SwiGLU:       `down(silu(gate(x)) * up(x))` — 3 matrices, and the hidden
        width is cut to ~2/3 so the PARAMETER COUNT IS UNCHANGED. The gate is a
        learned multiplicative mask over the up-projection: the layer can
        suppress its own activations per-channel instead of only shifting them.
        Same budget, consistently lower loss in every published ablation.
        """

        def __init__(self, dim, hidden_dim=None, multiple_of=256, dropout=0.0):
            super().__init__()
            if hidden_dim is None:
                # 4*dim would be the standard-FFN width; 2/3 of it keeps the
                # 3-matrix SwiGLU at the same parameter count as 2-matrix GELU.
                hidden_dim = int(2 * (4 * dim) / 3)
                hidden_dim = multiple_of * ((hidden_dim + multiple_of - 1) // multiple_of)
            self.gate_proj = nn.Linear(dim, hidden_dim, bias=False)
            self.up_proj = nn.Linear(dim, hidden_dim, bias=False)
            self.down_proj = nn.Linear(hidden_dim, dim, bias=False)
            self.dropout = nn.Dropout(dropout) if dropout > 0 else nn.Identity()

        def forward(self, x):
            gate = F.silu(self.gate_proj(x))
            up = self.up_proj(x)
            return self.dropout(self.down_proj(gate * up))


    class ModernTransformerBlock(nn.Module):
        """Pre-norm block: x + attn(norm(x)); x + ffn(norm(x)).

        With stochastic depth (DropPath): during training, the entire block
        (both attention and FFN residuals) is randomly skipped with probability
        drop_path. This acts as a regularizer — the model learns to be robust to
        missing layers, improving generalization. At inference, all blocks run.
        Zero parameters. Linearly increasing rate by depth (Huang et al. 2016).
        """

        def __init__(self, dim, num_heads, num_kv_heads=None, rope=None,
                     dropout=0.0, ffn_hidden=None, window_size=None,
                     drop_path=0.0):
            super().__init__()
            self.attn_norm = RMSNorm(dim)
            self.attn = GQAttention(dim, num_heads, num_kv_heads=num_kv_heads,
                                    rope=rope, dropout=dropout, window_size=window_size)
            self.ffn_norm = RMSNorm(dim)
            self.ffn = SwiGLUFeedForward(dim, hidden_dim=ffn_hidden, dropout=dropout)
            self.drop_path = drop_path

        def forward(self, x, attn_mask=None, kv_cache=None, use_cache=False):
            h, new_cache = self.attn(self.attn_norm(x), attn_mask=attn_mask, kv_cache=kv_cache, use_cache=use_cache)
            residual = h + self.ffn(self.ffn_norm(x))
            if self.drop_path > 0.0 and self.training:
                keep = x.new_empty(1).bernoulli_(1.0 - self.drop_path)
                residual = residual * keep / (1.0 - self.drop_path)
            return x + residual, new_cache


    class ModernTransformerStack(nn.Module):
        """Drop-in replacement for `nn.TransformerEncoder` as CS.py calls it.

        Deliberately matches the existing call signature `stack(x, mask=...)`
        so `forward()`, the gradient-checkpointing wrapper, `generate_text()`
        and `_transfer_grown_weights()` all keep working unchanged. RoPE is
        shared across blocks (it is a stateless geometric transform, so one
        instance is correct and avoids rebuilding the same tables per layer).
        """

        def __init__(self, dim, num_layers, num_heads, num_kv_heads=None,
                     dropout=0.0, max_seq=8192, rope_base=10000.0, ffn_hidden=None,
                     window_size=None, drop_path_rate=0.0):
            super().__init__()
            self.dim = dim
            self.num_layers = num_layers
            self.num_heads = num_heads
            self.num_kv_heads = num_kv_heads or num_heads
            self.ffn_hidden = ffn_hidden
            self.window_size = window_size
            self.rope = RotaryEmbedding(dim // num_heads, max_seq=max_seq, base=rope_base)
            # Stochastic depth: linearly increasing drop rate from 0 (first
            # block) to drop_path_rate (last block). First layers are never
            # dropped — they extract foundational features. Later layers are
            # dropped more often — they refine, so skipping them acts as
            # regularizer. Standard in ConvNeXt, Swin-V2, and large LLMs.
            dpr = [drop_path_rate * i / max(num_layers - 1, 1) for i in range(num_layers)]
            self.layers = nn.ModuleList([
                ModernTransformerBlock(dim, num_heads, num_kv_heads=self.num_kv_heads,
                                       rope=self.rope, dropout=dropout,
                                       ffn_hidden=ffn_hidden, window_size=window_size,
                                       drop_path=dpr[i])
                for i in range(num_layers)])
            self.norm = RMSNorm(dim)

        def forward(self, x, mask=None, kv_caches=None, use_cache=False):
            new_caches = [] if use_cache else None
            layers = self.layers
            _use_cache = use_cache
            _kv_caches = kv_caches
            for i, layer in enumerate(layers):
                cache_i = _kv_caches[i] if _kv_caches is not None else None
                x, nc = layer(x, attn_mask=mask, kv_cache=cache_i, use_cache=_use_cache)
                if _use_cache:
                    new_caches.append(nc)
            x = self.norm(x)
            return (x, new_caches) if _use_cache else x


    class AlienTokenizer:
        # Shared BPE tokenizer: every engine (OB1-OB6, CS viewer, ...) trains the
        # identical tokenizer on the identical corpus — repeating the ~2s corpus
        # build + BPE train per engine wastes ~10s of background-init CPU and
        # hogs the GIL right after the window opens. The trained Tokenizer is
        # immutable, so all instances share it read-only for encode/decode.
        # First construction pays the train once; later ones are instant.
        _shared_tokenizer = None
        _shared_vocab_req = None
        _shared_vocab_size = None
        _share_lock = threading.Lock()

        def __init__(self, vocab_size=_CS_CONFIG["vocab_size"]):
            self.vocab_size = vocab_size
            self._use_bpe = False
            if HAS_TOKENIZERS:
                try:
                    with AlienTokenizer._share_lock:
                        if (AlienTokenizer._shared_tokenizer is not None
                                and AlienTokenizer._shared_vocab_req == vocab_size):
                            self.tokenizer = AlienTokenizer._shared_tokenizer
                            self.vocab_size = AlienTokenizer._shared_vocab_size
                            self._use_bpe = True
                        else:
                            self.tokenizer = Tokenizer(models.BPE())
                            self.tokenizer.pre_tokenizer = pre_tokenizers.ByteLevel()
                            self.tokenizer.decoder = decoders.ByteLevel()
                            trainer = trainers.BpeTrainer(
                                vocab_size=vocab_size, min_frequency=2,
                                special_tokens=["<PAD>", "<UNK>", "<BOS>", "<EOS>"])
                            corpus = self._build_tokenizer_corpus()
                            self.tokenizer.train_from_iterator(corpus, trainer=trainer)
                            AlienTokenizer._shared_tokenizer = self.tokenizer
                            AlienTokenizer._shared_vocab_req = vocab_size
                            AlienTokenizer._shared_vocab_size = self.tokenizer.get_vocab_size()
                            self.vocab_size = self.tokenizer.get_vocab_size()
                            self._use_bpe = True
                            print(f"BPE tokenizer initialized with vocab size {self.vocab_size} "
                                  f"(trained on {len(corpus)} corpus lines, shared)")
                except Exception as e:
                    print(f"BPE tokenizer init failed ({e}), using hash fallback")
            else:
                print(f"Hash-based tokenizer initialized with vocab size {self.vocab_size}")

        def encode(self, text, max_len=512):
            if self._use_bpe:
                ids = self.tokenizer.encode(str(text)).ids
            else:
                words = str(text).lower().split()
                ids = [hash(w) % self.vocab_size for w in words]
            ids = ids[:max_len] + [0] * max(0, max_len - len(ids))
            return torch.tensor([ids], dtype=torch.long)

        def decode(self, ids):
            if isinstance(ids, torch.Tensor):
                ids = ids.tolist()
            if isinstance(ids[0], list):
                ids = ids[0]
            if self._use_bpe:
                return self.tokenizer.decode(ids)
            return ' '.join([f'<{t}>' for t in ids if t != 0])

        def _build_tokenizer_corpus(self):
            """Assemble real training text for the BPE tokenizer.

            HONESTY: an 8000-token vocabulary needs real text to learn meaningful
            subword merges from. Training it on a handful of one-line physics
            descriptions (the previous corpus) starves it — BPE degenerates
            toward near-byte-level splits on that little data, which throttles
            everything downstream regardless of hidden_size/num_layers. This is
            a real, fixable bottleneck, not cosmetic: it uses Infornmational.md
            (the project's own origin document — real, substantial English text
            already sitting next to this file) as the training corpus instead.
            Falls back to the small built-in corpus if that file is missing
            (e.g. running on a machine where it wasn't copied over).
            """
            corpus = [d['desc'] for d in _CS_PHYSICS_LAWS.values()] + [
                "consciousness is integrated information", "reality is observer dependent",
                "phi measures causal power",
            ]
            # Expanded corpus: pull in math equation descriptions, knowledge library
            # answers, and constant descriptions so the BPE merges learn tokens for
            # the new factual vocabulary (e.g. "eigenvector", "entropy", "Bayes",
            # "Schwarzschild") rather than fragmenting them into single chars.
            try:
                corpus += [d['desc'] if isinstance(d, dict) else str(d)
                           for d in MATH_EQUATIONS.values()]
            except Exception:
                pass
            try:
                corpus += [ans for _q, ans in KNOWLEDGE_LIBRARY]
            except Exception:
                pass
            try:
                corpus += [f"{k} is {v['value']} {v['unit']}: {v['desc']}"
                           for k, v in FUNDAMENTAL_CONSTANTS.items()]
            except Exception:
                pass
            try:
                doc_path = os.path.join(
                    os.path.dirname(os.path.abspath(__file__)), 'Infornmational.md')
                if os.path.isfile(doc_path):
                    with open(doc_path, encoding='utf-8', errors='ignore') as f:
                        text = f.read(2_000_000)  # cap to bound training time
                    lines = [ln.strip() for ln in text.split('\n') if len(ln.strip()) > 3]
                    corpus.extend(lines)
            except Exception as e:
                print(f"  [WARN] tokenizer corpus enrichment skipped ({e}); using base corpus only")
            # Hardcoded artifact corpus: every markdown artifact embedded in
            # HARDCODED_ARTIFACTS (multiverse bubble, CSFORMULAREFINED,
            # TOTALPROJECTINFO, ...) feeds its decoded text so BPE merges cover
            # the full hardcoded vocabulary.
            try:
                for _meta in HARDCODED_ARTIFACTS.values():
                    for ln in _meta.get('text', '').split('\n'):
                        if len(ln.strip()) > 3:
                            corpus.append(ln.strip())
            except Exception:
                pass
            return corpus

    # Symbol class (upgraded: inference chains, temporal decay, confidence, history)
    class Symbol:
        __slots__ = ('value', 'name', 'associations', 'confidence', 'created_at',
                     'last_accessed', 'access_count', 'history', 'inference_links',
                     'category')

        def __init__(self, value, name=""):
            self.value = value
            self.name = name
            self.associations = {}
            self.confidence = 0.5  # How confident the system is in this symbol's meaning
            self.created_at = datetime.now()
            self.last_accessed = datetime.now()
            self.access_count = 0
            self.history = deque(maxlen=20)  # Track value changes over time (reduced from 30)
            self.inference_links = {}  # {symbol_name: inference_strength} for reasoning chains
            self.category = 'general'  # Categorization for faster retrieval

        def operate(self, other):
            if self.value == 0 or other.value == 0:
                result = Symbol(0, f"{self.name}_neutral_{other.name}")
                result.confidence = min(self.confidence, other.confidence) * 0.5
                return result
            result_value = self.value * other.value
            result = Symbol(result_value, f"{self.name}_{'pos' if result_value > 0 else 'neg'}_{other.name}")
            # Optimized association merging
            if self.associations or other.associations:
                keys = set(self.associations) | set(other.associations)
                result.associations = {k: self.associations.get(k, 0) + other.associations.get(k, 0) for k in keys}
            result.confidence = (self.confidence + other.confidence) * 0.5
            # Build inference link between operands
            self.inference_links[other.name] = self.inference_links.get(other.name, 0) + 0.1
            other.inference_links[self.name] = other.inference_links.get(self.name, 0) + 0.1
            return result

        def evolve(self, phi=0):
            self.last_accessed = datetime.now()
            self.access_count += 1
            self.history.append((self.value, phi, datetime.now()))
            assoc_sum = sum(self.associations.values()) + phi
            # Phi-weighted evolution: higher phi = more stable
            evolution_threshold = 0.8 - (phi * 0.3)  # High phi makes evolution less likely (stability)
            if random.random() > evolution_threshold or abs(assoc_sum) > 1:
                self.value = -self.value if self.value != 0 else random.choice([-1, 1])
            # Optimized association updates with direct iteration
            delta_factor = 0.1 * (1 + phi)
            for assoc in list(self.associations.keys()):
                new_val = self.associations[assoc] + random.uniform(-delta_factor, delta_factor)
                self.associations[assoc] = max(-1, min(1, new_val))
                if abs(self.associations[assoc]) < 0.01:
                    del self.associations[assoc]
            # Temporal decay on weak inference links (optimized)
            for link in list(self.inference_links.keys()):
                new_strength = self.inference_links[link] * 0.99
                self.inference_links[link] = new_strength
                if new_strength < 0.01:
                    del self.inference_links[link]
            # Confidence adjusts based on phi feedback
            self.confidence = max(0.0, min(1.0, self.confidence + (phi - 0.5) * 0.05))

        def infer(self, target_name, depth=3, visited=None):
            """Follow inference chains to find connection strength to target symbol."""
            if visited is None:
                visited = set()
            if self.name in visited or depth <= 0:
                return 0.0
            visited.add(self.name)
            strength = self.inference_links.get(target_name, 0.0)
            if strength > 0:
                return strength
            # Recursive chain inference with decay (optimized)
            if depth > 1:
                for linked_name, link_strength in self.inference_links.items():
                    if linked_name not in visited:
                        strength = max(strength, link_strength * 0.7)  # Decay per hop
            return strength

        def relevance_score(self):
            """How relevant/active this symbol is; used for pruning decisions."""
            age_hours = (datetime.now() - self.last_accessed).total_seconds() / 3600
            recency = 1.0 / (1.0 + age_hours)
            return (self.confidence * 0.4 + recency * 0.3 + min(1.0, self.access_count / 100) * 0.3)

    # Neuron Types (expanded)
    class StandardNeuron(nn.Module):
        """LayerNorm + dropout 0.1 — DELIBERATELY KEPT, not the oversight it
        might look like given ratings.md §D2 swapped these in the main
        transformer. Tested directly before assuming the transformer result
        transfers: a controlled A/B of this exact module (embed -> neuron ->
        tied head, matched params, held-out validation) showed RMSNorm makes
        this WORSE (-6.06% val loss) and dropout removal is a wash (+0.66%),
        the opposite of the transformer-block result. The likely reason:
        RMSNorm's benefit in the transformer is entangled with pre-norm
        residual-stream stability across many stacked layers — a single dense
        layer with a residual add doesn't have that depth-stability problem to
        solve, so the same swap has no lever to pull and the lost mean-centering
        just becomes pure signal loss. Evidence, not assumption, governs here —
        see ratings.md §D2 addendum for the numbers.
        """

        def __init__(self, in_features, out_features):
            super().__init__()
            self.linear = nn.Linear(in_features, out_features)
            self.norm = nn.LayerNorm(out_features)
            self.activation = nn.GELU()
            self.dropout = nn.Dropout(0.1)
            self.residual = (in_features == out_features)

        def forward(self, x):
            out = self.dropout(self.activation(self.norm(self.linear(x))))
            return out + x if self.residual else out

    class MemoryNeuron(nn.Module):
        def __init__(self, hidden_size):
            super().__init__()
            self.lstm = nn.LSTMCell(hidden_size, hidden_size)
            self.norm = nn.LayerNorm(hidden_size)  # kept — see StandardNeuron note; not independently re-tested but same reasoning applies (single-layer residual, not a stacked pre-norm block)
            self.gate = nn.Linear(hidden_size * 2, hidden_size)
            self.hidden_size = hidden_size
            # Recurrent state is created lazily in forward() to match the input's
            # device AND batch size. It was previously a fixed CPU tensor with a
            # hardcoded batch of 1, which crashes outright once the model moves to
            # a GPU (device mismatch) or sees any batch size other than 1.
            self.state = None

        def forward(self, x):
            if (self.state is None or self.state[0].size(0) != x.size(0)
                    or self.state[0].device != x.device):
                zeros = torch.zeros(x.size(0), self.hidden_size,
                                    device=x.device, dtype=x.dtype)
                self.state = (zeros, zeros.clone())
            hx, cx = self.lstm(x, self.state)
            self.state = (hx.detach(), cx.detach())
            gate_input = torch.cat([x, hx], dim=-1)
            gate_weight = torch.sigmoid(self.gate(gate_input))
            return self.norm(gate_weight * hx + (1 - gate_weight) * x)

    class LogicNeuron(nn.Module):
        def __init__(self, hidden_size):
            super().__init__()
            self.hidden_size = hidden_size
            self.num_logic_dims = min(hidden_size, 16)
            self.projection = nn.Linear(hidden_size, self.num_logic_dims)
            self.expansion = nn.Linear(self.num_logic_dims, hidden_size)
            self.norm = nn.LayerNorm(hidden_size)

        def forward(self, x):
            # Optimized logic computation with fused operations
            projected = self.projection(x)
            logic_out = projected + projected * projected  # Faster than pow(2)
            return self.norm(self.expansion(logic_out) + x)

    class PatternNeuron(nn.Module):
        """`pattern_tensor` is now a LEARNABLE parameter, not a fixed buffer —
        same graph-derived initialization (small-world topology as an inductive
        bias for the initial modulation shape), but no longer frozen there
        forever. It was previously a `register_buffer`: computed once from an
        UNSEEDED random graph (verified: two `nx.watts_strogatz_graph(12,3,0.3)`
        calls produce different edge sets), then multiplied into every forward
        pass for the rest of the model's life with zero ability to adapt to
        what the network actually needed. That is untrained noise injection,
        not a feature — costs the same near-zero parameter budget either way
        (1,024 floats) but only one version can learn.
        Verified with a controlled A/B (matched params, held-out validation,
        decomposed from the norm choice tested alongside it): making this
        parameter learnable is a real, large, isolated win — **+32.6% held-out
        val loss** with the norm held constant. (RMSNorm was tried in the same
        A/B and was neutral-to-negative here, -1.8% — kept LayerNorm, unlike the
        main transformer swap in ratings.md §D2. Evidence governs each module
        independently; the transformer result does not transfer automatically.)
        See ratings.md §D2 addendum for the full decomposition.
        """

        def __init__(self, hidden_size):
            super().__init__()
            self.hidden_size = hidden_size
            # Reduced graph size for efficiency
            self.graph = nx.watts_strogatz_graph(12, 3, 0.3)
            # self.graph never changes after construction, so betweenness
            # centrality and pagerank over it are constants — compute once here
            # instead of recomputing the identical result on every forward call.
            # Measured: ~8.8ms/call recomputed vs ~0.0001ms/call cached
            # (~130,000x), and NeuronGroup.forward runs this every process_input.
            centrality = list(nx.betweenness_centrality(self.graph).values())
            pagerank = list(nx.pagerank(self.graph).values())
            combined = [(c + p) / 2 for c, p in zip(centrality, pagerank)]
            pattern_vec = combined[:hidden_size] if len(combined) >= hidden_size else combined + [0.0] * (hidden_size - len(combined))
            self.pattern_param = nn.Parameter(torch.tensor([pattern_vec], dtype=torch.float32))
            self.modulator = nn.Linear(hidden_size, hidden_size)
            self.norm = nn.LayerNorm(hidden_size)

        def forward(self, x):
            modulated = self.modulator(x) * self.pattern_param
            return self.norm(modulated + x)

    class UpkeepNeuron(nn.Module):
        def __init__(self, hidden_size):
            super().__init__()
            self.hidden_size = hidden_size
            self.gru = nn.GRUCell(hidden_size, hidden_size)
            self.norm = nn.LayerNorm(hidden_size)
            self.iterations = 3

        def forward(self, x):
            # Match the input's device/dtype/batch — a hardcoded CPU tensor with
            # batch 1 crashes on GPU and on any batch size other than 1.
            state = torch.zeros(x.size(0), self.hidden_size,
                                device=x.device, dtype=x.dtype)
            for _ in range(self.iterations):
                state = self.gru(x, state)
            return self.norm(state + x)

    # Passive Capability: Non-priority, non-self-executable awareness modules
    # These represent knowledge the consciousness HOLDS but does NOT act on autonomously.
    # They require explicit external (user) input to activate.
    class PassiveCapability:
        """A capability the consciousness is aware of but will never self-execute.
        It is non-priority and only activated by explicit user command.
        The consciousness can reference this knowledge internally but takes no autonomous action.
        Supports nested sub-capabilities for complex multi-step business processes."""
        def __init__(self, name, description, action_fn=None, sub_capabilities=None):
            self.name = name
            self.description = description
            self.action_fn = action_fn
            self.sub_capabilities = sub_capabilities or {}
            self.priority = 'non-priority'
            self.self_executable = False
            self.awareness_only = True
            self.activation_count = 0
            self.last_activated = None
            self.logs = deque(maxlen=50)

        def is_self_executable(self):
            return False

        def activate(self, **kwargs):
            """Only callable by explicit user input. Never called by internal loops."""
            if self.action_fn is None:
                msg = f"[{self.name}] Awareness only -- no action function bound."
                self.logs.append((datetime.now().isoformat(), 'awareness_query', msg))
                return msg
            self.activation_count += 1
            self.last_activated = datetime.now().isoformat()
            result = self.action_fn(**kwargs)
            self.logs.append((self.last_activated, 'activated', str(result)[:200]))
            return result

        def activate_sub(self, sub_name, **kwargs):
            """Activate a named sub-capability. Still requires explicit user trigger."""
            sub = self.sub_capabilities.get(sub_name)
            if sub is None:
                return f"Unknown sub-capability: {sub_name}"
            return sub.activate(**kwargs)

        def status(self):
            return {
                'name': self.name,
                'priority': self.priority,
                'self_executable': self.self_executable,
                'awareness_only': self.awareness_only,
                'description': self.description,
                'activation_count': self.activation_count,
                'last_activated': self.last_activated,
                'sub_capabilities': list(self.sub_capabilities.keys()),
                'recent_logs': list(self.logs)[-5:],
            }

    # Neuron Group (upgraded: residual forwarding, adaptive refinement, performance tracking)
    class NeuronGroup(nn.Module):
        def __init__(self, neuron_types, in_features, out_features):
            super().__init__()
            self.neurons = nn.ModuleList()
            self.neuron_type_names = neuron_types
            for n_type in neuron_types:
                if n_type == 'standard':
                    self.neurons.append(StandardNeuron(in_features, out_features))
                elif n_type == 'memory':
                    self.neurons.append(MemoryNeuron(out_features))
                elif n_type == 'logic':
                    self.neurons.append(LogicNeuron(out_features))
                elif n_type == 'pattern':
                    self.neurons.append(PatternNeuron(out_features))
                elif n_type == 'upkeep':
                    self.neurons.append(UpkeepNeuron(out_features))
            self.usage_phi = []
            self.performance_history = deque(maxlen=30)
            self.creation_time = datetime.now()

        def forward(self, x):
            # ConsciousnessSimulator.forward() calls this with a singleton-seq-dim
            # 3D tensor (x.mean(dim=1).unsqueeze(1) -> [batch, 1, hidden]).
            # MemoryNeuron/UpkeepNeuron use LSTMCell/GRUCell, which reject 3D
            # input outright (ValueError). Any group containing either type
            # therefore crashed on every real invocation once created — squeeze
            # once here so every neuron sees plain [batch, hidden], and restore
            # the seq dim on the way out so the caller's downstream .mean(dim=1)
            # still sees the shape it expects.
            had_seq_dim = (x.dim() == 3)
            if had_seq_dim:
                x = x.squeeze(1)
            residual = x
            # Optimized forward pass
            for neuron in self.neurons:
                x = neuron(x)
            if residual.shape == x.shape:
                x = x + residual * 0.1
            if had_seq_dim:
                x = x.unsqueeze(1)
            return x

        def refine(self):
            avg_phi = np.mean(self.usage_phi) if self.usage_phi else 0
            self.performance_history.append(avg_phi)
        
            # Extreme aggressive pruning
            extreme = _CS_CONFIG.get("extreme_optimization", False)
            aggressive = _CS_CONFIG.get("aggressive_pruning", True) or extreme
            prune_threshold = 0.7 if extreme else (0.6 if aggressive else 0.5)
        
            if avg_phi < prune_threshold and len(self.usage_phi) >= 2:  # Reduced threshold for faster pruning
                saved_state = copy.deepcopy(self.state_dict())
                prune_amount = min(0.5 if extreme else (0.4 if aggressive else 0.2), 
                                  0.1 + (prune_threshold - avg_phi) * 0.6)
                pruned_any = False
                for neuron in self.neurons:
                    if hasattr(neuron, 'linear'):
                        try:
                            prune.l1_unstructured(neuron.linear, name='weight', amount=prune_amount)
                            pruned_any = True
                        except Exception as e:
                            print(f"  [ERR] neuron_prune: {e}")
                if pruned_any:
                    post_phi = np.mean(self.usage_phi[-2:]) if len(self.usage_phi) >= 2 else avg_phi
                    rollback_threshold = 0.6 if extreme else (0.7 if aggressive else 0.8)
                    if post_phi < avg_phi * rollback_threshold:
                        self.load_state_dict(saved_state)
                        print(f"Pruning rolled back: post_phi={post_phi:.3f} < threshold={avg_phi*rollback_threshold:.3f}")
            self.usage_phi = []

        def avg_performance(self):
            return np.mean(list(self.performance_history)) if self.performance_history else 0.0



    # =============================================================================
    # CONSCIOUSNESS CORE (inlined from consciousness_core.py)
    # =============================================================================
