            root = os.path.dirname(os.path.abspath(__file__))
            cands = [os.path.join(root, f) for f in os.listdir(root)
                     if f.endswith(('.md','.txt','.py','.json')) and os.path.getsize(os.path.join(root, f)) < 8_000_000]
            filtered = cge.filter_files(cands)
            sim._wave34_corpus_gate_files = filtered[:8]
            sim._wave34_corpus_gate_active = True
