    def _wave35_any_wave34_active(sim):
        return any(hasattr(sim, a) for a in _WAVE34_TRACE_ATTRS)


    def _wave35_weight_from_dict(obj, count_key='id', scale=0.1):
        try:
            if not obj:
                return 0.0
            val = obj.get(count_key, 0)
            if isinstance(val, (int, float)):
                return min(1.0, float(val) * scale)
            return 0.0
        except Exception:
            return 0.0


    class Wave35SynergyMixer:
        """Multiplies the active signals from Waves 31, 32, 34 into a synergy score
        and power multiplier.  This is the 'synergy to amplify power' step."""
        __slots__ = ('_sim',)

        def __init__(self, sim):
            self._sim = sim

        def step(self):
            try:
                s = self._sim
                b31 = getattr(s, '_wave31_active_barrier', {}) or {}
                t32 = getattr(s, '_wave32_active_tuning', {}) or {}
                w34 = 1.0 if _wave35_any_wave34_active(s) else 0.0

                w31 = _wave35_weight_from_dict(b31, 'resolved_hits', 0.1)
                w32 = _wave35_weight_from_dict(t32, 'applied_hits', 0.1)

                # multiplicative synergy: co-active waves reinforce each other
                synergy = (1.0 + w31) * (1.0 + w32) * (1.0 + w34) - 1.0

                s._wave35_synergy_score = float(synergy)
                s._wave35_power_multiplier = float(1.0 + min(2.0, synergy * 0.5))
                s._wave35_resonance_boost = float(min(1.0, synergy * 0.25))
                s._wave35_attention_boost = float(min(1.0, w31 * 0.1 + w32 * 0.05 + w34 * 0.2))
                s._wave35_synthesized_action = (
                    f"synergy: w31={w31:.3f} w32={w32:.3f} w34={w34:.1f} -> {synergy:.3f}"
                )
                s._wave35_synergy_hits = getattr(s, '_wave35_synergy_hits', 0) + 1
            except Exception:
                pass

        def get_status(self):
            s = self._sim
            return {
                'synergy_score': getattr(s, '_wave35_synergy_score', 0.0),
                'power_multiplier': getattr(s, '_wave35_power_multiplier', 1.0),
                'resonance_boost': getattr(s, '_wave35_resonance_boost', 0.0),
                'attention_boost': getattr(s, '_wave35_attention_boost', 0.0),
                'synthesized_action': getattr(s, '_wave35_synthesized_action', ''),
                'hits': getattr(s, '_wave35_synergy_hits', 0),
            }


    class Wave35SurpassIndex:
        """Live 'vs. mainstream' index that combines evolution, quality, and synergy."""
        __slots__ = ('_sim',)

        def __init__(self, sim):
            self._sim = sim

        def step(self):
            try:
                s = self._sim
                kept = getattr(s, '_evolution_kept', 0)
                rolled = getattr(s, '_evolution_rolled_back', 0)
                quality = getattr(s, '_wave32_quality_12_after', 0.0)
                synergy = getattr(s, '_wave35_synergy_score', 0.0)

                total = max(1, kept + rolled)
                keep_rate = kept / total

                # index is a percentage of a hypothetical 'mainstream' baseline (100%)
                index = (
                    keep_rate * 0.25 +
                    min(1.0, quality / 100.0) * 0.25 +
                    min(1.0, synergy / 5.0) * 0.25 +
                    min(1.0, kept / 50.0) * 0.25
                ) * 200.0

                s._wave35_surpass_index = float(index)
                s._wave35_vs_mainstream_pct = float(index)
                s._wave35_surpass_hits = getattr(s, '_wave35_surpass_hits', 0) + 1
            except Exception:
                pass

        def get_status(self):
            s = self._sim
            return {
                'surpass_index': getattr(s, '_wave35_surpass_index', 0.0),
                'vs_mainstream_pct': getattr(s, '_wave35_vs_mainstream_pct', 0.0),
                'hits': getattr(s, '_wave35_surpass_hits', 0),
            }


    class Wave35SynergyResolver(_ResolverBase):
        """Applies a pair of resolvers to exploit cross-resolver synergy."""
        __slots__ = ('_rng',)

        def __init__(self, sim):
            super().__init__(sim, 'high')
            self._rng = random.Random(20260804 + hash(id(sim)))

        def apply(self, sim, barrier):
            try:
                eng = getattr(sim, '_evolution_engine', None)
                if eng is None:
                    return False
                btype = barrier.get('type', 'unknown')
                arms = list(eng._resolvers.get(btype, []))
                # exclude self and pick two distinct resolvers
                others = [a for a in arms if a.name() != self.name()]
                if len(others) < 2:
                    return False
                self._rng.shuffle(others)
                a, b = others[0], others[1]
                ra = a.apply(sim, barrier)
                rb = b.apply(sim, barrier)
                sim._wave35_synergy_pair = (a.name(), b.name(), ra, rb)
                sim._wave35_synergy_active = True
                return ra or rb  # success if either applied something
            except Exception:
                return False


    class Wave35MainstreamSurpassResolver(_ResolverBase):
        """Scores the current model against a public baseline perplexity."""
        __slots__ = ()

        def __init__(self, sim):
            super().__init__(sim, 'low')

        def apply(self, sim, barrier):
            try:
                # Use a 12000 random-guess PPL as a public LLM baseline
                sim._wave35_mainstream_baseline_ppl = 12000.0
                # Try a tiny benchmark, but don't fail if the corpus is empty
                bench = sim.run_internal_benchmark(n_lines=4, verbose=False)
                loss = bench.get('mean_loss')
                if loss is None:
                    sim._wave35_current_ppl = 12000.0
                    sim._wave35_ppl_surpass_pct = 0.0
                    return True
                ppl = math.exp(min(loss, 20.0))
                sim._wave35_current_ppl = ppl
                sim._wave35_ppl_surpass_pct = ((12000.0 - ppl) / 12000.0) * 100.0
                sim._wave35_mainstream_surpass_active = True
                return True
            except Exception:
                return False


