    # Extensions that count as loaded code for the DLL path check — a
    # memory-mapped .db/.mui data file is not an injected module.
    _IMAGE_EXTS = ('.dll', '.exe', '.ocx', '.sys', '.cpl', '.drv', '.ax')


    def _progdata_safe(path_lower: str) -> bool:
        return any(s in path_lower for s in _SAFE_PROGDATA_SUBTREES)


    def _is_image_path(path_lower: str) -> bool:
        base = path_lower.rsplit('\\', 1)[-1]
        return '.' not in base or base.endswith(_IMAGE_EXTS)

