    # Fast LRU cache for _is_public_ip — called on every packet and every connection.
    # ipaddress.ip_address() + .is_global is expensive; most IPs repeat frequently.
    from functools import lru_cache as _lru_cache

    _RDNS_BOUNDED_CACHE: dict = {}
    _RDNS_BOUNDED_LOCK = threading.Lock()


    def _proc_connections(proc, kind: str = 'inet'):
        """Per-process sockets, across psutil versions.

    Process.connections() is deprecated in favour of Process.net_connections()
    and emits a DeprecationWarning on every call.
    """
        getter = getattr(proc, 'net_connections', None) or proc.connections
        return getter(kind=kind)


    def _rdns_bounded(ip: str, timeout: float = 3.0) -> str:
        """socket.gethostbyaddr() with a wall-clock bound.

    gethostbyaddr honours no timeout argument and on Windows can block for
    30+ seconds on a filtered host, which stalls whichever worker called it.
    Run it on a throwaway daemon thread and abandon it if it overruns. The
    result (including the empty string for a failure) is cached so a slow IP
    is only ever waited on once.
    """
        with _RDNS_BOUNDED_LOCK:
            if ip in _RDNS_BOUNDED_CACHE:
                return _RDNS_BOUNDED_CACHE[ip]
        box = {}

        def _work():
            try:
                box['host'] = socket.gethostbyaddr(ip)[0]
            except Exception:
                box['host'] = ''

        t = threading.Thread(target=_work, daemon=True, name="rdns-bounded")
        t.start()
        t.join(timeout)
        host = box.get('host', '')
        if t.is_alive():
            # Timed out — don't cache, the abandoned thread may still land a result.
            return ''
        with _RDNS_BOUNDED_LOCK:
            if len(_RDNS_BOUNDED_CACHE) > 20000:
                _RDNS_BOUNDED_CACHE.clear()
            _RDNS_BOUNDED_CACHE[ip] = host
        return host


    def _fwd_lookup_bounded(host: str, timeout: float = 4.0):
        """getaddrinfo() with the same wall-clock bound pattern as
    _rdns_bounded — a hung forward lookup stalls the probe wave.
    Returns the resolved address set (possibly empty)."""
        box = {}

        def _work():
            try:
                box['a'] = {ai[4][0] for ai in socket.getaddrinfo(host, None)}
            except Exception:
                box['a'] = set()

        t = threading.Thread(target=_work, daemon=True, name="fwd-bounded")
        t.start()
        t.join(timeout)
        return box.get('a', set())


    @_lru_cache(maxsize=4096)
    def _is_public_ip_cached(ip: str) -> bool:
        """Cached version of _is_public_ip — avoids repeated ipaddress parsing."""
        try:
            return ipaddress.ip_address(ip).is_global
        except (ValueError, Exception):
            return False

    @_lru_cache(maxsize=8192)
    def _net_contains(ip: str, net) -> bool:
        """ipaddress.ip_address(ip) in net — the LAN-membership check ran a full
    parse+compare for EVERY packet; the set of distinct src addresses is tiny,
    so cache it. `net` is an ip_network (hashable) fixed at startup."""
        try:
            return ipaddress.ip_address(ip) in net
        except Exception:
            return False

    def _haversine_km(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
        """Great-circle distance between two lat/lon points in km."""
        import math
        R = 6371.0
        rlat1, rlat2 = math.radians(lat1), math.radians(lat2)
        dlat = math.radians(lat2 - lat1)
        dlon = math.radians(lon2 - lon1)
        a = (math.sin(dlat / 2) ** 2
             + math.cos(rlat1) * math.cos(rlat2) * math.sin(dlon / 2) ** 2)
        return R * 2 * math.asin(min(1, math.sqrt(a)))


    # ==================== SILENT-TUNNEL WIRE SIGNATURES ====================
    # These classifiers identify VPN/tunnel protocols by their on-wire packet
    # shape — the ONLY evidence available for protocols engineered to never
    # answer unauthenticated traffic. WireGuard is the canonical case: it
    # black-holes every probe (no IKE answer, no TCP listener, no TLS
    # handshake), so a port-scanning verifier can never see it — but its
    # handshake on the wire is unmistakable. Zero packets are generated; this
    # reads what the sniffer already captured.
    #
    # WireGuard message types (wireguard.com/protocol): type byte 1-4 followed
    # by three reserved zero bytes. Handshake messages have exact sizes;
    # transport data (type 4) is >=32 bytes.
    _WG_MSG_SIZES = {1: 148, 2: 92, 3: 64}
    _WG_MSG_NAMES = {1: 'handshake-init', 2: 'handshake-response',
                     3: 'cookie-reply', 4: 'transport-data'}
