            # --- 19c) PROX — live protocol negotiation on the flagged proxy
            # ports. SOCKS5 `\x05\x00`, SOCKS4 grant, or HTTP CONNECT answers
            # upgrade the PortFP heuristic into a PROVEN relay.
            px = probes.get('prox')
            if px:
                states = {p['proto'] for p in px if p.get('state') == 'open'}
                auth = [p for p in px if p.get('state') == 'auth']
                answer = [p for p in px if p.get('state') == 'answered']
                if states:
                    report['proxy_state'] = 'open'
                    report['is_proxy'] = True
                    det = ("OPEN RELAY confirmed by live negotiation: "
                           + "; ".join(sorted(states))
                           + " — endpoint forwards traffic for arbitrary clients")
                    report['conflicts'].append(det)
                    report['labels'].append('open proxy relay (negotiated)')
                elif auth or answer:
                    report['proxy_state'] = 'auth'
                    report['is_proxy'] = True
                    who = '; '.join(
                        f"{p['proto']} (locked)" for p in (auth or answer))
                    det = f"proxy service confirmed by negotiation: {who}"
                    report['conflicts'].append(det)
                    report['labels'].append('proxy service (negotiated)')
                report['proxy_detail'] = '; '.join(
                    f"{p['port']}/{p['proto']}:{p['state']}" for p in px)
                report['methods'].append(
                    {'name': 'PROX', 'cc': '', 'city': '',
                     'status': 'conflict' if (states or auth or answer) else 'info',
                     'detail': report['proxy_detail'] or 'no proxy service answered'})

            # --- 19d) TLSALT — certificate grab on alt VPN/TLS ports. OpenVPN's
            # TCP listener on 1194 serves a TLS cert that usually names the
            # provider or the OpenVPN/Easy-RSA toolchain itself.
            ta = probes.get('tlsalt')
            if ta:
                report['tlsalt_port'] = ta.get('port', 0)
                report['tlsalt_cn'] = ta.get('cn', '')
                report['tlsalt_org'] = ta.get('org', '')
                blob = ' '.join(str(x) for x in
                                (ta.get('cn', ''), ta.get('org', ''),
                                 ta.get('issuer', ''), *ta.get('sans', []))).lower()
                vpn_hit = next((kw for kw in _VPN_ORG_MARKERS if kw in blob), None)
                vpn_hit = vpn_hit or ('openvpn' if 'openvpn' in blob or 'easy-rsa'
                                        in blob or 'easyrsa' in blob else None)
                det = (f"tcp/{ta.get('port')} cert CN={ta.get('cn') or '?'} "
                       f"O={ta.get('org') or '?'} iss={ta.get('issuer') or '?'}")
                if vpn_hit:
                    det += f" — '{vpn_hit.strip()}' names VPN infrastructure"
                    report['is_vpn'] = True
                    report['conflicts'].append(det)
                    report['labels'].append(
                        f"VPN identity in alt-port TLS cert ({vpn_hit.strip()})")
                report['methods'].append(
                    {'name': 'TLSALT', 'cc': '', 'city': '',
                     'status': 'conflict' if vpn_hit else 'info', 'detail': det})

            # --- 19e) BANNER — service banners yield a THIRD OS-family signal
            # (independent of ping TTL and passive TCP fp) and often a real
            # hostname. An OS-class triple-disagreement means middlebox/NAT.
            bn = probes.get('banner')
            if bn:
                report['banner_ports'] = [b.get('port') for b in bn]
                bos = next((b.get('os') for b in bn if b.get('os')), '')
                bhost = next((b.get('host') for b in bn if b.get('host')), '')
                report['banner_os'] = bos
                report['banner_host'] = bhost
                det = '; '.join(f"{b['port']}/{b['proto']}: {b['banner'][:48]}"
                                for b in bn[:3])
                # OS triple-check — banner vs ping TTL vs passive TCPFP.
                _os_set = {o for o in (bos, report.get('ttl_os', ''),
                                      report.get('tcpfp_os', '')) if o}
                _wins = sum('windows' in o.lower() for o in _os_set)
                _unix = sum(('windows' not in o.lower() and
                             'net-device' not in o.lower()) for o in _os_set)
                if len(_os_set) >= 2 and _wins and _unix:
                    det += (f" — OS classes disagree across "
                            f"{len(_os_set)} signals: middlebox/NAT on path")
                    report['conflicts'].append(
                        f"OS split: banner={bos or '?'} ttl={report.get('ttl_os') or '?'} "
                        f"tcpfp={report.get('tcpfp_os') or '?'}")
                    report['labels'].append('OS fingerprint triple-disagreement')
                    _st = 'conflict'
                else:
                    _st = 'info'
                if bhost and report.get('rdns') and \
                        bhost.lower() != report['rdns'].lower():
                    det += f" · host '{bhost}' differs from rDNS"
                report['methods'].append(
                    {'name': 'BANNER', 'cc': '', 'city': '', 'status': _st,
                     'detail': det})

            # --- 19f) WIRE — passive silent-tunnel / non-IP-channel evidence.
            # The protocols that defeat EVERY active probe are proven here by
            # their own on-wire signatures: WireGuard answers no
            # unauthenticated packet (it is the literal "one-way encrypted
            # send-out" — a WG peer black-holes strangers entirely), ESP/GRE
            # carry no port layer for a scan to find, ICMP tunnels ride echo
            # bodies, and Shadowsocks/V2Ray/obfs4 transports are engineered to
            # be indistinguishable noise — which is itself the signature.
            quic_r = probes.get('quic')
            if quic_r:
                report['quic'] = True
                report['quic_versions'] = quic_r.get('versions', [])
                det = (f"QUIC Version-Negotiation on udp/{quic_r.get('port', 443)}"
                       f" ({len(report['quic_versions'])} version(s): "
                       f"{', '.join(report['quic_versions'][:5])}) — the "
                       f"endpoint speaks HTTP/3: MASQUE-class relays "
                       f"(connect-udp / connect-ip) ride this transport")
                report['methods'].append(
                    {'name': 'QUICV', 'cc': '', 'city': '',
                     'status': 'info', 'detail': det})

            wire = wire_hint or {}
            if wire:
                # WireGuard — the silent VPN. Types 1-3 are exact-size
                # handshake messages (proof-positive); transport-data packets
                # need volume to count.
                wg_shake = sum(int(wire.get(k) or 0) for k in ('wg1', 'wg2', 'wg3'))
                wg_data = int(wire.get('wg4') or 0)
                if wg_shake:
                    report['wire_wg'] = wg_shake
                    kinds = ', '.join(
                        f"{_WG_MSG_NAMES[int(k[2:])]}×{wire[k]}"
                        for k in ('wg1', 'wg2', 'wg3') if wire.get(k))
                    det = (f"WireGuard handshake ON THE WIRE ({kinds}) — the "
                           f"tunnel that answers no probe identified itself; "
                           f"an unprobeable VPN proven by its own traffic")
                    report['conflicts'].append(det)
                    report['labels'].append('WireGuard tunnel (on-wire handshake)')
                    report['is_vpn'] = True
                    report['methods'].append(
                        {'name': 'WGWIRE', 'cc': '', 'city': '',
                         'status': 'conflict', 'detail': det})
                elif wg_data >= 4:
                    report['wire_wg'] = wg_data
                    det = (f"{wg_data} WireGuard transport-data packets on the "
                           f"wire (handshake not yet sampled) — encrypted WG "
                           f"channel signature")
                    report['conflicts'].append(det)
                    report['labels'].append('WireGuard data channel (on-wire)')
                    report['is_vpn'] = True
                    report['methods'].append(
                        {'name': 'WGWIRE', 'cc': '', 'city': '',
                         'status': 'conflict', 'detail': det})
                # OpenVPN — reset opcodes are unique to OpenVPN session setup.
                # False-positive guard: a random payload's first byte lands in
                # the opcode range ~34% of the time, so hits ALONE prove
                # nothing. The discriminator is opcode diversity — a real
                # OpenVPN session speaks a few opcodes (reset + control +
                # data), while noise scatters across all 11 values.
                ops = wire.get('ovpn') or {}
                if ops:
                    reset_hits = sum(ops.get(f'ovpn{o}', 0)
                                     for o in _OVPN_RESET_OPS)
                    ctrl_hits = sum(v for k, v in ops.items()
                                    if k not in ('ovpn6', 'ovpn9'))
                    n_ops = len(ops)
                    total = sum(ops.values())
                    real_shape = n_ops <= 6
                    if (reset_hits >= 2 and real_shape) or \
                            (reset_hits >= 1 and n_ops <= 3 and total >= 3) or \
                            (ctrl_hits >= 4 and n_ops <= 4):
                        opnames = ', '.join(
                            _OVPN_OPS.get(int(k[4:]), k) + f'×{v}'
                            for k, v in list(ops.items())[:4]
                            if k[4:].isdigit())
                        report['wire_ovpn'] = opnames
                        det = (f"OpenVPN control traffic ON THE WIRE "
                               f"({opnames}) — session-setup opcodes unique "
                               f"to OpenVPN")
                        report['conflicts'].append(det)
                        report['labels'].append('OpenVPN tunnel (on-wire opcodes)')
                        report['is_vpn'] = True
                        report['methods'].append(
                            {'name': 'OVPNOP', 'cc': '', 'city': '',
                             'status': 'conflict', 'detail': det})
                    elif ctrl_hits or reset_hits:
                        report['methods'].append(
                            {'name': 'OVPNOP', 'cc': '', 'city': '',
                             'status': 'info',
                             'detail': f"OpenVPN-shaped UDP payloads ×{total} "
                                       f"across {n_ops} opcode values — "
                                       f"inconclusive (noise scatters wider)"})
                # DTLS on UDP — AnyConnect/F5/WebRTC-class encrypted transport.
                if wire.get('dtls'):
                    report['wire_dtls'] = wire['dtls']
                    det = (f"DTLS records on the wire ×{wire['dtls']} — UDP TLS "
                           f"transport (AnyConnect/F5-class VPN or WebRTC)")
                    report['conflicts'].append(det)
                    report['labels'].append('DTLS transport on UDP')
                    report['methods'].append(
                        {'name': 'DTLSOP', 'cc': '', 'city': '',
                         'status': 'conflict', 'detail': det})
                # Non-port IP tunnels — protocols a port scan can never see.
                l3 = wire.get('l3') or {}
                if l3:
                    report['wire_l3'] = dict(l3)
                    vpn_l3 = {n: c for n, c in l3.items()
                              if n in _L3_VPN_NAMES}
                    encap_l3 = {n: c for n, c in l3.items()
                                if n in _L3_ENCAP_NAMES}
                    other_l3 = {n: c for n, c in l3.items()
                                if n not in _L3_VPN_NAMES | _L3_ENCAP_NAMES}
                    if vpn_l3:
                        det = (f"non-port tunnel protocols ON THE WIRE: "
                               + ', '.join(f"{n}×{c}" for n, c in vpn_l3.items())
                               + " — encrypted payload protocols no scan finds")
                        report['conflicts'].append(det)
                        report['labels'].append('L3 tunnel traffic (ESP/GRE-class)')
                        report['is_vpn'] = True
                        report['methods'].append(
                            {'name': 'L3TUN', 'cc': '', 'city': '',
                             'status': 'conflict', 'detail': det})
                    if encap_l3:
                        det = ('encapsulation protocols on the wire: '
                               + ', '.join(f"{n}×{c}" for n, c in encap_l3.items())
                               + " — IP-in-IP/transition tunnels, non-port "
                                 "channels a scan cannot see")
                        report['conflicts'].append(det)
                        report['labels'].append('L3 encap tunnel on-wire')
                        report['methods'].append(
                            {'name': 'L3TUN', 'cc': '', 'city': '',
                             'status': 'conflict', 'detail': det})
                    if other_l3:
                        report['methods'].append(
                            {'name': 'L3TUN', 'cc': '', 'city': '',
                             'status': 'info',
                             'detail': 'encap/infra protocols: ' +
                                       ', '.join(f"{n}×{c}"
                                                 for n, c in other_l3.items())})
                # ICMP data channel — ping packets carrying payload.
                if wire.get('icmp', 0) >= 2:
                    report['icmp_tun'] = wire['icmp']
                    det = (f"ICMP data channel: ×{wire['icmp']} oversized echo "
                           f"payloads (max {wire.get('icmp_big', 0)}B — normal "
                           f"echo carries ~56B): a tunnel riding ping packets")
                    report['conflicts'].append(det)
                    report['labels'].append('ICMP data channel')
                    report['methods'].append(
                        {'name': 'ICMPTUN', 'cc': '', 'city': '',
                         'status': 'conflict', 'detail': det})
                elif wire.get('icmp'):
                    report['icmp_tun'] = wire['icmp']
                    report['methods'].append(
                        {'name': 'ICMPTUN', 'cc': '', 'city': '',
                         'status': 'info',
                         'detail': f"{wire['icmp']} oversized ICMP payload "
                                   f"(max {wire.get('icmp_big', 0)}B)"})
                # Teredo — IPv6-over-UDP transition tunnel.
                if wire.get('teredo'):
                    report['methods'].append(
                        {'name': 'TUN6', 'cc': '', 'city': '', 'status': 'info',
                         'detail': f"Teredo IPv6-transition tunnel traffic "
                                   f"×{wire['teredo']} — IPv6 rides UDP/3544, "
                                   f"outside the IPv4 path checks"})
                # Obfuscated transport — sustained high-entropy payloads that
                # match NO protocol header = built-to-be-unrecognizable
                # traffic: Shadowsocks / V2Ray VMess / obfs4 / SSTP-class masks.
                enc = int(wire.get('enc') or 0)
                report['enc_flows'] = enc
                if enc >= 3:
                    det = (f"{enc} high-entropy payloads (H≈"
                           f"{wire.get('enc_ent', 7.5)}) with NO protocol "
                           f"header — obfuscated encrypted transport "
                           f"(Shadowsocks/V2Ray/obfs4-class): traffic "
                           f"engineered to be unrecognizable")
                    report['conflicts'].append(det)
                    report['labels'].append('obfuscated encrypted transport')
                    report['methods'].append(
                        {'name': 'ENCF', 'cc': '', 'city': '',
                         'status': 'conflict', 'detail': det})
                elif enc:
                    report['methods'].append(
                        {'name': 'ENCF', 'cc': '', 'city': '',
                         'status': 'info',
                         'detail': f"{enc} unidentified high-entropy payload(s)"})
                # TLS on a non-standard port / WebSocket masked tunnel.
                if wire.get('tls_weird'):
                    report['tls_weird'] = wire['tls_weird']
                    report['methods'].append(
                        {'name': 'TLSW', 'cc': '', 'city': '', 'status': 'info',
                         'detail': f"TLS records on non-standard port "
                                   f"×{wire['tls_weird']} — covert TLS channel"})
                if wire.get('wstun'):
                    report['wstun'] = wire['wstun']
                    report['methods'].append(
                        {'name': 'WSTUN', 'cc': '', 'city': '', 'status': 'info',
                         'detail': f"WebSocket upgrade ×{wire['wstun']} — "
                                   f"HTTP-masked tunnel transport"})
                # Hidden service names — ECH encrypts the real SNI; an absent
                # SNI is a direct-IP TLS connect; an SNI never seen in local
                # DNS answers was never resolved here — fronting suspects.
                if wire.get('ech'):
                    report['ech_seen'] = True
                    report['methods'].append(
                        {'name': 'ECH', 'cc': '', 'city': '', 'status': 'info',
                         'detail': "Encrypted ClientHello — real service name "
                                   "is hidden; the visible SNI is a cover "
                                   "name (domain-fronting capable endpoint)"})
                report['no_sni'] = int(wire.get('no_sni') or 0)
                sni_seen = {str(s).lower() for s in (wire.get('sni') or set())}
                dns_names = {str(d).lower()
                             for d in (wire.get('dns_names') or set())}
                unresolved = sorted(
                    s for s in sni_seen
                    if not any(s == d or s.endswith('.' + d)
                               or d.endswith('.' + s) for d in dns_names))
                report['sni_unresolved'] = unresolved
                frontable = [s for s in unresolved
                             if any(f in s for f in _FRONTABLE_CDNS)]
                if frontable:
                    report['fronting'] = True
                    det = (f"SNI names never resolved via local DNS and hosted "
                           f"on a frontable CDN: {', '.join(frontable[:3])} — "
                           f"domain-fronting signature (the visible name masks "
                           f"the real backend)")
                    report['conflicts'].append(det)
                    report['labels'].append('domain-fronting suspect')
                    report['methods'].append(
                        {'name': 'SNIFX', 'cc': '', 'city': '',
                         'status': 'conflict', 'detail': det})
                elif unresolved:
                    report['methods'].append(
                        {'name': 'SNIFX', 'cc': '', 'city': '', 'status': 'info',
                         'detail': f"SNI not seen in DNS answers: "
                                   f"{', '.join(unresolved[:3])} — direct-IP/"
                                   f"fronted connect"})
                elif sni_seen:
                    report['methods'].append(
                        {'name': 'SNIFX', 'cc': '', 'city': '', 'status': 'info',
                         'detail': f"{len(sni_seen)} SNI name(s), all resolved "
                                   f"via local DNS — no fronting signal"})
                # DEADDROP — the "non-VPN data server" mask: an endpoint
                # that exists purely to accept anonymous uploads / serve
                # stored blobs is a data courier, not a service. SNI and
