                                f'<td class="{risk_cls}">{esc(p["risk"])}</td>'
                                f'<td>{esc(p.get("ml_score",""))}</td>'
                                f'<td>{esc(p["connections"])}</td>'
                                f'<td>{esc(p.get("destinations",""))}</td>'
                                f'<td>{esc(", ".join(p.get("countries", [])))}</td>'
                                f'<td>{esc(p.get("cpu_percent",""))}</td>'
                                f'<td>{esc(p.get("memory_mb",""))}</td>'
