    _TRACK_PARAMS = frozenset({
        'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'utm_id',
        'utm_name', 'utm_reader', 'utm_referrer', 'utm_social', 'utm_brand', 'utm_viz_id',
        'fbclid', 'gclid', 'gbraid', 'wbraid', 'dclid', 'msclkid', 'mc_cid', 'mc_eid',
        '_hsenc', '_hsmi', 'hsa_cam', 'hsa_grp', 'hsa_mt', 'hsa_src', 'hsa_ad', 'hsa_acc',
        'hsa_net', 'hsa_ver', 'hsa_la', 'hsa_ol', 'hsa_kw', 'oly_anon_id', 'oly_enc_id',
        'vero_id', 'wickedid', 'yclid', 'igshid', 'si', 'spm', 'twclid', 'ttclid', 'zanpid',
        'pk_campaign', 'pk_kwd', 'pk_source', 'pk_medium', 'pk_cid', 'ref_src', 'ref_url',
    })
    # id/class tokens that almost always mean ad/tracker furniture — used to clean
    # reading surfaces. Only whole tokens match, so 'header'/'read'/etc. are safe.
    _AD_TOKENS = frozenset({
        'ad', 'ads', 'advert', 'adverts', 'advertisement', 'sponsored', 'sponsor',
        'promo', 'promoted', 'adslot', 'ad-slot', 'adspace', 'adsbox', 'adbox',
        'adcontainer', 'ad-container', 'adwrapper', 'ad-wrapper', 'adframe', 'ad-frame',
        'adunit', 'ad-unit', 'dfp', 'gpt', 'gpt-ad', 'native-ad', 'in-feed', 'outbrain',
        'taboola', 'doubleclick', 'leaderboard-ad', 'skyscraper-ad', 'ad-banner',
    })
    _TRACK_HOST_FRAGS = ('doubleclick', 'googlesyndication', 'google-analytics',
                         'googletagmanager', 'adservice', 'adsystem', 'adnxs',
                         'criteo', 'scorecardresearch', 'outbrain', 'taboola',
                         'hotjar', 'fullstory', 'facebook.net', 'analytics')


    def _strip_track_params(abs_url):
        """Drop tracking query params from a resolved URL (fast path when clean)."""
        try:
            if '?' not in abs_url:
                return abs_url
            parts = urllib.parse.urlsplit(abs_url)
            pairs = urllib.parse.parse_qsl(parts.query, keep_blank_values=True)
            kept = [(k, v) for k, v in pairs if k.lower() not in _TRACK_PARAMS]
            if len(kept) == len(pairs):
                return abs_url
            new_q = urllib.parse.urlencode(kept, doseq=True)
            return urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path, new_q, parts.fragment))
        except Exception:
            return abs_url


    def _is_ad_element(tag):
        """Heuristic: element id/class tokens or src host say 'advertisement'."""
        attrs = ' '.join(filter(None, [str(tag.get('id') or ''), ' '.join(tag.get('class') or [])]))
        toks = set(t.lower() for t in re.split(r'[\s_\-]+', attrs) if t)
        if toks & _AD_TOKENS:
            return True
        for attr in ('src', 'data-src', 'href'):
            v = tag.get(attr) or ''
            if v and any(f in v for f in _TRACK_HOST_FRAGS):
                return True
        return False


    def rewrite_for_browse(markup, base_url):
        """Sanitize + rewrite a fetched page for in-app reading:
    strips scripts/iframes/forms, makes resources absolute, routes links back
    through /browse so navigation stays inside GNA."""
        soup = _bs4_soup(markup)
        if soup:
            for tag in soup(['script', 'iframe', 'object', 'embed', 'form', 'noscript']):
                tag.decompose()
            for tag in soup.find_all(['ins', 'amp-ad', 'amp-embed']):
                tag.decompose()
            for tag in soup.find_all('meta'):
                if (tag.get('http-equiv') or '').lower() == 'refresh': tag.decompose()
            for tag in soup.find_all(['div', 'section', 'aside', 'span', 'figure', 'a', 'img', 'picture', 'svg']):
                if _is_ad_element(tag):
                    tag.decompose()
            for a in soup.find_all('a', href=True):
                href = a['href'].strip()
                if href.startswith(('javascript:', 'data:', 'mailto:', 'tel:', '#')):
                    continue
                abs_url = _strip_track_params(urllib.parse.urljoin(base_url, href))
                if abs_url.startswith(('http://', 'https://')):
                    a['href'] = '/browse?url=' + urllib.parse.quote(abs_url, safe='')
            for tag, attr in (('img', 'src'), ('link', 'href'), ('source', 'src'), ('video', 'src'), ('audio', 'src')):
                for el in soup.find_all(tag):
                    v = el.get(attr)
                    if v and not v.startswith('data:'):
                        el[attr] = urllib.parse.urljoin(base_url, v)
            for el in soup.find_all(srcset=True):
                parts = []
                for chunk in el['srcset'].split(','):
                    bits = chunk.strip().split()
                    if bits:
                        parts.append(urllib.parse.urljoin(base_url, bits[0]) + (' ' + bits[1] if len(bits) > 1 else ''))
                el['srcset'] = ', '.join(parts)
            for el in soup.find_all(style=True):
                el['style'] = re.sub(r'url\((["\']?)(?!data:|https?:|/browse)([^)"\']+)\1\)',
                                     lambda m: 'url(' + urllib.parse.urljoin(base_url, m.group(2)) + ')', el['style'])
            body = soup.find('body')
            toolbar = _bs4_soup('<div id="__tb">' + _browse_toolbar(base_url) + '</div>')
            tb = toolbar.find('div', id='__tb') if toolbar else None
            if body and tb:
                body.insert(0, tb)
            return str(soup)
        # no bs4 — regex fallback
        text = re.sub(r'(?is)<(script|iframe|object|embed|form)[^>]*>.*?</\1>', '', markup)
        def _link_sub(m):
            href = m.group(2)
            if href.startswith(('javascript:', 'data:', 'mailto:', '#')):
                return m.group(0)
            abs_url = urllib.parse.urljoin(base_url, href)
            if not abs_url.startswith(('http://', 'https://')):
                return m.group(0)
            return m.group(1) + '"/browse?url=' + urllib.parse.quote(abs_url, safe='') + '"'
        text = re.sub(r'(<a\s[^>]*href=)["\']([^"\']+)["\']', _link_sub, text, flags=re.IGNORECASE)
        text = re.sub(r'(<(?:img|source|video|audio|link)\s[^>]*(?:src|href)=)["\'](?!data:|https?:|/browse)([^"\']+)["\']',
                      lambda m: m.group(1) + '"' + urllib.parse.urljoin(base_url, m.group(2)) + '"', text, flags=re.IGNORECASE)
        return _browse_toolbar(base_url) + text


    _VIDEO_FILE_EXT = {'.mp4', '.webm', '.m4v', '.mov', '.ogv', '.ts'}
    _AUDIO_FILE_EXT = {'.mp3', '.m4a', '.aac', '.ogg', '.oga', '.opus', '.flac', '.wav'}


    def _video_embed_for(url):
        """Return a player descriptor for URLs that are playable media:
    provider watch pages map to their embed endpoints (the embed runs the
    provider's real player inside an iframe, which the sanitized article
    view strips), direct media files play through <video>/<audio> sourced
    via /api/fetch (same-origin, no hotlink Referer), HLS playlists use
    hls.js. Returns None for ordinary pages."""
        try:
            p = urllib.parse.urlsplit(url)
        except Exception:
            return None
        host = (p.hostname or '').lower()
        path = p.path or ''
        q = urllib.parse.parse_qs(p.query)
        ext = os.path.splitext(path)[1].lower()

        # --- direct media files ---
        if ext == '.m3u8':
            return {'kind': 'hls', 'src': url, 'label': 'HLS stream'}
        if ext in _VIDEO_FILE_EXT:
            return {'kind': 'video', 'label': 'video',
                    'src': '/api/fetch?url=' + urllib.parse.quote(url, safe='')}
        if ext in _AUDIO_FILE_EXT:
            return {'kind': 'audio', 'label': 'audio',
                    'src': '/api/fetch?url=' + urllib.parse.quote(url, safe='')}

        # --- provider watch pages -> embed endpoints ---
        yt_id = None
        if host in ('www.youtube.com', 'youtube.com', 'm.youtube.com',
                    'music.youtube.com', 'youtube-nocookie.com',
                    'www.youtube-nocookie.com'):
            if path == '/watch' and q.get('v'):
                yt_id = q['v'][0]
            else:
                m = re.match(r'^/(?:shorts|live|embed|v)/([\w-]{6,20})', path)
                if m:
                    yt_id = m.group(1)
        elif host == 'youtu.be':
            m = re.match(r'^/([\w-]{6,20})', path)
            if m:
                yt_id = m.group(1)
        if yt_id:
            return {'kind': 'iframe', 'label': 'YouTube',
                    'src': 'https://www.youtube-nocookie.com/embed/' + yt_id + '?autoplay=1&rel=0'}
        if host.endswith('vimeo.com'):
            m = re.match(r'^/(?:video/)?(\d{6,12})', path)
            if m:
                return {'kind': 'iframe', 'label': 'Vimeo',
                        'src': 'https://player.vimeo.com/video/' + m.group(1) + '?autoplay=1'}
        if 'dailymotion' in host:
            m = re.search(r'/video/(\w+)', path)
            if m:
                return {'kind': 'iframe', 'label': 'Dailymotion',
                        'src': 'https://www.dailymotion.com/embed/video/' + m.group(1) + '?autoplay=1'}
        if host == 'dai.ly':
            m = re.match(r'^/(\w+)', path)
            if m:
                return {'kind': 'iframe', 'label': 'Dailymotion',
                        'src': 'https://www.dailymotion.com/embed/video/' + m.group(1) + '?autoplay=1'}
        if host == 'clips.twitch.tv':
            m = re.match(r'^/(\w+)', path)
            if m:
                return {'kind': 'iframe', 'label': 'Twitch clip',
                        'src': 'https://clips.twitch.tv/embed?clip=' + m.group(1) +
                               '&parent=127.0.0.1&parent=localhost&autoplay=true'}
        if host.endswith('twitch.tv'):
            m = re.match(r'^/videos/(\d+)', path)
            if m:
                return {'kind': 'iframe', 'label': 'Twitch',
                        'src': 'https://player.twitch.tv/?video=v' + m.group(1) +
                               '&parent=127.0.0.1&parent=localhost&autoplay=true'}
        if 'bitchute' in host:
            m = re.match(r'^/video/([\w-]+)', path)
            if m:
                return {'kind': 'iframe', 'label': 'BitChute',
                        'src': 'https://www.bitchute.com/embed/' + m.group(1) + '/'}
        if 'rumble' in host:
            m = re.match(r'^/(v\w+)-', path)
            if m:
                return {'kind': 'iframe', 'label': 'Rumble',
                        'src': 'https://rumble.com/embed/' + m.group(1) + '/'}
        if 'streamable' in host:
            m = re.match(r'^/(?:e/)?(\w+)', path)
            if m:
                return {'kind': 'iframe', 'label': 'Streamable',
                        'src': 'https://streamable.com/e/' + m.group(1) + '?autoplay=1'}
        if 'tiktok' in host:
            m = re.search(r'/video/(\d{10,25})', path)
            if m:
                return {'kind': 'iframe', 'label': 'TikTok',
                        'src': 'https://www.tiktok.com/embed/v2/' + m.group(1)}
        if 'bilibili' in host:
            m = re.search(r'/video/(BV\w+)', path)
            if m:
                return {'kind': 'iframe', 'label': 'Bilibili',
                        'src': 'https://player.bilibili.com/player.html?bvid=' + m.group(1) + '&autoplay=1'}
        if 'odysee' in host or 'lbry' in host:
            segs = [s for s in path.split('/') if s]
            if segs:
                return {'kind': 'iframe', 'label': 'Odysee',
                        'src': 'https://odysee.com/$/embed/' + path.lstrip('/')}
        # PeerTube watch URLs are /w/{id} on each instance's own domain.
        if 'peertube' in host or re.match(r'^/w/[\w-]{4,}', path):
            m = re.match(r'^/w/([\w-]+)', path)
            if m:
                return {'kind': 'iframe', 'label': 'PeerTube',
                        'src': 'https://' + host + '/videos/embed/' + m.group(1) + '?autoplay=1'}
        return None


    def _video_player_page(url, embed):
        """Full-viewport player page — what /browse serves for playable media
    links instead of the sanitized article view (which strips the scripts
    and iframes every provider's player needs)."""
        kind = embed['kind']
        src = _html_lib.escape(embed['src'], quote=True)
        if kind == 'iframe':
            player = ('<iframe src="' + src + '" style="width:100%;height:calc(100vh - 37px);border:0" '
                      'allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen" '
                      'allowfullscreen referrerpolicy="no-referrer-when-downgrade"></iframe>')
        elif kind == 'hls':
            player = ('<video id="v" data-src="' + src + '" controls autoplay style="width:100%;height:calc(100vh - 37px);background:#000"></video>'
                      '<script src="https://cdn.jsdelivr.net/npm/hls.js@1"></script>'
                      '<script>var v=document.getElementById("v"),s=v.dataset.src;if(window.Hls&&Hls.isSupported()){var h=new Hls();h.loadSource(s);h.attachMedia(v);}else if(v.canPlayType("application/vnd.apple.mpegurl")){v.src=s;}</script>')
        elif kind == 'audio':
            player = ('<div style="display:flex;align-items:center;justify-content:center;height:calc(100vh - 37px)">'
                      '<audio src="' + src + '" controls autoplay style="width:min(680px,90vw)"></audio></div>')
        else:
            player = ('<video src="' + src + '" controls autoplay '
                      'style="width:100%;height:calc(100vh - 37px);background:#000"></video>')
        return ('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>' +
                _html_lib.escape(embed.get('label') or 'media') + ' — GNA Player</title></head>'
                '<body style="margin:0;background:#000">' +
                _browse_toolbar(url).replace('Reader mode', 'Playing &middot; ' + _html_lib.escape(embed.get('label') or 'media')) +
                player + '</body></html>')


    def _extract_article(markup, base_url):
        """Readability-style extraction: locate the densest text container on the
    page and re-render it in a clean reading layout. Falls back to the normal
    sanitized rewrite when no good candidate exists."""
        soup = _bs4_soup(markup)
        if not soup:
            return rewrite_for_browse(markup, base_url)
        for tag in soup(['script', 'iframe', 'object', 'embed', 'form', 'noscript',
                         'nav', 'header', 'footer', 'aside', 'button', 'select',
                         'input', 'textarea', 'ins', 'style']):
            tag.decompose()
        for tag in soup.find_all('meta'):
            if (tag.get('http-equiv') or '').lower() == 'refresh':
                tag.decompose()
        title = ''
        try:
            title = _clean_text(soup.title.get_text(' ')) if soup.title else ''
            for junk in (' | ', ' — ', ' - ', ' » ', ' · ', ' :: '):
                if junk in title:
                    head = title.split(junk)[0].strip()
                    if len(head) >= 8:
                        title = head
                        break
        except Exception:
            pass

        def _score(tag):
            try:
                text = tag.get_text(' ', strip=True)
                if len(text) < 120:
                    return 0
                link_txt = sum(len(a.get_text(' ', strip=True)) for a in tag.find_all('a'))
                density = link_txt / max(1, len(text))
                score = len(text) + 90 * len(tag.find_all('p'))
                score *= max(0.0, 1.0 - density * 2.2)
                name = ' '.join([str(tag.get('id') or ''), ' '.join(tag.get('class') or [])]).lower()
                if re.search(r'article|content|post|entry|story|body|main|text|read', name):
                    score *= 1.35
                if re.search(r'comment|footer|sidebar|nav|menu|related|promo|share|social|widget|modal|banner', name):
                    score *= 0.3
                return score
            except Exception:
                return 0

        candidates = soup.find_all(['article', 'main']) + \
            soup.find_all(attrs={'role': 'main'}) + \
            soup.find_all(['div', 'section'])[:400]
        best, best_score = None, 0
        for tag in candidates:
            s = _score(tag)
            if s > best_score:
                best, best_score = tag, s
        if best is None or best_score < 400:
            return rewrite_for_browse(markup, base_url)

        for tag in best.find_all(['div', 'section', 'aside', 'span', 'figure', 'a', 'img', 'picture', 'svg']):
            if _is_ad_element(tag):
                tag.decompose()
        for tag in best.find_all(True):
            for attr in ('onclick', 'onload', 'onerror', 'style', 'class', 'id'):
                tag.attrs.pop(attr, None)
        for a in best.find_all('a', href=True):
            href = a['href'].strip()
            if href.startswith(('javascript:', 'data:', 'mailto:', 'tel:', '#')):
                continue
            abs_url = _strip_track_params(urllib.parse.urljoin(base_url, href))
            if abs_url.startswith(('http://', 'https://')):
                a['href'] = '/browse?url=' + urllib.parse.quote(abs_url, safe='')
        for tag, attr in (('img', 'src'), ('source', 'src'), ('video', 'src'), ('audio', 'src')):
            for el in best.find_all(tag):
                v = el.get(attr)
                if v and not v.startswith('data:'):
                    el[attr] = urllib.parse.urljoin(base_url, v)
        for el in best.find_all(srcset=True):
            parts = []
            for chunk in el['srcset'].split(','):
                bits = chunk.strip().split()
                if bits:
                    parts.append(urllib.parse.urljoin(base_url, bits[0]) + (' ' + bits[1] if len(bits) > 1 else ''))
            el['srcset'] = ', '.join(parts)

        css = ('body{background:#0d1117;color:#e6edf3;font:18px/1.7 Georgia,serif;margin:0;}'
               '.read{max-width:740px;margin:0 auto;padding:26px 22px 60px}'
               'h1{font:700 1.55em/1.25 "Segoe UI",system-ui,sans-serif;color:#fff;margin:.4em 0 .7em}'
               'h1 a{color:#fff;text-decoration:none}'
               'a{color:#58a6ff}img,video{max-width:100%;height:auto;border-radius:6px}'
               'p{margin:0 0 1.05em}pre,code{font-family:Consolas,monospace;background:#161b22;border-radius:5px}'
               'pre{padding:12px;overflow-x:auto}blockquote{border-left:3px solid #58a6ff;margin:1em 0;padding:2px 16px;color:#c9d1d9}'
               'figure{margin:1.2em 0}figcaption{font-size:.8em;color:#8b949e;text-align:center;margin-top:6px}'
               'table{border-collapse:collapse;width:100%;margin:1em 0}td,th{border:1px solid #30363d;padding:6px 10px;font-size:.9em}')
        return ('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>' +
                _html_lib.escape(title or 'Reader') + '</title><style>' + css + '</style></head><body>' +
                _browse_toolbar(base_url) +
                '<div class="read">' +
                ('<h1><a href="/browse?url=' + urllib.parse.quote(base_url, safe='') + '">' +
                 _html_lib.escape(title) + '</a></h1>' if title else '') +
                str(best) + '</div></body></html>')


