            ('sys-audio-btn', 'Sys Audio'), ('input-monitor-btn', 'Keylog'),
            ('wol-btn', 'Wake-on-LAN'), ('app-launch-btn', 'App Launch'),
            ('file-exec-btn', 'File Exec'), ('disk-info-btn', 'Disk Info'),
