        @app.route('/browse')
        def browse_proxy():
            url = (flask_request.args.get('url') or '').strip()
            if not url: return redirect('/internet')
            if not re.match(r'^https?://', url, re.IGNORECASE):
                url = 'https://' + url
            try:
                parsed = urllib.parse.urlsplit(url)
                if parsed.scheme not in ('http', 'https') or not parsed.netloc:
                    return render_browse_error(url, 'Only http:// and https:// addresses can be browsed.')
            except Exception:
                return render_browse_error(url, 'Invalid address.')
            # Playable media (provider watch pages, direct video/audio files,
            # HLS streams) gets a real player page — the sanitized article view
            # below strips the scripts/iframes every player needs.
            embed = _video_embed_for(url)
            if embed:
                return Response(_video_player_page(url, embed),
                                content_type='text/html; charset=utf-8')
            mode = flask_request.args.get('mode', '')
            prefetch = flask_request.args.get('pre') == '1'
            cache_key = url + '|' + ('reader' if mode == 'reader' else 'clean')
            hit = _browse_cache_get(cache_key)
            if hit is not None:
                if prefetch: return ('', 204)
                body, ctype = hit
                return Response(body, content_type=ctype)
            try:
                resp = _HTTP_SESSION.get(url, headers=_WEB_UA, timeout=12, stream=True,
                                    allow_redirects=True, verify=True)
                chunks, size = [], 0
                for chunk in resp.iter_content(chunk_size=65536):
                    chunks.append(chunk); size += len(chunk)
                    if size > 3 * 1024 * 1024: break
                raw = b''.join(chunks)
            except requests.exceptions.SSLError:
                try:
                    resp = _HTTP_SESSION.get(url, headers=_WEB_UA, timeout=12, verify=False)
                    raw = resp.content[:3 * 1024 * 1024]
                except Exception as e2:
                    if prefetch: return ('', 204)
                    return render_browse_error(url, e2)
            except Exception as e:
                if prefetch: return ('', 204)
                return render_browse_error(url, e)
            final_url = resp.url
            ctype = (resp.headers.get('Content-Type') or '').split(';')[0].strip().lower()
            if ctype and 'html' not in ctype and not ctype.startswith('text/'):
                _browse_cache_put(cache_key, raw, ctype)
                if prefetch: return ('', 204)
                return Response(raw, content_type=ctype)
            try:
                text = raw.decode(resp.encoding or 'utf-8', errors='replace')
            except Exception:
                text = raw.decode('utf-8', errors='replace')
            body = (_extract_article(text, final_url) if mode == 'reader'
                    else rewrite_for_browse(text, final_url))
            _browse_cache_put(cache_key, body, 'text/html; charset=utf-8')
            if prefetch: return ('', 204)
            return Response(body, content_type='text/html; charset=utf-8')

