        @app.route('/api/fetch')
        def fetch_proxy():
            """Same-origin fetch proxy used by the browser chrome for downloads,
        save-page, and view-source on remote URLs. Streams with a hard cap."""
            url = (flask_request.args.get('url') or '').strip()
            if not re.match(r'^https?://', url, re.IGNORECASE):
                return jsonify({'error': 'Only http:// and https:// URLs allowed'}), 400
            name = re.sub(r'[^\w.\- ()\[\]{}&+=]', '_', (flask_request.args.get('name') or '').strip())[:120]
            try:
                resp = _HTTP_SESSION.get(url, headers=_WEB_UA, timeout=25, stream=True,
                                    verify=False, allow_redirects=True)
            except Exception as e:
                return jsonify({'error': f'Fetch failed: {e}'}), 502
            def gen():
                sent = 0
                try:
                    for chunk in resp.iter_content(chunk_size=65536):
                        sent += len(chunk)
                        if sent > 200 * 1024 * 1024:
                            break
                        yield chunk
                finally:
                    resp.close()
            headers = {}
            if flask_request.args.get('raw'):
                headers['Content-Type'] = 'text/plain; charset=utf-8'
            else:
                headers['Content-Type'] = resp.headers.get('Content-Type') or 'application/octet-stream'
            if name or flask_request.args.get('save'):
                fn = name or re.sub(r'[^\w.\- ()\[\]{}&+=]', '_', url.rstrip('/').rsplit('/', 1)[-1] or 'download')[:120] or 'download'
                headers['Content-Disposition'] = f'attachment; filename="{fn}"'
            return Response(stream_with_context(gen()), status=200, headers=headers)

