        # ===== Software =====
        @app.route('/api/software/<peer_id>')
        def software_list(peer_id):
            try:
                if peer_id == str(state.my_id):
                    items = []
                    # Registry enumeration in-process — the PowerShell
                    # Get-ItemProperty spawn cost ~1-2s per request and only
                    # saw the 64-bit view; this also covers WOW6432Node.
                    _seen_uninst = set()
                    if _IS_WINDOWS:
                        for root in (
                            r'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
                            r'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall',
                        ):
                            try:
                                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, root,
                                                    0, winreg.KEY_READ) as k:
                                    i = 0
                                    while True:
                                        try:
                                            sub = winreg.EnumKey(k, i)
                                            i += 1
                                        except OSError:
                                            break
                                        try:
                                            with winreg.OpenKey(k, sub, 0,
                                                                winreg.KEY_READ) as sk:
                                                name = ver = ''
                                                try:
                                                    name, _ = winreg.QueryValueEx(sk, 'DisplayName')
                                                except (OSError, FileNotFoundError):
                                                    pass
                                                try:
                                                    ver, _ = winreg.QueryValueEx(sk, 'DisplayVersion')
                                                except (OSError, FileNotFoundError):
                                                    pass
                                                if name and name not in _seen_uninst:
                                                    _seen_uninst.add(name)
                                                    items.append({'name': name, 'version': ver or ''})
                                        except OSError:
                                            continue
                            except Exception:
                                continue
                    if items:
                        items.sort(key=lambda d: d['name'].lower())
                        return jsonify({'success': True, 'items': items})
                    cflags = subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0
                    r = subprocess.run(['powershell', '-Command', "Get-ItemProperty HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\* | Select-Object DisplayName, DisplayVersion | Where-Object { $_.DisplayName } | Sort-Object DisplayName | ConvertTo-Json -Compress"], capture_output=True, text=True, timeout=20, creationflags=cflags)
                    try:
                        data = json.loads(r.stdout)
                        if isinstance(data, dict): data = [data]
                        for d in data:
                            items.append({'name': d.get('DisplayName', ''), 'version': d.get('DisplayVersion', '')})
                    except Exception:
                        for line in r.stdout.strip().splitlines():
                            items.append({'name': line.strip(), 'version': ''})
                    return jsonify({'success': True, 'items': items})
                peer_info = state.known_peers.get(peer_id)
                if not peer_info:
                    return jsonify({'success': False, 'error': 'Peer not found'})
                resp = _HTTP_SESSION.get(f"http://{peer_info.ip}:{peer_info.port}/api/software/{peer_id}", timeout=25)
                return jsonify(resp.json())
            except requests.exceptions.ConnectionError:
                return jsonify({'success': False, 'error': 'Peer unreachable'})
            except Exception as e:
                return jsonify({'success': False, 'error': str(e)})

        # ===== Registry =====
        @app.route('/api/registry/<peer_id>', methods=['POST'])
        def registry_query(peer_id):
            try:
                data = flask_request.get_json(force=True)
                path = data.get('path', '').strip()
                if not path:
                    return jsonify({'success': False, 'error': 'No registry path'})
                if peer_id == str(state.my_id):
                    # In-process winreg first — identical output to `reg query`
                    # but ~200ms faster per request; subprocess stays as the
                    # fallback for odd paths winreg can't parse.
                    info = _winreg_query(path)
                    if info is not None:
                        return jsonify({'success': True, 'info': info})
                    cflags = subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0
                    r = subprocess.run(['reg', 'query', path], capture_output=True, text=True, timeout=10, creationflags=cflags)
                    if r.returncode == 0:
                        return jsonify({'success': True, 'info': r.stdout.strip()})
                    return jsonify({'success': False, 'error': r.stderr.strip() or 'Registry query failed'})
                peer_info = state.known_peers.get(peer_id)
                if not peer_info:
                    return jsonify({'success': False, 'error': 'Peer not found'})
                resp = _HTTP_SESSION.post(f"http://{peer_info.ip}:{peer_info.port}/api/registry/{peer_id}", json=data, timeout=15)
                return jsonify(resp.json())
            except requests.exceptions.ConnectionError:
                return jsonify({'success': False, 'error': 'Peer unreachable'})
            except Exception as e:
                return jsonify({'success': False, 'error': str(e)})

