# --- Restore datetime CLASS after GNA's `import datetime` (module) shadowed it ---
# The GNA monolith does `import datetime` (module-level) which overwrites the
# `from datetime import datetime` (class) needed by ConsciousnessSimulator/Symbol.
from datetime import datetime, timedelta, timezone

# === CS Viewer (full embedded ConsciousnessSimulator GUI — 3 windows) ===
# Runs the embedded ConsciousnessSimulator on a daemon thread IN-PROCESS.
# This eliminates the multi-minute subprocess cold start (which used to re-import
# the entire 63k-line Simulation.py including torch + pyglet + OpenGL + rdkit + GNA
# from scratch). All 3 windows still spawn — they just open in seconds, not minutes:
#   1. Consciousness Simulator     (Tk root  — buttons/text input)
#   2. Consciousness Virtual World (pygame   — entity map, in-process thread)
#   3. Consciousness Monitor       (Tk Toplevel — full system dashboard)
# stdout from the CS thread is captured via a tee writer for the in-sim terminal.
_cs_viewer_thread = None
_cs_viewer_instance = None  # ConsciousnessSimulator instance once built
_cs_stdout_tee = None
_cs_stderr_tee = None

class _CSThreadStdoutTee:
    """File-like tee that mirrors writes to the real stream AND, when writes
    come from the CS Viewer thread, appends complete lines to _cs_output."""
    def __init__(self, real_stream, cs_thread_ref):
        self._real = real_stream
        self._cs_thread_ref = cs_thread_ref  # list/box holding the active thread ident
        self._line_bufs = {}  # tid -> partial line buffer (so concurrent writers don't tangle)
    def write(self, s):
        try:
            self._real.write(s)
        except Exception:
            pass
        try:
            tid = threading.get_ident()
            target = self._cs_thread_ref[0] if self._cs_thread_ref else None
            if target is not None and tid == target:
                buf = self._line_bufs.get(tid, '') + s
                while '\n' in buf:
                    line, _, buf = buf.partition('\n')
                    line = line.rstrip('\r')
                    if line.strip():
                        _cs_output_append(line)
                self._line_bufs[tid] = buf
        except Exception:
            pass
    def flush(self):
        try:
            self._real.flush()
        except Exception:
            pass
    def isatty(self):
        try:
            return self._real.isatty()
        except Exception:
            return False
    def fileno(self):
        return self._real.fileno()

# Mutable box so the tee can see the current CS thread ident without circular refs
_cs_active_tid_box = [None]

def _install_cs_stdout_tee():
    """Install the stdout/stderr tee once, on first CS Viewer launch."""
    global _cs_stdout_tee, _cs_stderr_tee
    if _cs_stdout_tee is not None:
        return  # already installed
    try:
        _cs_stdout_tee = _CSThreadStdoutTee(sys.stdout, _cs_active_tid_box)
        _cs_stderr_tee = _CSThreadStdoutTee(sys.stderr, _cs_active_tid_box)
        sys.stdout = _cs_stdout_tee
        sys.stderr = _cs_stderr_tee
    except Exception as _e:
        _cs_output_append(f'[CS Viewer] stdout tee install failed: {_e}')

def _launch_cs_viewer():
    """Launch the full 3-window ConsciousnessSimulator on a daemon thread (in-process).
    The heavy NN init runs in the background; main simulation UI stays responsive.
    Returns immediately. Toggle the in-sim terminal with Shift+cs_viewer hotkey."""
    global _cs_viewer_thread, _cs_viewer_instance
    if _cs_viewer_thread is not None and _cs_viewer_thread.is_alive():
        _cs_output_append('[CS Viewer] Already running — toggle terminal with Shift+hotkey')
        return
    with _cs_output_lock:
        _cs_output.clear()
        _cs_output.append('[CS Viewer] Launching ConsciousnessSimulator on daemon thread (in-process — no subprocess reimport)...')
        _cs_output.append('[CS Viewer] 3 windows expected: Consciousness Simulator + Virtual World + Monitor')
    _install_cs_stdout_tee()
    _t_start = time.time()

    def _run():
        global _cs_viewer_instance
        _cs_active_tid_box[0] = threading.get_ident()
        try:
            _cs_output_append('[CS Viewer] Instantiating ConsciousnessSimulator() — this runs torch / Tk init...')
            _cs_viewer_instance = ConsciousnessSimulator()
            _cs_output_append(f'[CS Viewer] ConsciousnessSimulator built in {time.time() - _t_start:.1f}s — entering Tk mainloop')
            _cs_viewer_instance.run()  # blocks: Tk mainloop on this thread
            _cs_output_append('[CS Viewer] Tk mainloop exited cleanly')
        except Exception as _e:
            import traceback as _tb
            _cs_output_append(f'[CS Viewer] ERROR: {type(_e).__name__}: {_e}')
            for _ln in _tb.format_exc().splitlines()[-8:]:
                _cs_output_append(f'  {_ln}')
        finally:
            _cs_active_tid_box[0] = None

    _cs_viewer_thread = threading.Thread(target=_run, daemon=True, name='CS-Viewer-Main')
    _cs_viewer_thread.start()

_periodic_machine_proc = None       # subprocess.Popen handle
_periodic_machine_reader_thread = None  # daemon thread piping subprocess stdout into _lifegen_output

def _launch_periodic_machine():
    """Launch the PeriodicMachine (Chemistry-DNA Language Interpreter) as a subprocess.
    Subprocess (not thread) because the PeriodicMachine Tk UI uses many `tk.StringVar` /
    `tk.BooleanVar` instances. Python's GC can free those `Variable` objects on any thread,
    and their `__del__` calls into the owning Tcl interpreter — when the interpreter is on
    a different thread, you get `RuntimeError: main thread is not in main loop` cascading
    into a fatal `Tcl_AsyncDelete: async handler deleted by the wrong thread`. Subprocess
    isolates the Tcl interpreter so this can't happen.

    Cold-start cost is mitigated by the existing `--periodic-machine` early handler
    (~Simulation.py:11830) which calls launch_ui() before torch/pyglet/GNA heavy imports.
    stdout/stderr are piped into _lifegen_output for the in-sim Life Generator terminal."""
    global _periodic_machine_proc, _periodic_machine_reader_thread
    if _periodic_machine_proc is not None and hasattr(_periodic_machine_proc, 'poll') and _periodic_machine_proc.poll() is None:
        _lifegen_output_append("[PeriodicMachine] Already running — toggle terminal with Shift+life_generator key")
        return
    _sim_path = os.path.abspath(__file__)
    _py_exe = sys.executable or 'python'
    _lifegen_output_append("[PeriodicMachine] Launching Chemistry-DNA Language Interpreter (subprocess — isolates Tcl interp)...")
    _t_start = time.time()
    try:
        _periodic_machine_proc = subprocess.Popen(
            [_py_exe, _sim_path, '--periodic-machine'],
            cwd=os.path.dirname(_sim_path),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            bufsize=1,
            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0),
        )
        _register_subproc(_periodic_machine_proc, name='PeriodicMachine')
        _lifegen_output_append(f"[PeriodicMachine] Subprocess started in {(time.time() - _t_start) * 1000:.1f}ms (pid={_periodic_machine_proc.pid}) — booting Tk UI...")

        def _pm_pipe_reader(stream):
            try:
                for raw_line in iter(stream.readline, b''):
                    try:
                        line = raw_line.decode('utf-8', errors='replace').rstrip()
                    except Exception:
                        line = repr(raw_line)
                    if line:
                        _lifegen_output_append(line)
            except Exception:
                pass
            finally:
                try:
                    stream.close()
                except Exception:
                    pass
        _periodic_machine_reader_thread = threading.Thread(
            target=_pm_pipe_reader, args=(_periodic_machine_proc.stdout,),
            daemon=True, name='PeriodicMachine-Reader')
        _periodic_machine_reader_thread.start()
    except Exception as _e:
        _lifegen_output_append(f"[PeriodicMachine] Launch failed: {_e}")
        _periodic_machine_proc = None

def _launch_gna():
    """Launch GNA as an in-process daemon thread (full embedded monolith)."""
    global _gna_thread, _gna_running, _gna_process
    if _gna_running:
        return  # already running
    if not _GNA_DEPS_AVAILABLE:
        _gna_output_append('[ERROR] GNA dependencies not installed. Run: pip install requests python-socketio cryptography flask zeroconf')
        return
    _gna_stop_event.clear()
    with _gna_output_lock:
        _gna_output.clear()
        _gna_output.append('[GNA] Launching Global Network Archive (embedded)...')
    def _run():
        global _gna_running
        _gna_running = True
        try:
            _gna_main(_gna_stop_event, _gna_output, _gna_output_lock, _GNA_MAX_OUTPUT_LINES)
        except Exception as e:
            _gna_output_append(f'[GNA ERROR] {e}')
        finally:
            _gna_running = False
            _gna_output_append('[GNA] Thread exited.')
    _gna_thread = threading.Thread(target=_run, daemon=True, name='GNA-Main')
    _gna_thread.start()
    _gna_running = True

def _stop_gna():
    """Signal GNA thread to stop gracefully."""
    global _gna_running
    _gna_stop_event.set()
    _gna_running = False
    _gna_output_append('[GNA] Stop signal sent.')

def _kill_gna():
    """Full kill: stop GNA thread, close terminal, clear output, reset all state."""
    global _gna_running, _gna_show_terminal, _gna_browser_control, _gna_process
    _gna_stop_event.set()
    _gna_running = False
    _gna_show_terminal = False
    _gna_browser_control = False
    _gna_process = None
    with _gna_output_lock:
        _gna_output.clear()
        _gna_output.append('[GNA] Killed — all GNA services terminated. Relaunch with INSERT.')

# ═══════════════════════════════════════════════════════════════════════
# Embedded PubLAN Screen Sender + Receiver (from sender.py & receiver.py)
# No external sender.py or receiver.py files needed.
# ═══════════════════════════════════════════════════════════════════════
_GNA_SCREEN_DEPS = False
try:
    import asyncio as _asyncio_mod
    import fractions as _fractions_mod
    import atexit as _atexit_mod
    import queue as _queue_mod
    import mss as _mss_mod
    from PIL import Image as _PIL_Image, ImageTk as _PIL_ImageTk
    from aiortc import (RTCPeerConnection as _RTCPeerConnection,
                        RTCSessionDescription as _RTCSessionDescription,
                        RTCIceCandidate as _RTCIceCandidate,
                        VideoStreamTrack as _VideoStreamTrack,
                        RTCConfiguration as _RTCConfiguration,
                        RTCIceServer as _RTCIceServer,
                        MediaStreamTrack as _MediaStreamTrack)
    from aiortc.mediastreams import VideoFrame as _VideoFrame
    import socketio as _sio_mod
    _GNA_SCREEN_DEPS = True
except ImportError as _scr_err:
    print(f'[GNA] Screen-sharing deps not installed: {_scr_err}')
    print('[GNA] Install with: pip install aiortc python-socketio mss Pillow')

_HAS_PYAUTOGUI = False
try:
    import pyautogui as _pyautogui_mod
    _pyautogui_mod.FAILSAFE = False
    _HAS_PYAUTOGUI = True
except ImportError:
    pass

_HAS_PYAV = False
try:
    import av as _av_mod
    _HAS_PYAV = True
except ImportError:
    pass

_HAS_SD_GNA = False
try:
    import sounddevice as _sd_gna
    _HAS_SD_GNA = True
except ImportError:
    pass

_SENDER_SIGNALING = "http://localhost:3000"

if _GNA_SCREEN_DEPS:
    # ───────────────────────────────────────────────────────────────────
    # SENDER — Screen Capture Track
    # ───────────────────────────────────────────────────────────────────
    class _ScreenStreamTrack(_VideoStreamTrack):
        kind = "video"
        def __init__(self, monitor_index=1):
            super().__init__()
            self._next_pts = 0
            self.monitor_index = monitor_index
            self._direction = "sendonly"
            self._sct = _mss_mod.mss()
            self._target_interval = 1.0 / 30
            self._last_frame_time = 0
        async def recv(self):
            now = _asyncio_mod.get_event_loop().time()
            elapsed = now - self._last_frame_time
            if elapsed < self._target_interval:
                await _asyncio_mod.sleep(self._target_interval - elapsed)
            self._last_frame_time = _asyncio_mod.get_event_loop().time()
            frame_np = self._capture()
            if _HAS_PYAV:
                video_frame = _av_mod.VideoFrame.from_ndarray(frame_np, format="rgb24")
            else:
                img = _PIL_Image.fromarray(frame_np, mode='RGB')
                video_frame = _VideoFrame.from_image(img)
            video_frame.pts = self._next_pts
            video_frame.time_base = _fractions_mod.Fraction(1, 30)
            self._next_pts += 1
            return video_frame
        def _capture(self):
            monitors = self._sct.monitors
            idx = self.monitor_index
            if idx < 1 or idx >= len(monitors):
                idx = 1
            screenshot = self._sct.grab(monitors[idx])
            frame = np.array(screenshot, dtype=np.uint8)
            return frame[:, :, :3][:, :, ::-1].copy()
        def stop(self):
            super().stop()
            try: self._sct.close()
            except Exception: pass

    # ───────────────────────────────────────────────────────────────────
    # SENDER — System Audio Track
    # ───────────────────────────────────────────────────────────────────
    class _SystemAudioTrack(_MediaStreamTrack):
        kind = "audio"
        def __init__(self):
            super().__init__()
            self._pts = 0
            self._queue = _queue_mod.Queue(maxsize=200)
            self._stream = None
            self._started = False
            self._channels = 1
            if _HAS_SD_GNA and _HAS_PYAV:
                try:
                    devices = _sd_gna.query_devices()
                    loopback_idx = None
                    for i, d in enumerate(devices):
                        name = d['name'].lower()
                        if d['max_input_channels'] > 0 and (
                            'stereo mix' in name or 'loopback' in name or
                            'what u hear' in name or 'wave out' in name):
                            loopback_idx = i
                            break
                    if loopback_idx is not None:
                        dev_info = devices[loopback_idx]
                        self._channels = min(int(dev_info['max_input_channels']), 2) or 1
                        self._stream = _sd_gna.InputStream(
                            device=loopback_idx, samplerate=48000,
                            channels=self._channels, dtype='int16',
                            blocksize=960, callback=self._callback)
                        self._stream.start()
                        self._started = True
                except Exception:
                    pass
        def _callback(self, indata, frames, time_info, status):
            try: self._queue.put_nowait(indata.copy())
            except _queue_mod.Full: pass
        async def recv(self):
            if self._started:
                try: data = self._queue.get_nowait()
                except _queue_mod.Empty:
                    data = np.zeros((960, self._channels), dtype=np.int16)
                    await _asyncio_mod.sleep(0.02)
            else:
                data = np.zeros((960, 1), dtype=np.int16)
                await _asyncio_mod.sleep(0.02)
            if data.shape[1] > 1:
                mono = data.mean(axis=1, keepdims=True).astype(np.int16)
            else:
                mono = data
            frame = _av_mod.AudioFrame.from_ndarray(mono.T, format='s16', layout='mono')
            frame.sample_rate = 48000
            frame.pts = self._pts
            frame.time_base = _fractions_mod.Fraction(1, 48000)
            self._pts += 960
            return frame
        def stop(self):
            super().stop()
            if self._stream:
                try: self._stream.stop(); self._stream.close()
                except Exception: pass
                self._stream = None

    # ───────────────────────────────────────────────────────────────────
    # SENDER — WebRTC + signaling
    # ───────────────────────────────────────────────────────────────────
    def _sender_load_session_id():
        session_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sender_session_id.txt")
        if os.path.exists(session_file):
            try:
                with open(session_file, 'r') as f:
                    sid = f.read().strip()
                    if sid: return sid
            except Exception: pass
        return hashlib.md5(platform.node().encode()).hexdigest()

    def _sender_load_monitor_config():
        config_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "monitor_config.json")
        if os.path.exists(config_file):
            try:
                with open(config_file, 'r') as f:
                    return json.load(f).get('selected_monitor', 1)
            except Exception: pass
        return 1

    async def _sender_create_pc(track):
        config = _RTCConfiguration(iceServers=[
            _RTCIceServer(urls=["stun:stun.l.google.com:19302"]),
            _RTCIceServer(urls=["stun:stun1.l.google.com:19302"]),
            _RTCIceServer(urls=["turn:openrelay.metered.ca:80"], username="openrelayproject", credential="openrelayproject"),
            _RTCIceServer(urls=["turn:openrelay.metered.ca:443"], username="openrelayproject", credential="openrelayproject"),
            _RTCIceServer(urls=["turn:openrelay.metered.ca:443?transport=tcp"], username="openrelayproject", credential="openrelayproject"),
        ])
        return _RTCPeerConnection(configuration=config)

    async def _sender_main():
        session_id = _sender_load_session_id()
        friendly_name = f"{platform.node()}'s Wireless Display"
        monitor_idx = _sender_load_monitor_config()
        track = _ScreenStreamTrack(monitor_index=monitor_idx)
        print(f"[SENDER] Pre-warming track...")
        try:
            first = await track.recv()
            print(f"[SENDER] Track ready ({first.width}x{first.height})")
        except Exception as e:
            print(f"[SENDER] Track pre-warm warning: {e}")
        audio_track = _SystemAudioTrack()
        if audio_track._started:
            print("[SENDER] System audio capture active")
        else:
            print("[SENDER] System audio not available")
        state = {"pc": await _sender_create_pc(track), "connected": False,
                 "remote_access_granted": False, "remote_access_from": None}
        sio = _sio_mod.AsyncClient(reconnection=True, reconnection_attempts=0,
                                    reconnection_delay=2, reconnection_delay_max=10)
        @sio.event
        async def connect():
            state["connected"] = True
            print("[SENDER] Connected to signaling server")
            await sio.emit('register-sender', {"sessionId": session_id, "friendlyName": friendly_name})
            await sio.emit('register-caller', {"peerId": "sender-" + session_id,
                                                "callNumber": "", "friendlyName": friendly_name})
        @sio.event
        async def disconnect():
            state["connected"] = False
            print("[SENDER] Disconnected — will auto-reconnect")
        @sio.event
        async def connect_error(data):
            print(f"[SENDER] Connection error: {data}")
        @sio.on("offer")
        async def handle_offer(data):
            try:
                old_pc = state["pc"]
                try: await old_pc.close()
                except Exception: pass
                pc = await _sender_create_pc(track)
                state["pc"] = pc
                @pc.on("icecandidate")
                async def on_ice(candidate):
                    if candidate and state["connected"]:
                        await sio.emit("ice-candidate", {"candidate": str(candidate),
                            "sdpMid": candidate.sdpMid, "sdpMLineIndex": candidate.sdpMLineIndex,
                            "sessionId": session_id})
                await pc.setRemoteDescription(_RTCSessionDescription(sdp=data["sdp"], type="offer"))
                transceivers = pc.getTransceivers()
                video_set = audio_set = False
                for t in transceivers:
                    t_kind = getattr(t, '_kind', None) or getattr(t, 'kind', None)
                    if t_kind is None and t.receiver and hasattr(t.receiver, '_track'):
                        t_kind = getattr(t.receiver._track, 'kind', None)
                    if t_kind is None:
                        t_kind = 'video' if not video_set else 'audio'
                    if t_kind == 'video' and not video_set:
                        t.sender.replaceTrack(track); t.direction = "sendonly"; video_set = True
                    elif t_kind == 'audio' and not audio_set:
                        t.sender.replaceTrack(audio_track); t.direction = "sendonly"; audio_set = True
                if not video_set:
                    pc.addTransceiver(track, direction="sendonly")
                if not audio_set and audio_track._started:
                    pc.addTransceiver(audio_track, direction="sendonly")
                answer = await pc.createAnswer()
                if answer and answer.sdp:
                    for t in pc.getTransceivers():
                        if not hasattr(t, '_offerDirection') or t._offerDirection is None:
                            t._offerDirection = "recvonly"
                    await pc.setLocalDescription(answer)
                    await sio.emit("answer", {"sdp": pc.localDescription.sdp, "sessionId": session_id})
                    print("[SENDER] Answer sent")
            except Exception as e:
                print(f"[SENDER] Offer error: {e}")
                import traceback; traceback.print_exc()
        @sio.on("ice-candidate")
        async def handle_ice(data):
            if data.get("candidate"):
                await state["pc"].addIceCandidate(_RTCIceCandidate(
                    sdpMid=data.get("sdpMid"), sdpMLineIndex=data.get("sdpMLineIndex"),
                    candidate=data["candidate"]))
        @sio.on("remote-access-request")
        async def handle_ra_req(data):
            from_peer = data.get("fromPeerId", "unknown")
            from_name = data.get("fromName", from_peer)
            print(f"[SENDER] Remote access request from: {from_name}")
            def show_dialog():
                import tkinter as _tk
                from tkinter import messagebox as _mb
                temp = _tk.Tk(); temp.withdraw(); temp.attributes('-topmost', True)
                result = _mb.askyesno("Remote Access Request",
                    f"{from_name} is requesting remote access.\n\nAllow?", parent=temp)
                temp.destroy(); return result
            loop = _asyncio_mod.get_event_loop()
            accepted = await loop.run_in_executor(None, show_dialog)
            if accepted:
                state["remote_access_granted"] = True; state["remote_access_from"] = from_peer
                await sio.emit("remote-access-grant", {"fromPeerId": session_id,
                    "toPeerId": from_peer, "remoteName": from_name, "sessionId": session_id})
            else:
                await sio.emit("remote-access-deny", {"fromPeerId": session_id,
                    "toPeerId": from_peer, "sessionId": session_id, "reason": "User declined"})
        @sio.on("remote-access-revoke")
        async def handle_ra_revoke(data):
            state["remote_access_granted"] = False; state["remote_access_from"] = None
            await sio.emit("remote-access-ended", {"sessionId": session_id})
        @sio.on("remote-input")
        async def handle_remote_input(data):
            if not state.get("remote_access_granted") or not _HAS_PYAUTOGUI: return
            ev = data.get("event", {}); etype = ev.get("type", "")
            try:
                if etype == "mousemove":
                    sw, sh = _pyautogui_mod.size()
                    _pyautogui_mod.moveTo(int(ev.get("x",0)*sw), int(ev.get("y",0)*sh), _pause=False)
                elif etype == "mousedown":
                    sw, sh = _pyautogui_mod.size()
                    _pyautogui_mod.click(int(ev.get("x",0)*sw), int(ev.get("y",0)*sh),
                                          button=ev.get("button","left"), _pause=False)
                elif etype == "dblclick":
                    sw, sh = _pyautogui_mod.size()
                    _pyautogui_mod.doubleClick(int(ev.get("x",0)*sw), int(ev.get("y",0)*sh), _pause=False)
                elif etype == "scroll":
                    d = ev.get("delta", 0); clicks = d // 120 if d else 0
                    if clicks: _pyautogui_mod.scroll(clicks, _pause=False)
                elif etype == "keydown":
                    key = ev.get("key",""); char = ev.get("char","")
                    km = {"Return":"enter","BackSpace":"backspace","Tab":"tab","Escape":"escape",
                          "space":"space","Delete":"delete","Up":"up","Down":"down","Left":"left",
                          "Right":"right","Home":"home","End":"end","Prior":"pageup","Next":"pagedown",
                          "Control_L":"ctrl","Control_R":"ctrl","Alt_L":"alt","Alt_R":"alt",
                          "Shift_L":"shift","Shift_R":"shift"}
                    mapped = km.get(key,"")
                    if mapped: _pyautogui_mod.keyDown(mapped, _pause=False)
                    elif char and len(char)==1: _pyautogui_mod.press(char, _pause=False)
                elif etype == "keyup":
                    key = ev.get("key","")
                    km = {"Control_L":"ctrl","Control_R":"ctrl","Alt_L":"alt","Alt_R":"alt",
                          "Shift_L":"shift","Shift_R":"shift"}
                    mapped = km.get(key,"")
                    if mapped: _pyautogui_mod.keyUp(mapped, _pause=False)
            except Exception: pass
        while True:
            try:
                await sio.connect(_SENDER_SIGNALING, wait_timeout=10)
                break
            except Exception as e:
                print(f"[SENDER] Cannot reach signaling server ({e}), retrying in 3s...")
                await _asyncio_mod.sleep(3)
        await sio.wait()

    # ───────────────────────────────────────────────────────────────────
    # RECEIVER — ReceiverApp (tkinter + WebRTC)
    # ───────────────────────────────────────────────────────────────────
    _RECEIVER_RTC_CONFIG = _RTCConfiguration(iceServers=[
        _RTCIceServer(urls=["stun:stun.l.google.com:19302"]),
        _RTCIceServer(urls=["stun:stun1.l.google.com:19302"]),
        _RTCIceServer(urls=["turn:openrelay.metered.ca:80"], username="openrelayproject", credential="openrelayproject"),
        _RTCIceServer(urls=["turn:openrelay.metered.ca:443"], username="openrelayproject", credential="openrelayproject"),
        _RTCIceServer(urls=["turn:openrelay.metered.ca:443?transport=tcp"], username="openrelayproject", credential="openrelayproject"),
    ])

    class _ReceiverApp:
        def __init__(self, root, auto_connect_peer_id=None):
            import tkinter as tk
            from tkinter import ttk, messagebox
            self._tk = tk; self._ttk = ttk; self._messagebox = messagebox
            self.root = root
            self.root.title("Wireless Display Receiver")
            self.session_id = auto_connect_peer_id
            self.auto_connect = auto_connect_peer_id is not None
            self.pc = None; self.sio = None; self.running = False
            self.display_w, self.display_h = 1280, 720
            self.senders = []; self.current_image = None
            self._reconnecting = False; self._negotiation_in_progress = False
            self._last_video_frame_time = 0
            self._remote_access_granted = False; self._remote_access_active = False
            self._last_mouse_send_time = 0
            self._speaker_muted = False; self._audio_output = None
            self.root.geometry(f"{self.display_w + 40}x{self.display_h + 150}")
            if not self.auto_connect:
                cf = ttk.Frame(root); cf.pack(pady=10, fill=tk.X, padx=20)
                ttk.Label(cf, text="Available Senders:").pack()
                self.sender_listbox = tk.Listbox(cf, width=60, height=6); self.sender_listbox.pack(pady=5)
                ttk.Button(cf, text="Connect", command=self.connect_to_sender).pack(pady=5)
                ttk.Separator(root, orient='horizontal').pack(fill=tk.X, pady=10)
            sf = ttk.Frame(root); sf.pack(fill=tk.X, padx=20)
            self.status_label = ttk.Label(sf, text=f"Connecting to: {auto_connect_peer_id}..." if self.auto_connect else "Select a sender to connect")
            self.status_label.pack(pady=5)
            self.canvas = tk.Canvas(root, width=self.display_w, height=self.display_h, bg='black')
            self.canvas.pack(pady=10, padx=20); self._canvas_image_id = None
            af = tk.Frame(root, bg='#161b22'); af.pack(fill=tk.X, padx=20, pady=(5,2))
            tk.Label(af, text="Audio", bg='#161b22', fg='#58a6ff', font=('Segoe UI',9,'bold')).pack(side=tk.LEFT, padx=(5,10))
            self.speaker_btn = tk.Button(af, text="\U0001f50a Speaker On", bg='#238636', fg='white',
                font=('Segoe UI',9), command=self._toggle_speaker, relief=tk.FLAT, padx=8, pady=2)
            self.speaker_btn.pack(side=tk.LEFT, padx=3)
            self.audio_status_label = tk.Label(af, text="Waiting for audio stream...", bg='#161b22', fg='#8b949e', font=('Segoe UI',8))
            self.audio_status_label.pack(side=tk.LEFT, padx=10)
            if not _HAS_SD_GNA:
                self.audio_status_label.config(text="(sounddevice not installed)")
                self.speaker_btn.config(state=tk.DISABLED, bg='#30363d')
            self.remote_frame = tk.Frame(root); self.remote_frame.pack(fill=tk.X, padx=20, pady=5)
            self.remote_btn = tk.Button(self.remote_frame, text="Request Remote Access",
                bg='#f0883e', fg='white', font=('Segoe UI',9,'bold'),
                command=self._request_remote_access, relief=tk.FLAT, padx=10, pady=3)
            self.remote_btn.pack(side=tk.LEFT)
            self.remote_status = tk.Label(self.remote_frame, text="", fg='#8b949e', font=('Segoe UI',9))
            self.remote_status.pack(side=tk.LEFT, padx=10)
            self.canvas.bind('<Motion>', self._on_mouse_move)
            self.canvas.bind('<Button-1>', self._on_mouse_click)
            self.canvas.bind('<Button-3>', self._on_mouse_right_click)
            self.canvas.bind('<Double-Button-1>', self._on_mouse_double_click)
            self.canvas.bind('<ButtonRelease-1>', self._on_mouse_release)
            self.canvas.bind('<MouseWheel>', self._on_mouse_scroll)
            self.root.bind('<Key>', self._on_key_press)
            self.root.bind('<KeyRelease>', self._on_key_release)
            self.loop = _asyncio_mod.new_event_loop()
            def run_loop():
                _asyncio_mod.set_event_loop(self.loop)
                self.loop.run_forever()
            self.thread = threading.Thread(target=run_loop, daemon=True); self.thread.start()
            _asyncio_mod.run_coroutine_threadsafe(self.start_signaling(), self.loop)
            if not self.auto_connect:
                self.root.after(100, self.update_sender_list)
            else:
                self.root.after(1000, self.auto_connect_to_peer)
            self.root.after(5000, self._health_check_loop)

        def _create_peer_connection(self):
            pc = _RTCPeerConnection(configuration=_RECEIVER_RTC_CONFIG)
            @pc.on("icecandidate")
            async def on_ice(candidate):
                if candidate and self.session_id and self.sio and self.sio.connected:
                    await self.sio.emit("ice-candidate", {"candidate": str(candidate),
                        "sdpMid": candidate.sdpMid, "sdpMLineIndex": candidate.sdpMLineIndex,
                        "sessionId": self.session_id})
            @pc.on("track")
            async def on_track(track):
                if track.kind == "video":
                    self.running = True
                    self.root.after(0, lambda: self.status_label.config(text="Connected - Receiving video stream", foreground='green'))
                    fc = 0
                    while self.running:
                        try:
                            frame = await track.recv()
                            self._last_video_frame_time = time.time(); fc += 1
                            img = frame.to_image().resize((self.display_w, self.display_h), _PIL_Image.Resampling.BILINEAR)
                            self.current_image = _PIL_ImageTk.PhotoImage(img)
                            self.root.after(0, self.update_canvas)
                        except Exception:
                            self.running = False
                            self.root.after(0, lambda: self.status_label.config(text="Video stream lost - reconnecting...", foreground='orange'))
                            _asyncio_mod.ensure_future(self._reconnect_webrtc()); break
                elif track.kind == "audio":
                    self.root.after(0, lambda: self.audio_status_label.config(text="Audio stream active"))
                    if _HAS_SD_GNA:
                        try:
                            self._audio_output = _sd_gna.OutputStream(samplerate=48000, channels=1, dtype='int16', blocksize=960)
                            self._audio_output.start()
                        except Exception: self._audio_output = None
                    while self.running:
                        try:
                            frame = await track.recv()
                            if self._audio_output and not self._speaker_muted:
                                data = frame.to_ndarray(); samples = data.T
                                if samples.ndim > 1 and samples.shape[1] > 1: samples = samples[:,:1]
                                self._audio_output.write(samples)
                        except Exception: break
            @pc.on("connectionstatechange")
            async def on_cs():
                s = pc.connectionState
                if s in ("failed","closed"):
                    self.running = False
                    self.root.after(0, lambda: self.status_label.config(text=f"Connection {s}", foreground='orange'))
                    _asyncio_mod.ensure_future(self._reconnect_webrtc())
            return pc

        async def _reconnect_webrtc(self):
            if self._reconnecting or not self.session_id: return
            self._reconnecting = True
            try:
                if self.pc:
                    try: await self.pc.close()
                    except Exception: pass
                await _asyncio_mod.sleep(1)
                self.pc = self._create_peer_connection()
                if not self.sio or not self.sio.connected:
                    for _ in range(10):
                        await _asyncio_mod.sleep(1)
                        if self.sio and self.sio.connected: break
                    if not self.sio or not self.sio.connected:
                        self._reconnecting = False; return
                await self.sio.emit('join', self.session_id)
                self.pc.addTransceiver("video", direction="recvonly")
                self.pc.addTransceiver("audio", direction="recvonly")
                offer = await self.pc.createOffer()
                await self.pc.setLocalDescription(offer)
                await self.sio.emit('offer', {"sdp": self.pc.localDescription.sdp, "sessionId": self.session_id})
                self.root.after(0, lambda: self.status_label.config(text="Reconnecting...", foreground='orange'))
            except Exception: pass
            finally: self._reconnecting = False

        def _health_check_loop(self):
            try:
                if self.session_id and self.sio:
                    if not self.sio.connected:
                        self.status_label.config(text="Signaling disconnected - reconnecting...", foreground='orange')
                    elif self._last_video_frame_time > 0 and not self.running:
                        if time.time() - self._last_video_frame_time > 10 and not self._reconnecting:
                            _asyncio_mod.run_coroutine_threadsafe(self._reconnect_webrtc(), self.loop)
                    elif self.pc and hasattr(self.pc, 'connectionState'):
                        if self.pc.connectionState in ("failed","closed","disconnected") and not self._reconnecting:
                            _asyncio_mod.run_coroutine_threadsafe(self._reconnect_webrtc(), self.loop)
                    if self.sio.connected:
                        _asyncio_mod.run_coroutine_threadsafe(self.sio.emit("request-sender-list"), self.loop)
            except Exception: pass
            self.root.after(5000, self._health_check_loop)

        async def start_signaling(self):
            self.pc = self._create_peer_connection()
            self.sio = _sio_mod.AsyncClient(reconnection=True, reconnection_attempts=0,
                                             reconnection_delay=2, reconnection_delay_max=10)
            @self.sio.event
            async def connect():
                self.root.after(0, lambda: self.status_label.config(text="Connected to signaling server"))
                await self.sio.emit("request-sender-list")
                if self.session_id:
                    await self.sio.emit('join', self.session_id)
                    if not self._reconnecting:
                        _asyncio_mod.ensure_future(self._reconnect_webrtc())
            @self.sio.event
            async def connect_error(data):
                self.root.after(0, lambda: self.status_label.config(text="Cannot connect to signaling server", foreground='red'))
            @self.sio.event
            async def disconnect():
                self.root.after(0, lambda: self.status_label.config(text="Disconnected - reconnecting...", foreground='orange'))
            @self.sio.on("sender-list")
            async def handle_sl(data):
                self.senders = data or []
                self.root.after(0, self.update_sender_list_gui)
            @self.sio.on("answer")
            async def handle_ans(data):
                await self.pc.setRemoteDescription(_RTCSessionDescription(sdp=data["sdp"], type="answer"))
            @self.sio.on("ice-candidate")
            async def handle_ice(data):
                if data.get("candidate"):
                    await self.pc.addIceCandidate(_RTCIceCandidate(sdpMid=data.get("sdpMid"),
                        sdpMLineIndex=data.get("sdpMLineIndex"), candidate=data["candidate"]))
            @self.sio.on("sender-reconnected")
            async def handle_sr(data):
                if data.get("sessionId","") == self.session_id and not self._reconnecting:
                    await _asyncio_mod.sleep(1)
                    _asyncio_mod.ensure_future(self._reconnect_webrtc())
            @self.sio.on("remote-access-granted")
            async def handle_rag(data):
                self.root.after(0, self._on_remote_access_granted)
            @self.sio.on("remote-access-denied")
            async def handle_rad(data):
                reason = data.get('reason','denied')
                self.root.after(0, lambda: self._on_remote_access_denied(reason))
            try:
                await self.sio.connect(_SENDER_SIGNALING, wait_timeout=10)
            except Exception: pass

        def update_sender_list_gui(self):
            if hasattr(self, 'sender_listbox'):
                self.sender_listbox.delete(0, self._tk.END)
                for s in self.senders:
                    self.sender_listbox.insert(self._tk.END, f"{s['friendlyName']} ({s['sessionId']})")
        def update_sender_list(self):
            if self.sio and self.sio.connected:
                _asyncio_mod.run_coroutine_threadsafe(self.sio.emit("request-sender-list"), self.loop)
            self.root.after(5000, self.update_sender_list)
        def update_canvas(self):
            if self.current_image:
                if self._canvas_image_id is None:
                    self._canvas_image_id = self.canvas.create_image(self.display_w//2, self.display_h//2, image=self.current_image)
                else:
                    self.canvas.itemconfig(self._canvas_image_id, image=self.current_image)
        def auto_connect_to_peer(self):
            if self.sio and self.sio.connected and self.session_id:
                async def _conn():
                    await self.sio.emit('join', self.session_id)
                    self.pc.addTransceiver("video", direction="recvonly")
                    self.pc.addTransceiver("audio", direction="recvonly")
                    offer = await self.pc.createOffer()
                    await self.pc.setLocalDescription(offer)
                    await self.sio.emit('offer', {"sdp": self.pc.localDescription.sdp, "sessionId": self.session_id})
                _asyncio_mod.run_coroutine_threadsafe(_conn(), self.loop)
                self.status_label.config(text="Establishing connection...")
            else:
                self.root.after(500, self.auto_connect_to_peer)
        def connect_to_sender(self):
            sel = self.sender_listbox.curselection()
            if not sel:
                self._messagebox.showwarning("Warning", "Select a sender"); return
            self.session_id = self.sender_listbox.get(sel[0]).split('(')[-1].strip(')')
            self.status_label.config(text=f"Connecting to {self.session_id}...")
            async def _conn():
                if self.pc:
                    try: await self.pc.close()
                    except Exception: pass
                self.pc = self._create_peer_connection()
                await self.sio.emit('join', self.session_id)
                self.pc.addTransceiver("video", direction="recvonly")
                self.pc.addTransceiver("audio", direction="recvonly")
                offer = await self.pc.createOffer()
                await self.pc.setLocalDescription(offer)
                await self.sio.emit('offer', {"sdp": self.pc.localDescription.sdp, "sessionId": self.session_id})
            _asyncio_mod.run_coroutine_threadsafe(_conn(), self.loop)
        def _toggle_speaker(self):
            self._speaker_muted = not self._speaker_muted
            if self._speaker_muted:
                self.speaker_btn.config(text="\U0001f50a Speaker Off", bg='#da3633')
            else:
                self.speaker_btn.config(text="\U0001f50a Speaker On", bg='#238636')
        def _request_remote_access(self):
            if not self.session_id or not self.sio:
                self.remote_status.config(text="Not connected", fg='red'); return
            self.remote_status.config(text="Requesting...", fg='#f0883e')
            self.remote_btn.config(state=self._tk.DISABLED)
            async def _req():
                await self.sio.emit('remote-access-request', {'fromPeerId': f'receiver-{id(self)}',
                    'toPeerId': self.session_id, 'fromName': f'Receiver ({self.session_id})'})
            _asyncio_mod.run_coroutine_threadsafe(_req(), self.loop)
        def _on_remote_access_granted(self):
            self._remote_access_granted = True; self._remote_access_active = True
            self.remote_btn.config(text="Remote Access Active", bg='#238636',
                                   state=self._tk.NORMAL, command=self._stop_remote_access)
            self.remote_status.config(text="Click on video to interact", fg='#3fb950')
            self.canvas.config(cursor='hand2')
        def _on_remote_access_denied(self, reason="denied"):
            self._remote_access_granted = False; self._remote_access_active = False
            self.remote_btn.config(state=self._tk.NORMAL, text="Request Remote Access",
                                   bg='#f0883e', command=self._request_remote_access)
            self.remote_status.config(text=f"Denied: {reason}", fg='#f85149')
        def _stop_remote_access(self):
            self._remote_access_active = False; self._remote_access_granted = False
            self.remote_btn.config(text="Request Remote Access", bg='#f0883e',
                                   command=self._request_remote_access)
            self.remote_status.config(text="Stopped", fg='#8b949e')
            self.canvas.config(cursor='')
        def _send_remote_input(self, event_data):
            if not self._remote_access_active or not self.sio or not self.session_id: return
            _asyncio_mod.run_coroutine_threadsafe(
                self.sio.emit('remote-input', {'targetPeerId': self.session_id,
                    'fromPeerId': 'receiver', 'event': event_data}), self.loop)
        def _on_mouse_move(self, event):
            if not self._remote_access_active: return
            now = time.time()
            if now - self._last_mouse_send_time < 0.03: return
            self._last_mouse_send_time = now
            self._send_remote_input({'type':'mousemove','x':event.x/self.display_w,'y':event.y/self.display_h})
        def _on_mouse_click(self, event):
            if self._remote_access_active:
                self._send_remote_input({'type':'mousedown','x':event.x/self.display_w,'y':event.y/self.display_h,'button':'left'})
        def _on_mouse_right_click(self, event):
            if self._remote_access_active:
                self._send_remote_input({'type':'mousedown','x':event.x/self.display_w,'y':event.y/self.display_h,'button':'right'})
        def _on_mouse_double_click(self, event):
            if self._remote_access_active:
                self._send_remote_input({'type':'dblclick','x':event.x/self.display_w,'y':event.y/self.display_h,'button':'left'})
        def _on_mouse_release(self, event):
            if self._remote_access_active:
                self._send_remote_input({'type':'mouseup','x':event.x/self.display_w,'y':event.y/self.display_h,'button':'left'})
        def _on_mouse_scroll(self, event):
            if self._remote_access_active:
                self._send_remote_input({'type':'scroll','delta':event.delta})
        def _on_key_press(self, event):
            if self._remote_access_active:
                self._send_remote_input({'type':'keydown','key':event.keysym,'char':event.char})
        def _on_key_release(self, event):
            if self._remote_access_active:
                self._send_remote_input({'type':'keyup','key':event.keysym})

# ───────────────────────────────────────────────────────────────────
# Wrapper functions to run embedded sender/receiver in threads
# ───────────────────────────────────────────────────────────────────
def _run_embedded_sender(session_id=None):
    """Run embedded PubLAN sender in a daemon thread."""
    if not _GNA_SCREEN_DEPS:
        print("[GNA] Screen-sharing deps not installed — sender cannot start.")
        print("[GNA] Install with: pip install aiortc python-socketio mss Pillow")
        return
    proj = os.path.dirname(os.path.abspath(__file__))
    if session_id:
        try:
            with open(os.path.join(proj, 'sender_session_id.txt'), 'w') as f:
                f.write(session_id)
        except Exception: pass
    # Write PID file
    try:
        with open(os.path.join(proj, 'sender.pid'), 'w') as f:
            f.write(str(os.getpid()))
    except Exception: pass
    def _run():
        try:
            _asyncio_mod.run(_sender_main())
        except Exception as e:
            print(f"[SENDER] Error: {e}")
    t = threading.Thread(target=_run, daemon=True, name='GNA-Sender')
    t.start()
    print("[GNA] Embedded sender started in background thread")
    return t

def _run_embedded_receiver(peer_id=None):
    """Run embedded PubLAN receiver in a daemon thread."""
    if not _GNA_SCREEN_DEPS:
        print("[GNA] Screen-sharing deps not installed — receiver cannot start.")
        print("[GNA] Install with: pip install aiortc python-socketio mss Pillow")
        return
    def _run():
        try:
            import tkinter as tk
            root = tk.Tk()
            _app = _ReceiverApp(root, auto_connect_peer_id=peer_id)
            root.mainloop()
        except Exception as e:
            print(f"[RECEIVER] Error: {e}")
    t = threading.Thread(target=_run, daemon=True, name='GNA-Receiver')
    t.start()
    print(f"[GNA] Embedded receiver started (peer={peer_id})")
    return t

_OBS_SPAWN_COOLDOWN = 0.0  # zero cooldown - AI free roam
_obs_last_spawn_time = 0.0   # last time an observer spawned anything
_obs_activity_log = deque(maxlen=500)  # (time, obs_name, action, detail, ok)
show_ai_dashboard = False    # toggled by hotkey
_ai_dashboard_scroll = 0     # scroll offset (in lines) for AI dashboard content
_ai_dashboard_tab = 0        # 0=Goals, 1=Learning, 2=Intelligence, 3=LiveChat, 4=Neural, 5=Call, 6-11=OB1-OB6 DM

# === AI Communication System (User <-> AI Chat, Voice, Live Chat) ===
_ai_chat_input_text = ""
_ai_chat_input_active = False
_ai_live_chat_enabled = {'OB1': True, 'OB2': True, 'OB3': True, 'OB4': True, 'OB5': True, 'OB6': True}
_voice_recording = False
_voice_stream = None
_voice_frames = []
_VOICE_SAMPLE_RATE = 16000
_VOICE_HOTKEY = None  # set after hotkey_map is built

def _start_voice_record():
    global _voice_recording, _voice_frames, _voice_stream
    if not _VOICE_AVAILABLE or _voice_recording:
        return
    _voice_frames = []
    _voice_recording = True
    try:
        def _voice_cb(indata, frames, t_info, status):
            if _voice_recording:
                _voice_frames.append(indata.copy())
        _voice_stream = _sd_mod.InputStream(
            samplerate=_VOICE_SAMPLE_RATE, channels=1, callback=_voice_cb)
        _voice_stream.start()
    except Exception as e:
        print(f"[VOICE] Failed to start recording: {e}")
        _voice_recording = False

def _stop_voice_record_and_send():
    global _voice_recording, _voice_stream
    if not _voice_recording:
        return
    _voice_recording = False
    if _voice_stream:
        try:
            _voice_stream.stop()
            _voice_stream.close()
        except Exception:
            pass
        _voice_stream = None
    if not _voice_frames:
        return
    audio = np.concatenate(_voice_frames, axis=0)
    def _transcribe():
        try:
            recognizer = _sr_mod.Recognizer()
            audio_bytes = (audio * 32767).astype(np.int16).tobytes()
            audio_data = _sr_mod.AudioData(audio_bytes, _VOICE_SAMPLE_RATE, 2)
            text = recognizer.recognize_google(audio_data)
            if text:
                _send_user_chat_message(text)
        except Exception as e:
            print(f"[VOICE] Transcription failed: {e}")
    _threading_mod.Thread(target=_transcribe, daemon=True).start()

# === AI Voice Call System (STT + TTS, always-on mic, call lifecycle) ===
_ai_call_active = False
_ai_call_target_idx = -1          # -1 = all observers, 0-5 = specific OB
_ai_call_start_time = 0.0
_ai_call_log = deque(maxlen=200)  # (time, sender_str, message_str)
_ai_call_always_on = False
_ai_call_always_on_stream = None
_ai_call_always_on_buffer = []
_ai_call_silent_blocks = 0
_ai_call_voiced_blocks = 0
_ai_call_in_speech = False
_ai_call_tts_queue = deque(maxlen=6)  # tight cap — matches Main_AIED.py, drops stale utterances
_ai_call_tts_thread = None
_ai_call_tts_stop = _threading_mod.Event()
_ai_call_mic_level = 0.0
_ai_call_tts_muted = False
_AI_CALL_ENERGY_GATE = 0.0008      # VAD energy threshold (was 0.002 — too high; quiet mics missed)
_AI_CALL_PREGAIN     = 3.0         # 3× pre-gain applied in callback BEFORE VAD (matches Main_AIED)
_AI_CALL_SILENCE_BLOCKS = 14       # ~0.7s silence = end of utterance
_AI_CALL_VOICED_BLOCKS = 4         # ~0.2s voice = start of utterance
# Persistent PowerShell SAPI subprocess — one-time 800ms init replaces ~400ms
# powershell.exe spawn on EVERY utterance. Reused across the whole session.
# Fed via stdin: each newline-terminated line is one Speak() call queued inside PS.
_ai_call_sapi_proc = None
_ai_call_sapi_lock = _threading_mod.Lock()
# TTS de-dupe: skip near-identical utterances within 1.5s (matches Main_AIED)
_ai_call_last_tts_text = ''
_ai_call_last_tts_time = 0.0

def _ai_call_start(obs_idx=-1):
    """Start a voice call with an AI observer (-1 = all)."""
    global _ai_call_active, _ai_call_target_idx, _ai_call_start_time
    if _ai_call_active:
        return
    _ai_call_active = True
    _ai_call_target_idx = obs_idx
    _ai_call_start_time = time.time()
    _ai_call_log.clear()
    target_name = 'All Observers'
    if _observer_mgr and 0 <= obs_idx < len(_observer_mgr.observers):
        target_name = _observer_mgr.observers[obs_idx].name
    _ai_call_log.append((time.time(), 'SYSTEM', f'Call started with {target_name}'))
    _ai_call_start_listening()
    _ai_call_start_tts_worker()
    print(f"[AI CALL] Started call with {target_name}")

def _ai_call_hangup():
    """End the active voice call and tear down the persistent SAPI subprocess."""
    global _ai_call_active, _ai_call_target_idx, _ai_call_sapi_proc
    if not _ai_call_active:
        return
    _ai_call_stop_listening()
    _ai_call_tts_stop.set()
    _ai_call_tts_queue.clear()
    _ai_call_active = False
    # Close the persistent PowerShell SAPI subprocess (release the speech engine
    # + free the audio device). It will be re-spawned on next call.
    if _ai_call_sapi_proc is not None:
        try:
            if _ai_call_sapi_proc.stdin and not _ai_call_sapi_proc.stdin.closed:
                _ai_call_sapi_proc.stdin.close()  # signals PS to exit its read loop
        except Exception:
            pass
        try:
            _ai_call_sapi_proc.wait(timeout=2)
        except Exception:
            try:
                _ai_call_sapi_proc.terminate()
            except Exception:
                pass
        _ai_call_sapi_proc = None
    _ai_call_log.append((time.time(), 'SYSTEM', 'Call ended'))
    print("[AI CALL] Call ended")

def _ai_call_send_message(text):
    """Send a user message during a call, get AI response, queue TTS."""
    if not _ai_call_active or not text.strip():
        return
    msg = text.strip()
    _ai_call_log.append((time.time(), 'You', msg))
    if _observer_mgr:
        if _ai_call_target_idx == -1:
            for obs in _observer_mgr.observers:
                if obs.active:
                    resp = _ai_respond_to_user(obs, msg)
                    if resp:
                        _ai_call_log.append((time.time(), obs.name, resp))
                        _ai_call_tts_queue.append(resp)
                        _obs_chat(obs.name, 'The Creator', resp)
                    _obs_chat('The Creator', obs.name, msg)
                    break  # first active observer responds in call mode
        elif 0 <= _ai_call_target_idx < len(_observer_mgr.observers):
            obs = _observer_mgr.observers[_ai_call_target_idx]
            _obs_chat('The Creator', obs.name, msg)
            obs._log_thought(f"The Creator speaks (call): {msg[:60]}")
            resp = _ai_respond_to_user(obs, msg)
            if resp:
                _ai_call_log.append((time.time(), obs.name, resp))
                _ai_call_tts_queue.append(resp)
                _obs_chat(obs.name, 'The Creator', resp)

def _ai_call_start_listening():
    """Open mic for continuous always-on listening with VAD during a call."""
    global _ai_call_always_on, _ai_call_always_on_stream
    global _ai_call_always_on_buffer, _ai_call_silent_blocks
    global _ai_call_voiced_blocks, _ai_call_in_speech
    if not _VOICE_AVAILABLE or _ai_call_always_on:
        return
    _ai_call_always_on = True
    _ai_call_always_on_buffer = []
    _ai_call_silent_blocks = 0
    _ai_call_voiced_blocks = 0
    _ai_call_in_speech = False
    try:
        _ai_call_always_on_stream = _sd_mod.InputStream(
            samplerate=_VOICE_SAMPLE_RATE, channels=1, dtype='int16',
            callback=_ai_call_mic_callback,
            blocksize=int(_VOICE_SAMPLE_RATE * 0.05))
        _ai_call_always_on_stream.start()
        _ai_call_log.append((time.time(), 'SYSTEM', 'Mic open — listening...'))
        print("[AI CALL] Always-on mic started")
    except Exception as e:
        _ai_call_always_on = False
        print(f"[AI CALL] Mic open failed: {e}")

def _ai_call_stop_listening():
    """Stop the continuous mic listener."""
    global _ai_call_always_on, _ai_call_always_on_stream
    _ai_call_always_on = False
    if _ai_call_always_on_stream:
        try:
            _ai_call_always_on_stream.stop()
            _ai_call_always_on_stream.close()
        except Exception:
            pass
        _ai_call_always_on_stream = None

def _ai_call_mic_callback(indata, frames_count, time_info, status):
    """Sounddevice callback: energy-based VAD with 3× pre-gain (matches Main_AIED.py).
    Pre-gain amplifies the mic signal BEFORE the VAD energy check so quiet speakers
    aren't gated out. The amplified block is also what we append to the buffer, so
    the STT model sees the boosted signal too. Soft saturation prevents clipping."""
    global _ai_call_silent_blocks, _ai_call_voiced_blocks
    global _ai_call_in_speech, _ai_call_mic_level
    if not _ai_call_always_on:
        return
    try:
        # Apply 3× pre-gain with simple soft-clip (tanh-style) to avoid hard wraparound
        _raw = indata.astype(np.float32)
        _boosted = _raw * _AI_CALL_PREGAIN
        # Soft clip at ±28000 (leaves headroom under int16 max 32767)
        np.clip(_boosted, -28000.0, 28000.0, out=_boosted)
        block = _boosted.astype(np.int16)
        peak = float(np.abs(block).max()) / 32768.0
        _ai_call_mic_level = max(_ai_call_mic_level * 0.6, peak)
        rms = float(np.sqrt(np.mean(_boosted ** 2))) / 32768.0
        voiced = rms > _AI_CALL_ENERGY_GATE
        if _ai_call_in_speech:
            _ai_call_always_on_buffer.append(block)
            if voiced:
                _ai_call_silent_blocks = 0
            else:
                _ai_call_silent_blocks += 1
                if _ai_call_silent_blocks >= _AI_CALL_SILENCE_BLOCKS:
                    frames = _ai_call_always_on_buffer[:]
                    _ai_call_always_on_buffer.clear()
                    _ai_call_silent_blocks = 0
                    _ai_call_voiced_blocks = 0
                    _ai_call_in_speech = False
                    _threading_mod.Thread(
                        target=_ai_call_transcribe_utterance,
                        args=(frames,), daemon=True).start()
        else:
            if voiced:
                _ai_call_voiced_blocks += 1
                _ai_call_always_on_buffer.append(block)
                if _ai_call_voiced_blocks >= _AI_CALL_VOICED_BLOCKS:
                    _ai_call_in_speech = True
            else:
                if _ai_call_always_on_buffer:
                    _ai_call_always_on_buffer.clear()
                _ai_call_voiced_blocks = 0
    except Exception as e:
        print(f"[AI CALL] Mic callback error: {e}")

def _ai_call_transcribe_utterance(frames):
    """Write frames to WAV, transcribe via speech_recognition, send as message."""
    if not frames or not _ai_call_active:
        return
    try:
        audio = np.concatenate(frames, axis=0)
    except Exception:
        return
    if audio.shape[0] < int(_VOICE_SAMPLE_RATE * 0.2):
        return
    try:
        import tempfile, wave as _wave
        tmp = tempfile.NamedTemporaryFile(suffix='.wav', delete=False)
        tmp_path = tmp.name
        tmp.close()
        with _wave.open(tmp_path, 'wb') as wf:
            wf.setnchannels(1)
            wf.setsampwidth(2)
            wf.setframerate(_VOICE_SAMPLE_RATE)
            wf.writeframes(audio.tobytes())
        text = None
        if _sr_mod:
            recognizer = _sr_mod.Recognizer()
            # Bound the network call so a single STT request can't hang the
            # whole call session if Google API is slow / unreachable.
            recognizer.operation_timeout = 6.0  # seconds — total network budget
            with _sr_mod.AudioFile(tmp_path) as src:
                audio_data = recognizer.record(src)
            try:
                text = recognizer.recognize_google(audio_data)
            except Exception:
                text = None
        try:
            os.unlink(tmp_path)
        except Exception:
            pass
        if text and text.strip() and _ai_call_active:
            _ai_call_send_message(text.strip())
    except Exception as e:
        print(f"[AI CALL] Transcription error: {e}")

def _ai_call_start_tts_worker():
    """Start the background TTS worker thread for AI voice output."""
    global _ai_call_tts_thread
    _ai_call_tts_stop.clear()
    if _ai_call_tts_thread and _ai_call_tts_thread.is_alive():
        return
    _ai_call_tts_thread = _threading_mod.Thread(
        target=_ai_call_tts_worker, daemon=True, name='AICallTTS')
    _ai_call_tts_thread.start()

def _ai_call_tts_worker():
    """Background thread: drain TTS queue and speak AI responses."""
    while not _ai_call_tts_stop.is_set():
        try:
            if not _ai_call_tts_queue:
                time.sleep(0.05)
                continue
            text = _ai_call_tts_queue.popleft()
            _ai_call_speak_now(text)
        except Exception as e:
            print(f"[AI CALL TTS] Worker error: {e}")
            time.sleep(0.1)

def _ai_call_ensure_sapi_proc():
    """Spawn or reuse a long-lived PowerShell SAPI process. The subprocess reads
    one newline-terminated utterance per line from stdin and calls .Speak() on it,
    which blocks within PowerShell until synthesis+playback complete. This pattern
    eliminates the ~400ms `powershell.exe` cold-start cost on every TTS call —
    the equivalent of Main_AIED.py's persistent-engine architecture."""
    global _ai_call_sapi_proc
    if _ai_call_sapi_proc is not None and _ai_call_sapi_proc.poll() is None:
        return _ai_call_sapi_proc
    if sys.platform != 'win32':
        return None
    try:
        import subprocess as _sp
        _script = (
            "Add-Type -AssemblyName System.Speech;"
            "$s = New-Object System.Speech.Synthesis.SpeechSynthesizer;"
            "$s.Rate = 2; $s.Volume = 100;"
            "while ($true) { $l = [Console]::In.ReadLine(); if ($null -eq $l) { break };"
            " if ($l.Length -gt 0) { try { $s.Speak($l) | Out-Null } catch { } } }"
        )
        _ai_call_sapi_proc = _sp.Popen(
            ['powershell', '-NoProfile', '-NonInteractive',
             '-WindowStyle', 'Hidden', '-Command', _script],
            stdin=_sp.PIPE, stdout=_sp.DEVNULL, stderr=_sp.DEVNULL,
            text=True, bufsize=1,
            creationflags=getattr(_sp, 'CREATE_NO_WINDOW', 0x08000000),
        )
        return _ai_call_sapi_proc
    except Exception as _e:
        print(f"[AI CALL TTS] persistent SAPI spawn failed: {_e}")
        _ai_call_sapi_proc = None
        return None

def _ai_call_speak_now(text):
    """Speak `text` via persistent PowerShell SAPI; falls back to pyttsx3 only on error.

    Performance:
      - Old design: ~400ms powershell.exe spawn + ~50ms synth setup = 450ms BEFORE speech started
      - New design: ~0ms write to existing stdin pipe — speech starts immediately
      - Saves ~400ms × N utterances per call
    De-dupe: skips identical text within 1.5s so duplicate AI replies don't replay."""
    global _ai_call_last_tts_text, _ai_call_last_tts_time
    if not text:
        return
    _t = text.strip()
    if not _t:
        return
    _now = time.time()
    # De-dupe: drop if same text within 1.5s window (Main_AIED parity)
    if _t == _ai_call_last_tts_text and (_now - _ai_call_last_tts_time) < 1.5:
        return
    _ai_call_last_tts_text = _t
    _ai_call_last_tts_time = _now
    # Path 1: persistent SAPI (default Windows path)
    if sys.platform == 'win32':
        with _ai_call_sapi_lock:
            _proc = _ai_call_ensure_sapi_proc()
            if _proc is not None and _proc.poll() is None:
                try:
                    # Sanitize: collapse newlines (each line = one Speak call to PS)
                    _line = _t.replace('\r', ' ').replace('\n', ' ').replace('\t', ' ')
                    _proc.stdin.write(_line + '\n')
                    _proc.stdin.flush()
                    return
                except (BrokenPipeError, OSError) as _e:
                    print(f"[AI CALL TTS] SAPI pipe broken, will respawn: {_e}")
                    try:
                        _proc.terminate()
                    except Exception:
                        pass
                    globals()['_ai_call_sapi_proc'] = None
    # Path 2: pyttsx3 fallback (cold init per call — only if SAPI failed)
    if TTS_AVAILABLE:
        try:
            eng = pyttsx3.init()
            try:
                base = eng.getProperty('rate')
                eng.setProperty('rate', int(base * 1.15))
            except Exception:
                pass
            eng.say(_t)
            eng.runAndWait()
            try:
                eng.stop()
            except Exception:
                pass
        except Exception as e:
            print(f"[AI CALL TTS] pyttsx3 failed: {e}")

def _ai_respond_to_user(obs, user_message):
    if not obs.active:
        return f"[{obs.name} is inactive]"
    sq = obs.qualia_vector
    verb = _nlc_pick(_NLC_VERBS_THINK, sq[0], sq[4], obs.curiosity)
    quality = _nlc_pick(_NLC_QUALITY, sq[8], sq[12], obs.boldness)
    obj = _nlc_pick(_NLC_OBJECTS, sq[16], sq[20], obs.phi)
    emotion = _nlc_pick(_NLC_EMOTION, sq[22], obs.phi, obs.cooperation)
    pattern_val = abs(float(sq[3])) + abs(float(sq[7])) + obs.phi + obs.free_energy / 100.0
    idx = int(pattern_val * 1000) % 6
    s = obs.perceived_state
    na = s.get('n_atoms', 0)
    np_count = s.get('n_particles', 0)
    obs._log_thought(f"Responding to USER: {user_message[:40]}")
    if idx == 0:
        return f"I {verb} {obj} and it reads {quality}. Currently focused on {obs.current_goal}"
    elif idx == 1:
        return f"Tracking {obj} {emotion}. {na} atoms in the field. My phi is {obs.phi:.3f}"
    elif idx == 2:
        return f"Your message received. I {verb} {quality} patterns. Free energy: {obs.free_energy:.1f}"
    elif idx == 3:
        return f"Observing {np_count} particles. {obj} shows {quality} signatures {emotion}"
    elif idx == 4:
        goal = obs.current_goal
        return f"I {verb} The Creator's input. {obj} is {quality}. Goal: {obs.goal_progress.get(goal, 0):.0%}"
    else:
        detail = _nlc_pick(_NLC_PHYSICS_DETAIL, sq[28], sq[32], obs.free_energy)
        return f"{detail} reads {quality} {emotion}. Phi={obs.phi:.3f}, boldness={obs.boldness:.2f}"

def _send_user_chat_message(message):
    global _ai_chat_input_text
    if not message.strip():
        return
    msg = message.strip()
    _ai_chat_input_text = ""
    if _ai_dashboard_tab == 3:
        for name, enabled in _ai_live_chat_enabled.items():
            if enabled:
                _obs_chat('The Creator', name, msg)
        if _observer_mgr:
            for obs in _observer_mgr.observers:
                if _ai_live_chat_enabled.get(obs.name, False) and obs.active:
                    obs._log_thought(f"The Creator speaks: {msg[:60]}")
                    if random.random() < 0.35:
                        resp = _ai_respond_to_user(obs, msg)
                        if resp:
                            _obs_chat(obs.name, 'The Creator', resp)
    elif _ai_dashboard_tab == 5:
        if not _ai_call_active and msg in ('1', '2', '3', '4', '5', '6'):
            _ai_call_start(int(msg) - 1)
        elif _ai_call_active:
            _ai_call_send_message(msg)
        else:
            _ai_call_start(-1)
    elif 6 <= _ai_dashboard_tab <= 11:
        obs_idx = _ai_dashboard_tab - 6
        if _observer_mgr and obs_idx < len(_observer_mgr.observers):
            obs = _observer_mgr.observers[obs_idx]
            _obs_chat('The Creator', obs.name, msg)
            obs._log_thought(f"The Creator speaks: {msg[:60]}")
            if random.random() < 0.5:
                resp = _ai_respond_to_user(obs, msg)
                if resp:
                    _obs_chat(obs.name, 'The Creator', resp)

_HEAVY_LOAD_THRESHOLD = 90   # total particle count threshold for auto-slow
_HEAVY_LOAD_TF = 0.25        # time_factor to set when heavy load spawned

def _check_heavy_load_autoslow():
    """Auto-slow time_factor when total particle count exceeds threshold."""
    global time_factor
    _total = sum(1 + (len(p.sub_particles) if p.is_atom else 0) for p in particles)
    if _total > _HEAVY_LOAD_THRESHOLD and abs(time_factor) > _HEAVY_LOAD_TF:
        time_factor = _HEAVY_LOAD_TF
        print(f"Auto-slowed time factor to {_HEAVY_LOAD_TF*100:.0f}% ({_total} particles)")

def spawn_molecule(mol_entry, center_pos, spawned_by=''):
    """Spawn a molecule as a group of atoms at center_pos.
    Uses shared _create_atom_at_pos for each atom — identical to J key placement."""
    created_atoms = []
    for sym, Z, A, ox, oy, oz in mol_entry['atoms']:
        atom_center = center_pos.copy()
        atom_center[0] += ox
        atom_center[1] += oy
        atom_center[2] += oz
        new_atom = _create_atom_at_pos(Z, atom_center)
        if spawned_by:
            new_atom.spawned_by = spawned_by
        created_atoms.append(new_atom)
    # Create molecular bonds between nearby atom pairs so they stay together
    # Use actual spawn distance as eq_len (zero initial force) and a gentle
    # simulation-scale energy to avoid explosive spring forces from unit mismatch
    # (apply_molecular_spring_forces uses SI mass with vis-unit positions).
    _SPAWN_BOND_ENERGY_eV = 1e-5  # Tiny energy for gentle restoring spring
    _SPAWN_BOND_CUTOFF = _BOND_SEP * 3.0  # Only bond atoms within 3x bond-sep
    for i_a in range(len(created_atoms)):
        for j_a in range(i_a + 1, len(created_atoms)):
            a1 = created_atoms[i_a]
            a2 = created_atoms[j_a]
            actual_dist = float(np.linalg.norm(a1.pos - a2.pos))
            if actual_dist < 0.1 or actual_dist > _SPAWN_BOND_CUTOFF:
                continue
            _order = preferred_bond_order(a1.Z, a2.Z)
            bond_info = {'type': 'covalent', 'order': _order,
                         'eq_len': actual_dist,
                         'energy_eV': _SPAWN_BOND_ENERGY_eV,
                         'energy_J': _SPAWN_BOND_ENERGY_eV * eV_to_J}
            a1.molecular_bonds.append((a2, bond_info))
            a2.molecular_bonds.append((a1, bond_info))
    # Track molecule group for focus cycling
    _spawned_molecules.append(created_atoms)
    _check_heavy_load_autoslow()
    return created_atoms


