# === Deterministic Time Travel Frame Buffer ===
# Dense recording of simulation state every render frame.
# Reverse time restores from recorded frames (byte-identical determinism).
# Forward within recorded range replays from frames.
# Forward past recorded range runs live physics and records new frames.
# When reversing past recorded frames, runs live reverse physics.
_det_frames = []          # Ring buffer: [(sim_time, exp_scale, cloud_r, V_total, V_pct, [(pos,vel),...]), ...]
_det_frame_max = 18000    # Max frames stored (~5 min at 60fps)
_det_playhead = -1        # -1 = live mode, 0..N-1 = replay index
_reverse_live_mode = False # True when recorded frames exhausted during reverse â€” runs live reverse physics

def _record_particle_states(particles):
    """Record full state for all particles, including atom sub-particles and quarks.
    Returns list of tuples: (pos, vel, sub_data) where sub_data is None for non-atoms,
    or [(sp_pos, sp_vel, [(q_pos, q_vel), ...]), ...] for atoms."""
    states = []
    for p in particles:
        if p.is_atom and hasattr(p, 'sub_particles') and p.sub_particles:
            sub_data = []
            for sp in p.sub_particles:
                quarks = []
                for q in getattr(sp, 'constituent_quarks', []):
                    quarks.append((q.pos.copy(), q.vel.copy()))
                sub_data.append((sp.pos.copy(), sp.vel.copy(), quarks))
            states.append((p.pos.copy(), p.vel.copy(), sub_data))
        else:
            states.append((p.pos.copy(), p.vel.copy(), None))
    return states

def _restore_particle_states(particles, states):
    """Restore full state for all particles from recorded states,
    including atom sub-particles and their constituent quarks."""
    for i, p in enumerate(particles):
        if i >= len(states):
            break
        st = states[i]
        p.pos = st[0].copy()
        p.vel = st[1].copy()
        # Restore sub-particle + quark state if this is an atom
        sub_data = st[2] if len(st) > 2 else None
        if sub_data is not None and p.is_atom and hasattr(p, 'sub_particles'):
            for si, sp in enumerate(p.sub_particles):
                if si >= len(sub_data):
                    break
                sp.pos = sub_data[si][0].copy()
                sp.vel = sub_data[si][1].copy()
                quark_data = sub_data[si][2] if len(sub_data[si]) > 2 else []
                for qi, q in enumerate(getattr(sp, 'constituent_quarks', [])):
                    if qi >= len(quark_data):
                        break
                    q.pos = quark_data[qi][0].copy()
                    q.vel = quark_data[qi][1].copy()

def _interpolate_particle_states(particles, states_a, states_b, blend):
    """Interpolate particle state between two recorded snapshots, including sub-particles."""
    n_a = len(states_a)
    n_b = len(states_b)
    for i, p in enumerate(particles):
        if i < n_a and i < n_b:
            sa = states_a[i]
            sb = states_b[i]
            p.pos = sa[0] + (sb[0] - sa[0]) * blend
            p.vel = sa[1] + (sb[1] - sa[1]) * blend
            sub_a = sa[2] if len(sa) > 2 else None
            sub_b = sb[2] if len(sb) > 2 else None
            if sub_a is not None and sub_b is not None and p.is_atom and hasattr(p, 'sub_particles'):
                for si, sp in enumerate(p.sub_particles):
                    if si >= len(sub_a) or si >= len(sub_b):
                        break
                    sp.pos = sub_a[si][0] + (sub_b[si][0] - sub_a[si][0]) * blend
                    sp.vel = sub_a[si][1] + (sub_b[si][1] - sub_a[si][1]) * blend
                    q_a = sub_a[si][2] if len(sub_a[si]) > 2 else []
                    q_b = sub_b[si][2] if len(sub_b[si]) > 2 else []
                    for qi, q in enumerate(getattr(sp, 'constituent_quarks', [])):
                        if qi >= len(q_a) or qi >= len(q_b):
                            break
                        q.pos = q_a[qi][0] + (q_b[qi][0] - q_a[qi][0]) * blend
                        q.vel = q_a[qi][1] + (q_b[qi][1] - q_a[qi][1]) * blend
        elif i < n_a:
            sa = states_a[i]
            p.pos = sa[0].copy()
            p.vel = sa[1].copy()
            sub_a = sa[2] if len(sa) > 2 else None
            if sub_a is not None and p.is_atom and hasattr(p, 'sub_particles'):
                for si, sp in enumerate(p.sub_particles):
                    if si >= len(sub_a):
                        break
                    sp.pos = sub_a[si][0].copy()
                    sp.vel = sub_a[si][1].copy()
                    for qi, q in enumerate(getattr(sp, 'constituent_quarks', [])):
                        q_data = sub_a[si][2] if len(sub_a[si]) > 2 else []
                        if qi < len(q_data):
                            q.pos = q_data[qi][0].copy()
                            q.vel = q_data[qi][1].copy()

def _find_nearest_frame_by_time(target_time):
    """Binary search _det_frames for the frame nearest to target_time.
    Returns frame index or -1 if no frames."""
    if not _det_frames:
        return -1
    lo, hi = 0, len(_det_frames) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if _det_frames[mid][0] < target_time:
            lo = mid + 1
        else:
            hi = mid
    # lo is now the first frame >= target_time; check which neighbor is closer
    if lo > 0 and abs(_det_frames[lo - 1][0] - target_time) < abs(_det_frames[lo][0] - target_time):
        return lo - 1
    return lo

# (Behavioral extrapolation cache removed — all time factors use raw physics only)

# === Space Expansion (Hubble-like, CMB-calibrated) ===
# Real Hubble constant H0 = 67.4 km/s/Mpc ~ 2.184e-18 /s.
# CMB temperature scales as T_cmb = 2.725 K / a(t), where a(t) is the scale factor.
# We use H_real scaled up so expansion is visible within the simulation's
# timescale while preserving the correct exponential growth character.
# At H_sim = 2.184e-6, expansion doubles every ~317,000 sim-seconds (~3.7 days).
# This is 1e12× faster than reality but keeps the same Hubble-flow physics.
H_real = 2.184e-18    # true Hubble constant (/s) — for reference
H_sim = 2.184e-6      # sim Hubble parameter: H_real × 1e12 (visible expansion)
expansion_scale = 1.0  # current cumulative expansion factor (starts at 1)

def sphere_coords_to_3d_pos(degree, xz, xx, xy, radius):
    """Convert dimensional sphere coordinates to a 3D simulation position.
    degree (0-360) â†’ azimuthal angle (longitude),
    xz (0-59)      â†’ polar angle (latitude, mapped 0-180Â°),
    xx (0-59)      â†’ radial depth fraction,
    xy (0-59)      â†’ fine radial subdivision,
    radius          â†’ current expansion radius of the universe."""
    theta = math.radians(degree)                    # azimuthal (longitude)
    phi = math.pi * xz / max(59.0, 1.0)            # polar (latitude, 0â†’Ï€)
    r_frac = (xx + xy / 60.0) / 60.0               # 0..1 radial fraction
    r = radius * max(0.05, r_frac)                  # at least 5% of radius
    x_3d = r * math.sin(phi) * math.cos(theta)
    y_3d = r * math.sin(phi) * math.sin(theta)
    z_3d = r * math.cos(phi)
    return np.array([x_3d, y_3d, z_3d] + [0.0] * (dims - 3))

def _safe_float(v):
    """Clamp a value to a safe finite range for location hashing."""
    import math as _m
    if _m.isnan(v) or _m.isinf(v):
        return 0.0
    return max(-1e15, min(1e15, v))


def particle_infinity_location(p):
    """Compute a particle's unique location within the V_total infinity map.
    Returns a high-precision fractional address (0..1) within INFINITY_MAP,
    deterministic and ever-changing based on the particle's state and V_total.
    This is the particle's 'address in infinity' â€” where it exists in the
    dimensional sphere at this moment in time.
    Positions are comoving: divided by expansion_scale so the 5,184,000 grid
    represents the full expanded space and locations become finer decimals
    as the universe expands."""
    _einv = 1.0 / max(1e-30, expansion_scale)  # comoving inverse
    _pos_hash = _safe_float((float(p.pos[0]) * _einv) * 7.13 + (float(p.pos[1]) * _einv) * 11.37 + (float(p.pos[2]) * _einv) * 3.91)
    _vel_hash = _safe_float(float(p.vel[0]) * 2.71 + float(p.vel[1]) * 5.43 + float(p.vel[2]) * 1.67)
    _mass_c = _safe_float(p.mass * 1e10) if p.mass > 0 else 1e-20
    _e_c = _safe_float(p.energy_kin + getattr(p, 'energy_rot', 0) + 1e-40)
    _charge_c = _safe_float((p.charge + 2.0) * 3.7)
    _spin_c = _safe_float((getattr(p, 'spin', 0) + 1.0) * 13.0)
    _raw = abs(_pos_hash) + abs(_vel_hash) + abs(_mass_c) + abs(_e_c) + abs(_charge_c) + abs(_spin_c)
    _raw += _safe_float(abs(V_total) * 1e-8) + _safe_float(simulation_time * 0.0137)
    _raw = _safe_float(_raw)
    if _raw == 0.0:
        _raw = 1e-20
    _frac = (_raw % INFINITY_MAP) / INFINITY_MAP
    return _frac


def particle_frame_location(p):
    """Compute a particle's deterministic state-space frame location (Î¦).
    Unlike the ever-changing âˆž address, this is a FIXED coordinate for the
    current simulation frame â€” it gives the exact, solved location of this
    particle within the dimensional sphere at this instant. When paused,
    this value is frozen and represents the particle's definite position
    in the infinity map.
    Positions are comoving: divided by expansion_scale so locations become
    smaller decimal addresses as the universe expands.
    Returns (location_index, degree, coord_str)."""
    # Use individual position components with prime multipliers for unique spreading
    # Comoving: divide by expansion_scale so the grid covers expanded space
    _einv = 1.0 / max(1e-30, expansion_scale)
    _px = _safe_float(float(p.pos[0]) * _einv)
    _py = _safe_float(float(p.pos[1]) * _einv)
    _pz = _safe_float(float(p.pos[2]) * _einv)
    _vx = _safe_float(float(p.vel[0]))
    _vy = _safe_float(float(p.vel[1]))
    _vz = _safe_float(float(p.vel[2]))
    _mass_v = _safe_float(p.mass * 1e12)
    _e_v = _safe_float(p.energy_kin + getattr(p, 'energy_rot', 0))
    _charge_v = _safe_float(p.charge)
    _spin_v = _safe_float(getattr(p, 'spin', 0))
    # Per-particle unique hash using non-commutative combination of all state
    _h1 = _px * 7.13 + _py * 11.37 + _pz * 3.91
    _h2 = _vx * 2.71 + _vy * 5.43 + _vz * 1.67
    _h3 = _mass_v * 0.0031 + _e_v * 0.0017 + _charge_v * 197.3 + _spin_v * 53.0
    # Use id(p) for a truly unique per-particle seed that survives even when
    # multiple particles share identical state (e.g. freshly spawned)
    _pid = id(p) % 5184000
    # Combine: particle-specific terms dominate, time modulates slowly
    _state = abs(_h1) * 137.036 + abs(_h2) * 29.97 + abs(_h3) + _pid
    _state += _safe_float(simulation_time * 0.37)  # slow time modulation
    _state = _safe_float(_state)
    if _state == 0.0:
        _state = 1e-20
    loc = int(_state % INFINITY_MAP)
    cycle = loc // 216000
    rem = loc % 216000
    xz = rem // 3600
    xx = (rem % 3600) // 60
    xy = rem % 60
    degree = (cycle / 24.0) * 360.0
    coord_str = f"{degree:.1f}\u00b0,{xz},{xx},{xy}"
    return loc, degree, coord_str


def particle_frame_location_f(p):
    """Float variant of particle_frame_location: identical state hash but
    keeps the sub-cell decimals of _state mod INFINITY_MAP instead of
    truncating to an integer cell. Returns (loc_f, degree, coord_str) where
    loc_f is a float AS address and coord_str shows fractional coords with
    as_loc_decimals() decimal places."""
    _einv = 1.0 / max(1e-30, expansion_scale)
    _px = _safe_float(float(p.pos[0]) * _einv)
    _py = _safe_float(float(p.pos[1]) * _einv)
    _pz = _safe_float(float(p.pos[2]) * _einv)
    _vx = _safe_float(float(p.vel[0]))
    _vy = _safe_float(float(p.vel[1]))
    _vz = _safe_float(float(p.vel[2]))
    _mass_v = _safe_float(p.mass * 1e12)
    _e_v = _safe_float(p.energy_kin + getattr(p, 'energy_rot', 0))
    _charge_v = _safe_float(p.charge)
    _spin_v = _safe_float(getattr(p, 'spin', 0))
    _h1 = _px * 7.13 + _py * 11.37 + _pz * 3.91
    _h2 = _vx * 2.71 + _vy * 5.43 + _vz * 1.67
    _h3 = _mass_v * 0.0031 + _e_v * 0.0017 + _charge_v * 197.3 + _spin_v * 53.0
    _pid = id(p) % 5184000
    _state = abs(_h1) * 137.036 + abs(_h2) * 29.97 + abs(_h3) + _pid
    _state += _safe_float(simulation_time * 0.37)
    _state = _safe_float(_state)
    if _state == 0.0:
        _state = 1e-20
    loc_f = _state % float(INFINITY_MAP)
    cyc, xz_f, xx_f, xy_f = infinity_map_loc_decode_f(loc_f)
    degree = (int(cyc) / 24.0) * 360.0
    _nd = as_loc_decimals()
    coord_str = (f"{degree:.1f}\u00b0,{xz_f:.{_nd}f},{xx_f:.{_nd}f},"
                 f"{xy_f:.{_nd}f}")
    return loc_f, degree, coord_str


def parse_time_input(txt):
    """Parse a time input string into seconds.
    Supported formats:
      - Plain number â‰¤100 â†’ None (caller treats as time factor %)
      - 'Xs' â†’ X seconds          e.g. '500s' = 500 seconds
      - 'Xm' â†’ X minutes          e.g. '30m' = 1800 seconds
      - 'Xh' â†’ X hours            e.g. '2h' = 7200 seconds
      - 'Xy' â†’ X years            e.g. '1y' = 31,540,000 seconds
      - '2h30m15s' â†’ combined     e.g. 2*3600 + 30*60 + 15 = 9015 seconds
      - 'HH:MM:SS' â†’ hours:min:s  e.g. '1:30:00' = 5400 seconds
      - 'MM:SS' â†’ min:sec         e.g. '5:30' = 330 seconds
    Returns (mode, value) where mode is 'time_seconds', 'time_factor', or None on error.
    """
    import re
    txt = txt.strip().lower()
    if not txt:
        return None, 0.0
    # Check for colon-separated format (HH:MM:SS or MM:SS)
    if ':' in txt:
        parts = txt.split(':')
        try:
            nums = [float(p) for p in parts]
        except ValueError:
            return None, 0.0
        if len(nums) == 3:
            return 'time_seconds', nums[0] * 3600 + nums[1] * 60 + nums[2]
        elif len(nums) == 2:
            return 'time_seconds', nums[0] * 60 + nums[1]
        return None, 0.0
    # Check for suffix-based format (e.g. '2h30m15s', '500s', '1y')
    _has_suffix = bool(re.search(r'[hmsy]', txt))
    if _has_suffix:
        total = 0.0
        for val_str, unit in re.findall(r'([0-9]*\.?[0-9]+)\s*([hmsy])', txt):
            v = float(val_str)
            if unit == 's':
                total += v
            elif unit == 'm':
                total += v * 60.0
            elif unit == 'h':
                total += v * 3600.0
            elif unit == 'y':
                total += v * 3.154e7
        if total != 0.0:
            return 'time_seconds', total
        return None, 0.0
    # Plain number: try float
    try:
        val = float(txt)
    except ValueError:
        return None, 0.0
    # â‰¤100 â†’ time factor %; >100 â†’ seconds to jump to
    if abs(val) <= 100:
        return 'time_factor', val
    else:
        return 'time_seconds', val


def particle_infinity_addr_str(p):
    """Format a particle's infinity location as a high-precision string.
    Returns e.g. '0.00000003184729...' â€” the ever-changing address in the
    dimensional sphere of V_total."""
    frac = particle_infinity_location(p)
    if frac == 0.0:
        return "0." + "0" * 18 + "..."
    s = f"{frac:.20f}"
    return s.rstrip('0') + '...'


def particle_frame_addr_str(p):
    """Format a particle's state-space frame location as a string.
    Returns e.g. 'Î¦:142857 (45.0Â°,2,13,57)' â€” the solved, fixed location
    at this exact frame/instant in time."""
    loc_f, deg, coord = particle_frame_location_f(p)
    # AS: every frame address also carries its time HH:MM:SS.ff (decimal ff)
    _nd = as_loc_decimals()
    return (f"{loc_f:,.{_nd}f}/{INFINITY_MAP:,} ({coord}) "
            f"t={infinity_map_time_str_f(loc_f, _nd)}")


def vtotal_to_sphere_coords(v_total_val):
    """Convert V_total to dimensional sphere coordinates.
    Returns (degree, xz, xx, xy, cycle, time_str, location_index)."""
    _abs_v = abs(v_total_val)
    if math.isnan(_abs_v) or math.isinf(_abs_v):
        _abs_v = 0.0
    loc = int(_abs_v % INFINITY_MAP)
    cycle = loc // 216000  # 0-23 (60*60*60 = 216000)
    rem = loc % 216000
    xz = rem // 3600  # 0-59
    xx = (rem % 3600) // 60  # 0-59
    xy = rem % 60  # 0-59
    degree = (cycle / 24.0) * 360.0
    # Map to time: cycle=hour, xz=minute, xx=second, xy=fractional
    time_str = f"{cycle:02d}:{xz:02d}:{xx:02d}.{xy:02d}"
    return degree, xz, xx, xy, cycle, time_str, loc


def _mandelbrot_compute(res, center_r, center_i, zoom, max_iter):
    """Compute an INVERTED (outward-looking) Mandelbrot grid.
    Uses c → 1/c̄ inversion: the exterior of the standard set maps to the
    rendered plane, so scrolling expands outward from the boundary.
    The boundary itself is the 'barrier of translation' between the
    sphere (inward) and Mandelbrot (outward) coordinate systems.
    Returns (iter_grid, r_min, r_max, i_min, i_max) in the INVERTED plane."""
    scale = 3.5 / max(zoom, 0.001)
    r_min = center_r - scale / 2.0
    r_max = center_r + scale / 2.0
    i_min = center_i - scale / 2.0
    i_max = center_i + scale / 2.0
    r = np.linspace(r_min, r_max, res)
    i = np.linspace(i_min, i_max, res)
    C_view = r[np.newaxis, :] + 1j * i[:, np.newaxis]
    # Inversion: map each view-plane point through 1/c̄ (Riemann sphere
    # antipodal map).  Points near the origin in the view correspond to
    # the FAR exterior of the standard set; points far from the origin
    # correspond to points near the set boundary — exactly the outward-
    # looking perspective described by the 180° rotation (image 3).
    mag_sq = np.abs(C_view) ** 2
    safe = mag_sq > 1e-30
    C = np.where(safe, np.conj(C_view) / np.where(safe, mag_sq, 1.0), 0.0 + 0j)
    Z = np.zeros_like(C)
    M = np.full(C.shape, max_iter, dtype=np.int32)
    mask = np.ones(C.shape, dtype=bool)
    for n in range(max_iter):
        Z[mask] = Z[mask] ** 2 + C[mask]
        escaped = mask & (np.abs(Z) > 2.0)
        M[escaped] = n
        mask &= ~escaped
        if not mask.any():
            break
    # Invert iteration counts: exterior points that escape quickly should
    # appear as HIGH values (far outward), interior (never-escape) stays 0.
    # This makes the 3D wireframe rise outward from the boundary.
    M_out = np.where(M < max_iter, max_iter - M, 0).astype(np.int32)
    return M_out, r_min, r_max, i_min, i_max


def _mandelbrot_iter_color(n, max_iter):
    """Map INVERTED iteration count to an RGBA color tuple.
    n=0 = interior/boundary (dark); n>0 = exterior (colored by outward distance).
    Higher n = farther outward = brighter."""
    if n <= 0:
        return (8, 8, 40, 220)
    t = n / max(max_iter, 1)
    if t < 0.15:
        r = int(t / 0.15 * 80)
        g = int(t / 0.15 * 20)
        b = int(80 + t / 0.15 * 120)
        return (r, g, b, 220)
    elif t < 0.4:
        f = (t - 0.15) / 0.25
        return (int(80 + f * 100), int(20 + f * 200), int(200 - f * 80), 220)
    elif t < 0.65:
        f = (t - 0.4) / 0.25
        return (int(180 + f * 75), int(220 - f * 40), int(120 - f * 80), 220)
    else:
        f = (t - 0.65) / 0.35
        return (int(255 - f * 60), int(180 - f * 120), int(40 + f * 40), 220)


def _mandelbrot_build_image(data, max_iter, draw_w, draw_h):
    """Vectorized: convert iteration grid to a pyglet ImageData scaled to draw_w x draw_h.
    Returns a pyglet.image.ImageData ready for .blit()."""
    res_y, res_x = data.shape
    t = data.astype(np.float64) / max(max_iter, 1)
    inside = data <= 0  # Inverted: 0 = interior/boundary (dark)
    # Allocate RGB arrays
    r = np.zeros_like(t)
    g = np.zeros_like(t)
    b = np.zeros_like(t)
    # Inside set
    r[inside] = 8; g[inside] = 8; b[inside] = 40
    # Band 1: t < 0.15
    m1 = (~inside) & (t < 0.15)
    f1 = t[m1] / 0.15
    r[m1] = f1 * 80; g[m1] = f1 * 20; b[m1] = 80 + f1 * 120
    # Band 2: 0.15 <= t < 0.4
    m2 = (~inside) & (t >= 0.15) & (t < 0.4)
    f2 = (t[m2] - 0.15) / 0.25
    r[m2] = 80 + f2 * 100; g[m2] = 20 + f2 * 200; b[m2] = 200 - f2 * 80
    # Band 3: 0.4 <= t < 0.65
    m3 = (~inside) & (t >= 0.4) & (t < 0.65)
    f3 = (t[m3] - 0.4) / 0.25
    r[m3] = 180 + f3 * 75; g[m3] = 220 - f3 * 40; b[m3] = 120 - f3 * 80
    # Band 4: t >= 0.65
    m4 = (~inside) & (t >= 0.65)
    f4 = (t[m4] - 0.65) / 0.35
    r[m4] = 255 - f4 * 60; g[m4] = 180 - f4 * 120; b[m4] = 40 + f4 * 40
    # Clamp and convert to uint8
    r = np.clip(r, 0, 255).astype(np.uint8)
    g = np.clip(g, 0, 255).astype(np.uint8)
    b = np.clip(b, 0, 255).astype(np.uint8)
    # Interleave into RGB bytes (pyglet expects bottom-to-top row order)
    rgb = np.stack([r, g, b], axis=-1)  # (res_y, res_x, 3)
    raw = bytes(rgb.tobytes())
    img = pyglet.image.ImageData(res_x, res_y, 'RGB', raw, pitch=res_x * 3)
    return img


def _mandelbrot_to_sphere_loc(c_real, c_imag):
    """Map Mandelbrot complex coordinates to an INFINITY_MAP location address.
    Standard Mandelbrot view: real âˆˆ [-2.5, 1.5], imag âˆˆ [-2.0, 2.0].
    Returns integer location 0..INFINITY_MAP-1."""
    # AS bijection inverse: row = floor((re+2.5)*540), col = floor((im+2)*600)
    return infinity_map_mandelbrot_to_loc(c_real, c_imag)


def _sphere_loc_to_mandelbrot(loc):
    """Reverse map: INFINITY_MAP location â†’ Mandelbrot (c_real, c_imag)."""
    loc = loc % INFINITY_MAP
    row = loc // 2400
    col = loc % 2400
    # AS cell-centre bijection: re = -2.5 + (row+.5)/540,
    # im = -2 + (col+.5)/600  (2160x2400 px = 1 cell per address)
    c_real = -2.5 + (row + 0.5) / 540.0
    c_imag = -2.0 + (col + 0.5) / 600.0
    return c_real, c_imag

# =============================================================================
# AS.png -- "accurate & solved" -- the map of infinity, proven (simulation tier)
# =============================================================================
# The CS tier (above, `if _TORCH:`) carries INFINITY_MAP_LIBRARY, the sympy
# MATH_EQUATIONS, the _AS_PNG_B64 embedded image, and the import-time
# _infinity_map_verify()/INFINITY_MAP_VERIFIED self-check. This block brings
# the SAME corrected spec to the torch-independent simulation side: every
# formula the sheet proves is executable here, and the hotkey displays
# (N/V/X lists, F4 grid, F7 sphere nav, F8 sphere map, 0/. Mandelbrot)
# all show locations in the AS address format.
#
#   24 looped cycles x 60^3 cells = 5,184,000 locations
#     = 86,400 s x 60 = 2160 x 2400 = infinity
#   corrected + completed version of LMFAO.png:
#     index <-> coords <-> time <-> C-pixel <-> 3-D space
#
# The map is 24 vertical FINS (half-discs) fanned 15 deg apart around the
# z-axis -- NOT a filled volume. deg is FIXED within a cycle (= cyc*15);
# only xz, xx, xy vary inside a fin. Poles (xz=0/59) and the r-floor
# (xx+xy/60 <= 3 -> .05R) are the only degenerate cells; else injective.
INFINITY_MAP_CYCLES = 24                      # looped cycles, cyc in [0, 24)
INFINITY_MAP_CELLS_PER_CYCLE = 216_000        # 60 * 60 * 60
INFINITY_MAP_GRID = 60                        # xz, xx, xy each in [0, 60)
INFINITY_MAP_SECONDS = 86_400                 # 24 cyc * 3600 s = 1 day
INFINITY_MAP_ROWS = 2160                      # Mandelbrot pixel rows
INFINITY_MAP_COLS = 2400                      # Mandelbrot pixel cols


def infinity_map_deg_to_cycle(deg):
    """AS: deg in -> cyc = floor(deg/15) mod 24. 270.0..284.99 -> cyc 18."""
    try:
        return int(math.floor(float(deg) / 15.0)) % INFINITY_MAP_CYCLES
    except Exception:
        return 0


def infinity_map_cycle_deg(cyc):
    """AS: deg stored = cyc*15 in {0, 15, ..., 345} (deg = the cycle)."""
    return (int(cyc) % INFINITY_MAP_CYCLES) * 15.0


def infinity_map_signed_wrap(s):
    """AS: signed s in [-30,+30) -> unsigned cell coord u = (s+30) mod 60."""
    try:
        return (int(s) + 30) % INFINITY_MAP_GRID
    except Exception:
        return 0


def infinity_map_loc(cyc, xz, xx, xy):
    """AS: loc = cyc*216000 + xz*3600 + xx*60 + xy in [0, 5,184,000)."""
    return ((int(cyc) % INFINITY_MAP_CYCLES) * 216000
            + (int(xz) % INFINITY_MAP_GRID) * 3600
            + (int(xx) % INFINITY_MAP_GRID) * 60
            + (int(xy) % INFINITY_MAP_GRID))


def infinity_map_loc_decode(loc):
    """AS: loc -> (cyc, xz, xx, xy); cyc = loc//216000, xz = rem//3600,
    xx = (rem%3600)//60, xy = rem%60."""
    loc = int(loc) % INFINITY_MAP
    cyc = loc // INFINITY_MAP_CELLS_PER_CYCLE
    rem = loc % INFINITY_MAP_CELLS_PER_CYCLE
    xz = rem // 3600
    xx = (rem % 3600) // 60
    xy = rem % 60
    return cyc, xz, xx, xy


def infinity_map_time_str(loc):
    """AS: t = cycle:xz:xx.xy = HH:MM:SS.ff (1 cell = 1/60 s;
    span 00:00:00.00 .. 23:59:59.59 = one day)."""
    cyc, xz, xx, xy = infinity_map_loc_decode(loc)
    return f"{cyc:02d}:{xz:02d}:{xx:02d}.{xy:02d}"


def infinity_map_time_to_loc(HH, MM, SS, FF=0):
    """AS: loc = HH*216000 + MM*3600 + SS*60 + FF -- the t -> cell
    bijection (every t with ff 00..59 names a cell, every cell a t)."""
    return (int(HH) * 216000 + int(MM) * 3600 + int(SS) * 60
            + int(FF)) % INFINITY_MAP


def infinity_map_radial_frac(xx, xy):
    """AS: r = R*max(.05, (xx + xy/60)/60); xy is the in-depth axis.
    r-floor: (xx+xy/60) <= 3 -> .05R (degenerate); max cell r = .9997R."""
    try:
        return max(0.05, (float(xx) + float(xy) / 60.0) / 60.0)
    except Exception:
        return 0.05


def infinity_map_cell_pos(cyc, xz, xx, xy, radius=1.0):
    """AS: pos = r*(sin phi cos theta, sin phi sin theta, cos phi);
    phi = pi*xz/59 (top->bottom), theta = cyc*15 deg (azimuth, 0 deg at
    +x, CCW). r = R*max(.05, (xx+xy/60)/60); R = current radius."""
    theta = math.radians(infinity_map_cycle_deg(cyc))
    phi = math.pi * (float(xz) % INFINITY_MAP_GRID) / 59.0
    r = float(radius) * infinity_map_radial_frac(xx, xy)
    sp = math.sin(phi)
    return (r * sp * math.cos(theta), r * sp * math.sin(theta), r * math.cos(phi))


def infinity_map_loc_to_mandelbrot(loc):
    """AS Mandelbrot cell bijection: row = loc/2400, col = loc%2400,
    c = re + im*i at cell centres: re = -2.5 + (row+.5)/540,
    im = -2 + (col+.5)/600  (2160 x 2400 px = 1 cell per address;
    centres round-trip, corners 20.7% alias float)."""
    loc = int(loc) % INFINITY_MAP
    row = loc // INFINITY_MAP_COLS
    col = loc % INFINITY_MAP_COLS
    re = -2.5 + (row + 0.5) / 540.0
    im = -2.0 + (col + 0.5) / 600.0
    return row, col, re, im


def infinity_map_mandelbrot_to_loc(re, im):
    """Inverse of infinity_map_loc_to_mandelbrot: C-pixel -> loc
    (clamped to the 2160 x 2400 cell grid)."""
    row = int((float(re) + 2.5) * 540.0)
    col = int((float(im) + 2.0) * 600.0)
    row = max(0, min(INFINITY_MAP_ROWS - 1, row))
    col = max(0, min(INFINITY_MAP_COLS - 1, col))
    return row * INFINITY_MAP_COLS + col


def infinity_map_warp(xx, xz, radius=1.0):
    """AS square->circle PI stretch (warp): X = 2*xx/59-1, Z = 2*xz/59-1
    in [-1,1]^2; rho = max(|X|,|Z|); g = atan2(Z,X) in [-pi,pi];
    P = rho*R*(cos g, sin g), |P| <= R. EDGE rho=1 -> |P| = R: the square
    rim stretches onto the FULL circumference; each edge -> arc pi*R/2;
    rim arc L = R*g. Returns (Px, Py, rho, g)."""
    X = 2.0 * float(xx) / 59.0 - 1.0
    Z = 2.0 * float(xz) / 59.0 - 1.0
    rho = max(abs(X), abs(Z))
    g = math.atan2(Z, X)
    return (float(radius) * rho * math.cos(g),
            float(radius) * rho * math.sin(g), rho, g)


def infinity_map_cube_warp(xx, xy, xz, radius=1.0):
    """AS 3-D warp (cube shell -> sphere): normed cube pt
    p = (X,Y,Z) = (2*xx/59-1, 2*xy/59-1, 2*xz/59-1);
    P = R * max(|X|,|Y|,|Z|) * p/|p|  (radial rescale; cube shell
    rho=1 lands exactly on |P|=R). Returns (Px, Py, Pz, rho)."""
    X = 2.0 * float(xx) / 59.0 - 1.0
    Y = 2.0 * float(xy) / 59.0 - 1.0
    Z = 2.0 * float(xz) / 59.0 - 1.0
    rho = max(abs(X), abs(Y), abs(Z))
    n = math.sqrt(X * X + Y * Y + Z * Z)
    if n < 1e-30:
        return (0.0, 0.0, 0.0, rho)
    scale = float(radius) * rho / n
    return (X * scale, Y * scale, Z * scale, rho)


def infinity_map_frac(loc):
    """AS: frac = loc/5,184,000 (grid); the ever-changing fractional
    address -- loc 1 -> ..00000019.."""
    return (int(loc) % INFINITY_MAP) / float(INFINITY_MAP)


def infinity_map_hud(loc):
    """AS HUD string, e.g. '3897660/5184000 (270.0 deg,2,41,0)'."""
    cyc, xz, xx, xy = infinity_map_loc_decode(loc)
    return (f"{int(loc) % INFINITY_MAP}/{INFINITY_MAP} "
            f"({cyc * 15.0:.1f}\u00b0,{xz},{xx},{xy})")


def as_cell_str(loc):
    """Compact AS cell tuple for list/grid labels: '270 deg,2,41,0'."""
    cyc, xz, xx, xy = infinity_map_loc_decode(loc)
    return f"{cyc * 15.0:.0f}\u00b0,{xz},{xx},{xy}"


def infinity_map_signed_address(deg_in, s_z, s_x, s_y, radius=1.0):
    """AS full pipeline for the sheet's signed-input form
    (e.g. 276 deg, -28z, 11x, -30y): deg -> cyc = floor(deg/15) mod 24;
    signed -> unsigned u = (s+30) mod 60; then loc, t, pos, C-pixel,
    frac, HUD. Returns a dict with every AS field."""
    cyc = infinity_map_deg_to_cycle(deg_in)
    xz = infinity_map_signed_wrap(s_z)
    xx = infinity_map_signed_wrap(s_x)
    xy = infinity_map_signed_wrap(s_y)
    loc = infinity_map_loc(cyc, xz, xx, xy)
    px, py, pz = infinity_map_cell_pos(cyc, xz, xx, xy, radius)
    row, col, re, im = infinity_map_loc_to_mandelbrot(loc)
    return {
        'cyc': cyc, 'deg': infinity_map_cycle_deg(cyc), 'deg_in': deg_in,
        'deg_residual': float(deg_in) - cyc * 15.0,
        'xz': xz, 'xx': xx, 'xy': xy, 'loc': loc,
        'time': infinity_map_time_str(loc),
        'r_frac': infinity_map_radial_frac(xx, xy),
        'phi': math.pi * xz / 59.0, 'theta': math.radians(cyc * 15.0),
        'pos': (px, py, pz),
        'mandelbrot': (row, col, re, im),
        'frac': infinity_map_frac(loc),
        'hud': infinity_map_hud(loc),
    }


def world_pos_to_as_loc(px, py, pz):
    """Canonical AS address for a world-space point: the inverse of
    infinity_map_cell_pos at R = cloud_radius*expansion_scale.
    theta = atan2(y,x) -> deg mod 360 -> cyc = floor(deg/15);
    phi = atan2(hypot(x,y), z) -> xz = round(phi*59/pi);
    |p|/R -> radial s = clamp(r/R, .05, .9997)*3600 -> xx = s//60, xy = s%60."""
    _d = math.sqrt(px * px + py * py + pz * pz)
    _R = max(1e-9, cloud_radius * expansion_scale)
    _theta = math.degrees(math.atan2(py, px)) % 360.0
    _cyc = int(math.floor(_theta / 15.0)) % INFINITY_MAP_CYCLES
    _phi = math.atan2(math.sqrt(px * px + py * py), pz)
    _xz = max(0, min(59, int(round(_phi * 59.0 / math.pi))))
    _rf = max(0.05, min(0.9997, _d / _R))
    _s = int(_rf * 3600.0)
    _xx = max(0, min(59, _s // 60))
    _xy = max(0, min(59, _s % 60))
    return infinity_map_loc(_cyc, _xz, _xx, _xy)


# --- AS.png decimal precision: fractional (sub-cell) addresses ----------------
# The integer map has 5,184,000 cells. As the simulated space grows
# (expansion_scale / cloud_radius / |V_total|) each cell covers more physical
# distance, so integer locs lose positional accuracy. The _f variants keep
# the SAME bijection but carry decimal places through every coordinate, and
# as_loc_decimals() picks how many decimals the current space size requires
# (bigger space -> more decimals, capped by float64 resolution on a 7-digit
# loc). Integer entry points above are unchanged — _f functions are additive.

def as_loc_decimals(per_cell_scale=None):
    """Decimal places the AS address needs at the current space size.

    per_cell_scale = physical units covered by one map cell. Defaults to the
    live sphere radius R = cloud_radius*expansion_scale (position-derived
    locs); pass abs(V_total)/INFINITY_MAP for V_total-derived locs. Rule of
    thumb: ~3 decimals beyond the cell scale's order of magnitude, clamped
    to [3, 9] — float64 keeps ~9 reliable decimals on a 7-digit loc, so 9 is
    the hard ceiling regardless of how large the space gets."""
    try:
        if per_cell_scale is None:
            per_cell_scale = max(1e-9, cloud_radius * expansion_scale)
        s = abs(float(per_cell_scale))
        if not math.isfinite(s) or s <= 0.0:
            return 4
        return max(3, min(9, int(math.floor(math.log10(s))) + 3))
    except Exception:
        return 4


def infinity_map_loc_f(cyc, xz, xx, xy):
    """Float AS address: loc_f = cyc*216000 + xz*3600 + xx*60 + xy with
    fractional coordinates allowed (cyc stays a whole fin index 0..23;
    xz,xx,xy may carry decimals). Returns a float loc in [0, 5,184,000)."""
    return ((float(cyc) % INFINITY_MAP_CYCLES) * 216000.0
            + (float(xz) % INFINITY_MAP_GRID) * 3600.0
            + (float(xx) % INFINITY_MAP_GRID) * 60.0
            + (float(xy) % INFINITY_MAP_GRID))


def infinity_map_loc_decode_f(loc_f):
    """Decode a (possibly fractional) AS loc into fractional coordinates.

    Returns (cyc, xz_f, xx_f, xy_f): cyc is the integer fin 0..23; xz_f, xx_f
    are fractional coords in [0,60) carrying integer+sub-cell parts; xy_f is
    the fractional frame coordinate in [0,60). floor() of each gives the
    integer cell, matching infinity_map_loc_decode(int(loc_f))."""
    loc_f = float(loc_f) % float(INFINITY_MAP)
    cyc = int(loc_f // INFINITY_MAP_CELLS_PER_CYCLE)
    rem = loc_f - cyc * INFINITY_MAP_CELLS_PER_CYCLE          # [0, 216000)
    xz_f = rem / 3600.0                                      # [0, 60)
    rem2 = rem - int(xz_f) * 3600.0                          # [0, 3600)
    xx_f = rem2 / 60.0                                       # [0, 60)
    xy_f = rem2 - int(xx_f) * 60.0                           # [0, 60)
    return cyc, xz_f, xx_f, xy_f


def infinity_map_time_str_f(loc_f, nd=None):
    """AS time string with decimal places: 'HH:MM:SS.ff.frac'.

    Same bijection as infinity_map_time_str but the ff field (the xy frame
    coordinate, 1 frame = 1/60 s) carries nd decimals — e.g. loc_f giving
    xy_f = 1.3700 renders '18:44:59.01.3700' = frame 1.3700. nd defaults to
    as_loc_decimals(); nd<=0 falls back to the canonical 2-digit frame."""
    if nd is None:
        nd = as_loc_decimals()
    try:
        nd = int(nd)
    except Exception:
        nd = 4
    cyc, xz_f, xx_f, xy_f = infinity_map_loc_decode_f(loc_f)
    HH = int(cyc) % 24
    MM = int(xz_f) % 60
    SS = int(xx_f) % 60
    FF = xy_f % 60.0
    if nd <= 0:
        return f"{HH:02d}:{MM:02d}:{SS:02d}.{int(FF):02d}"
    return f"{HH:02d}:{MM:02d}:{SS:02d}.{FF:0{3 + nd}.{nd}f}"


def infinity_map_frac_f(loc_f):
    """Float variant of infinity_map_frac: loc_f/5,184,000 in [0,1)."""
    return (float(loc_f) % float(INFINITY_MAP)) / float(INFINITY_MAP)


def infinity_map_hud_f(loc_f, nd=None):
    """AS HUD string with decimals, e.g.
    '3897660.3700/5184000 (270.0°,2.6834,41.0062,0.3700)'."""
    if nd is None:
        nd = as_loc_decimals()
    try:
        nd = int(nd)
    except Exception:
        nd = 4
    cyc, xz_f, xx_f, xy_f = infinity_map_loc_decode_f(loc_f)
    return (f"{float(loc_f) % INFINITY_MAP:.{nd}f}/{INFINITY_MAP} "
            f"({cyc * 15.0:.1f}\u00b0,{xz_f:.{nd}f},{xx_f:.{nd}f},{xy_f:.{nd}f})")


def as_cell_str_f(loc_f, nd=None):
    """Compact AS cell tuple with decimals: '270.0°,2.6834,41.0062,0.3700'."""
    if nd is None:
        nd = as_loc_decimals()
    try:
        nd = int(nd)
    except Exception:
        nd = 4
    cyc, xz_f, xx_f, xy_f = infinity_map_loc_decode_f(loc_f)
    return f"{cyc * 15.0:.1f}\u00b0,{xz_f:.{nd}f},{xx_f:.{nd}f},{xy_f:.{nd}f}"


def infinity_map_loc_to_mandelbrot_f(loc_f):
    """Float Mandelbrot cell bijection: fractional row/col plus the
    continuous C-pixel (re, im). Self-consistent inverse of
    infinity_map_mandelbrot_to_loc_f (round-trips to float precision)."""
    loc_f = float(loc_f) % float(INFINITY_MAP)
    row_f = loc_f / INFINITY_MAP_COLS
    col_f = loc_f % INFINITY_MAP_COLS
    re = -2.5 + row_f / 540.0
    im = -2.0 + col_f / 600.0
    return row_f, col_f, re, im


def infinity_map_mandelbrot_to_loc_f(re, im):
    """Inverse of infinity_map_loc_to_mandelbrot_f: continuous C-pixel ->
    float loc in [0, 5,184,000) (clamped to the cell grid)."""
    row_f = (float(re) + 2.5) * 540.0
    col_f = (float(im) + 2.0) * 600.0
    loc_f = row_f * INFINITY_MAP_COLS + col_f
    return max(0.0, min(float(INFINITY_MAP) - 1e-9, loc_f))


def vtotal_to_sphere_coords_f(v_total_val):
    """Float variant of vtotal_to_sphere_coords: keeps the sub-cell decimals
    of |V_total| mod INFINITY_MAP instead of truncating to an integer cell.
    Returns (degree, xz_f, xx_f, xy_f, cycle, time_str_f, loc_f) — same
    tuple shape as the integer version; degree/cycle stay fin-quantized,
    coords and loc carry decimals, time_str_f has nd decimals."""
    _abs_v = abs(v_total_val)
    if math.isnan(_abs_v) or math.isinf(_abs_v):
        _abs_v = 0.0
    loc_f = _abs_v % float(INFINITY_MAP)
    cyc, xz_f, xx_f, xy_f = infinity_map_loc_decode_f(loc_f)
    degree = (int(cyc) / 24.0) * 360.0
    nd = as_loc_decimals(_abs_v / INFINITY_MAP if _abs_v > 0 else None)
    time_str = infinity_map_time_str_f(loc_f, nd)
    return degree, xz_f, xx_f, xy_f, int(cyc), time_str, loc_f


def world_pos_to_as_loc_f(px, py, pz):
    """Float variant of world_pos_to_as_loc: the inverse of
    infinity_map_cell_pos at R = cloud_radius*expansion_scale, keeping
    sub-cell decimals in xz (polar), xx/xy (radial depth) instead of
    rounding to the nearest integer cell. cyc stays the integer fin
    (deg is quantized to 15 deg per the AS spec); all within-fin
    coordinates are continuous. Returns float loc in [0, 5,184,000)."""
    _d = math.sqrt(px * px + py * py + pz * pz)
    _R = max(1e-9, cloud_radius * expansion_scale)
    _theta = math.degrees(math.atan2(py, px)) % 360.0
    _cyc = int(math.floor(_theta / 15.0)) % INFINITY_MAP_CYCLES
    _phi = math.atan2(math.sqrt(px * px + py * py), pz)
    _xz_f = max(0.0, min(59.999999, _phi * 59.0 / math.pi))
    _rf = max(0.05, min(0.9997, _d / _R))
    _s_f = _rf * 3600.0                                # radial index, [0,3600)
    return infinity_map_loc_f(_cyc, _xz_f, _s_f / 60.0, _s_f % 60.0)


def _infinity_map_verify():
    """Recompute the AS sheet's solved + proof examples exactly; the
    sheet is 'accurate & solved', so the arithmetic must close. Checks
    the whole bijection chain: signed input -> cyc/u -> loc -> decode ->
    t -> C-pixel -> pos -> frac, plus the cyc-18 wedge, radial floor,
    full-360 wrap, and Mandelbrot round-trip."""
    try:
        # Example A (solved): input 276 deg, -28z, 11x, -30y -> exact
        a = infinity_map_signed_address(276, -28, 11, -30)
        if not (a['cyc'] == 18 and a['deg'] == 270.0
                and (a['xz'], a['xx'], a['xy']) == (2, 41, 0)
                and a['loc'] == 3897660 and a['time'] == '18:02:41.00'):
            return False
        _ar, _ac, _are, _aim = a['mandelbrot']
        if not ((_ar, _ac) == (1624, 60)
                and abs(_are - 0.5083) < 1e-3 and abs(_aim + 1.8992) < 1e-3):
            return False
        _ax, _ay, _az = a['pos']
        if not (abs(_ax) < 1e-9 and abs(_ay + 0.0727) < 1e-3
                and abs(_az - 0.6795) < 1e-3):
            return False
        if not abs(a['frac'] - 0.7518634) < 1e-6:
            return False
        # Example B (proof): t 18:44:59.01 -> (cyc 18, xz 44, xx 59, xy 1)
        loc_b = infinity_map_time_to_loc(18, 44, 59, 1)
        if not (loc_b == 4049941
                and infinity_map_loc_decode(loc_b) == (18, 44, 59, 1)
                and infinity_map_time_str(loc_b) == '18:44:59.01'):
            return False
        _br, _bc, _bre, _bim = infinity_map_loc_to_mandelbrot(loc_b)
        if not ((_br, _bc) == (1687, 1141)
                and abs(_bre - 0.6250) < 1e-3 and abs(_bim + 0.0975) < 1e-3):
            return False
        _bx, _by, _bz = infinity_map_cell_pos(18, 44, 59, 1)
        if not (abs(_bx) < 1e-9 and abs(_by + 0.7047) < 1e-3
                and abs(_bz + 0.6862) < 1e-3):
            return False
        if not abs(infinity_map_frac(loc_b) - 0.7812386) < 1e-6:
            return False
        # Cyc-18 wedge: deg inputs 270.0..284.99 -> floor(deg/15) = 18;
        # loc range 3,888,000..4,103,999; the whole "18" hour.
        if not (infinity_map_deg_to_cycle(270.0) == 18
                and infinity_map_deg_to_cycle(284.99) == 18
                and infinity_map_deg_to_cycle(285.0) == 19
                and infinity_map_loc(18, 0, 0, 0) == 3888000
                and infinity_map_loc(18, 59, 59, 59) == 4103999):
            return False
        # Full-360 closure: last cell +1 wraps to loc 0 (deg 360 == deg 0).
        if not (infinity_map_loc(23, 59, 59, 59) == INFINITY_MAP - 1
                and (INFINITY_MAP - 1 + 1) % INFINITY_MAP == 0):
            return False
        # Radial floor: (xx+xy/60) <= 3 -> .05R; max cell r = .9997R.
        if not (infinity_map_radial_frac(0, 0) == 0.05
                and abs(infinity_map_radial_frac(59, 59) - 0.99972) < 1e-4):
            return False
        # Mandelbrot round-trip on both worked cells (centres round-trip).
        for _l in (3897660, 4049941):
            _r2, _c2, _re2, _im2 = infinity_map_loc_to_mandelbrot(_l)
            if infinity_map_mandelbrot_to_loc(_re2, _im2) != _l:
                return False
        return True
    except Exception:
        return False


INFINITY_MAP_VERIFIED = _infinity_map_verify()
assert INFINITY_MAP_VERIFIED, "AS.png infinity-map worked examples failed to recompute"
try:
    print("[AS] infinity-map verified: 3897660->18:02:41.00, "
          "4049941->18:44:59.01 (24 fins x 60^3 = 5,184,000)")
except Exception:
    pass


def _get_as_png_image():
    """Decode AS.png (the 'accurate & solved' map-of-infinity sheet) into a
    pyglet image for the F8 mapping display. Primary source: the embedded
    _AS_PNG_B64 blob (zlib+base64, carried in the CS tier when _TORCH is
    active). Fallback: AS.png next to this script / in the project root.
    Cached after first decode; returns None if the sheet is unavailable."""
    global _as_png_img
    if _as_png_img is not None:
        return _as_png_img
    try:
        import base64 as _b64, zlib as _z, io as _bio
        _blob_b64 = globals().get('_AS_PNG_B64', '') or ''
        if _blob_b64:
            _png = _z.decompress(_b64.b64decode(_blob_b64))
            _as_png_img = pyglet.image.load('AS.png', file=_bio.BytesIO(_png))
            return _as_png_img
    except Exception:
        pass
    try:
        import os as _os
        _here = _os.path.dirname(_os.path.abspath(__file__))
        for _cand in (_os.path.join(_here, 'AS.png'),
                      _os.path.join(_os.path.dirname(_here), 'AS.png'),
                      _os.path.join(_os.getcwd(), 'AS.png')):
            if _os.path.exists(_cand):
                _as_png_img = pyglet.image.load(_cand)
                return _as_png_img
    except Exception:
        pass
    return None


_as_png_img = None  # decoded AS.png pyglet image (lazy via _get_as_png_image)


def _sphere_map_layout():
    """Shared geometry for the F8 Sphere Location Map: the live sphere
    occupies a fixed 560 px section on the left; the AS.png reference
    sheet is appended on the right whenever it fits. Returns
    (x, y, w, h, sc_r, sc_cx, sc_cy, as_x, as_y, as_w, as_h)."""
    _sm_w0 = 560
    _sm_h = min(520, HEIGHT - 40)
    _as_img = _get_as_png_image()
    _as_w = 0
    _as_h = 0
    if _as_img is not None:
        _as_h = _sm_h - 110
        _as_w = int(_as_h * (_as_img.width / max(1, _as_img.height)))
        _avail = WIDTH - 40 - _sm_w0 - 30
        if _as_w > _avail:
            _as_w = _avail
            _as_h = int(_as_w * (_as_img.height / max(1, _as_img.width)))
        if _as_w < 120 or _as_h < 160:
            _as_w = _as_h = 0
    _sm_w = _sm_w0 + (30 + _as_w if _as_w else 0)
    _sm_x = WIDTH // 2 - _sm_w // 2
    _sm_y = (HEIGHT - _UI_BAR_H) // 2 - _sm_h // 2
    _sc_r = min(_sm_w0, _sm_h) // 2 - 80
    _sc_cx = _sm_x + _sm_w0 // 2
    _sc_cy = _sm_y + _sm_h // 2 + 10
    _as_x = _sm_x + _sm_w0 + 15
    _as_y = _sm_y + 55
    return (_sm_x, _sm_y, _sm_w, _sm_h, _sc_r, _sc_cx, _sc_cy,
            _as_x, _as_y, _as_w, _as_h)



