# On resize
@window.event
def on_resize(width, height):
    global WIDTH, HEIGHT, _UI_BAR_H, particle_list_x, particle_list_y, particle_list_width, particle_list_height
    global positron_list_x, positron_list_y, positron_list_width, positron_list_height
    global atom_list_x, atom_list_y, atom_list_width, atom_list_height
    global ai_body_list_x, ai_body_list_y, ai_body_list_width, ai_body_list_height
    if width < 10 or height < 10:
        return
    try:
        WIDTH, HEIGHT = width, height
        glViewport(0, 0, width, height)
        # Dynamic bar height: simulate button wrapping to count rows
        _hint_fs = max(6, int(9 * ui_scale))
        _btn_h = _hint_fs + 6
        _btn_gap = 3
        _char_w = max(5, _hint_fs * 0.72)
        _line_px = _hint_fs + 5
        _bx_test = 12
        _btn_rows = 1
        _hk = _hotkey_display
        _hk_items_r = [(None, 'ESC=Menu')]
        for _aid, _dname, _dkey in _HOTKEY_ACTIONS:
            _hk_items_r.append((_aid, f"{_hk(_aid)}={_dname}"))
        _hk_items_r += [(None, 'WASD=Cam'), (None, 'Q/E=Roll'), (None, 'Scroll=Zoom')]
        for _aid, _dtxt in _hk_items_r:
            _btn_w = int(len(_dtxt) * _char_w) + 8
            if _bx_test + _btn_w > WIDTH - 12 and _bx_test > 12:
                _bx_test = 12
                _btn_rows += 1
            _bx_test += _btn_w + _btn_gap
        _buttons_total_h = _btn_rows * (_btn_h + 2)
        _UI_BAR_H = max(96, _buttons_total_h + 50)
        # Top bar â€” positioned at top of screen
        ui_background.x = 0
        ui_background.y = HEIGHT - _UI_BAR_H
        ui_background.width = WIDTH
        ui_background.height = _UI_BAR_H
        popup_bg.x = WIDTH // 2 - WIDTH // 4
        popup_bg.y = HEIGHT // 2 - 50
        popup_bg.width = max(200, WIDTH // 2)
        popup_prompt.x = WIDTH // 2
        popup_prompt.y = HEIGHT // 2 + 10
        popup_input.x = WIDTH // 2
        popup_input.y = HEIGHT // 2 - 20
        # List panels â€” below the top UI bar, with margin
        _list_avail = max(200, HEIGHT - _UI_BAR_H - 30)
        list_panel_h = min(max(200, HEIGHT - 400), _list_avail)
        list_panel_w = max(250, (WIDTH - 60) // 3)
        particle_list_x = 10
        particle_list_y = max(10, HEIGHT - _UI_BAR_H - list_panel_h - 10)
        particle_list_width = list_panel_w
        particle_list_height = list_panel_h
        atom_list_x = particle_list_x + list_panel_w + 10
        atom_list_y = max(10, HEIGHT - _UI_BAR_H - list_panel_h - 10)
        atom_list_width = list_panel_w
        atom_list_height = list_panel_h
        positron_list_x = atom_list_x + list_panel_w + 10
        positron_list_y = max(10, HEIGHT - _UI_BAR_H - list_panel_h - 10)
        positron_list_width = list_panel_w
        positron_list_height = list_panel_h
        ai_body_list_width = min(300, list_panel_w)
        ai_body_list_x = max(10, WIDTH - ai_body_list_width - 10)
        ai_body_list_y = max(10, HEIGHT - _UI_BAR_H - list_panel_h - 10)
        ai_body_list_height = list_panel_h

    except Exception:
        pass

