@window.event
def on_mouse_drag(x, y, dx, dy, buttons, modifiers):
    global dragging, panning, particle_thumb_dragging, cluster_thumb_dragging, atom_thumb_dragging, positron_thumb_dragging, ai_body_thumb_dragging, _shadow_focus_orbit
    # --- Panel dragging ---
    if _panel_dragging is not None:
        _cur = _panel_drag_pos.get(_panel_dragging, (0, 0))
        _panel_drag_pos[_panel_dragging] = (_cur[0] + dx, _cur[1] + dy)
        return
    if particle_thumb_dragging:
        # handle drag
        line_height = int(22 * ui_scale)
        visible_lines = int(particle_list_height / line_height)
        total_items = len(particle_labels)
        max_scroll = max(0, total_items - visible_lines)
        dy_drag = y - particle_drag_start_y
        scale_factor = max_scroll / (particle_list_height - max(20, particle_list_height * visible_lines / total_items))
        particle_list_offset = max(0, min(particle_drag_start_offset - int(dy_drag * scale_factor), max_scroll))
    elif atom_thumb_dragging:
        line_height = int(22 * ui_scale)
        visible_lines = int(atom_list_height / line_height)
        total_items = len(atom_labels)
        max_scroll = max(0, total_items - visible_lines)
        dy_drag = y - atom_drag_start_y
        scale_factor = max_scroll / (atom_list_height - max(20, atom_list_height * visible_lines / total_items))
        atom_list_offset = max(0, min(atom_drag_start_offset - int(dy_drag * scale_factor), max_scroll))
    elif positron_thumb_dragging:
        line_height = int(22 * ui_scale)
        visible_lines = int(positron_list_height / line_height)
        total_items = len(positron_labels)
        max_scroll = max(0, total_items - visible_lines)
        dy_drag = y - positron_drag_start_y
        scale_factor = max_scroll / (positron_list_height - max(20, positron_list_height * visible_lines / total_items))
        positron_list_offset = max(0, min(positron_drag_start_offset - int(dy_drag * scale_factor), max_scroll))
    elif ai_body_thumb_dragging:
        line_height = int(22 * ui_scale)
        visible_lines = int(ai_body_list_height / line_height)
        total_items = len(ai_body_labels)
        max_scroll = max(0, total_items - visible_lines)
        dy_drag = y - ai_body_drag_start_y
        scale_factor = max_scroll / (ai_body_list_height - max(20, ai_body_list_height * visible_lines / total_items))
        ai_body_list_offset = max(0, min(ai_body_drag_start_offset - int(dy_drag * scale_factor), max_scroll))
    elif buttons & pyglet.window.mouse.MIDDLE and _shadow_focus_idx >= 0:
        # Middle-click drag orbits the focused shadow body
        _shadow_focus_orbit += dx * 0.5
    elif panning and buttons & pyglet.window.mouse.RIGHT:
        camera.pan(dx, dy)
        _mark_camera_busy()
    elif dragging and buttons & pyglet.window.mouse.LEFT:
        camera.rotate(dx, dy)
        _mark_camera_busy()

