@window.event
def on_mouse_motion(x, y, dx, dy):
    global _hud_hover_action
    _hud_hover_action = None
    if show_ui and _hud_hotkey_rects:
        for _bx, _by, _bw, _bh, _aid, _dtxt in _hud_hotkey_rects:
            if _bx <= x <= _bx + _bw and _by <= y <= _by + _bh:
                _hud_hover_action = _aid
                break


MAX_PHYSICS_SUBSTEPS = 48  # Cap sub-steps per frame â€” higher for smoother high-speed motion
_gc_frame_counter = 0  # Periodic GC counter for indefinite runtime
def update(dt):
    global total_fps, time_factor, V_total, V_total_percent, V_subfactors, current_fps, simulation_time, frame_count, last_fps_time, selected_particle, physics_accumulator, _gc_frame_counter, selected_cluster, _sphere_snap_counter, expansion_scale, cloud_radius, _sound_update_counter, _render_alpha, _det_playhead, _det_frames, vtotal_manual, _reverse_live_mode, paused, _pause_start_time, _afk_enabled, _afk_auto_unpause, _replay_active, _massive_pos_cache, _massive_mass_cache, _dormant_batch
    # Cap dt to prevent spiral-of-death from OS sleep/lag spikes
    dt = min(dt, 0.25)
    # Life Generator panel: auto-refresh from disk when the Periodic Machine
    # subprocess saves a new organism .json into the library folder.
    _check_lifegen_auto_refresh()
    # === Step-6 render/physics decoupling: frozen-frame cache gate ===
    # When physics is frozen (paused / menu / input popup / sphere-nav replay)
    # particle state cannot change, so the O(N) per-frame caches below would
    # rebuild byte-identical data every frame. Their only consumers run inside
    # the physics substep loop (same condition as the gate at ~L219413) or in
    # display toggles that tolerate a one-frame-stale fallback. Skipping them
    # removes 3-4 full particle-list scans per frozen frame — the single
    # biggest "calculator" cost at million-atom scale while paused.
    _physics_frozen = paused or show_menu or show_input_popup or sphere_nav_frozen
    if not _physics_frozen:
        # Frame-cached charged-particle list (EM-field rendering only — the sole
        # consumer). Skip entirely when the F2 toggle is off: the list was being
        # rebuilt every frame even though nothing ever read it.
        if toggle_em_field:
            try:
                globals()['_charged_particles_cache'] = [
                    p for p in particles
                    if abs(getattr(p, 'charge', 0)) > 0
                    and getattr(p, 'mass', 0) > 0
                    and getattr(p, 'base_type', '') != 'decayed'
                ]
            except Exception:
                globals()['_charged_particles_cache'] = []
        else:
            globals()['_charged_particles_cache'] = []
        # Step-7: the massive-particle caches and the atom-neighbor voxel hash
        # are now built INSIDE the physics branch from the shared per-frame
        # SoA arrays (all_positions/all_masses) — one O(N) attribute fill feeds
        # gravity, massive caches, neighbor hash and dormant batching instead
        # of three separate O(N) Python scans. They are also skipped entirely
        # on replay / lqcd frames where no particle updates run (previously
        # rebuilt there for nothing).
    # Performance governor: record frame time and adapt quality
    _perf.record_frame(dt, len(particles))
    _perf.maybe_adjust()
    # Conservation audit: snapshot KE + momentum once per ~10s and surface drift.
    # Cheap (single numpy reduction) but only triggers every _CONSERVATION_AUDIT_INTERVAL
    # frames; no-op the rest of the time. Skipped entirely while physics is frozen —
    # conserved quantities cannot drift when nothing integrates.
    if not _physics_frozen:
        _perf_tic('audit')
        try:
            _conservation_audit(particles, frame_count)
        except Exception:
            pass
        _perf_toc('audit')
    # === Item-19: Microbiome step + host exchange (once per ~5s) ===
    # Advance any attached host-microbiome ecology forward by 1 sim-minute.
    # Cheap (handful of dict updates per taxon), bounded to ~12 frames/min so
    # render budget is untouched. No-op until a human is spawned.
    if frame_count % 300 == 0:
        try:
            _mb_global = globals().get('_GLOBAL_MICROBIOME')
            if _mb_global is not None and _mb_global.host_organism is not None:
                _mb_global.step(dt_minutes=1.0)
                _mb_global.exchange_with_host(dt_minutes=1.0)
        except Exception:
            pass
    # Sample a global "frame total" tic — the matching toc fires at the end of update().
    _perf_tic('update_total')
    # Default render alpha to 0.0; overwritten by physics substep loop if active
    _render_alpha = 0.0
    # Periodic garbage collection every ~600 frames (~10s at 60fps)
    _gc_frame_counter += 1
    if _gc_frame_counter >= 600:
        _gc_frame_counter = 0
        gc.collect(generation=0)
    # AFK auto-unpause: if paused for longer than _afk_auto_unpause seconds
    if paused and _afk_enabled and _afk_auto_unpause > 0 and _pause_start_time > 0:
        if time.time() - _pause_start_time >= _afk_auto_unpause:
            paused = False
            _pause_start_time = 0.0
            physics_accumulator = 0.0
            _history_log.append((simulation_time, f"[USER] AFK auto-unpause after {_afk_auto_unpause:.0f}s"))
            if len(_history_log) > _history_max:
                _history_log.pop(0)
    if not paused and not show_menu and not show_input_popup and not sphere_nav_frozen:
        # === Deterministic Time Travel: Replay Check ===
        # Reverse time restores from recorded frames (byte-identical determinism).
        # Forward within recorded range replays frames. Forward past = live physics.
        # When reverse replay exhausts all frames, transitions to LIVE REVERSE PHYSICS
        # which computes the simulation backward indefinitely (negative simulation_time).
        _replay_active = False
        # Reset reverse-live mode when user switches to forward time
        if time_factor >= 0:
            _reverse_live_mode = False
        if (time_factor < 0 or _det_playhead >= 0) and _det_frames and not _reverse_live_mode:
            if time_factor < 0:
                # BACKWARD: step through recorded frames (guaranteed identical)
                if _det_playhead < 0:
                    _det_playhead = len(_det_frames) - 1
                _step = max(1, int(abs(time_factor) * dt * 60))
                _new_ph = _det_playhead - _step
                if _new_ph < 0:
                    # Exhausted recorded frames â€” transition to live reverse physics
                    # Restore frame 0 state as starting point for live reverse
                    _fr = _det_frames[0]
                    simulation_time = _fr[0]
                    expansion_scale = _fr[1]
                    cloud_radius = _fr[2]
                    V_total = _fr[3]
                    V_total_percent = _fr[4]
                    _restore_particle_states(particles, _fr[5])
                    _det_playhead = -1
                    vtotal_manual = False
                    _reverse_live_mode = True
                    # _replay_active stays False â€” fall through to live physics
                else:
                    _det_playhead = _new_ph
                    _replay_active = True
            elif _det_playhead >= 0 and _det_playhead < len(_det_frames) - 1:
                # FORWARD REPLAY: step forward through recorded frames
                _step = max(1, int(max(time_factor, 0.5) * dt * 60))
                _det_playhead = min(_det_playhead + _step, len(_det_frames) - 1)
                _replay_active = True
                if _det_playhead >= len(_det_frames) - 1:
                    _det_playhead = -1  # Reached end of recording, go live
                    vtotal_manual = False
                    _replay_active = False
            elif _det_playhead >= 0:
                # Playhead active but at end â€” go live
                _det_playhead = -1
                vtotal_manual = False
            if _replay_active:
                _fr = _det_frames[_det_playhead]
                simulation_time = _fr[0]
                expansion_scale = _fr[1]
                cloud_radius = _fr[2]
                V_total = _fr[3]
                V_total_percent = _fr[4]
                vtotal_manual = True
                _restore_particle_states(particles, _fr[5])
        if not _replay_active:
            # If transitioning from replay to live, truncate future frames
            if _det_playhead >= 0:
                del _det_frames[_det_playhead + 1:]
                _det_playhead = -1
                vtotal_manual = False
            # Advance simulation time by physics time (not wall-clock)
            # Negative time_factor moves time backward (negative simulation_time allowed)
            simulation_time += dt * time_factor
            # Clamp to prevent float precision loss after very long runtime
            if abs(simulation_time) > 3.154e9:  # ~100 years in seconds
                simulation_time = 0.0
        if _replay_active:
            pass  # Physics skipped â€” state restored from deterministic frame buffer
        elif lqcd_mode:
            lqcd.hmc_step()
            observable_label.text = (f"Plaq:{lqcd.plaquette:.4f}  Poly:{abs(lqcd.polyakov):.4f}  "
                                     f"Q:{lqcd.topological_charge:.2f}  ÏƒaÂ²:{lqcd.string_tension_a2:.3f}  "
                                     f"Acc:{lqcd.accept_rate:.0%}")
        else:
            # Physics runs at consistent rate regardless of zoom level
            effective_time_factor = time_factor
            _n_parts = len(particles)
            # === Raw Physics for ALL time factors ===
            # All time factors (forward, reverse, fast, slow) use real physics
            # computation with adaptive substeps. No cached delta replay.
            # Accumulate wall-clock time for sub-stepping
            physics_accumulator += dt
            # Adaptive substep cap: scale with time_factor for smoother high-speed motion
            _gov_max = _perf.max_substeps
            _base_max = min(_gov_max, MAX_PHYSICS_SUBSTEPS) if _n_parts < 200 else (min(_gov_max, 48) if _n_parts < 500 else min(_gov_max, 24))
            # At high time_factor, subdivide into more steps with smaller per-step factor
            _tf_abs = abs(time_factor)
            if _tf_abs > 1.0:
                _tf_substeps = min(int(_tf_abs * 6), 64)
                _adaptive_max = max(_base_max, _tf_substeps)
                # Split time_factor across substeps for smooth interpolation
                effective_time_factor = time_factor / max(1, _adaptive_max // _base_max)
            else:
                # Ensure minimum substep quality even at very low speeds
                _adaptive_max = max(_base_max, 8)
            # Clamp accumulator to prevent too many sub-steps when framerate drops
            physics_accumulator = min(physics_accumulator, PHYSICS_DT * _adaptive_max)
            # Compute gravity + EM forces once per render frame
            # GPU-FIRST: always use GPU when available (no particle count threshold)
            # CPU Barnes-Hut is fallback only when GPU unavailable or fails
            all_particles = list(particles)
            _NP = len(all_particles)
            # === JIT BATCH PATH: compile pairwise forces + Verlet to machine code ===
            # When the fast engine is active, `sync_from_particles` does the
            # single O(N) attribute fill AND binds every non-atom particle's
            # .pos (and covered particles' .vel/.prev_pos/.prev_accel) as SoA
            # row views — gravity then reads the arrays directly with no copy.
            _use_jit = _FAST_PHYSICS_AVAILABLE and _fast_soa is not None and _NP >= 2
            if _use_jit:
                _fast_soa.sync_from_particles(all_particles)
                all_positions = _fast_soa.positions[:_NP]
                all_masses = _fast_soa.masses[:_NP]
            elif _NP > 0:
                # Pre-allocate + direct fill instead of `np.array([p.pos for p in ...])`.
                # The list-comprehension path builds an intermediate Python list of N
                # numpy refs and then numpy must inspect each + copy into the final
                # 2D buffer. At 1M particles the comprehension alone costs ~200ms.
                # Direct fill avoids the temporary list — ~50% faster at scale.
                all_positions = np.empty((_NP, dims), dtype=np.float64)
                all_masses = np.empty(_NP, dtype=np.float64)
                for _i in range(_NP):
                    all_positions[_i] = all_particles[_i].pos
                    all_masses[_i] = all_particles[_i].mass
            else:
                all_positions = np.empty((0, dims))
                all_masses = np.empty(0)
            _bh_theta = 0.5 if _n_parts < 200 else (0.7 if _n_parts < 500 else 1.0)
            _em_on_gpu = False  # Track whether GPU handled EM forces
            if len(all_positions) > 0:
                _used_gpu = False
                # GPU-first: use GPU at nearly all particle counts (>=8)
                # CPU Barnes-Hut only for N<8 where kernel launch overhead dominates
                _use_gpu_this_frame = _perf.use_gpu_gravity and _n_parts >= 8
                if _use_gpu_this_frame:
                    try:
                        _gp, _gm, _on_gpu = _gpu_to_tensors(all_positions, all_masses)
                        if _on_gpu:
                            grav_accels = _gpu_pairwise_gravity(_gp, _gm, G)
                            _used_gpu = True
                            # GPU EM forces: batch Coulomb computation on GPU
                            if _perf.use_gpu_em and _n_parts >= 2:
                                try:
                                    # Step-7: the SoA sync already extracted
                                    # charges this frame — reuse it instead of
                                    # a second O(N) per-particle getattr pass.
                                    if _use_jit:
                                        _charges = _fast_soa.charges[:_NP].astype(np.float32)
                                    else:
                                        _charges = np.empty(_NP, dtype=np.float32)
                                        for _ci in range(_NP):
                                            _charges[_ci] = all_particles[_ci].charge
                                    _has_charges = np.any(np.abs(_charges) > 1e-30)
                                    if _has_charges:
                                        _ch_t = torch.as_tensor(_charges, dtype=torch.float32, device=_PERF_GPU_DEVICE)
                                        # vel arg is unused by the Coulomb kernel —
                                        # pass the resident position tensor rather
                                        # than re-filling an O(N) velocity array.
                                        _em_accels = _gpu_pairwise_em_forces(_gp, _ch_t, _gp, _gm, k_e, mu_0)
                                        grav_accels = grav_accels + _em_accels
                                        _em_on_gpu = True
                                except Exception:
                                    pass  # EM falls back to per-particle CPU loop
                    except Exception:
                        _used_gpu = False
                if not _used_gpu:
                    grav_accels = GravAccel(all_positions, all_masses, thetamax=_bh_theta, G=G)
            else:
                grav_accels = np.empty((0, dims))
            n_grav = len(grav_accels)
            # === Step-7: derive per-frame caches from the shared SoA arrays ===
            # Massive-particle cache (photon gravitational redshift): was two
            # O(N) Python passes at the top of update(); now a single numpy
            # mask over all_masses — identical membership, identical order.
            try:
                _mmask = all_masses > _MASSIVE_MIN_MASS
                if _mmask.any():
                    _massive_pos_cache = all_positions[_mmask]
                    _massive_mass_cache = all_masses[_mmask]
                else:
                    _massive_pos_cache = None
                    _massive_mass_cache = None
            except Exception:
                _massive_pos_cache = None
                _massive_mass_cache = None
            # Atom neighbor spatial-hash cache — built only when scene exceeds
            # the threshold (below that, full-particles iteration is already
            # faster than the hash build itself). Reuses all_positions for its
            # voxel hash (was a second O(N) attribute fill) and passes atom
            # indices so the occupancy-grid fast path needs no id-map.
            _atoms_only = None
            _atom_idx_arr = None
            _atom_cap = 0
            if _NP > _ATOM_NEIGHBOR_THRESHOLD:
                try:
                    _perf_tic('spatial_hash')
                    _atoms_only = []
                    _atom_idx_list = []
                    for _ai in range(_NP):
                        _ap = all_particles[_ai]
                        if getattr(_ap, 'is_atom', False):
                            _atoms_only.append(_ap)
                            _atom_idx_list.append(_ai)
                    _atom_cap = len(_atoms_only)
                    _atom_idx_arr = np.asarray(_atom_idx_list, dtype=np.intp)
                    _build_atom_neighbor_cache(all_particles, _atoms_only,
                                               _pos_arr=all_positions,
                                               _atom_idx=_atom_idx_arr)
                    _perf_toc('spatial_hash')
                except Exception:
                    globals()['_atom_neighbor_cache'] = {}
                    _atoms_only = None
                    _atom_idx_arr = None
                    _atom_cap = 0
            # === Step-7 dormant-atom batching ===
            # Classify dormant atoms ONCE per frame instead of re-checking every
            # particle every substep. Membership inputs (_cached_neighbors,
            # radioactive, excitation_energy, is_atom) can only change via the
            # atom's OWN update, so frame-start dormant atoms stay dormant all
            # frame; active atoms are re-checked before each update exactly
            # like the original per-substep gate and promoted the moment they
            # become eligible — preserving identical integration semantics.
            # `_active_idx_list` holds every index that still needs a Python
            # update; dormant atoms cost zero per-substep loop iterations.
            _dormant_set = None
            _active_idx_list = None
            _dbuf = None
            _zero_accel = np.zeros(dims)
            if _NP > 0:
                if _n_parts > _ATOM_NEIGHBOR_THRESHOLD:
                    _dormant_set = set()
                    _active_idx_list = []
                    for _di, _dp in enumerate(all_particles):
                        if _dp.is_atom:
                            _nb = getattr(_dp, '_cached_neighbors', None)
                            if (_nb is not None and len(_nb) == 0
                                    and not getattr(_dp, 'radioactive', False)
                                    and not getattr(_dp, 'excitation_energy', 0) > 1e-25):
                                _dormant_set.add(_di)
                                continue
                        _active_idx_list.append(_di)
                    if _dormant_set:
                        # Step-7c: PERSISTENT dormant batch. reconcile() diffs
                        # last frame's enrollment against this frame's dormant
                        # set and enrolls/de-enrolls only the DELTA — steady
                        # state costs ~zero Python attr traffic instead of
                        # re-enrolling every dormant atom each frame (O(D)
                        # traffic → O(|ΔD|)). Object-identity swaps at the same
                        # index are detected inside reconcile.
                        if _dormant_batch is None:
                            _dormant_batch = _DormantMotionBatch(max(_atom_cap, _NP, 64))
                        _dormant_batch.reconcile(
                            all_particles,
                            np.fromiter(sorted(_dormant_set), dtype=np.intp,
                                        count=len(_dormant_set)),
                            grav_accels, n_grav)
                        # Periodic alias heal: an external `p.pos = ...` rebind
                        # (drag, teleport, file load) detaches the row view —
                        # re-check every ~1s at 60fps like the other audits.
                        if frame_count % 60 == 0:
                            _dormant_batch.verify_aliases()
                        _dbuf = _dormant_batch
                else:
                    _active_idx_list = list(range(_NP))
            # Run multiple fixed-timestep physics steps to fill in motion smoothly
            steps_done = 0
            _substep_t0 = time.perf_counter()
            _substep_budget = _perf.substep_budget  # Adaptive wall-clock budget from performance governor
            # === JIT BATCH PATH: compile pairwise forces + Verlet to machine code ===
            # (_use_jit was decided above at the SoA fill; the sync already ran —
            # a second sync would only re-do the O(N) attribute pass.)
            if _use_jit:
                _physics_constants = {
                    'k_e': k_e, 'mu_0': mu_0, 'strong_g2': strong_g2,
                    'strong_lambda': strong_lambda, 'nuclear_range': nuclear_range,
                    'alpha_s': alpha_s, 'string_tension': string_tension,
                    'hbar': hbar, 'e0': e0, 'G': G,
                    'c': c, 'EPSILON': EPSILON, 'bound': bound,
                }
            while physics_accumulator >= PHYSICS_DT and steps_done < _adaptive_max:
                _fire_hooks('pre_physics_substep', particles, PHYSICS_DT)
                if _use_jit:
                    # -- JIT batch: pairwise forces + Verlet as native machine code --
                    _dt_step = PHYSICS_DT * effective_time_factor
                    _batch_copy_prev_pos(_fast_soa.positions[:_fast_soa.n],
                                         _fast_soa.prev_positions[:_fast_soa.n],
                                         _fast_soa.n, cov=_fast_soa.cov[:_fast_soa.n])
                    # Snapshot prev_pos for atoms (sub-particles handled by Atom.update).
                    # At organism scale we skip the sub-particle and quark prev_pos
                    # snapshots — the LOD path collapses each atom to a single sphere
                    # so the per-electron / per-quark interpolation data is never read.
                    # Saves ~36 array copies per atom per substep at 1M-atom scale.
                    _skip_subatomic_snap = _n_parts > 2000
                    for _ai in _active_idx_list:
                        p = all_particles[_ai]
                        if p.is_atom:
                            p.prev_pos = p.pos.copy()
                            if not _skip_subatomic_snap:
                                for _sp in p.sub_particles:
                                    _sp.prev_pos = _sp.pos.copy()
                                    for _q in _sp.constituent_quarks:
                                        _q.prev_pos = _q.pos.copy()
                        elif not getattr(p, '_bjit', False):
                            # Non-atom, not batch-covered (photon/gluon, in_atom,
                            # decayed): prev_pos snapshot for render interp —
                            # covered particles get theirs from _batch_copy_prev_pos
                            # via the SoA prev_positions view.
                            p.prev_pos = p.pos.copy()
                    _perf_tic('physics_substep')
                    _batch_physics_substep(
                        _fast_soa, grav_accels, _dt_step, _physics_constants,
                        em_on_gpu=_em_on_gpu)
                    _perf_toc('physics_substep')
                    # Atoms: use Python update for complex internal dynamics.
                    # === DORMANT-ATOM SKIP ===
                    # At organism scale most atoms are "interior" — no nearby
                    # particles AND not radioactive. Their Atom.update() body
                    # does nothing meaningful (all chemistry scans short-circuit
                    # immediately) but the Python function dispatch alone costs
                    # ~50ns × 1M = 50ms per substep. We skip those atoms here
                    # and apply motion in a single batched pass at the end of
                    # the substep so they still drift correctly with gravity.
                    # Step-7: same _active_idx_list/_dormant_set/_dbuf machinery
                    # as the fallback branch — dormant atoms cost zero Python.
                    _promoted = None
                    if _dormant_set is not None:
                        for idx, p in ((i, all_particles[i]) for i in _active_idx_list):
                            if p.is_atom:
                                _nb = getattr(p, '_cached_neighbors', None)
                                if (_nb is not None and len(_nb) == 0
                                        and not getattr(p, 'radioactive', False)
                                        and not getattr(p, 'excitation_energy', 0) > 1e-25):
                                    if _promoted is None:
                                        _promoted = [(idx, p)]
                                    else:
                                        _promoted.append((idx, p))
                                    continue
                            ga = grav_accels[idx] if idx < n_grav else _zero_accel
                            p.update(all_particles, effective_time_factor, ga, em_on_gpu=_em_on_gpu)
                    else:
                        for idx in _active_idx_list:
                            p = all_particles[idx]
                            ga = grav_accels[idx] if idx < n_grav else _zero_accel
                            p.update(all_particles, effective_time_factor, ga, em_on_gpu=_em_on_gpu)
                    if _promoted:
                        if _dbuf is None:
                            # Reuse the persistent batch — a fresh object here
                            # would orphan _dormant_batch's enrollment (atoms
                            # bound to two batches → stale row writes).
                            if _dormant_batch is None:
                                _dormant_batch = _DormantMotionBatch(
                                    max(_atom_cap or 0, _NP, 64))
                            _dbuf = _dormant_batch
                        _pset = set()
                        for _pi, _pp in _promoted:
                            _pset.add(_pi)
                            _dormant_set.add(_pi)
                            _dbuf.add(_pi, _pp, grav_accels, n_grav)
                        _active_idx_list = [i for i in _active_idx_list if i not in _pset]
                    if _dbuf is not None:
                        _dbuf.step(grav_accels, n_grav, PHYSICS_DT * effective_time_factor)
                else:
                    # -- Fallback: pure Python per-particle update --
                    # Step-7: iterate only `_active_idx_list` — indices of
                    # particles that still need a Python update. Dormant atoms
                    # are integrated by `_DormantMotionBatch` (persistent SoA
                    # buffers + row views) with zero per-substep Python cost,
                    # and their prev_pos snapshots are owned by the batch's
                    # prev buffer. Atoms that become dormant-eligible are
                    # promoted before each update exactly like the original
                    # per-substep gate, then enrolled prior to `_dbuf.step`
                    # so they receive this substep's Verlet — identical
                    # integration semantics, ~D×substeps less Python work.
                    _skip_subatomic_snap = _n_parts > 2000
                    for _ai in _active_idx_list:
                        _p = all_particles[_ai]
                        _p.prev_pos = _p.pos.copy()
                        if _p.is_atom and not _skip_subatomic_snap:
                            for _sp in _p.sub_particles:
                                _sp.prev_pos = _sp.pos.copy()
                                for _q in _sp.constituent_quarks:
                                    _q.prev_pos = _q.pos.copy()
                    _promoted = None
                    if _dormant_set is not None:
                        for _ai in _active_idx_list:
                            _p = all_particles[_ai]
                            if _p.is_atom:
                                _nb = getattr(_p, '_cached_neighbors', None)
                                if (_nb is not None and len(_nb) == 0
                                        and not getattr(_p, 'radioactive', False)
                                        and not getattr(_p, 'excitation_energy', 0) > 1e-25):
                                    if _promoted is None:
                                        _promoted = [(_ai, _p)]
                                    else:
                                        _promoted.append((_ai, _p))
                                    continue
                            _ga = grav_accels[_ai] if _ai < n_grav else _zero_accel
                            _p.update(all_particles, effective_time_factor, _ga, em_on_gpu=_em_on_gpu)
                    else:
                        for _ai in _active_idx_list:
                            _p = all_particles[_ai]
                            _ga = grav_accels[_ai] if _ai < n_grav else _zero_accel
                            _p.update(all_particles, effective_time_factor, _ga, em_on_gpu=_em_on_gpu)
                    # Enroll freshly-dormant atoms BEFORE the batch step so
                    # they get this substep's Verlet (original behavior: they
                    # were in _dormant_idx for this same substep's batch call).
                    if _promoted:
                        if _dbuf is None:
                            # Reuse the persistent batch — a fresh object here
                            # would orphan _dormant_batch's enrollment (atoms
                            # bound to two batches → stale row writes).
                            if _dormant_batch is None:
                                _dormant_batch = _DormantMotionBatch(
                                    max(_atom_cap or 0, _NP, 64))
                            _dbuf = _dormant_batch
                        _pset = set()
                        for _pi, _pp in _promoted:
                            _pset.add(_pi)
                            _dormant_set.add(_pi)
                            _dbuf.add(_pi, _pp, grav_accels, n_grav)
                        _active_idx_list = [i for i in _active_idx_list if i not in _pset]
                    if _dbuf is not None:
                        _dbuf.step(grav_accels, n_grav, PHYSICS_DT * effective_time_factor)
                physics_accumulator -= PHYSICS_DT
                steps_done += 1
                # Break early if wall-clock budget exceeded (prioritize frame rate)
                if steps_done >= 4 and (time.perf_counter() - _substep_t0) > _substep_budget:
                    break
                # Recompute gravity midway through large substep counts for better accuracy
                # GPU-FIRST: use GPU for midway recompute too.
                # Optimization: when JIT is active, read positions directly from the SoA
                # buffer (already up-to-date from _batch_physics_substep) instead of
                # rebuilding the array via Python list comprehension — saves an O(N)
                # per-particle attribute lookup at the midway point.
                if steps_done == _adaptive_max // 2 and _adaptive_max >= 16:
                    if _use_jit and _fast_soa is not None:
                        _mid_pos = _fast_soa.positions[:_fast_soa.n].copy()
                        # Atom rows are frame-start copies (atoms are never
                        # SoA-bound) — refresh them from the live objects so
                        # midway gravity sees current positions, matching the
                        # original all-particles gather.
                        _am = np.nonzero(_fast_soa._was_atom[:_fast_soa.n])[0]
                        for _mi in _am:
                            _mid_pos[int(_mi)] = all_particles[int(_mi)].pos
                    else:
                        _mid_pos = np.array([p.pos for p in all_particles]) if all_particles else np.empty((0, dims))
                    if len(_mid_pos) > 0:
                        _mid_gpu_ok = False
                        if _perf.use_gpu_gravity:
                            try:
                                _mp, _mm, _mon = _gpu_to_tensors(_mid_pos, all_masses)
                                if _mon:
                                    grav_accels = _gpu_pairwise_gravity(_mp, _mm, G)
                                    _mid_gpu_ok = True
                            except Exception:
                                pass
                        if not _mid_gpu_ok:
                            grav_accels = GravAccel(_mid_pos, all_masses, thetamax=_bh_theta, G=G)
                        n_grav = len(grav_accels)
                _fire_hooks('post_physics_substep', particles, PHYSICS_DT)
            # Sync JIT results back to particle objects after all substeps
            if _use_jit and steps_done > 0:
                _fast_soa.sync_to_particles(all_particles)
            # Interpolation alpha: fraction of next physics step elapsed [0,1)
            # 0 = render at prev_pos (last completed step), approaching 1 = render at pos
            _render_alpha = physics_accumulator / PHYSICS_DT if PHYSICS_DT > 0 else 0.0
            # ══════════════════════════════════════════════════════════════
            # CONSERVATION LAW MONITOR — Noether's theorem enforcement
            # Tracks: total energy, momentum, charge, baryon #, lepton #
            # Ref: Noether (1918); Peskin & Schroeder Ch.2
            # ══════════════════════════════════════════════════════════════
            if steps_done > 0 and _n_parts > 0 and frame_count % 30 == 0:
                _total_E = 0.0
                _total_p = np.zeros(3)
                _total_Q = 0.0
                _total_B = 0.0
                _total_L = 0.0
                # Step-7: fused conservation + NaN-firewall pass — previously two
                # separate O(N) Python loops over all_particles every 30 frames.
                # Conservation reads happen BEFORE each particle's sanitize so
                # the accumulated totals see identical (pre-scrub) values.
                for _cp in all_particles:
                    if getattr(_cp, 'base_type', '') == 'decayed':
                        continue
                    _cp_m = getattr(_cp, 'mass', 0.0)
                    if _cp_m > 0:
                        _cp_v2 = np.dot(_cp.vel, _cp.vel)
                        _cp_beta2 = min(_cp_v2 / (c * c), 0.999999)
                        _cp_gamma = 1.0 / math.sqrt(1.0 - _cp_beta2)
                        _total_E += (_cp_gamma - 1.0) * _cp_m * c * c + _cp_m * c * c
                        _total_p += _cp_gamma * _cp_m * _cp.vel
                    _total_Q += getattr(_cp, 'charge', 0.0)
                    _total_B += getattr(_cp, 'baryon_number', 0.0)
                    _total_L += getattr(_cp, 'lepton_number', 0.0)
                    # == GLOBAL NaN FIREWALL (same iteration) ==
                    # Catches corruption from any source (GPU, pairwise, integrator)
                    # Step-7: in-place zero keeps SoA row views attached.
                    _bad = False
                    if not np.all(np.isfinite(_cp.pos)):
                        _cp.pos[:] = 0.0
                        _bad = True
                    if not np.all(np.isfinite(_cp.vel)):
                        _cp.vel[:] = 0.0
                        _bad = True
                    if hasattr(_cp, 'prev_accel') and not np.all(np.isfinite(_cp.prev_accel)):
                        _cp.prev_accel[:] = 0.0
                        _bad = True
                    if not math.isfinite(getattr(_cp, 'energy_kin', 0.0)):
                        _cp.energy_kin = 0.0
                        _bad = True
                    if _bad:
                        if not hasattr(update, '_nan_purge_count'):
                            update._nan_purge_count = 0
                        update._nan_purge_count += 1
                        if update._nan_purge_count <= 20:
                            print(f"[NaN FIREWALL] Sanitized {_cp.base_type} (frame {frame_count})")
                # Store for HUD display and violation detection
                if not hasattr(update, '_prev_Q'):
                    update._prev_Q = _total_Q
                    update._prev_B = _total_B
                    update._prev_L = _total_L
                    update._conservation_warn_count = 0
                # Check discrete conservation laws (charge, baryon, lepton must be exact)
                _dQ = abs(_total_Q - update._prev_Q)
                _dB = abs(_total_B - update._prev_B)
                _dL = abs(_total_L - update._prev_L)
                if _dQ > 0.01 or _dB > 0.01 or _dL > 0.01:
                    update._conservation_warn_count += 1
                    if update._conservation_warn_count <= 10:
                        print(f"[CONSERVATION] ΔQ={_dQ:.3f} ΔB={_dB:.3f} ΔL={_dL:.3f} (frame {frame_count})")
                update._prev_Q = _total_Q
                update._prev_B = _total_B
                update._prev_L = _total_L
                update._last_total_E = _total_E
                update._last_total_p = _total_p

                # == CONSERVATION VIOLATION ALERT + EMERGENCY STATE SAVE ==
                # If discrete conservation laws are violated repeatedly,
                # dump simulation state to disk for post-mortem analysis.
                # Also tracks energy drift rate for continuous conservation.
                if not hasattr(update, '_prev_E'):
                    update._prev_E = _total_E
                    update._nan_purge_count = 0
                    update._emergency_saves = 0
                _dE_rel = abs(_total_E - update._prev_E) / (abs(update._prev_E) + EPSILON)
                update._prev_E = _total_E
                # Emergency save if >5 discrete violations or >50% energy drift
                _needs_emergency = (update._conservation_warn_count > 5 and
                                    update._emergency_saves < 3)
                if _dE_rel > 0.5 and update._emergency_saves < 3:
                    _needs_emergency = True
                    print(f"[ENERGY DRIFT] {_dE_rel*100:.1f}% in one frame!")
                if _needs_emergency:
                    update._emergency_saves += 1
                    try:
                        import pickle as _pkl
                        _efile = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                              f'emergency_state_{frame_count}.pkl')
                        _edata = {
                            'frame': frame_count,
                            'sim_time': simulation_time,
                            'particles': [(p.base_type, p.pos.copy(), p.vel.copy(),
                                           p.mass, p.charge) for p in all_particles
                                          if getattr(p, 'base_type', '') != 'decayed'],
                            'total_E': _total_E,
                            'total_p': _total_p.tolist(),
                            'total_Q': _total_Q,
                            'total_B': _total_B,
                            'total_L': _total_L,
                        }
                        with open(_efile, 'wb') as _ef:
                            _pkl.dump(_edata, _ef)
                        print(f"[EMERGENCY] State saved to {_efile}")
                    except Exception as _ee:
                        print(f"[EMERGENCY] Save failed: {_ee}")

            # === Space Expansion (Hubble-like) â€” works in both directions ===
            # Every particle drifts outward: v_expansion = H_sim * distance_from_origin
            # expansion_scale tracks cumulative growth; cloud_radius grows with it
            # When time_factor < 0, expansion reverses (contraction)
            _exp_dt = dt * effective_time_factor
            _exp_factor = H_sim * _exp_dt  # fractional expansion this frame (negative = contraction)
            _is_reverse_live = (effective_time_factor < 0)
            if abs(_exp_factor) > 1e-30:
                _exp_scale = 1.0 + _exp_factor
                expansion_scale *= _exp_scale
                expansion_scale = max(expansion_scale, 1e-10)  # prevent collapse to zero
                cloud_radius *= _exp_scale
                cloud_radius = max(cloud_radius, 1.0)
                # Step-7: SoA-bound rows (every non-atom synced this frame) are
                # scaled + clamped in one numpy pass — the Python loop below then
                # only pays for atoms (sub-particle shift) and unbound stragglers
                # (mid-frame appends like brems/annihilation photons).
                _exp_jit = (_use_jit and _fast_soa is not None
                            and _fast_soa.n == _NP)
                if _exp_jit:
                    _batch_expansion(_fast_soa, _exp_scale, bound)
                for p in particles:
                    # Step-7: _old_p is only needed to shift atom sub-particles —
                    # skip the copy for non-atoms, and clamp IN PLACE so dormant
                    # atoms keep their _DormantMotionBatch buffer views linked
                    # (the old `p.pos = np.clip(...)` rebound a fresh array and
                    # detached the view for the rest of the frame).
                    _is_at = p.is_atom
                    if (_exp_jit and not _is_at
                            and getattr(p, '_soa_bound', False)
                            and getattr(p.pos, 'base', None) is _fast_soa.positions):
                        continue  # already scaled by _batch_expansion via row view
                    if _is_at:
                        _old_p = p.pos.copy()
                    p.pos *= _exp_scale
                    # Clamp after expansion to prevent runaway positions
                    np.clip(p.pos, -bound, bound, out=p.pos)
                    if _is_at:
                        # Shift sub-particles & quarks by atom center delta (not absolute scale)
                        # to prevent internal structure drift from the nucleus
                        _atom_delta = p.pos - _old_p
                        for sp in p.sub_particles:
                            sp.pos += _atom_delta
                            for _q in getattr(sp, 'constituent_quarks', []):
                                _q.pos += _atom_delta
            # Remove decayed particles and cull distant massless/neutrino particles
            # Skip culling during reverse to preserve particle count
            # Merged: count atoms in same pass to avoid redundant iteration
            _pre_atoms = 0
            _atom_list_merged = []  # Merged: collect atom list during cull to skip second pass
            if not _is_reverse_live:
                # No hard particle cap — unlimited atoms and spatial expansion supported
                cull_dist = max(5000.0, 2000.0 * camera.zoom)
                to_remove = []
                for p in particles:
                    bt = getattr(p, 'base_type', '')
                    if bt == 'decayed' and p.mass <= 0:
                        to_remove.append(p)
                    elif bt in ('photon', 'gluon') and np.linalg.norm(p.pos - camera.pos) > cull_dist:
                        to_remove.append(p)
                    elif 'neutrino' in bt and np.linalg.norm(p.pos - camera.pos) > cull_dist * 0.5:
                        to_remove.append(p)
                    elif p.is_atom and bt != 'decayed':
                        _pre_atoms += 1
                        _atom_list_merged.append(p)
                if to_remove:
                    _remove_set = set(to_remove)
                    if selected_particle in _remove_set:
                        selected_particle = None
                    particles[:] = [p for p in particles if p not in _remove_set]
            _pre_n = len(particles)
            if not _is_reverse_live:
                # Double-slit experiment: emit photons and detect interference
                _double_slit_exp.emit_photons(particles)
                _double_slit_exp.step(particles)
            # === Self-Assembly & Information Code Scan ===
            if not _is_reverse_live:
                _sa_pre_asm = _self_assembly.total_assemblies
                _sa_pre_cod = _self_assembly.total_codes
                _self_assembly.scan_for_assembly(particles, simulation_time)
                if _self_assembly.run_odds_active:
                    _ro_result = _self_assembly.run_odds_step(particles, simulation_time)
                    # === Run Odds Time Travel: life form discovered ===
                    if _ro_result == 'found':
                        # Auto-target camera on the found life form
                        _ro_atoms = _self_assembly._ro_found_life_atoms
                        if _ro_atoms:
                            _ro_center = np.mean([a.pos for a in _ro_atoms if hasattr(a, 'pos')], axis=0)
                            camera.pos = _ro_center.copy()
                            # Select the first atom of the life form for tracking
                            selected_particle = _ro_atoms[0]
                            selected_cluster = None
                            focus_label.text = f"LIFE FOUND: {_self_assembly.run_odds_target_name} ({len(_ro_atoms)} atoms) â€” Press 7 to revert"
                        # Log discovery to history
                        _history_log.append((simulation_time, _self_assembly.run_odds_last_event))
                        if len(_history_log) > _history_max:
                            _history_log.pop(0)
                        # Pause simulation at discovery moment so user can inspect
                        paused = True
                # Log self-assembly / Run Odds events to history
                if _self_assembly.total_assemblies > _sa_pre_asm:
                    _history_log.append((simulation_time, f"Self-Assembly: new structure ({_self_assembly.total_assemblies} total)"))
                    if len(_history_log) > _history_max:
                        _history_log.pop(0)
                if _self_assembly.total_codes > _sa_pre_cod:
                    _history_log.append((simulation_time, f"Info Code emerged: {_self_assembly.info_codes[-1] if _self_assembly.info_codes else '?'}"))
                    if len(_history_log) > _history_max:
                        _history_log.pop(0)
            # History event logging (skip atom counting in reverse — never used)
            _post_n = len(particles)
            if not _is_reverse_live:
                # Reuse atom list from merged cull pass — no second iteration needed.
                # Step-7 fix: build the membership set ONCE — it was previously
                # constructed inside BOTH generator expressions, i.e. O(A×N)
                # set-builds per frame (quadratic at million-atom scale).
                _post_set = set(particles)
                _post_atoms = sum(1 for p in _atom_list_merged if p in _post_set)
                _atom_list = [p for p in _atom_list_merged if p in _post_set]
                if _post_atoms > _pre_atoms:
                    _names = [f"{atom_data.get(a.Z, {}).get('symbol', '?')}-{getattr(a, 'A', '?')}" for a in _atom_list[-(_post_atoms - _pre_atoms):]]
                    _history_log.append((simulation_time, f"Atom formed: {', '.join(_names)}"))
                    if len(_history_log) > _history_max:
                        _history_log.pop(0)
                elif _post_atoms < _pre_atoms:
                    _history_log.append((simulation_time, f"Atom lost ({_pre_atoms - _post_atoms} decayed/fissioned)"))
                    if len(_history_log) > _history_max:
                        _history_log.pop(0)
                if abs(_post_n - _pre_n) > 5:
                    _history_log.append((simulation_time, f"Particles: {_pre_n} -> {_post_n} (delta {_post_n - _pre_n:+d})"))
                    if len(_history_log) > _history_max:
                        _history_log.pop(0)
    # === Camera Focus Tracking (always active, even when paused/menu open) ===
    # Runs unconditionally so V/N/X/4/5 focus is never broken by pause or panning.
    # Uses render-interpolated position so camera matches the particle's drawn position.
    # NOTE: _render_alpha is a global; use it directly (dir() inside functions omits globals)
    if selected_particle:
        _sp_prev = getattr(selected_particle, 'prev_pos', selected_particle.pos)
        camera.pos = _sp_prev + (selected_particle.pos - _sp_prev) * _render_alpha
    elif _nanotech_focus_idx >= 0 and _nanotech_focus_idx < len(nanotech_loaded):
        _nt = nanotech_loaded[_nanotech_focus_idx]
        _nt_prev = getattr(_nt, 'prev_pos', _nt.pos)
        camera.pos = _nt_prev + (_nt.pos - _nt_prev) * _render_alpha
    # === Observer Consciousness System: Always Perceive, Free-Roam Always ===
    # The AI bodies are NOT part of the frozen formula: while the simulation is
    # paused the state space holds still (V_total and every sub-component
    # frozen until the next tick), but the observers still perceive at full
    # rate, keep thinking on their own threads, and may teleport/roam/touch/
    # focus at whatever personal time factor they chose. Only actions that
    # would mutate the frozen state space (spawns, builds, world toggles,
    # global time) are held back until the next state space.
    if _observer_mgr and _OBSERVER_AVAILABLE:
        # Throttle observer perception to every 6 frames (~10Hz). AI subconscious
        # threads run at their own cadence (~20Hz) for fine-grained perception, so
        # halving the main-thread perception rate is safe and doubles the budget
        # left for physics/rendering. Was every 3 frames (~20Hz).
        # Throttle observer perception. For the first ~3s and on empty scenes,
        # skip the heavy `_get_sim_state_for_observers()` snapshot — it iterates
        # particles + builds per-shadow-body spatial-awareness maps and is the
        # second-biggest hotspot on cold-boot empty-scene benchmarks.
        _obs_should_run = (frame_count % 6 == 0)
        if _obs_should_run and frame_count < 180 and len(particles) == 0:
            _obs_should_run = False
        # Don't build the snapshot unless the manager will consume it — its
        # internal interval (0.1s × governor) means ~60% of snapshots at 6-
        # frame cadence were discarded unused. Same AI cadence, ~60% less work.
        if _obs_should_run:
            _obs_due = getattr(_observer_mgr, '_last_update', 0.0)
            if (time.time() - _obs_due) < (_observer_mgr._update_interval
                                           * _perf.observer_update_mul):
                _obs_should_run = False
        if _obs_should_run:
            try:
                _obs_state = _get_sim_state_for_observers()
                _obs_state['ai_spawn_allowed'] = _ai_spawn_allowed
                _observer_mgr.update(_obs_state, time.time())
                # Frozen state space = the same gate as sim_state['physics_frozen']
                # (pause, menu, input popup, sphere-nav replay) — not just `paused`.
                # Embodiment-only actions still execute so the AI free-roam while
                # the formula is held still; world-mutating actions (including
                # subconscious-channel ones that bypass decide()'s score
                # suppression) are consumed and discarded until next state space.
                _obs_frozen = bool(paused or show_menu or show_input_popup
                                   or sphere_nav_frozen)
                for _obs_entity, _obs_act, _obs_params in _observer_mgr.get_resolved_actions():
                    if _obs_frozen and _obs_act not in _OBS_FREE_ACTIONS:
                        continue
                    _execute_observer_action(_obs_entity, _obs_act, _obs_params)
            except Exception as _obs_main_err:
                print(f"[Observer] Error: {type(_obs_main_err).__name__}: {_obs_main_err}")
        if frame_count % 60 == 0:
            _write_ob_state(_observer_mgr, len(particles))
        _abs_st = abs(simulation_time)
        _t_sign = "-" if simulation_time < 0 else ""
        hours = int(_abs_st // 3600)
        minutes = int((_abs_st % 3600) // 60)
        seconds = int(_abs_st % 60)
        _replay_tag = f" | REPLAY {_det_playhead}/{len(_det_frames)}" if _replay_active else ""
        _rev_live_tag = " | REVERSE LIVE" if _reverse_live_mode else ""
        _run_odds_tag = f" | RUN ODDS [{_self_assembly.run_odds_iterations:,}]" if _self_assembly.run_odds_active else ""
        _gpu_tag = f" | GPU: {_PERF_GPU_NAME}" if _PERF_GPU_AVAILABLE else " | CPU-only"
        # HUD text writes are gated to ~10Hz: every `.text =` reflows a pyglet
        # TextLayout (reshape glyph quads + rebuild the draw batch). Writing
        # 5+ labels ×120fps cost ~2-3ms/frame of pure layout churn — the
        # displayed values visibly change at 10Hz anyway.
        _hud_tick = (frame_count % 6 == 0)
        if _hud_tick:
            simulation_label.text = f"T: {_t_sign}{hours:02d}h:{minutes:02d}m:{seconds:02d}s | Particles: {len(particles)}{_gpu_tag}{_replay_tag}{_rev_live_tag}{_run_odds_tag}"
        _tf_pct = time_factor * 100.0
        # Ratio display: express time_factor as a fraction (e.g. 1:2 = half speed)
        _tf_abs = abs(time_factor)
        if _tf_abs == 0:
            _ratio_str = "0:1"
        elif _tf_abs >= 1.0:
            _ratio_str = f"{_tf_abs:.1f}:1"
        else:
            _ratio_str = f"1:{1.0/_tf_abs:.1f}"
        _rev_tag = " (REVERSE)" if time_factor < 0 else ""
        _extrap_tag = ""
        if _hud_tick:
            if time_factor == 0:
                time_factor_label.text = "Time Factor: 0% [0:1] (PAUSED)"
            elif abs(_tf_pct) < 0.01:
                time_factor_label.text = f"Time Factor: {_tf_pct:.2e}% [{_ratio_str}]{_rev_tag}{_extrap_tag}"
            elif abs(_tf_pct) < 1.0:
                time_factor_label.text = f"Time Factor: {_tf_pct:.6f}% [{_ratio_str}]{_rev_tag}{_extrap_tag}"
            else:
                time_factor_label.text = f"Time Factor: {_tf_pct:.1f}% [{_ratio_str}]{_rev_tag}{_extrap_tag}"
        # Single-pass stats to avoid multiple list traversals (throttled).
        # While physics is frozen every input to V_total is constant, so the
        # O(N) stats pass drops from every-5-frames to every-30 — the cached
        # tuple keeps labels/formula/sim-state fed with identical values.
        _stats_every = 5 if not _physics_frozen else 30
        if frame_count % _stats_every != 0 and hasattr(update, '_cached_stats'):
            total_mass, total_energy, n_atoms, n_independent, n_sub, n_stable, n_anti, total_charge, rank_score, quantum_bindings, _positions = update._cached_stats
        else:
            total_mass = 0.0
            total_energy = 0.0
            n_atoms = 0
            n_independent = 0
            n_sub = 0
            n_stable = 0
            n_anti = 0
            total_charge = 0.0
            rank_score = 0
            quantum_bindings = 0
            _positions = []
            _max_v2 = 0.0
            for p in particles:
                total_mass += p.mass
                total_energy += p.energy_kin + p.energy_rot
                total_charge += p.charge
                bt = getattr(p, 'base_type', '')
                if bt != 'decayed':
                    n_stable += 1
                    _positions.append(p.pos)
                if 'anti_' in bt:
                    n_anti += 1
                if p.is_atom:
                    n_atoms += 1
                    _nsub = len(p.sub_particles)
                    n_sub += _nsub
                    rank_score += 3 + 2 * _nsub
                    quantum_bindings += _nsub
                else:
                    n_independent += 1
                    rank_score += 1
                # Relativity gauge for the live formula panel: fastest particle
                # this stats pass (v² only — sqrt deferred to display).
                _pv = p.vel
                _v2 = float(_pv[0] * _pv[0] + _pv[1] * _pv[1] + _pv[2] * _pv[2])
                if _v2 > _max_v2:
                    _max_v2 = _v2
            update._cached_stats = (total_mass, total_energy, n_atoms, n_independent, n_sub, n_stable, n_anti, total_charge, rank_score, quantum_bindings, _positions)
            update._rel_stats = (_max_v2, math.sqrt(_max_v2) if _max_v2 > 0 else 0.0)
        # === V_total: Unified Reality-Weight (refined formula) ===
        # Dimensional Sphere: INFINITY_MAP = 5,184,000 = practical infinity
        # Formula: V = [5Â·(innerÂ²) + 1.001Â·VÂ·(VÂ²+V)Â·0.001V] Â· recursive Â· âˆž_norm Â· V
        _rest_E = total_mass * c ** 2
        E_energy = _rest_E + total_energy
        T_minutes = abs(simulation_time) / 60.0
        _tnorm = T_minutes / 1440.0 if T_minutes > 0 else 0.0
        # 11 base subfactors
        sf_Z = math.sqrt(abs(_rest_E) + EPSILON)
        sf_A = float(n_stable)
        if len(_positions) > 1:
            _parr = np.array(_positions)
            _cmean = np.mean(_parr, axis=0)
            _dists = np.linalg.norm(_parr - _cmean, axis=1)
            _spatial_r = float(np.mean(_dists))
            _spatial_std = float(np.std(_parr))
        else:
            _spatial_r = 0.0
            _spatial_std = 0.0
        sf_C = math.sqrt(abs(math.pi * _spatial_r * _spatial_std) + EPSILON)
        sf_E = 5.0 * E_energy
        sf_Q = 13.0 * quantum_bindings / 2.0
        sf_U = math.sqrt(float(len(particles)) + EPSILON)
        sf_D = -float(n_anti)
        sf_T = (7.0 ** 12) * _tnorm
        sf_R = 9.0 * rank_score
        sf_P = 780.0 * (V_total_percent / 100.0)
        sf_B = -abs(total_charge)
        # Base inner sum of 11 subfactors
        _base = sf_Z + sf_A + sf_C + sf_E + sf_Q + sf_U + sf_D + sf_T + sf_R + sf_P + sf_B
        # Normalize V_prev for recursive terms (map to 0..1 via INFINITY_MAP)
        _Vn = min(abs(V_total) / INFINITY_MAP, 1.0) if V_total != 0 else 0.0
        # Exponential term: sum(V^n/n!) = e^V (Taylor series)
        _exp_term = math.exp(min(_Vn * 3.0, 20.0))
        # Quadratic + infinity-scaled: VÂ² + VÂ·(âˆžÂ²/2)
        _quad_term = _Vn ** 2 + _Vn * 0.5
        # Cubic polynomial: (4VÂ² + 0.001V)Â³
        _poly = 4.0 * _Vn ** 2 + 0.001 * _Vn
        _cubic_term = _poly ** 3
        # Duality and light: 2 + Ï€Â·V^1.5Â·0.137
        _dual_term = 2.0 + math.pi * max(_Vn, EPSILON) ** 1.5 * 0.137
        # Inner sum
        _inner = _exp_term + _quad_term + _cubic_term + _dual_term + _base
        # Squared inner: 5Â·(innerÂ²)
        _inner = max(-1e150, min(_inner, 1e150))
        _inner_sq = 5.0 * _inner ** 2
        # Perturbation: 1.001Â·VÂ·(VÂ²+V)Â·0.001V
        _perturb = 1.001 * _Vn * (_Vn ** 2 + _Vn) * 0.001 * _Vn
        # Recursive power terms: V^V + V^(VÂ²) + V^(âˆšV) â€” capped in log space
        _Vn_safe = max(_Vn, EPSILON)
        _log_vv = min(_Vn_safe * math.log(max(_Vn_safe, 1e-10) + 1.0), 20.0)
        _log_vv2 = min(_Vn_safe ** 2 * math.log(max(_Vn_safe, 1e-10) + 1.0), 20.0)
        _log_vsqrt = min(math.sqrt(_Vn_safe) * math.log(max(_Vn_safe, 1e-10) + 1.0), 20.0)
        _rec_vv = math.exp(_log_vv)
        _rec_vv2 = math.exp(_log_vv2)
        _rec_vsqrt = math.exp(_log_vsqrt)
        _recursive = _rec_vv + _rec_vv2 + _rec_vsqrt
        # Infinity normalization: time fraction of 24h cycle
        _inf_norm = max(_tnorm, EPSILON)
        # Final V_total: [5Â·innerÂ² + perturbation] Â· recursive Â· âˆž_norm
        if not _replay_active:
            V_total = (_inner_sq + _perturb) * _recursive * _inf_norm
        # Auto-calculate percentage unless user manually set via slider
        # V% = V_total / INFINITY_MAP * 100 â€” uncapped, reflects actual scale
        # With limited atoms this is a smaller-scale infinity; V% shows true ratio
        if not vtotal_manual:
            V_total_percent = abs(V_total) / INFINITY_MAP * 100.0
        # Store subfactors + every intermediate term for F1 info display and
        # the live Relativity Formula panel (F13 / Click=Formula). Display-only
        # data — the physics values themselves are computed above unchanged.
        V_subfactors = {'Z': sf_Z, 'A': sf_A, 'C': sf_C, 'E': sf_E, 'Q': sf_Q,
                        'U': sf_U, 'D': sf_D, 'T': sf_T, 'R': sf_R, 'P': sf_P, 'B': sf_B,
                        'exp': _exp_term, 'rec': _recursive, 'inf': _inf_norm,
                        # --- full formula tree for the live panel ---
                        'Vn': _Vn, 'rest_E': _rest_E, 'E_tot': E_energy,
                        'tnorm': _tnorm, 'T_min': T_minutes,
                        'quad': _quad_term, 'cubic': _cubic_term, 'dual': _dual_term,
                        'base': _base, 'inner': _inner, 'inner_sq': _inner_sq,
                        'perturb': _perturb,
                        'rec_vv': _rec_vv, 'rec_vv2': _rec_vv2, 'rec_vsqrt': _rec_vsqrt,
                        'mass': total_mass, 'charge': total_charge,
                        'n_stable': float(n_stable), 'n_atoms': float(n_atoms),
                        'n_indep': float(n_independent), 'n_anti': float(n_anti),
                        'rank': float(rank_score), 'qbind': float(quantum_bindings),
                        'spatial_r': _spatial_r, 'spatial_std': _spatial_std,
                        'V_total': V_total, 'V_pct': V_total_percent}
        _formula_history.append((simulation_time, V_total, V_total_percent))
        # === 11-Dimensional String Theory: fractal decomposition of V_total ===
        # infinity/11 â†’ fractal basis per dimension; V_total drives amplitudes & phases
        # "Size of infinity" scales with total complexity (more exists â†’ larger infinity)
        _dim11_infinity_scale = 1.0 + math.log10(max(abs(V_total), 1.0))
        _abs_V = abs(V_total)
        _subfactors_list = [sf_Z, sf_A, sf_C, sf_E, sf_Q, sf_U, sf_D, sf_T, sf_R, sf_P, sf_B]
        for _di in range(STRING_DIMENSIONS):
            # Each dimension gets a fractal slice: V_total mod (fractal_base * (d+1))
            _dim_period = _STRING_FRACTAL_BASE * (_di + 1)
            _dim_frac = (_abs_V % _dim_period) / max(_dim_period, 1e-20)
            # Amplitude: subfactor contribution scaled by fractal fraction
            _sf_val = abs(_subfactors_list[_di]) if _di < len(_subfactors_list) else _abs_V
            _dim11_amplitudes[_di] = min(1.0, _dim_frac * (0.3 + 0.7 * min(_sf_val / max(_abs_V, 1e-20), 1.0)))
            # Phase: golden-ratio-spaced rotation driven by time and V_total
            _dim11_phases[_di] = (simulation_time * (0.1 + 0.05 * _di) + _dim_frac * math.pi * 2.0 * (_di + 1) / STRING_DIMENSIONS) % (2.0 * math.pi)
        # Format V% with appropriate precision based on magnitude
        if V_total_percent < 0.001:
            _vpct_str = f"{V_total_percent:.6e}%"
        elif V_total_percent < 1.0:
            _vpct_str = f"{V_total_percent:.6f}%"
        elif V_total_percent > 1000:
            _vpct_str = f"{V_total_percent:.2e}%"
        else:
            _vpct_str = f"{V_total_percent:.4f}%"
        if _hud_tick:
            v_total_label.text = f"V_total: {V_total:.2e}  ({_vpct_str})  M={total_mass:.2e}  Chg={total_charge:.2e}"
            v_subfactors_label.text = f"E={E_energy:.2e}  R={sf_R:.0f}  Q={sf_Q:.0f}  T={sf_T:.2e}  Z={sf_Z:.1f}  A={sf_A:.0f}  Rec={_recursive:.2f}"
            # Update V_total percentage slider fill (logarithmic scale for wide range)
            if V_total_percent > 0:
                _log_pct = math.log10(V_total_percent + 1) / math.log10(INFINITY_MAP + 1)
                vtotal_slider_fill.width = min(_log_pct, 1.0) * vtotal_slider_width
            else:
                vtotal_slider_fill.width = 0
            _v_abs = abs(V_total)
            _v_loc_f = (_v_abs if math.isfinite(_v_abs) else 0.0) % float(INFINITY_MAP)
            _v_nd = as_loc_decimals(_v_abs / INFINITY_MAP if _v_abs > 0 else None)
            vtotal_pct_label.text = (f"V%: {_vpct_str}  loc={_v_loc_f:,.{_v_nd}f} "
                                     f"t={infinity_map_time_str_f(_v_loc_f, _v_nd)}")
        # Save dimensional sphere snapshot and/or deterministic frame for time travel
        # Share _record_particle_states result if both trigger in the same frame (expensive deep copy)
        _frame_states = None
        _need_sphere = not sphere_nav_frozen and not _replay_active
        _need_det = not _replay_active and not _perf.skip_det_frames and (frame_count % _perf.det_record_interval == 0)
        if _need_sphere:
            _sphere_snap_counter += 1
            if _sphere_snap_counter >= _perf.sphere_snap_interval:
                _sphere_snap_counter = 0
                _frame_states = _record_particle_states(particles)
                _sphere_snapshots.append((simulation_time, V_total, V_total_percent, _frame_states))
                # deque(maxlen=_sphere_snap_max) auto-evicts oldest snapshot — no manual pop needed
        if _need_det:
            if _frame_states is None:
                _frame_states = _record_particle_states(particles)
            _det_frames.append((
                simulation_time, expansion_scale, cloud_radius, V_total, V_total_percent,
                _frame_states
            ))
            if len(_det_frames) > _det_frame_max:
                _det_frames.pop(0)
        # Fill bar: center=0, right=positive, left=negative
        _half_w = slider_width // 2
        _tf_vis = min(abs(time_factor) / max_time_factor, 1.0)  # visual fraction (capped at bar edge)
        if time_factor > 0:
            fill_bar.x = slider_x + _half_w
            fill_bar.width = int(_tf_vis * _half_w)
            fill_bar.color = _TH_BAR_FILL
        elif time_factor < 0:
            _neg_w = int(_tf_vis * _half_w)
            fill_bar.x = slider_x + _half_w - _neg_w
            fill_bar.width = _neg_w
            fill_bar.color = (200, 100, 80, 255)  # Red for reverse
        else:
            fill_bar.x = slider_x + _half_w - 1
            fill_bar.width = 2
            fill_bar.color = (120, 120, 120, 255)  # Gray for paused
        total_particle_label.text = f"Total Particles: {n_independent + n_sub}"
        total_independent_label.text = f"Independent: {n_independent}"
        total_atom_label.text = f"Atoms: {n_atoms}"
        frame_count += 1
        current_time = time.time()
        if current_time - last_fps_time >= 1.0:
            current_fps = frame_count / (current_time - last_fps_time)
            frame_count = 0
            last_fps_time = current_time
        _q_names = ['SURV', 'LOW', 'MED', 'HIGH', 'ULTRA']
        _q_tag = _q_names[min(_perf.quality, 4)]
        _gpu_tag = ' GPU' if _perf.use_gpu_gravity else ''
        fps_label.text = f"FPS: {current_fps:.1f} [{_q_tag}{_gpu_tag}]"
        # Update nanotech entities (alive AND dead â€” dead ones drift and decompose)
        # Respect pause: motor rotation, thrust, ion dynamics all freeze when paused
        if not paused:
            for _nt in nanotech_loaded:
                _nt.update(dt, particles)
        # Matter persists: dead entities remain as inert matter with residual energy/motion
        # They are NEVER removed â€” only their physics state changes (no despawn)
        # Process deferred observer window spawns (avoids pyglet Set iteration crash)
        for _pending_target in _pending_observer_spawns:
            try:
                _obs = ObserverWindow(target_particle=_pending_target)
                _observer_windows.append(_obs)
            except Exception as _owe:
                print(f"Failed to create observer window: {_owe}")
        _pending_observer_spawns.clear()
        # Invalidate observer windows so they redraw each frame
        for _ow in _observer_windows:
            if _ow._alive:
                try:
                    _ow._win.invalid = True
                except Exception:
                    pass
    # Per-frame shadow body animation tick (smooth rendering independent of observer update rate)
    # NOTE: anim_time, talk_timer, breath_phase, aura_pulse_phase, walk_phase, life_aura_phase
    # are already incremented inside ShadowBody.update() â€” only update supplemental fields here
    if _shadow_bodies:
        for _sbf in _shadow_bodies:
            # Smooth pose blending between frames
            if _sbf._blend_t < 1.0:
                _sbf._blend_t = min(1.0, _sbf._blend_t + dt * _sbf._blend_speed)
                _sbf._current_pose = _lerp_pose(_sbf._current_pose, _sbf._target_pose,
                                                  min(1.0, dt * _sbf._blend_speed * 2))
            if _sbf.teleport_alpha < 1.0:
                _sbf.teleport_alpha = min(1.0, _sbf.teleport_alpha + dt * 2.0)

    # === ALWAYS update time display (even when frozen/paused) ===
    # This ensures F7 timeline clicks and key 3 time jumps reflect immediately.
    _t_abs = abs(simulation_time)
    _t_sgn = "-" if simulation_time < 0 else ""
    _t_hrs = int(_t_abs // 3600)
    _t_min = int((_t_abs % 3600) // 60)
    _t_sec = int(_t_abs % 60)
    _t_tags = []
    if _det_playhead >= 0:
        _t_tags.append(f"REPLAY {_det_playhead}/{len(_det_frames)}")
    if _reverse_live_mode:
        _t_tags.append("REVERSE LIVE")
    if sphere_nav_frozen:
        _t_tags.append("FROZEN")
    _t_tag_str = (" | " + " | ".join(_t_tags)) if _t_tags else ""
    simulation_label.text = f"T: {_t_sgn}{_t_hrs:02d}h:{_t_min:02d}m:{_t_sec:02d}s | Particles: {len(particles)}{_t_tag_str}"
    # Close out the update-total timer started near the top of update(). Render
    # cost is timed separately via _perf_tic/_perf_toc('render_total') inside on_draw.
    _perf_toc('update_total')

# On draw
@window.event
def on_draw():
    # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    # on_draw — primary render pipeline (T3.18: section banners for navigation)
    # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    # Render order (top-to-bottom inside this function; search the banner
    # text below to jump to a section):
    #   §A  BUSY-LOD GATE + camera projection setup + lighting
    #   §B  Grid, Mandelbrot wireframe, 11-D string-theory overlay
    #   §C  Shadow body humanoid avatars (OB1-6) + brain neurons
    #   §D  Connectome (brain) for spawned life forms (always-on)
    #   §E  Batched atom GL_POINTS draw + cluster-LOD blobs
    #   §F  Opaque + transparent sphere passes (chemistry + nanotech)
    #   §G  Bonds, photons, fields, EM trails, wave field
    #   §H  Switch to 2D — labels, speech bubbles, photon overlay
    #   §I  F1 help overlay (8-column with auto-generated hotkey reference)
    #   §J  Panels: particles list, atoms list, nanotech, molecules, life-gen,
    #       AI dashboard, sphere nav, mandelbrot map, history, controls
    #   §K  HUD bar bottom strip + FPS/V_total/focus labels
    #   §L  PERF HUD (T2.13, when enabled) + render_total toc
    # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    global current_fps, particle_list_offset, cluster_list_offset, atom_list_offset, positron_list_offset, input_number, _nanotech_focus_scroll, _molecule_focus_scroll, _lifeform_focus_scroll, _f1_scroll_offset, _f1_scroll_max, _mandelbrot_3d_cache, _mandelbrot_3d_cache_key, _mandelbrot_2d_cache, _mandelbrot_2d_cache_key, _mandelbrot_cache, _mandelbrot_cache_key, _f1_page, _pause_start_time, _afk_auto_unpause, _afk_enabled, paused, _ai_dashboard_scroll, _mb_vbo_key, _cs_terminal_rect, _lifegen_terminal_rect, _mandelbrot_img, _mandelbrot_img_key
    _fire_hooks('pre_render_frame', camera)
    if WIDTH < 10 or HEIGHT < 10:
        return
    _perf_tic('render_total')
    # ─── §A  BUSY-LOD + CAMERA + LIGHTING ─────────────────────────────────
    # === BUSY-LOD GATE ===
    # During active camera manipulation (rotate / pan / zoom), every detail
    # branch below checks `_camera_busy` and drops to its fastest path. The
    # 250ms hold means a fluid rotation is rendered at low LOD; the instant
    # the user lets go of the mouse, full detail returns. Single timestamp
    # check, evaluated once per frame.
    _camera_busy = time.time() < _camera_busy_until
    try:
        window.switch_to()  # Restore GL context after observer windows
    except Exception:
        return
    while glGetError() != GL_NO_ERROR:
        pass
    glClearColor(0, 0, 0, 1)
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT)
    _panel_rects.clear()

    glMatrixMode(GL_PROJECTION)
    glLoadIdentity()
    # Clip planes: both scale with zoom so grid/Mandelbrot remain visible at all zoom levels
    near_clip = max(0.001, camera.zoom * 0.1)
    far_clip = max(1e7, camera.zoom * 500)
    gluPerspective(45, WIDTH / max(1, HEIGHT), near_clip, far_clip)
    glMatrixMode(GL_MODELVIEW)
    glLoadIdentity()
    glTranslatef(0, 0, -camera.zoom * 100)
    glRotatef(camera.rot[0] * 180 / math.pi, 1, 0, 0)
    glRotatef(camera.rot[1] * 180 / math.pi, 0, 1, 0)
    glRotatef(camera.rot[2] * 180 / math.pi, 0, 0, 1)

    model = (c_double * 16)()
    proj = (c_double * 16)()
    view = (c_int * 4)()
    glGetDoublev(GL_MODELVIEW_MATRIX, model)
    glGetDoublev(GL_PROJECTION_MATRIX, proj)
    glGetIntegerv(GL_VIEWPORT, view)

    # Setup lighting for 3D effect
    glEnable(GL_LIGHTING)
    glEnable(GL_LIGHT0)
    light_pos = (c_float * 4)(0.0, 0.0, 100.0, 1.0)
    glLightfv(GL_LIGHT0, GL_POSITION, light_pos)
    light_diff = (c_float * 4)(1.0, 1.0, 1.0, 1.0)
    glLightfv(GL_LIGHT0, GL_DIFFUSE, light_diff)
    glEnable(GL_DEPTH_TEST)
    glEnable(GL_NORMALIZE)  # Re-normalize normals after glScalef in display-list sphere/cylinder rendering
    glEnable(GL_COLOR_MATERIAL)
    glColorMaterial(GL_FRONT_AND_BACK, GL_DIFFUSE)
    # Step-6 material upgrade: a subtle specular sheen makes lit spheres read as
    # glossy 3D atoms/molecules instead of flat diffuse blobs. GL_COLOR_MATERIAL
    # only tracks GL_DIFFUSE, so this persists across per-sphere color changes.
    glMaterialfv(GL_FRONT_AND_BACK, GL_SPECULAR, (c_float * 4)(0.18, 0.18, 0.22, 1.0))
    glMateriali(GL_FRONT_AND_BACK, GL_SHININESS, 26)

    # Draw grid (capped to prevent crash at high zoom)
    grid_spacing = GRID_SPACING * (1 + camera.zoom)
    step = max(1, int(grid_spacing))
    effective_grid_size = GRID_SIZE * (1 + camera.zoom)
    if toggle_grid:
        glColor4ub(*GRID_COLOR)
        glDisable(GL_LIGHTING)
        # Cap grid lines to ~200 per axis to avoid GPU overload at macro zoom
        max_grid_lines = 200
        grid_count = int(2 * effective_grid_size / step) if step > 0 else 0
        if grid_count > max_grid_lines:
            step = max(1, int(2 * effective_grid_size / max_grid_lines))
        # GPU-first: use VBO-cached grid (single glDrawArrays on GPU)
        # Falls back to immediate mode only if VBO creation fails
        if not _draw_grid_vbo(effective_grid_size, step):
            glBegin(GL_LINES)
            for i in range(-int(effective_grid_size), int(effective_grid_size) + 1, step):
                glVertex3f(i, -effective_grid_size, 0)
                glVertex3f(i, effective_grid_size, 0)
                glVertex3f(-effective_grid_size, i, 0)
                glVertex3f(effective_grid_size, i, 0)
                glVertex3f(i, 0, -effective_grid_size)
                glVertex3f(i, 0, effective_grid_size)
                glVertex3f(-effective_grid_size, 0, i)
                glVertex3f(effective_grid_size, 0, i)
                glVertex3f(0, i, -effective_grid_size)
                glVertex3f(0, i, effective_grid_size)
                glVertex3f(0, -effective_grid_size, i)
                glVertex3f(0, effective_grid_size, i)
            glEnd()
        glEnable(GL_LIGHTING)

    if lqcd_mode and lqcd:
        # Draw LQCD lattice tiled periodically across ALL visible space
        _L = lqcd.L
        _fixed_t = lqcd.T // 2
        _Nc = lqcd.Nc
        # Precompute rotation matrix once (avoid per-vertex overhead)
        _cp = math.cos(camera.rot[0]); _sp = math.sin(camera.rot[0])
        _cy = math.cos(camera.rot[1]); _sy = math.sin(camera.rot[1])
        _cr = math.cos(camera.rot[2]); _sr = math.sin(camera.rot[2])
        _rot_mat = np.array([[_cr*_cy, _cr*_sy*_sp - _sr*_cp, _cr*_sy*_cp + _sr*_sp],
                             [_sr*_cy, _sr*_sy*_sp + _cr*_cp, _sr*_sy*_cp - _cr*_sp],
                             [-_sy,    _cy*_sp,                _cy*_cp]])
        # Precompute color LUT for all L^3 * 3 links (192 entries for L=4)
        _lqcd_lut = {}
        for _lx in range(_L):
            for _ly in range(_L):
                for _lz in range(_L):
                    for _mu in range(3):
                        _U = lqcd._get_link((_lx, _ly, _lz, _fixed_t), _mu)
                        _tr = np.trace(_U) / _Nc
                        _re_tr = max(-1.0, min(1.0, _tr.real))
                        _rc = int((1 - _re_tr) * 127)
                        _gc = int((1 + _re_tr) * 127)
                        _bc = int(abs(_tr.imag) * 128)
                        _lqcd_lut[(_lx, _ly, _lz, _mu)] = (min(_rc, 255), min(_gc, 255), min(_bc, 255), 140)
        # Determine grid density: ~8 sites per axis for performance
        _target_n = 8
        _lqcd_sp = max(1.0, effective_grid_size * 2.0 / _target_n)
        _n_half = int(effective_grid_size / _lqcd_sp)
        _cam_pos = camera.pos
        glDisable(GL_LIGHTING)
        glBegin(GL_LINES)
        for _ix in range(-_n_half, _n_half + 1):
            for _iy in range(-_n_half, _n_half + 1):
                for _iz in range(-_n_half, _n_half + 1):
                    _pos = np.array([_ix * _lqcd_sp, _iy * _lqcd_sp, _iz * _lqcd_sp])
                    _rel = _rot_mat @ (_pos - _cam_pos)
                    _lx = _ix % _L; _ly = _iy % _L; _lz = _iz % _L
                    for _mu in range(3):
                        _col = _lqcd_lut.get((_lx, _ly, _lz, _mu), (0, 200, 0, 140))
                        _p2 = _pos.copy()
                        _p2[_mu] += _lqcd_sp
                        _rel2 = _rot_mat @ (_p2 - _cam_pos)
                        glColor4ub(*_col)
                        glVertex3f(*_rel)
                        glVertex3f(*_rel2)
        glEnd()
        glEnable(GL_LIGHTING)

    # === 11-Dimensional String Theory: Background Dimensional Rendering ===
    # Dimensions 0-2 are the visible 3D spatial axes; dimensions 3-10 are compactified
    # Each compactified dimension is rendered as a faint geometric loop projected into 3D
    # Amplitudes and phases come from the fractal decomposition of V_total (computed in update)
    if _dim11_infinity_scale > 1.0:
        glDisable(GL_LIGHTING)
        glEnable(GL_BLEND)
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        _d11_base_r = max(5.0, 15.0 * camera.zoom * _dim11_infinity_scale * 0.1)
        _d11_seg = 24
        _d11_colors = [
            (80, 40, 160), (40, 80, 180), (40, 160, 160), (40, 160, 80),
            (160, 160, 40), (180, 100, 40), (180, 40, 80), (140, 40, 160),
        ]
        for _di in range(3, STRING_DIMENSIONS):
            _amp = _dim11_amplitudes[_di]
            if _amp < 0.01:
                continue
            _phase = _dim11_phases[_di]
            _ci = _di - 3
            _col = _d11_colors[_ci % len(_d11_colors)]
            _alpha = int(max(8, min(45, 40 * _amp * min(_dim11_infinity_scale * 0.3, 1.0))))
            _r = _d11_base_r * (0.5 + 0.5 * _amp) * (1.0 + 0.2 * _ci)
            _ax1 = _ci % 3
            _ax2 = (_ci + 1) % 3
            _tilt = _phase + _ci * 0.618033988 * math.pi
            glColor4ub(_col[0], _col[1], _col[2], _alpha)
            glBegin(GL_LINE_LOOP)
            for _si in range(_d11_seg):
                _a = 2.0 * math.pi * _si / _d11_seg + _tilt
                _v = [0.0, 0.0, 0.0]
                _v[_ax1] = _r * math.cos(_a)
                _v[_ax2] = _r * math.sin(_a)
                _ax3 = 3 - _ax1 - _ax2
                _v[_ax3] = _r * 0.15 * math.sin(_a * 2.0 + _phase * 3.0)
                glVertex3f(_v[0], _v[1], _v[2])
            glEnd()
        glDisable(GL_BLEND)
        glEnable(GL_LIGHTING)

    # Always draw particles (LQCD overlays on top, does not replace)
    if True:
        # Collect draw info for 3D with frustum culling
        draw_spheres = []
        draw_bonds = []
        label_infos = []
        _photon_wave_infos = []  # (screen_x, screen_y, wavelength_nm, frequency_Hz, color_rgb, vel_dir, pos_history) for photon wave overlay
        is_macro = camera.zoom > 50
        # === CEILING #1 FIX: BATCHED ATOM RENDERING ===
        # At organism scale, the per-atom `get_draw_info()` Python call is itself
        # the bottleneck — even with LOD-0 returning a single sphere entry. We
        # bypass it for atoms by pre-collecting them into a SoA and rendering
        # all of them in ONE `glDrawArrays(GL_POINTS, ...)` call. Million atoms
        # → 1 draw call (instead of 1M push/translate/material/pop sequences).
        # Sub-particles (electrons/nucleons/quarks) are invisible at this scale
        # anyway (sub-pixel even on a 4K monitor), so the batch represents each
        # atom as one CPK-colored point. Real-time research-grade convention,
        # same approach VMD's "QuickSurf" and PyMOL's CLOD modes use.
        # === Step-6: single-pass classification + frozen-frame render cache ===
        # One O(N) scan splits particles into batchable atoms / individually-drawn
        # atoms / nanotech atoms / non-atoms — replacing the old listcomp plus
        # per-particle set-membership checks (which also had a latent bug:
        # `_batch_atom_set` could go stale when cluster-LOD shrank
        # `_atoms_for_batch` below the batch threshold, hiding those atoms from
        # BOTH the batch path and the per-particle loop).
        # While `paused` with a static camera every derived render state is
        # frozen, so we cache it keyed on counts + camera + sampled particle
        # ids/positions + display toggles — a fully-idle million-atom frame then
        # costs ~0 instead of ~100ms+ of re-derivation every frame.
        _rc_hit = False
        _rc_key = None
        if paused:
            try:
                _rc_n = len(particles)
                _rc_step = max(1, _rc_n // 128)
                _rc_fp = hash(tuple(
                    (id(_fp), float(_fp.pos[0]), float(_fp.pos[1]), float(_fp.pos[2]))
                    for _fp in (particles[_i] for _i in range(0, _rc_n, _rc_step))
                ))
                _rc_key = (
                    _rc_n,
                    tuple(id(_e) for _e in _life_gen_spawned),
                    tuple(id(_e) for _e in nanotech_loaded),
                    float(camera.pos[0]), float(camera.pos[1]), float(camera.pos[2]),
                    float(camera.rot[0]), float(camera.rot[1]), float(camera.rot[2]),
                    float(camera.zoom), float(_render_alpha), bool(_camera_busy),
                    bool(toggle_particle_labels), bool(toggle_atom_names_macro),
                    bool(toggle_bond_lines), bool(_show_photon_wavelengths),
                    _rc_fp,
                )
                _rc = getattr(on_draw, '_arc', None)
                if _rc is not None and _rc.get('key') == _rc_key:
                    (_draw_particles, _atom_batch_active, _atoms_for_batch,
                     _ab_pos, _ab_col, _ab_size, _ab_visible_n,
                     _cluster_lod_blobs, _field_src, _em_atoms, _other_all) = _rc['data']
                    _rc_hit = True
            except Exception:
                _rc_hit = False
                _rc_key = None
        elif not paused:
            # Live scene: release the frozen-frame cache so its big arrays don't
            # sit in memory while physics is integrating.
            try:
                on_draw._arc = None
            except Exception:
                pass
        _ATOM_BATCH_RENDER_THRESHOLD = 1000
        if not _rc_hit:
            # ── Classification: one pass → four lists ──
            # Membership is camera-independent — a pan/rotate doesn't change
            # which particles are atoms vs non-atoms. Rebuild on count change
            # or every 4th frame (~66ms staleness cap for births/decays); the
            # expensive part during a million-atom drag was re-running this
            # O(N) Python scan every frame even though only the camera matrix
            # changed. The camera-space SoA transform below still runs every
            # frame (it's the actual render geometry).
            # Step-7: while the camera is actively being dragged, the cadence
            # drops to count-changes only — births/decays simply wait out the
            # (≤~1s) gesture instead of hitching the pan every 4th frame.
            if _camera_busy:
                _mem_key = (len(particles), 'busy')
            else:
                _mem_key = (len(particles), frame_count // 4)
            _mem = getattr(on_draw, '_mem', None)
            if _mem is not None and _mem.get('key') == _mem_key:
                (_atoms_all, _nanotech_atoms, _other_all, _other_draw) = _mem['data']
            else:
                _atoms_all = []        # is_atom, not nanotech-managed → batch/individual draw
                _nanotech_atoms = []   # is_atom but nanotech-owned (defensive; rare)
                _other_all = []        # non-atoms (any nanotech flag) — field/radiation sources
                _other_draw = []       # non-atoms, not nanotech — main sphere loop
                for _p in particles:
                    if _p.is_atom:
                        (_nanotech_atoms if _p.in_nanotech else _atoms_all).append(_p)
                    else:
                        _other_all.append(_p)
                        if not _p.in_nanotech:
                            _other_draw.append(_p)
                try:
                    on_draw._mem = {'key': _mem_key,
                                    'data': (_atoms_all, _nanotech_atoms,
                                             _other_all, _other_draw)}
                except Exception:
                    pass
            # === CEILING #3 FIX: CLUSTER-LEVEL ORGANISM LOD ===
            # When a spawned life-gen organism is far enough away that its bounding
            # sphere subtends only a few pixels on-screen, we render the WHOLE
            # organism as one blob (single sphere at the centroid) and exclude ALL
            # of its atoms from both the per-particle loop AND the batched-points
            # path. This makes organism-of-organisms scenes possible at constant
            # cost — e.g. 1000 cells each containing 10,000 atoms = 1000 spheres
            # rendered instead of 10,000,000 points.
            # Eligibility: organism's on-screen apparent radius < _CLUSTER_LOD_PX_THRESHOLD.
            _cluster_lod_blobs = []   # list of (rel_pos_rot, radius, color) for blob draws
            _cluster_lod_atom_set = None  # atoms inside cluster-LOD organisms (skipped elsewhere)
            if _life_gen_spawned:
                _cluster_lod_atom_set = set()
                _CLUSTER_LOD_APPARENT_RADIUS = 0.012  # screen-fraction threshold
                for _ent in _life_gen_spawned:
                    _ent_atoms = _ent.get('atoms') or []
                    if not _ent_atoms:
                        continue
                    _ent_center = _ent.get('center')
                    _ent_radius = float(_ent.get('radius', 50.0))
                    if _ent_center is None:
                        continue
                    _rel_c = np.asarray(_ent_center) - camera.pos
                    _rel_c_rot = rotate_vector(_rel_c, camera.rot)
                    _dist_c = math.sqrt(float(_rel_c_rot[0]**2 + _rel_c_rot[1]**2 + _rel_c_rot[2]**2))
                    _apparent = _ent_radius / (_dist_c + 1.0)
                    if _apparent < _CLUSTER_LOD_APPARENT_RADIUS:
                        # Cluster too small to see individual atoms — render as blob.
                        # Color from the organism's dominant element (most common Z)
                        try:
                            _zs = [getattr(_a, 'Z', 6) for _a in _ent_atoms[:50]]
                            _z_top = max(set(_zs), key=_zs.count) if _zs else 6
                        except Exception:
                            _z_top = 6
                        _blob_color = ELEMENT_COLORS.get(_z_top, (200, 200, 200, 255))
                        _cluster_lod_blobs.append((_rel_c_rot, _ent_radius, _blob_color))
                        for _a in _ent_atoms:
                            _cluster_lod_atom_set.add(_a)
                if not _cluster_lod_blobs:
                    _cluster_lod_atom_set = None  # no cluster-LOD active
            # Atoms needing individual/batch draw = all atoms minus cluster-LOD set
            if _cluster_lod_atom_set:
                _atoms_draw = [a for a in _atoms_all if a not in _cluster_lod_atom_set]
            else:
                _atoms_draw = _atoms_all
            _atom_batch_active = (len(particles) >= _ATOM_BATCH_RENDER_THRESHOLD
                                  and len(_atoms_draw) >= 100)
            _atoms_for_batch = _atoms_draw if _atom_batch_active else []
            _draw_particles = _other_draw if _atom_batch_active else (_other_draw + _atoms_draw)
            # ── Batched-atom SoA: vectorized build (step 6) ──
            # Replaces the old per-atom loop that allocated ~3 numpy temporaries
            # per atom per frame (~seconds at 1M atoms). Now: two list→array
            # stacks + vectorized lerp/rotate/cull — ~30-50x faster. Positions
            # are interpolated prev→pos by _render_alpha exactly as before.
            _ab_pos = _ab_col = _ab_size = None
            _ab_visible_n = 0
            _ab_dist2 = None
            if _atom_batch_active and _atoms_for_batch:
                rotate_vector(np.zeros(3), camera.rot)  # prime _rot_cache_mat
                _al = float(_render_alpha)
                # ── Step-7: world-array stride cache ──
                # Extracting pos/prev_pos/Z is the frame's most expensive
                # Python work (~O(A) object attribute reads ≈ hundreds of ms
                # at 1M atoms) but is CAMERA-INDEPENDENT. During a camera drag
                # we refresh these arrays only on a ~1Hz cadence and on
                # particle-count changes; the camera transform below still
                # runs every frame — that is what actually animates the pan.
                # Result: dragging at million-atom scale does ~numpy-only work
                # per frame instead of re-reading every atom's attributes.
                if _camera_busy:
                    _abw_key = (len(particles), frame_count // 60, 1)
                else:
                    _abw_key = (len(particles), frame_count, 0)
                _abw = getattr(on_draw, '_abw', None)
                if _abw is not None and _abw.get('key') == _abw_key:
                    (_pos_arr, _prev_arr, _ab_col, _ab_size) = _abw['data']
                else:
                    _pos_arr = np.asarray([a.pos for a in _atoms_for_batch], dtype=np.float32)
                    _prev_arr = np.asarray(
                        [getattr(a, 'prev_pos', a.pos) for a in _atoms_for_batch],
                        dtype=np.float32)
                    try:
                        _ab_Z = np.fromiter((a.Z for a in _atoms_for_batch),
                                            dtype=np.int32, count=len(_atoms_for_batch))
                    except Exception:
                        _ab_Z = np.fromiter((getattr(a, 'Z', 0) for a in _atoms_for_batch),
                                            dtype=np.int32, count=len(_atoms_for_batch))
                    _ab_Z = np.where((_ab_Z >= 0) & (_ab_Z < 120), _ab_Z, 0).astype(np.intp)
                    _ab_col = ELEMENT_COLOR_TABLE[_ab_Z]
                    _ab_size = ELEMENT_SIZE_TABLE[_ab_Z]
                    try:
                        on_draw._abw = {'key': _abw_key,
                                        'data': (_pos_arr, _prev_arr, _ab_col, _ab_size)}
                    except Exception:
                        pass
                _rp = _prev_arr if _al == 0.0 else (_prev_arr + (_pos_arr - _prev_arr) * np.float32(_al))
                _rel = _rp - np.asarray(camera.pos, dtype=np.float32)
                if _rot_cache_mat is not None:
                    _rel = (_rot_cache_mat @ _rel.T).T.astype(np.float32, copy=False)
                _ab_dist2 = (_rel * _rel).sum(axis=1)  # rotation preserves norm
                _ab_mask = _rel[:, 2] <= float(camera.zoom) * 100.0
                _ab_pos = np.ascontiguousarray(_rel[_ab_mask])
                if not bool(_ab_mask.all()):
                    _ab_col = np.ascontiguousarray(_ab_col[_ab_mask])
                    _ab_size = np.ascontiguousarray(_ab_size[_ab_mask])
                _ab_visible_n = int(_ab_pos.shape[0])
            # ── Field-toggle source lists: atoms distance-culled to view+margin ──
            # Toggle field displays (gravity/EM/wave/KE/trails) previously scanned
            # ALL particles every frame — O(N) even for atoms kilometres off-screen.
            # Now they iterate _field_src: every non-atom plus only the atoms
            # within _fc of the camera (atoms beyond it can't show field lines).
            _fc = max(400.0, 250.0 * float(camera.zoom))
            _fc2 = _fc * _fc
            if _atom_batch_active and _ab_dist2 is not None:
                _near_idx = np.nonzero(_ab_dist2 <= _fc2)[0]
                _em_atoms = [_atoms_for_batch[int(i)] for i in _near_idx]
            else:
                _em_atoms = _atoms_all
            _field_src = _other_all + _em_atoms + _nanotech_atoms
            # Persist for next frozen frame (only when the key built cleanly)
            if _rc_key is not None:
                try:
                    on_draw._arc = {'key': _rc_key, 'data': (
                        _draw_particles, _atom_batch_active, _atoms_for_batch,
                        _ab_pos, _ab_col, _ab_size, _ab_visible_n,
                        _cluster_lod_blobs, _field_src, _em_atoms, _other_all)}
                except Exception:
                    pass
        for p in _draw_particles:
            for rel_pos, radius, color, label_text, is_sub in p.get_draw_info(camera):
                # Frustum cull: skip if well behind camera (zoom*100 is camera distance)
                if rel_pos[2] > camera.zoom * 100 + radius:
                    continue
                dist = math.sqrt(rel_pos[0]*rel_pos[0] + rel_pos[1]*rel_pos[1] + rel_pos[2]*rel_pos[2])
                draw_spheres.append((rel_pos, radius, color, dist))
                if label_text and not _camera_busy:  # busy: skip ALL labels (gluProject is ~10µs each)
                    _show_lbl = False
                    if toggle_particle_labels:
                        if not is_macro:
                            _show_lbl = True
                        elif p.is_atom and not is_sub:
                            _show_lbl = True
                        elif is_sub and dist > 0 and radius / (dist + 1.0) > 0.003:
                            # Show sub-particle labels at macro zoom if close enough to camera
                            _show_lbl = True
                    elif (toggle_atom_names_macro or getattr(p, 'spawned_by', '')) and p.is_atom and not is_sub:
                        # Z toggle: show atom names even when R (labels) is off
                        _atom_z = getattr(p, 'Z', 0)
                        if _atom_z in atom_data:
                            label_text = f"{atom_data[_atom_z]['symbol']}-{getattr(p, 'A', '?')} ({atom_data[_atom_z].get('name', '')})"
                        _show_lbl = True
                    if _show_lbl:
                        # Prepend AI observer origin marker if spawned by an observer
                        _sb = getattr(p, 'spawned_by', '')
                        if _sb and not is_sub:
                            label_text = f"[{_sb}] {label_text}"
                        winx, winy, winz = gluProject(*rel_pos, model, proj, view)
                        if winz <= 1.0:
                            label_infos.append((winx, winy, label_text, radius, is_sub))
            # Collect photon wavelength overlay data (photons are always top-level, never sub-particles)
            if _show_photon_wavelengths and not _camera_busy and getattr(p, 'base_type', '') in ('photon', 'gluon'):
                _pw_rel = p.pos - camera.pos
                _pw_rel = rotate_vector(_pw_rel, camera.rot)
                _pw_dist = math.sqrt(_pw_rel[0]*_pw_rel[0] + _pw_rel[1]*_pw_rel[1] + _pw_rel[2]*_pw_rel[2])
                if _pw_dist < camera.zoom * 500 and _pw_rel[2] <= camera.zoom * 100:
                    _pw_wx, _pw_wy, _pw_wz = gluProject(*_pw_rel, model, proj, view)
                    if _pw_wz <= 1.0 and 0 <= _pw_wx <= WIDTH and 0 <= _pw_wy <= HEIGHT:
                        _pw_obs_wl = getattr(p, 'observed_wavelength', 0)
                        if _pw_obs_wl > 0:
                            _pw_nm = _pw_obs_wl * 1e9
                        else:
                            _pw_nm = getattr(p, 'rest_wavelength', 550e-9) * 1e9
                        _pw_freq = c / (max(_pw_obs_wl, 1e-15)) if _pw_obs_wl > 0 else 0
                        _pw_rgba = wavelength_to_rgb(_pw_nm)
                        _pw_r, _pw_g, _pw_b = _pw_rgba[0], _pw_rgba[1], _pw_rgba[2]
                        _pw_n = getattr(p, 'medium_n', 1.0)
                        _pw_grp_v = getattr(p, 'photon_group_vel', c)
                        _photon_wave_infos.append((_pw_wx, _pw_wy, _pw_nm, _pw_freq, (_pw_r, _pw_g, _pw_b), _pw_n, _pw_grp_v, p))
            # Skip bonds when bond display is toggled off
            # Also skip bonds for atoms at LOD 0 (too far away)
            if toggle_bond_lines:
                _skip_bonds = False
                if p.is_atom:
                    _ab_rel = p.pos - camera.pos
                    _ab_dist = math.sqrt(float(_ab_rel[0]*_ab_rel[0] + _ab_rel[1]*_ab_rel[1] + _ab_rel[2]*_ab_rel[2]))
                    _ab_app = getattr(p, 'VIS_SHELL_R0', 15.0) / (_ab_dist + 1.0)
                    if _ab_app < 0.0001:
                        _skip_bonds = True
                if not _skip_bonds:
                    for pos1, pos2 in p.get_bonds(camera):
                        draw_bonds.append((pos1, pos2))

        # Nanotech entities
        for _nt in nanotech_loaded:
            for rel_pos, radius, color, label_text, is_sub in _nt.get_draw_info(camera):
                if rel_pos[2] > camera.zoom * 100 + radius:
                    continue
                dist = math.sqrt(rel_pos[0]*rel_pos[0] + rel_pos[1]*rel_pos[1] + rel_pos[2]*rel_pos[2])
                draw_spheres.append((rel_pos, radius, color, dist))
                if label_text and (_nt.show_unit_labels or toggle_particle_labels or toggle_atom_names_macro):
                    winx, winy, winz = gluProject(*rel_pos, model, proj, view)
                    if winz <= 1.0:
                        label_infos.append((winx, winy, label_text, radius, is_sub))

        # Nanotech entity bonds (B key)
        if toggle_bond_lines:
            for _nt in nanotech_loaded:
                if hasattr(_nt, 'get_bonds'):
                    for pos1, pos2 in _nt.get_bonds(camera):
                        draw_bonds.append((pos1, pos2))

        # Life-form organism bonds (B key) — render the entire periodic machine as connected structure.
        # Sub-frame interpolation: bonds were drawn at the current `.pos` directly,
        # while the atom spheres lerp from prev_pos→pos via `_render_alpha`. That
        # mismatch made bonds visibly snap each physics step. Now we interpolate
        # the bond endpoints the same way the atom centres are, so the two move
        # together every rendered frame — proper research-grade alignment.
        if toggle_bond_lines and _life_gen_spawned:
            _bond_al = _render_alpha
            _cam_pos = camera.pos
            _bond_cull_sq = (camera.zoom * 500) ** 2
            for _lf_entry in _life_gen_spawned:
                _lf_atoms = _lf_entry['atoms']
                _lf_bonds = _lf_entry['bonds']
                if not _lf_bonds:
                    continue
                for _bi, _bj in _lf_bonds:
                    if _bi >= len(_lf_atoms) or _bj >= len(_lf_atoms):
                        continue
                    _ba = _lf_atoms[_bi]
                    _bb = _lf_atoms[_bj]
                    if _ba not in particles or _bb not in particles:
                        continue
                    # Interpolated atom centres (matches Atom.get_draw_info path)
                    _a_prev = getattr(_ba, 'prev_pos', _ba.pos)
                    _b_prev = getattr(_bb, 'prev_pos', _bb.pos)
                    _a_render = _a_prev + (_ba.pos - _a_prev) * _bond_al
                    _b_render = _b_prev + (_bb.pos - _b_prev) * _bond_al
                    _bp1 = _a_render - _cam_pos
                    _bp2 = _b_render - _cam_pos
                    # Apply camera rotation so bonds match atom-sphere transform.
                    # Atom.get_bonds() already does this for chemistry bonds; we
                    # were skipping it for life-gen bonds — that's why bonds
                    # appeared "in center" while atoms drifted off-axis.
                    _bp1 = rotate_vector(_bp1, camera.rot)
                    _bp2 = rotate_vector(_bp2, camera.rot)
                    # Squared-distance cull (skip sqrt)
                    _bd_mx = (_bp1[0] + _bp2[0]) * 0.5
                    _bd_my = (_bp1[1] + _bp2[1]) * 0.5
                    _bd_mz = (_bp1[2] + _bp2[2]) * 0.5
                    if (_bd_mx*_bd_mx + _bd_my*_bd_my + _bd_mz*_bd_mz) < _bond_cull_sq:
                        draw_bonds.append((_bp1, _bp2))

        # === Connectome (brain) rendering for spawned life forms ===
        # Brained organisms (C. elegans, Drosophila, mouse, human) carry a
        # pre-built connectome geometry (nodes + edges) attached at spawn time.
        # We render it as a translucent overlay on top of the chemistry atoms:
        # edges as thin glowing lines (chemical/gap synapses), nodes as small
        # colored spheres tinted by anatomical region. Activations modulate
        # brightness over time so the brain visibly "fires". Drawn ALWAYS —
        # not gated by camera-busy — because the brain is the defining
        # personhood signal for visible life forms.
        #
        # v0.5.1 perf gate: skip the entire connectome draw pass when the
        # user has not spawned/focused a life form AND the scene is otherwise
        # empty (cold-boot blank-screen case). Saves a few ms per frame on
        # cold-boot benchmarks without touching the user-visible behaviour.
        if _SIM_LIGHTWEIGHT and not _life_gen_spawned:
            pass
        elif _life_gen_spawned:
            _conn_time = time.time()
            _cam_pos_cn = camera.pos
            _conn_cull_sq = (camera.zoom * 1500) ** 2
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE)
            glDepthMask(GL_FALSE)
            for _lf_entry in _life_gen_spawned:
                _cn_nodes = _lf_entry.get('connectome_nodes')
                _cn_edges = _lf_entry.get('connectome_edges')
                _cn_colors = _lf_entry.get('connectome_colors')
                if _cn_nodes is None or len(_cn_nodes) == 0:
                    continue
                # Cull entire brain if its centroid is too far / behind camera
                _brain_center = _lf_entry.get('center', _cn_nodes.mean(axis=0))
                _bc_rel = rotate_vector(np.asarray(_brain_center, dtype=float) - _cam_pos_cn, camera.rot)
                _bc_d2 = float(_bc_rel[0]*_bc_rel[0] + _bc_rel[1]*_bc_rel[1] + _bc_rel[2]*_bc_rel[2])
                if _bc_d2 > _conn_cull_sq:
                    continue
                # Transform all nodes once via the cached rotation matrix
                rotate_vector(np.zeros(3), camera.rot)  # prime _rot_cache_mat
                _cn_rel = _cn_nodes.astype(np.float32) - _cam_pos_cn.astype(np.float32)
                if _rot_cache_mat is not None:
                    _cn_rel = (_rot_cache_mat @ _cn_rel.T).T.astype(np.float32, copy=False)
                _n_total = len(_cn_rel)
                # Per-neuron activation (smooth time-varying phase, deterministic)
                _phase = _conn_time * 1.5
                _act = 0.5 + 0.5 * np.sin(_phase + np.arange(_n_total, dtype=np.float32) * 0.37)
                # === Synapse edges (GL_LINES batch) ===
                if _cn_edges is not None and len(_cn_edges) > 0:
                    glLineWidth(1.0)
                    glBegin(GL_LINES)
                    _ne = len(_cn_edges)
                    # If extremely dense, sub-sample to keep frame budget sane
                    _edge_stride = max(1, _ne // 1500)
                    for _ei in range(0, _ne, _edge_stride):
                        _a, _b = int(_cn_edges[_ei, 0]), int(_cn_edges[_ei, 1])
                        if _a >= _n_total or _b >= _n_total:
                            continue
                        _pa = _cn_rel[_a]
                        _pb = _cn_rel[_b]
                        _act_e = (_act[_a] + _act[_b]) * 0.5
                        _alpha_e = max(8, min(80, int(_act_e * 110)))
                        # Use a/b avg color, biased blue (synaptic dye look)
                        _ca = _cn_colors[_a]; _cb = _cn_colors[_b]
                        _er = int((int(_ca[0]) + int(_cb[0])) * 0.35)
                        _eg = int((int(_ca[1]) + int(_cb[1])) * 0.45)
                        _eb = int(min(255, (int(_ca[2]) + int(_cb[2])) * 0.55 + 60))
                        glColor4ub(_er, _eg, _eb, _alpha_e)
                        glVertex3f(float(_pa[0]), float(_pa[1]), float(_pa[2]))
                        glVertex3f(float(_pb[0]), float(_pb[1]), float(_pb[2]))
                    glEnd()
                # === Neuron node sprites (step-6: shader point sprites) ===
                # Same math as before (per-neuron activation → alpha/brightness),
                # but drawn as one batched sprite call instead of N glColor+glVertex.
                _npt = max(2.0, min(7.0, 5.0 / max(camera.zoom, 0.05)))
                _cn_keep = np.nonzero(_cn_rel[:, 2] <= camera.zoom * 200.0)[0]
                if len(_cn_keep) > 0:
                    _act_k = _act[_cn_keep]
                    _cn_col = np.empty((len(_cn_keep), 4), dtype=np.uint8)
                    _cn_rgb = np.asarray(_cn_colors, dtype=np.float32)[_cn_keep][:, :3]
                    _cn_col[:, :3] = np.clip(
                        _cn_rgb * (0.45 + 0.55 * _act_k)[:, None], 0, 255).astype(np.uint8)
                    _cn_col[:, 3] = np.clip(120.0 + _act_k * 130.0, 60, 255).astype(np.uint8)
                    _cn_pos = np.ascontiguousarray(_cn_rel[_cn_keep], dtype=np.float32)
                    _cn_sz = np.full(len(_cn_keep), _npt, dtype=np.float32)
                    _draw_point_sprites(_cn_pos, _cn_col, _cn_sz)
            glDepthMask(GL_TRUE)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            glDisable(GL_BLEND)
            glEnable(GL_LIGHTING)

        # === CEILING #1 EXECUTION: BATCHED ATOM POINTS DRAW (step-6 sprites) ===
        # One glDrawArrays(GL_POINTS) call renders every atom in `_atoms_for_batch`.
        # The position/color/size SoA arrays were built vectorized in the
        # classification pass above (or unpacked from the frozen-frame cache) —
        # this site only does the GL draw via the shared sprite helper, which
        # routes to the GLSL point-sprite shader (round glowing atoms) or the
        # fixed-function GL_POINTS fallback automatically.
        if _atom_batch_active and _atoms_for_batch and _ab_visible_n > 0:
            # Point size scales with camera zoom (closer = bigger dots); the
            # per-element radius factor (∝ atomic_weight^(1/3)) is baked in.
            _ab_psize = max(1.5, min(8.0, 6.0 / max(camera.zoom, 0.05)))
            _ab_size_px = _ab_size * np.float32(_ab_psize)
            glDisable(GL_LIGHTING)
            _draw_point_sprites(_ab_pos, _ab_col, _ab_size_px)
            glEnable(GL_LIGHTING)

        # === CEILING #3 EXECUTION: CLUSTER-LOD BLOBS ===
        # Render each spawned organism that's too small to see individual atoms
        # as a single translucent bounding sphere. One sphere call replaces all
        # of its (potentially millions of) atom point draws.
        if _cluster_lod_blobs:
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            glDepthMask(GL_FALSE)
            for _blob_pos, _blob_r, _blob_col in _cluster_lod_blobs:
                glPushMatrix()
                glTranslatef(float(_blob_pos[0]), float(_blob_pos[1]), float(_blob_pos[2]))
                # Semi-transparent so overlapping organisms blend nicely
                _bc = (_blob_col[0]/255.0, _blob_col[1]/255.0, _blob_col[2]/255.0, 0.45)
                glMaterialfv(GL_FRONT_AND_BACK, GL_DIFFUSE, (c_float * 4)(*_bc))
                _draw_cached_sphere(_blob_r, 12)
                glPopMatrix()
            glDepthMask(GL_TRUE)
            glDisable(GL_BLEND)

        # Split into opaque and transparent for correct rendering
        # Skip zero-radius or fully-invisible spheres (label markers)
        opaque_spheres = []
        transparent_spheres = []
        for item in draw_spheres:
            rel_pos, radius, color, dist = item
            if radius < 0.001:
                continue
            if len(color) >= 4 and color[3] <= 0:
                continue
            if len(color) >= 4 and color[3] < 255:
                transparent_spheres.append(item)
            else:
                opaque_spheres.append(item)

        # Draw 3D spheres with LOD tessellation - opaque first
        # Performance governor: reduce tessellation at low quality
        # Uses display list cache: unit sphere compiled once per LOD, scaled at draw time
        # OPTIMIZATION: Tiny/distant particles rendered as GL_POINTS in single batch call
        _lod_div = 1 if _perf.quality >= 3 else (2 if _perf.quality >= 1 else 3)
        _point_threshold = 0.003 if _perf.quality >= 2 else 0.005
        _point_batch = []  # (x, y, z, r, g, b, point_size) for batch rendering
        for rel_pos, radius, color, dist in opaque_spheres:
            screen_frac = radius / (dist + 1.0)
            if screen_frac < _point_threshold:
                # Batch as GL_POINT — skip expensive Push/Translate/Material/Draw/Pop
                _pt_size = max(1.5, min(screen_frac * 800.0, 6.0))
                _point_batch.append((rel_pos[0], rel_pos[1], rel_pos[2],
                                     color[0], color[1], color[2], _pt_size))
            else:
                glPushMatrix()
                glTranslatef(*rel_pos)
                _mat_col = (c_float * 4)(color[0] / 255.0, color[1] / 255.0, color[2] / 255.0, color[3] / 255.0)
                glMaterialfv(GL_FRONT, GL_DIFFUSE, _mat_col)
                glMaterialfv(GL_FRONT, GL_AMBIENT, _mat_col)
                if screen_frac > 0.05:
                    segs = max(10, 20 // _lod_div)
                elif screen_frac > 0.01:
                    segs = max(8, 12 // _lod_div)
                else:
                    segs = max(6, 8 // _lod_div)
                _draw_cached_sphere(radius, segs)
                glPopMatrix()
        # Batch-render all distant/tiny particles as point sprites (step 6):
        # same shader-sprite path as atoms — round glowing dots instead of
        # square GL_POINTS, with automatic fixed-function fallback.
        if _point_batch:
            _pb_arr = np.asarray(_point_batch, dtype=np.float32)
            _pb_pos = np.ascontiguousarray(_pb_arr[:, 0:3])
            _pb_col = np.empty((_pb_arr.shape[0], 4), dtype=np.uint8)
            _pb_col[:, 0:3] = np.clip(_pb_arr[:, 3:6], 0, 255).astype(np.uint8)
            _pb_col[:, 3] = 255
            _pb_sz = np.ascontiguousarray(_pb_arr[:, 6], dtype=np.float32)
            glDisable(GL_LIGHTING)
            _draw_point_sprites(_pb_pos, _pb_col, _pb_sz)
            glEnable(GL_LIGHTING)

        # Transparent pass: blended nucleon shells drawn after opaque content
        if transparent_spheres:
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            glDepthMask(GL_FALSE)
            # Sort back-to-front for correct transparency (use pre-computed dist)
            transparent_spheres.sort(key=lambda s: -s[3])
            for rel_pos, radius, color, dist in transparent_spheres:
                glPushMatrix()
                glTranslatef(*rel_pos)
                _mat_col_t = (c_float * 4)(color[0] / 255.0, color[1] / 255.0, color[2] / 255.0, color[3] / 255.0)
                glMaterialfv(GL_FRONT_AND_BACK, GL_DIFFUSE, _mat_col_t)
                glMaterialfv(GL_FRONT_AND_BACK, GL_AMBIENT, _mat_col_t)
                screen_frac = radius / (dist + 1.0)
                # Large translucent shells (electron clouds) need higher tessellation
                # to look like proper spheres, not hexagons
                if screen_frac > 0.05:
                    segs = max(16, 24 // _lod_div)
                elif screen_frac > 0.01:
                    segs = max(12, 16 // _lod_div)
                elif screen_frac > 0.002:
                    segs = max(8, 10 // _lod_div)
                else:
                    segs = 6
                _draw_cached_sphere(radius, segs)
                glPopMatrix()
            glDepthMask(GL_TRUE)
            glDisable(GL_BLEND)

        # Draw glow ring for selected particle
        if selected_particle and not selected_particle.is_atom:
            sp_rel = selected_particle.pos - camera.pos
            sp_rel = rotate_vector(sp_rel, camera.rot)
            sp_size = selected_particle.get_size() * 1.4
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            glDepthMask(GL_FALSE)
            glPushMatrix()
            glTranslatef(*sp_rel)
            glColor4f(1.0, 1.0, 0.3, 0.25)
            _draw_cached_sphere(sp_size, 16)
            glPopMatrix()
            glDepthMask(GL_TRUE)
            glDisable(GL_BLEND)
            glEnable(GL_LIGHTING)

        # Draw bonds in 3D — Item-22: VBO path for large bond counts.
        # When draw_bonds >= 200, use np.empty + glDrawArrays(GL_LINES) for one
        # draw call instead of 2N glVertex3f calls. Below the threshold,
        # original immediate mode is used (setup overhead would dominate).
        # CRITICAL: preserve original glDisable/glEnable lighting toggle so
        # subsequent code sees the same GL state — toggle UNCONDITIONALLY
        # (even when draw_bonds is empty) to match Copy 3 behaviour exactly.
        glDisable(GL_LIGHTING)
        glLineWidth(2.0)
        glColor4ub(255, 220, 50, 255)  # Bright yellow for visibility
        _bn_count = len(draw_bonds)
        if _bn_count >= 200:
            try:
                _bond_array = np.empty((_bn_count * 2, 3), dtype=np.float32)
                for _bi, (_p1, _p2) in enumerate(draw_bonds):
                    _bond_array[_bi * 2] = _p1
                    _bond_array[_bi * 2 + 1] = _p2
                glEnableClientState(GL_VERTEX_ARRAY)
                glVertexPointer(3, GL_FLOAT, 0, _bond_array)
                glDrawArrays(GL_LINES, 0, _bn_count * 2)
                glDisableClientState(GL_VERTEX_ARRAY)
            except Exception:
                glBegin(GL_LINES)
                for pos1, pos2 in draw_bonds:
                    glVertex3f(*pos1)
                    glVertex3f(*pos2)
                glEnd()
        else:
            glBegin(GL_LINES)
            for pos1, pos2 in draw_bonds:
                glVertex3f(*pos1)
                glVertex3f(*pos2)
            glEnd()
        glLineWidth(1.0)
        glEnable(GL_LIGHTING)

        # ── DNA AURA EFFECT ──────────────────────────────────────────
        # When 'dna_aura' load-in is active, draw a translucent double-
        # helix glow around every spawned molecule group that came from a
        # DNA-catalog entry.  The helix is parametric:
        #   x(t) = R*cos(t), y(t) = R*sin(t), z(t) = pitch*t/(2*pi)
        # with two strands offset by pi for the antiparallel backbone.
        if _ai_loadins.get('dna_aura', {}).get('enabled', False) and _spawned_molecules:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            glDepthMask(GL_FALSE)
            _dna_R = 12.0   # helix radius in vis-units (~12 A = 1.2 nm ≈ half diameter)
            _dna_pitch = 35.7  # rise per full turn in vis-units (3.57 nm B-form)
            _dna_turns = 2.0
            _dna_steps = 60
            _dna_t_max = _dna_turns * 2.0 * math.pi
            _dna_dt = _dna_t_max / _dna_steps
            _aura_time = simulation_time * 0.3  # slow rotation
            for _mol_grp in _spawned_molecules:
                if not _mol_grp:
                    continue
                # Compute molecule centroid
                _mol_cx = sum(float(a.pos[0]) for a in _mol_grp if a in particles) / max(1, len(_mol_grp))
                _mol_cy = sum(float(a.pos[1]) for a in _mol_grp if a in particles) / max(1, len(_mol_grp))
                _mol_cz = sum(float(a.pos[2]) for a in _mol_grp if a in particles) / max(1, len(_mol_grp))
                _mol_rel = rotate_vector(
                    np.array([_mol_cx, _mol_cy, _mol_cz]) - camera.pos, camera.rot)
                glPushMatrix()
                glTranslatef(float(_mol_rel[0]), float(_mol_rel[1]), float(_mol_rel[2]))
                # Strand 1 (cyan glow)
                glColor4f(0.0, 0.8, 1.0, 0.18)
                glBegin(GL_LINE_STRIP)
                for _si in range(_dna_steps + 1):
                    _st = _si * _dna_dt + _aura_time
                    _sx = _dna_R * math.cos(_st)
                    _sy = _dna_R * math.sin(_st)
                    _sz = (_dna_pitch * _st / (2.0 * math.pi)) - _dna_pitch * _dna_turns * 0.5
                    glVertex3f(_sx, _sy, _sz)
                glEnd()
                # Strand 2 (magenta glow, pi offset = antiparallel)
                glColor4f(1.0, 0.2, 0.8, 0.18)
                glBegin(GL_LINE_STRIP)
                for _si in range(_dna_steps + 1):
                    _st = _si * _dna_dt + _aura_time + math.pi
                    _sx = _dna_R * math.cos(_st)
                    _sy = _dna_R * math.sin(_st)
                    _sz = (_dna_pitch * _st / (2.0 * math.pi)) - _dna_pitch * _dna_turns * 0.5
                    glVertex3f(_sx, _sy, _sz)
                glEnd()
                # Base-pair rungs (white, connecting the two strands)
                glColor4f(1.0, 1.0, 1.0, 0.10)
                glBegin(GL_LINES)
                for _si in range(0, _dna_steps + 1, 3):  # every 3rd step ≈ 1 bp
                    _st = _si * _dna_dt + _aura_time
                    _sx1 = _dna_R * math.cos(_st)
                    _sy1 = _dna_R * math.sin(_st)
                    _sx2 = _dna_R * math.cos(_st + math.pi)
                    _sy2 = _dna_R * math.sin(_st + math.pi)
                    _sz  = (_dna_pitch * _st / (2.0 * math.pi)) - _dna_pitch * _dna_turns * 0.5
                    glVertex3f(_sx1, _sy1, _sz)
                    glVertex3f(_sx2, _sy2, _sz)
                glEnd()
                glPopMatrix()
            glDepthMask(GL_TRUE)
            glDisable(GL_BLEND)
            glEnable(GL_LIGHTING)

        # Draw orbits if toggled
        if toggle_orbital_paths and selected_particle and selected_particle.is_atom:
          try:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            _nuc_sps = [sp.pos for sp in selected_particle.sub_particles if getattr(sp, 'base_type', '') not in ('electron', 'positron')]
            nucleus_pos = np.mean(_nuc_sps, axis=0) if _nuc_sps else selected_particle.pos
            atom_vel = selected_particle.vel  # bulk atom velocity
            # --- Electron orbital paths (green) ---
            for sp in selected_particle.sub_particles:
                sp_bt = getattr(sp, 'base_type', '')
                if sp_bt in ('electron', 'positron'):
                    glColor4ub(0, 255, 80, 160)  # Bright green for electron orbits
                    r_vec_world = sp.pos - nucleus_pos
                    r_norm = np.linalg.norm(r_vec_world)
                    if r_norm < 1e-12: continue
                    v_rel = sp.vel - atom_vel
                    cross_rv = np.cross(r_vec_world, v_rel)
                    cross_norm = np.linalg.norm(cross_rv)
                    if cross_norm < 1e-10: continue
                    _n_ax = cross_rv / cross_norm
                    u1 = r_vec_world / r_norm
                    cross_nu1 = np.cross(_n_ax, u1)
                    u2_norm = np.linalg.norm(cross_nu1)
                    if u2_norm < 1e-10: continue
                    u2 = cross_nu1 / u2_norm
                    glBegin(GL_LINE_LOOP)
                    for i in range(24):
                        theta = 2.0 * math.pi * i / 24
                        p_world = nucleus_pos + u1 * r_norm * math.cos(theta) + u2 * r_norm * math.sin(theta)
                        rel_p = rotate_vector(p_world - camera.pos, camera.rot)
                        glVertex3f(*rel_p)
                    glEnd()
            # --- Quark orbital paths (cyan) inside each nucleon ---
            for sp in selected_particle.sub_particles:
                sp_bt = getattr(sp, 'base_type', '')
                if sp_bt not in ('proton', 'neutron', 'anti_proton', 'anti_neutron'):
                    continue
                if not sp.constituent_quarks:
                    continue
                for q in sp.constituent_quarks:
                    r_vec_q = q.pos - sp.pos
                    r_norm_q = np.linalg.norm(r_vec_q)
                    if r_norm_q < 1e-12: continue
                    v_rel_q = q.vel - sp.vel
                    cross_rv_q = np.cross(r_vec_q, v_rel_q)
                    cross_norm_q = np.linalg.norm(cross_rv_q)
                    if cross_norm_q < 1e-10: continue
                    _n_q = cross_rv_q / cross_norm_q
                    u1_q = r_vec_q / r_norm_q
                    cross_nu1_q = np.cross(_n_q, u1_q)
                    u2_norm_q = np.linalg.norm(cross_nu1_q)
                    if u2_norm_q < 1e-10: continue
                    u2_q = cross_nu1_q / u2_norm_q
                    q_bt = getattr(q, 'base_type', '')
                    q_col = Particle.PARTICLE_COLORS.get(q_bt, (0, 255, 255, 140))
                    glColor4ub(q_col[0], q_col[1], q_col[2], 140)
                    glBegin(GL_LINE_LOOP)
                    for i in range(16):
                        theta = 2.0 * math.pi * i / 16
                        p_world_q = sp.pos + u1_q * r_norm_q * math.cos(theta) + u2_q * r_norm_q * math.sin(theta)
                        rel_q = rotate_vector(p_world_q - camera.pos, camera.rot)
                        glVertex3f(*rel_q)
                    glEnd()
            glDisable(GL_BLEND)
            glEnable(GL_LIGHTING)
          except Exception:
            glEnable(GL_LIGHTING)

        # Draw gravity pull direction if toggled
        if toggle_gravity_paths:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            # 1. Direction arrows: fixed visible length pointing where gravity pulls each particle
            arrow_base = max(3.0, 8.0 * camera.zoom)
            glColor4ub(255, 0, 255, 200)  # Magenta for gravity direction
            glBegin(GL_LINES)
            for p in _field_src:
                # Step-6: distance-gate — arrows are ~8·zoom long, so particles
                # beyond the field cull radius produce only off-screen pixels.
                _dp = p.pos - camera.pos
                if (_dp[0]*_dp[0] + _dp[1]*_dp[1] + _dp[2]*_dp[2]) > _fc2:
                    continue
                g = getattr(p, 'last_grav_accel', None)
                if g is None:
                    continue
                g_norm = np.linalg.norm(g)
                if g_norm < 1e-300:
                    continue
                g_dir = g / g_norm
                start = rotate_vector(_dp, camera.rot)
                end = rotate_vector(p.pos + g_dir * arrow_base - camera.pos, camera.rot)
                glVertex3f(*start)
                glVertex3f(*end)
            glEnd()
            # 2. Gravity web: faint lines between massive particle pairs showing field connections.
            # Optimizations: hoist max_web_dist computation out of inner loop; compare squared
            # distances to skip sqrt for rejected pairs; pre-rotate each particle once instead
            # of re-rotating both endpoints per pair (O(N²) → O(N) rotate_vector calls).
            # Step-6: sources come from _field_src (atoms already distance-culled) and the
            # pair loop is capped — O(M²) is unusable past a few hundred sources anyway.
            massive = [p for p in _field_src if p.mass > 0 and getattr(p, 'base_type', '') != 'decayed']
            if len(massive) > 350:
                _wstep = len(massive) / 350.0
                massive = [massive[int(i * _wstep)] for i in range(350)]
            _n_mass = len(massive)
            if _n_mass > 1:
                max_web_dist = max(100.0, 300.0 * camera.zoom)
                max_web_dist_sq = max_web_dist * max_web_dist
                eps_sq = EPSILON * EPSILON
                inv_max_web = 1.0 / max_web_dist
                # Pre-rotate every massive particle's position into camera space once
                _rel_pos = [rotate_vector(p.pos - camera.pos, camera.rot) for p in massive]
                glBegin(GL_LINES)
                for i in range(_n_mass):
                    _pi = massive[i].pos
                    _ri = _rel_pos[i]
                    for j in range(i + 1, _n_mass):
                        r_vec = massive[j].pos - _pi
                        r_dist_sq = float(r_vec[0]*r_vec[0] + r_vec[1]*r_vec[1] + r_vec[2]*r_vec[2])
                        if r_dist_sq > max_web_dist_sq or r_dist_sq < eps_sq:
                            continue
                        r_dist = math.sqrt(r_dist_sq)
                        # Alpha fades with distance
                        alpha = max(15, int(80 * (1.0 - r_dist * inv_max_web)))
                        glColor4ub(180, 80, 255, alpha)
                        _rj = _rel_pos[j]
                        glVertex3f(_ri[0], _ri[1], _ri[2])
                        glVertex3f(_rj[0], _rj[1], _rj[2])
                glEnd()
            glEnable(GL_LIGHTING)

        # Draw forward motion trails if toggled.
        # Optimizations: distance-gate to skip particles way outside the view frustum
        # (a particle 5000 units away from the camera produces invisible 1-pixel trails
        # that still cost a draw call each); compare squared distances to avoid sqrt;
        # use math.sqrt + manual squared-norm for v_norm (3x faster than np.linalg.norm
        # on size-3 arrays — np.linalg has python-side overhead per call).
        # SCALE GATE: with thousands of particles the trail render alone costs more
        # than the entire physics step, and trails of 200 history points each become
        # visually noisy — auto-disable above 5000 particles. User toggle still
        # controls the flag; this only short-circuits the draw pass.
        if toggle_forward_paths and len(particles) <= 5000:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            is_macro = camera.zoom > 50
            arrow_len = max(5.0, 12.0 * camera.zoom)
            # Distance gate: a particle more than _trail_cull_dist units away from the
            # camera produces sub-pixel trails — skip its entire trail / arrow.
            _trail_cull_dist = max(800.0, 1200.0 * camera.zoom)
            _trail_cull_sq = _trail_cull_dist * _trail_cull_dist
            _cam_pos = camera.pos
            # GPU-batched: all velocity arrows in a single draw call
            glColor4ub(0, 255, 255, 220)
            glBegin(GL_LINES)
            for p in _field_src:
                if getattr(p, 'base_type', '') == 'decayed' or p.mass <= 0:
                    continue
                _dp = p.pos - _cam_pos
                if (_dp[0]*_dp[0] + _dp[1]*_dp[1] + _dp[2]*_dp[2]) > _trail_cull_sq:
                    continue
                _vx, _vy, _vz = p.vel[0], p.vel[1], p.vel[2]
                v_norm_sq = _vx*_vx + _vy*_vy + _vz*_vz
                if v_norm_sq > 1e-60:
                    v_norm = math.sqrt(v_norm_sq)
                    inv_v = 1.0 / v_norm
                    start = rotate_vector(_dp, camera.rot)
                    _ed = np.array([_dp[0] + _vx*inv_v*arrow_len, _dp[1] + _vy*inv_v*arrow_len, _dp[2] + _vz*inv_v*arrow_len])
                    end = rotate_vector(_ed, camera.rot)
                    glVertex3f(start[0], start[1], start[2])
                    glVertex3f(end[0], end[1], end[2])
            glEnd()
            # Trails: per-particle LINE_STRIP with per-vertex alpha (cannot batch easily).
            # Distance gate eliminates far-away particles' trails entirely.
            for p in _field_src:
                if getattr(p, 'base_type', '') == 'decayed' or p.mass <= 0:
                    continue
                _dp = p.pos - _cam_pos
                if (_dp[0]*_dp[0] + _dp[1]*_dp[1] + _dp[2]*_dp[2]) > _trail_cull_sq:
                    continue
                hist = getattr(p, 'pos_history', None)
                if hist is None or len(hist) < 2:
                    continue
                trail = list(hist)
                n = len(trail)
                if is_macro and n > 60:
                    step_t = max(1, n // 60)
                    trail = trail[::step_t]
                    n = len(trail)
                _inv_nm1 = 1.0 / max(n - 1, 1)
                glBegin(GL_LINE_STRIP)
                for idx_t, hp in enumerate(trail):
                    alpha = int(40 + 160 * (idx_t * _inv_nm1))
                    glColor4ub(0, 255, 255, alpha)
                    rel = rotate_vector(hp - _cam_pos, camera.rot)
                    glVertex3f(rel[0], rel[1], rel[2])
                glEnd()
            glEnable(GL_LIGHTING)

        # Draw EM field lines if toggled (F2)
        if toggle_em_field:
          try:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            # Use the frame-cached charged-particle list built once in update(dt)
            # so we don't redo this filter every draw frame. Falls back to a fresh
            # filter if the cache hasn't been populated yet (first frame / paused),
            # and back-fills the cache so a paused scene doesn't re-filter every frame.
            if _charged_particles_cache:
                charged = list(_charged_particles_cache)
            else:
                charged = [
                    p for p in particles
                    if abs(p.charge) > 0 and p.mass > 0 and getattr(p, 'base_type', '') != 'decayed'
                ]
                try:
                    globals()['_charged_particles_cache'] = list(charged)
                except Exception:
                    pass
            # Also include charged sub-particles of atoms so EM field is visible at
            # atom zoom. Step-6: iterate _em_atoms (distance-culled atom subset)
            # instead of all particles — a million far atoms no longer get scanned.
            for p in _em_atoms:
                if hasattr(p, 'sub_particles'):
                    for sp in p.sub_particles:
                        if abs(getattr(sp, 'charge', 0)) > 0 and getattr(sp, 'base_type', '') != 'decayed':
                            charged.append(sp)
            field_len = max(5.0, max(15.0 * camera.zoom, 3.0))
            n_lines = 8  # field lines per particle
            # Step-6: drop off-screen sources — field lines reach at most
            # field_len, so anything beyond view+field_len draws only off-screen.
            _em_cull2 = (_fc + field_len) ** 2
            _cam_p_em = camera.pos
            charged = [p for p in charged
                       if ((p.pos[0] - _cam_p_em[0]) ** 2 + (p.pos[1] - _cam_p_em[1]) ** 2
                           + (p.pos[2] - _cam_p_em[2]) ** 2) <= _em_cull2]
            # GPU-batched: all E-field lines in a single glBegin/glEnd (1 draw call)
            glBegin(GL_LINES)
            for p in charged:
                q_sign = 1 if p.charge > 0 else -1
                _em_col = (255, 80, 80, 100) if p.charge > 0 else (80, 120, 255, 100)
                glColor4ub(*_em_col)
                for k in range(n_lines):
                    theta = 2.0 * math.pi * k / n_lines
                    phi = math.pi * ((k % 4) + 0.5) / 4
                    dx_f = math.sin(phi) * math.cos(theta)
                    dy_f = math.sin(phi) * math.sin(theta)
                    dz_f = math.cos(phi)
                    direction = np.array([dx_f, dy_f, dz_f]) * q_sign
                    start_w = p.pos
                    end_w = p.pos + direction * field_len
                    start_r = rotate_vector(start_w - camera.pos, camera.rot)
                    end_r = rotate_vector(end_w - camera.pos, camera.rot)
                    glVertex3f(*start_r)
                    glVertex3f(*end_r)
            glEnd()
            # GPU-batched: all B-field rings as GL_LINES (1 draw call instead of N)
            glBegin(GL_LINES)
            for p in charged:
                v_norm = np.linalg.norm(p.vel)
                if v_norm > 1e-20:
                    v_dir = p.vel / v_norm
                    if abs(v_dir[0]) < 0.9:
                        perp1 = np.cross(v_dir, np.array([1.0, 0.0, 0.0]))
                    else:
                        perp1 = np.cross(v_dir, np.array([0.0, 1.0, 0.0]))
                    perp1 = perp1 / (np.linalg.norm(perp1) + EPSILON)
                    perp2 = np.cross(v_dir, perp1)
                    mag_r = field_len * 0.6
                    glColor4ub(100, 255, 100, 60)  # Green for B-field
                    _bfn = 16
                    _bf_pts = []
                    for k in range(_bfn):
                        angle = 2.0 * math.pi * k / _bfn
                        pt = p.pos + perp1 * mag_r * math.cos(angle) + perp2 * mag_r * math.sin(angle)
                        _bf_pts.append(rotate_vector(pt - camera.pos, camera.rot))
                    for k in range(_bfn):
                        glVertex3f(*_bf_pts[k])
                        glVertex3f(*_bf_pts[(k + 1) % _bfn])
            glEnd()
            glEnable(GL_LIGHTING)
          except Exception:
            glEnable(GL_LIGHTING)

        # Draw de Broglie wave rings if toggled (F3) â€” high-contrast, accurate math
        if toggle_wave_field:
          try:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            h_planck = 6.62607015e-34
            # Cap wave_field_len so rings stay proportional at any zoom
            wave_field_len = max(5.0, min(80.0, 15.0 * max(camera.zoom, 1.0)))
            _wave_seg = 32  # Higher segment count for smoother rings
            # Step-6: rings reach at most ~180 units around a particle, so only
            # _field_src (distance-culled atoms + all non-atoms) can ever show.
            _wv_cull2 = (_fc + 180.0) ** 2
            _cam_p_wv = camera.pos
            for p in _field_src:
                if p.mass <= 0 or getattr(p, 'base_type', '') == 'decayed':
                    continue
                _wdp = p.pos - _cam_p_wv
                if (_wdp[0]*_wdp[0] + _wdp[1]*_wdp[1] + _wdp[2]*_wdp[2]) > _wv_cull2:
                    continue
                v_norm = np.linalg.norm(p.vel)
                if v_norm < 1e-30:
                    continue
                # de Broglie wavelength: Î» = h / (mÂ·v) with relativistic correction
                _beta = min(v_norm / c, 0.9999) if c > 0 else 0
                _gamma = 1.0 / math.sqrt(1.0 - _beta * _beta)
                _p_momentum = _gamma * p.mass * v_norm  # relativistic momentum
                wavelength = h_planck / (_p_momentum + EPSILON)
                # Frequency: f = v / Î»
                frequency = v_norm / (wavelength + EPSILON)
                # Scale for visibility: base on particle size, cap to wave_field_len
                _p_size = p.get_size() if hasattr(p, 'get_size') else 5.0
                vis_r = max(3.0, min(wave_field_len * 1.5, _p_size * 3.0 + wavelength * 1e12 * min(max(camera.zoom, 1.0), 2.0)))
                v_dir = p.vel / v_norm
                if abs(v_dir[0]) < 0.9:
                    perp1 = np.cross(v_dir, np.array([1.0, 0.0, 0.0]))
                else:
                    perp1 = np.cross(v_dir, np.array([0.0, 1.0, 0.0]))
                pn = np.linalg.norm(perp1)
                if pn < 1e-10:
                    continue
                perp1 = perp1 / pn
                perp2 = np.cross(v_dir, perp1)
                # Color by particle type for high contrast
                _bt = getattr(p, 'base_type', '')
                if p.is_atom:
                    _wr, _wg, _wb = 80, 255, 160  # Bright green for atoms
                elif _bt == 'electron':
                    _wr, _wg, _wb = 100, 180, 255  # Bright blue
                elif _bt in ('proton', 'anti_proton'):
                    _wr, _wg, _wb = 255, 120, 80  # Bright orange-red
                elif _bt in ('neutron', 'anti_neutron'):
                    _wr, _wg, _wb = 200, 200, 220  # Bright white-gray
                elif _bt in ('muon', 'tau'):
                    _wr, _wg, _wb = 220, 120, 255  # Bright purple
                else:
                    _wr, _wg, _wb = 255, 220, 100  # Bright yellow default
                # Draw concentric wave rings with fading alpha for depth
                for ring in range(1, 6):
                    r = vis_r * ring * 0.4
                    _alpha = max(30, 180 - ring * 30)
                    glColor4ub(_wr, _wg, _wb, _alpha)
                    glBegin(GL_LINE_LOOP)
                    for k in range(_wave_seg):
                        angle = 2.0 * math.pi * k / _wave_seg
                        pt = p.pos + perp1 * r * math.cos(angle) + perp2 * r * math.sin(angle)
                        rel = rotate_vector(pt - camera.pos, camera.rot)
                        glVertex3f(*rel)
                    glEnd()
                # Collect wavefront direction arrow for batched draw
                _arrow_len = vis_r * 2.5
                _arrow_start = p.pos - v_dir * _arrow_len * 0.3
                _arrow_end = p.pos + v_dir * _arrow_len * 0.7
                _as = rotate_vector(_arrow_start - camera.pos, camera.rot)
                _ae = rotate_vector(_arrow_end - camera.pos, camera.rot)
                if not hasattr(on_draw, '_wave_arrows'):
                    on_draw._wave_arrows = []
                on_draw._wave_arrows.append((_as, _ae, _wr, _wg, _wb))
            # GPU-batched: all wavefront direction arrows in 1 draw call
            if hasattr(on_draw, '_wave_arrows') and on_draw._wave_arrows:
                glBegin(GL_LINES)
                for _wa_s, _wa_e, _wa_r, _wa_g, _wa_b in on_draw._wave_arrows:
                    glColor4ub(_wa_r, _wa_g, _wa_b, 140)
                    glVertex3f(*_wa_s)
                    glVertex3f(*_wa_e)
                glEnd()
                on_draw._wave_arrows.clear()
            glEnable(GL_LIGHTING)
          except Exception as e:
            print(f"Error drawing wave field: {e}")
            glEnable(GL_LIGHTING)

        # Draw radiation density mapping if toggled (F6)
        if toggle_radiation_density:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            # Only count actual radiation: photons and gluons (not all energetic particles)
            # Step-6: photons/gluons are never atoms — scan _other_all (non-atoms)
            # instead of the full particle list.
            _rad_photons = [p for p in _other_all if getattr(p, 'base_type', '') in ('photon', 'gluon')]
            if _rad_photons:
                # Grid-based density: divide visible volume into cells
                _rad_grid_n = 12  # cells per axis — finer resolution
                # Cap range so cells never become absurdly large
                _rad_range = max(50.0, min(500.0, 100.0 * camera.zoom))
                _rad_cell = 2.0 * _rad_range / _rad_grid_n
                # Cap individual cell size to prevent huge quads
                _rad_cell = min(_rad_cell, 80.0)
                _rad_counts = {}
                _rad_energy = {}  # track total energy per cell for color
                for rp in _rad_photons:
                    rel = rp.pos - camera.pos
                    _rd = np.linalg.norm(rel)
                    if _rd > _rad_range * 1.5:
                        continue
                    ix = int((rel[0] + _rad_range) / max(_rad_cell, 1e-6))
                    iy = int((rel[1] + _rad_range) / max(_rad_cell, 1e-6))
                    iz = int((rel[2] + _rad_range) / max(_rad_cell, 1e-6))
                    ix = max(0, min(_rad_grid_n - 1, ix))
                    iy = max(0, min(_rad_grid_n - 1, iy))
                    iz = max(0, min(_rad_grid_n - 1, iz))
                    key = (ix, iy, iz)
                    _rad_counts[key] = _rad_counts.get(key, 0) + 1
                    _rad_energy[key] = _rad_energy.get(key, 0.0) + rp.energy_kin
                if _rad_counts:
                    _rad_max = max(_rad_counts.values())
                    _rad_e_max = max(_rad_energy.values()) if _rad_energy else 1.0
                    # GPU-batched: all radiation density quads in 1 draw call
                    glBegin(GL_QUADS)
                    for (ix, iy, iz), cnt in _rad_counts.items():
                        intensity = cnt / _rad_max
                        if intensity < 0.08:
                            continue
                        e_frac = _rad_energy.get((ix, iy, iz), 0.0) / max(_rad_e_max, 1e-30)
                        cx = -_rad_range + (ix + 0.5) * _rad_cell
                        cy = -_rad_range + (iy + 0.5) * _rad_cell
                        cz = -_rad_range + (iz + 0.5) * _rad_cell
                        cell_center = np.array([cx, cy, cz])
                        _cell_dist = np.linalg.norm(cell_center)
                        _dist_fade = max(0.2, 1.0 - _cell_dist / (_rad_range * 1.5))
                        alpha = int(min(50, intensity * 50 * _dist_fade))
                        if alpha < 3:
                            continue
                        # Color: blue(cold CMB) -> cyan -> yellow -> red(hot gamma)
                        if e_frac < 0.33:
                            r_c = int(40 * e_frac * 3)
                            g_c = int(80 + 140 * e_frac * 3)
                            b_c = int(200 + 55 * (1.0 - e_frac * 3))
                        elif e_frac < 0.66:
                            t = (e_frac - 0.33) * 3
                            r_c = int(40 + 200 * t)
                            g_c = int(220 - 40 * t)
                            b_c = int(100 - 80 * t)
                        else:
                            t = (e_frac - 0.66) * 3
                            r_c = int(240 + 15 * t)
                            g_c = int(180 - 140 * t)
                            b_c = int(20 - 20 * t)
                        r_c = max(0, min(255, r_c))
                        g_c = max(0, min(255, g_c))
                        b_c = max(0, min(255, b_c))
                        world_cx = camera.pos[0] + cx
                        world_cy = camera.pos[1] + cy
                        world_cz = camera.pos[2] + cz
                        world_center = np.array([world_cx, world_cy, world_cz])
                        rel_c = rotate_vector(world_center - camera.pos, camera.rot)
                        half = _rad_cell * 0.35
                        glColor4ub(r_c, g_c, b_c, alpha)
                        # XY face
                        glVertex3f(rel_c[0] - half, rel_c[1] - half, rel_c[2])
                        glVertex3f(rel_c[0] + half, rel_c[1] - half, rel_c[2])
                        glVertex3f(rel_c[0] + half, rel_c[1] + half, rel_c[2])
                        glVertex3f(rel_c[0] - half, rel_c[1] + half, rel_c[2])
                        # XZ face
                        glVertex3f(rel_c[0] - half, rel_c[1], rel_c[2] - half)
                        glVertex3f(rel_c[0] + half, rel_c[1], rel_c[2] - half)
                        glVertex3f(rel_c[0] + half, rel_c[1], rel_c[2] + half)
                        glVertex3f(rel_c[0] - half, rel_c[1], rel_c[2] + half)
                        # YZ face
                        glVertex3f(rel_c[0], rel_c[1] - half, rel_c[2] - half)
                        glVertex3f(rel_c[0], rel_c[1] + half, rel_c[2] - half)
                        glVertex3f(rel_c[0], rel_c[1] + half, rel_c[2] + half)
                        glVertex3f(rel_c[0], rel_c[1] - half, rel_c[2] + half)
                    glEnd()
            glDisable(GL_BLEND)
            glEnable(GL_LIGHTING)

        # Draw gravitational potential field if toggled (key 7).
        # Optimization: cap to top-K most-massive particles. The N² pair compute
        # was the dominant per-frame cost at scale — for a 1M-atom organism the
        # gradient is virtually unchanged by the lightest 99.99% of contributors,
        # so we compute the field only against the K heaviest sources. This
        # converts O(N²) → O(K²) where K is bounded regardless of total N.
        if toggle_grav_potential:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            glDepthMask(GL_FALSE)
            _gp_all = [p for p in _field_src if p.mass > 0 and getattr(p, 'base_type', '') != 'decayed']
            _GP_MAX_K = 100  # cap on number of sources contributing to the field viz
            if len(_gp_all) > _GP_MAX_K:
                # Partial-sort top-K by mass — O(N) via numpy argpartition, beats full sort
                try:
                    _masses_arr = np.fromiter((p.mass for p in _gp_all), dtype=np.float64, count=len(_gp_all))
                    _top_idx = np.argpartition(_masses_arr, -_GP_MAX_K)[-_GP_MAX_K:]
                    _gp_massive = [_gp_all[int(i)] for i in _top_idx]
                except Exception:
                    _gp_massive = sorted(_gp_all, key=lambda p: -p.mass)[:_GP_MAX_K]
            else:
                _gp_massive = _gp_all
            if len(_gp_massive) > 1:
                # Vectorize the O(K²) potential compute via numpy
                _gp_pos = np.array([p.pos for p in _gp_massive], dtype=np.float64)
                _gp_mass = np.array([p.mass for p in _gp_massive], dtype=np.float64)
                # Pairwise distances (K, K)
                _diff = _gp_pos[:, None, :] - _gp_pos[None, :, :]
                _r_mat = np.sqrt((_diff * _diff).sum(axis=2))
                _r_mat[_r_mat < EPSILON] = np.inf  # avoid self-term blowup
                # phi_i = -G * sum_j m_j / r_ij
                _phi_arr = -G * (_gp_mass[None, :] / _r_mat).sum(axis=1)
                _gp_pots = list(zip(_gp_massive, _phi_arr.tolist()))
                _gp_max_pot = max(1e-30, float(np.abs(_phi_arr).max()))
                # Draw potential wells as translucent spheres scaled by depth
                for p, _phi in _gp_pots:
                    _depth = abs(_phi) / (_gp_max_pot + EPSILON)
                    _gp_r = max(3.0, 8.0 * _depth * max(camera.zoom, 1.0))
                    _gp_alpha = int(30 + 100 * _depth)
                    # Deep blue for strong wells, cyan for weak
                    _gp_b = int(120 + 135 * _depth)
                    _gp_g = int(60 + 120 * (1.0 - _depth))
                    rel = rotate_vector(p.pos - camera.pos, camera.rot)
                    glPushMatrix()
                    glTranslatef(*rel)
                    glColor4ub(40, _gp_g, _gp_b, _gp_alpha)
                    _draw_cached_sphere(_gp_r, 10)
                    glPopMatrix()
                # Draw potential gradient lines between nearby pairs
                glBegin(GL_LINES)
                for i in range(len(_gp_massive)):
                    for j in range(i + 1, min(i + 20, len(_gp_massive))):
                        _r = np.linalg.norm(_gp_massive[i].pos - _gp_massive[j].pos)
                        _max_gp_dist = max(500.0, 400.0 * camera.zoom)
                        if _r > _max_gp_dist or _r < EPSILON:
                            continue
                        _gp_str = G * _gp_massive[i].mass * _gp_massive[j].mass / (_r * _r)
                        _gp_norm = min(1.0, _gp_str / (EPSILON + _gp_max_pot * 0.01))
                        _gp_a = max(15, int(80 * _gp_norm))
                        glColor4ub(60, 100, 255, _gp_a)
                        p1_rel = rotate_vector(_gp_massive[i].pos - camera.pos, camera.rot)
                        p2_rel = rotate_vector(_gp_massive[j].pos - camera.pos, camera.rot)
                        glVertex3f(*p1_rel)
                        glVertex3f(*p2_rel)
                glEnd()
            glDepthMask(GL_TRUE)
            glDisable(GL_BLEND)
            glEnable(GL_LIGHTING)

        # Draw kinetic energy field if toggled (key 8)
        if toggle_kinetic_field:
            glDisable(GL_LIGHTING)
            glEnable(GL_BLEND)
            # Additive blending so KE field glows through grav potential when both active
            glBlendFunc(GL_SRC_ALPHA, GL_ONE)
            glDepthMask(GL_FALSE)
            _ke_max = 1e-30
            _ke_data = []
            for p in particles:
                if getattr(p, 'base_type', '') == 'decayed':
                    continue
                _v2 = float(np.dot(p.vel, p.vel))
                _ke = 0.5 * p.mass * _v2 if p.mass > 0 else p.energy_kin
                if _ke < 1e-50:
                    continue
                _ke_data.append((p, _ke))
                if _ke > _ke_max:
                    _ke_max = _ke
            # Pre-compute KE sphere data and velocity line data
            _ke_line_verts = []  # collect (rel, end_rel, r, g, alpha) for batched line draw
            for p, _ke in _ke_data:
                _ke_frac = _ke / (_ke_max + EPSILON)
                _ke_r = max(2.0, 5.0 * _ke_frac * max(camera.zoom, 1.0))
                _ke_alpha = int(40 + 140 * _ke_frac)
                # Color: warm orange (slow) → hot red/white (fast) — high contrast vs blue grav field
                _ke_red = int(min(255, 180 + 75 * _ke_frac))
                _ke_grn = int(max(20, 140 * (1.0 - _ke_frac * 0.7)))
                _ke_blu = int(max(10, 40 * (1.0 - _ke_frac)))
                rel = rotate_vector(p.pos - camera.pos, camera.rot)
                glPushMatrix()
                glTranslatef(*rel)
                glColor4ub(_ke_red, _ke_grn, _ke_blu, _ke_alpha)
                _draw_cached_sphere(_ke_r, 8)
                glPopMatrix()
                # Collect velocity vector line for batched draw
                v_norm = np.linalg.norm(p.vel)
                if v_norm > 1e-30:
                    v_dir = p.vel / v_norm
                    _arrow_l = max(3.0, 10.0 * _ke_frac * max(camera.zoom, 1.0))
                    _end = p.pos + v_dir * _arrow_l
                    _end_rel = rotate_vector(_end - camera.pos, camera.rot)
                    _ke_line_verts.append((rel, _end_rel, _ke_red, _ke_grn, int(_ke_alpha * 0.8)))
            # GPU-batched: all KE velocity lines in 1 draw call
            if _ke_line_verts:
                glBegin(GL_LINES)
                for _kv_s, _kv_e, _kv_r, _kv_g, _kv_a in _ke_line_verts:
                    glColor4ub(_kv_r, _kv_g, 40, _kv_a)
                    glVertex3f(*_kv_s)
                    glVertex3f(*_kv_e)
                glEnd()
            glDepthMask(GL_TRUE)
            glDisable(GL_BLEND)
            glEnable(GL_LIGHTING)

    # === 3D Mandelbrot Fractal Grid wireframe (key 0) — must be in 3D projection ===
    if toggle_mandelbrot_grid:
        _mb_res = _mandelbrot_grid_res
        _mb_key = (_mandelbrot_zoom, _mandelbrot_center_r, _mandelbrot_center_i, _mb_res)
        if _mandelbrot_3d_cache is None or _mandelbrot_3d_cache_key != _mb_key:
            _mandelbrot_3d_cache = _mandelbrot_compute(
                _mb_res, _mandelbrot_center_r, _mandelbrot_center_i,
                _mandelbrot_zoom, _mandelbrot_max_iter)
            _mandelbrot_3d_cache_key = _mb_key
        _mb_data, _mb_rmin, _mb_rmax, _mb_imin, _mb_imax = _mandelbrot_3d_cache
        _mb_gs = effective_grid_size
        _mb_z_scale = _mb_gs * 0.3 / max(_mandelbrot_max_iter, 1)
        # GPU-first: use VBO-cached wireframe (single glDrawArrays)
        _mb_vbo_full_key = (_mb_key, int(_mb_gs * 100), int(_mb_z_scale * 10000))
        if _mb_vbo_key != _mb_vbo_full_key:
            try:
                _build_mandelbrot_vbo(_mb_data, _mb_res, _mb_gs, _mb_z_scale, _mandelbrot_max_iter)
                _mb_vbo_key = _mb_vbo_full_key
            except Exception:
                pass
        glDisable(GL_LIGHTING)
        glEnable(GL_BLEND)
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        if not _draw_mandelbrot_vbo():
            # CPU fallback: immediate mode
            _mb_step_x = (2.0 * _mb_gs) / max(_mb_res - 1, 1)
            _mb_step_y = (2.0 * _mb_gs) / max(_mb_res - 1, 1)
            glBegin(GL_LINES)
            for _miy in range(_mb_res):
                for _mix in range(_mb_res - 1):
                    _n1 = int(_mb_data[_miy, _mix])
                    _n2 = int(_mb_data[_miy, _mix + 1])
                    _c1 = _mandelbrot_iter_color(_n1, _mandelbrot_max_iter)
                    _x1 = -_mb_gs + _mix * _mb_step_x
                    _x2 = -_mb_gs + (_mix + 1) * _mb_step_x
                    _y1 = -_mb_gs + _miy * _mb_step_y
                    _z1 = _n1 * _mb_z_scale
                    _z2 = _n2 * _mb_z_scale
                    glColor4ub(_c1[0], _c1[1], _c1[2], _c1[3])
                    glVertex3f(_x1, _y1, _z1)
                    glVertex3f(_x2, _y1, _z2)
            for _mix in range(_mb_res):
                for _miy in range(_mb_res - 1):
                    _n1 = int(_mb_data[_miy, _mix])
                    _n2 = int(_mb_data[_miy + 1, _mix])
                    _c1 = _mandelbrot_iter_color(_n1, _mandelbrot_max_iter)
                    _x1 = -_mb_gs + _mix * _mb_step_x
                    _y1 = -_mb_gs + _miy * _mb_step_y
                    _y2 = -_mb_gs + (_miy + 1) * _mb_step_y
                    _z1 = _n1 * _mb_z_scale
                    _z2 = _n2 * _mb_z_scale
                    glColor4ub(_c1[0], _c1[1], _c1[2], _c1[3])
                    glVertex3f(_x1, _y1, _z1)
                    glVertex3f(_x1, _y2, _z2)
            glEnd()
        glDisable(GL_BLEND)
        glEnable(GL_LIGHTING)

    # === Shadow Body Rendering — AI observer avatars in 3D ===
    # PER-BODY LOD: a typical shadow body emits ~300 draw calls (50 face spheres
    # + 20 muscles + 240 hair-strand capsules + 30 limb capsules). Five bodies
    # = ~1500 draw calls per frame just for the avatars, which is what was
    # capping the simulation at ~2 FPS even with only 5 atoms in the scene.
    # Strategy: ONLY the focused body (the one tracked by the `_shadow_focus_idx`
    # cycle) renders full detail. Non-focused bodies render as a fast "stick
    # figure" — limb capsules + head sphere only (~32 draw calls each). The
    # focused body still gets full anatomy + hair + face features so the
    # detailed model is visible whenever you actually want to see it.
    # Also: at very low FPS (perf governor quality 0 = survival), even the
    # focused body drops to stick-figure mode so the sim stays responsive.
    _sb_tag_infos = []  # Collect for 2D pass
    if _shadow_bodies and _observer_mgr is not None and _shadow_bodies_visible:
        glDisable(GL_LIGHTING)
        glEnable(GL_BLEND)
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        _sb_focus_force_full = _perf.quality >= 2  # only render hair/face when not in surv/low mode
        for _idx, _sb in enumerate(_shadow_bodies):
            if not np.all(np.isfinite(_sb.pos)):
                continue
            _sb_rel = rotate_vector(_sb.pos - camera.pos, camera.rot)
            if not np.all(np.isfinite(_sb_rel)):
                continue
            _sb_dist = math.sqrt(float(_sb_rel[0]*_sb_rel[0] + _sb_rel[1]*_sb_rel[1] + _sb_rel[2]*_sb_rel[2]))
            if _sb_dist > 1e6 or _sb_dist < 0.01:
                continue
            # Project to screen for tag label (always)
            try:
                _sb_sx, _sb_sy, _sb_sz = gluProject(float(_sb_rel[0]), float(_sb_rel[1]), float(_sb_rel[2]), model, proj, view)
                if _sb_sz <= 1.0:
                    _sb_tag_infos.append((_sb_sx, _sb_sy, _sb.obs_id, _sb.color, _sb.anim_state, _sb.talk_bubble if _sb.talk_timer > 0 else '', _sb.gender))
            except Exception:
                pass
            # Full shadow body only at macro zoom
            if camera.zoom < _SHADOW_VIS_ZOOM:
                continue
            _sb_h = max(8.0, _sb_dist * 0.08)
            _sb_alpha = max(0, min(255, int(255 * _sb.teleport_alpha)))
            if _sb_alpha < 5:
                continue
            # 3D volumetric humanoid rendering using GLU capsules
            # Cache geometry — regenerate only every 3 frames (hair/face/muscles are expensive)
            _fc = frame_count
            if (_sb._render_cache is None or
                _fc - _sb._render_cache_frame >= 3 or
                abs(_sb._render_cache_h - _sb_h) > 0.5):
                _sb._render_cache = _sb.get_3d_limbs(_sb_h)
                _sb._render_cache_frame = _fc
                _sb._render_cache_h = _sb_h
            capsules, head_info, _sb_face, _sb_muscles, _sb_hair = _sb._render_cache
            glPushMatrix()
            glTranslatef(float(_sb_rel[0]), float(_sb_rel[1]), float(_sb_rel[2]))
            glRotatef(math.degrees(_sb.heading), 0, 1, 0)
            glDepthMask(GL_FALSE)
            # Skin tone body fill color — fixed brightness (no aura pulsing)
            _sk = _sb.skin_tone
            _ai = 0.75
            # Female skin rendered brighter/warmer for natural appearance
            _skin_bright = 0.78 if _sb.gender == 'female' else 0.65
            _skin_r = max(40, int(_sk[0] * _skin_bright * _ai))
            _skin_g = max(35, int(_sk[1] * _skin_bright * _ai))
            _skin_b = max(30, int(_sk[2] * _skin_bright * _ai))
            glColor4ub(_skin_r, _skin_g, _skin_b, _sb_alpha)
            _sb_slices = max(8, min(24, int(16 * min(_sb_dist / 200.0, 1.0) + 8)))
            for _cx1, _cy1, _cx2, _cy2, _cr, _ck in capsules:
                _cdx = _cx2 - _cx1
                _cdy = _cy2 - _cy1
                _clen = math.sqrt(_cdx * _cdx + _cdy * _cdy)
                if _clen < 0.001:
                    continue
                # Per-limb taper for athletic / supermodel silhouette — forearms
                # and shins taper sharply toward wrist/ankle; thighs and upper
                # arms taper moderately; torso_upper handles the hourglass /
                # V-shape via chest→waist narrowing. End-sphere also uses the
                # tapered radius so the joint blend reads correctly.
                _ctp = _LIMB_TAPER.get(_ck, 0.85)
                glPushMatrix()
                glTranslatef(_cx1, _cy1, 0)
                _cang = math.degrees(math.atan2(_cdy, _cdx))
                glRotatef(_cang, 0, 0, 1)
                glRotatef(90, 0, 1, 0)
                _draw_cached_cylinder(_cr, _clen, _sb_slices, _ctp)
                _draw_cached_sphere_abs(_cr, _sb_slices)
                glTranslatef(0, 0, _clen)
                _draw_cached_sphere_abs(_cr * _ctp, _sb_slices)
                glPopMatrix()
            # Head sphere (semi-transparent to show neural vis inside)
            if head_info is not None:
                _hcx, _hcy, _hr = head_info
                glPushMatrix()
                glTranslatef(_hcx, _hcy, 0)
                glColor4ub(_skin_r, _skin_g, _skin_b, int(_sb_alpha * 0.85))
                _draw_cached_sphere_abs(_hr, max(10, _sb_slices))
                glPopMatrix()
            # Neural network visualization inside head — ALWAYS rendered, on EVERY body,
            # even during camera-busy / non-focused state. The brain is the defining
            # personhood signal; the user explicitly wants it visible at all times so
            # they can see live cognition. Drawn BEFORE the busy/focus LOD gates below.
            if head_info is not None and _sb._neural_nodes:
                _hcx, _hcy, _hr = head_info
                _nn_scale = _hr * 0.8
                glBlendFunc(GL_SRC_ALPHA, GL_ONE)
                glBegin(GL_LINES)
                for _ne_a, _ne_b in _sb._neural_edges:
                    if _ne_a < len(_sb._neural_nodes) and _ne_b < len(_sb._neural_nodes):
                        _na = _sb._neural_nodes[_ne_a]
                        _nb = _sb._neural_nodes[_ne_b]
                        _act_a = min(2.0, abs(_sb.neural_activations[min(_ne_a, 63)])) if _ne_a < 64 else 0.2
                        _edge_a = max(15, min(120, int(_act_a * 180)))
                        glColor4ub(80, 180, 255, _edge_a)
                        glVertex3f(_hcx + _na[0] * _nn_scale, _hcy + _na[1] * _nn_scale, _na[2] * _nn_scale)
                        glVertex3f(_hcx + _nb[0] * _nn_scale, _hcy + _nb[1] * _nn_scale, _nb[2] * _nn_scale)
                glEnd()
                for _ni, _nn in enumerate(_sb._neural_nodes):
                    _act = min(2.0, abs(_sb.neural_activations[min(_ni, 63)])) if _ni < 64 else 0.1
                    _nr = _hr * 0.04 * (0.5 + _act)
                    _na_alpha = max(20, min(200, int(_act * 250)))
                    glPushMatrix()
                    glTranslatef(_hcx + _nn[0] * _nn_scale, _hcy + _nn[1] * _nn_scale, _nn[2] * _nn_scale)
                    glColor4ub(100, 200, 255, _na_alpha)
                    _draw_cached_sphere_abs(_nr, 6)
                    glPopMatrix()
                glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            # === SELECTIVE LOD GATE ===
            # The earlier "skip-everything-on-non-focused" approach was too
            # aggressive — bodies looked like stick figures and lost their
            # personhood (no face, no eyes, no neural activity). Instead we
            # split the per-body draw calls into two tiers:
            #
            #   ALWAYS-RENDER on every body (the personhood essentials):
            #     • face details (eyes, iris, lips, brows, nose, cheekbones)
            #     • neural network nodes + edges in the head
            #     • essential muscle shape (default/general muscle group: pecs,
            #       abs, glutes, calves) — what gives the body human silhouette
            #     • navel (anatomy landmark, single sphere)
            #
            #   FOCUSED-ONLY (the expensive / private detail tier):
            #     • hair strands (~240 capsules per body — the dominant cost)
            #     • areola, nipple, genitals (private anatomy not always wanted)
            #
            # Result: every body looks like a real person with eyes, mouth,
            # facial expression, and visible brain activity; only the heavy
            # hair simulation and private-anatomy detail spheres are gated.
            # ~70 draw calls per non-focused body (vs original 300), so 5
            # bodies = ~350 draw calls (vs original 1500 — still a 4× win).
            _is_focused_body = (_idx == _shadow_focus_idx)
            _render_expensive_detail = _is_focused_body and _sb_focus_force_full
            # === Busy LOD override ===
            # While the user is actively rotating / panning / zooming, drop
            # EVERY body to stick figure (limbs + head only) regardless of
            # focus state. The face, neurons, muscles, hair all skip until
            # the camera settles. Restores full detail 250ms after last input.
            if _camera_busy:
                _render_expensive_detail = False
                _busy_skip_personhood = True
            else:
                _busy_skip_personhood = False
            if _busy_skip_personhood:
                # Stick figure mode: matrix already pushed, skin color set,
                # limbs already drawn above. Just close out and move on.
                glDepthMask(GL_TRUE)
                glPopMatrix()
                continue
            # Muscle rendering — flesh-toned bulges with anatomical coloring.
            # Private-anatomy sub-types (areola, nipple, genitals, pubic detail)
            # only render on the focused body. Everything else (general muscle,
            # breast shape, navel, perineum landmark) renders on every body so
            # the silhouette and surface anatomy stay correct.
            _PRIVATE_MUSCLE_TYPES = {
                'areola', 'nipple',
                'penis_shaft', 'glans', 'scrotum',
                'labia_majora', 'labia_minora', 'clitoral_hood', 'clitoris', 'anus',
                'pubic_mound',
            }
            for _mx, _my, _mz, _mr, _mt in _sb_muscles:
                if _mr < 0.001:
                    continue
                if not _render_expensive_detail and _mt in _PRIVATE_MUSCLE_TYPES:
                    continue
                glPushMatrix()
                glTranslatef(_mx, _my, _mz)
                if _mt == 'breast':
                    glColor4ub(min(255, _skin_r + 8), min(255, _skin_g + 5), min(255, _skin_b + 5), _sb_alpha)
                elif _mt == 'areola':
                    glColor4ub(max(0, _skin_r - 25), max(0, _skin_g - 40), max(0, _skin_b - 40), _sb_alpha)
                elif _mt == 'nipple':
                    glColor4ub(max(0, _skin_r - 35), max(0, _skin_g - 50), max(0, _skin_b - 48), _sb_alpha)
                elif _mt == 'navel':
                    glColor4ub(max(0, _skin_r - 18), max(0, _skin_g - 15), max(0, _skin_b - 12), _sb_alpha)
                elif _mt in ('pubic_mound', 'perineum'):
                    glColor4ub(_skin_r, max(0, _skin_g - 8), max(0, _skin_b - 10), _sb_alpha)
                elif _mt == 'penis_shaft':
                    glColor4ub(max(0, _skin_r - 10), max(0, _skin_g - 15), max(0, _skin_b - 18), _sb_alpha)
                elif _mt == 'glans':
                    glColor4ub(min(255, _skin_r + 20), max(0, _skin_g - 25), max(0, _skin_b - 30), _sb_alpha)
                elif _mt == 'scrotum':
                    glColor4ub(max(0, _skin_r - 15), max(0, _skin_g - 20), max(0, _skin_b - 22), _sb_alpha)
                elif _mt in ('labia_majora', 'labia_minora'):
                    glColor4ub(min(255, _skin_r + 15), max(0, _skin_g - 30), max(0, _skin_b - 28), _sb_alpha)
                elif _mt in ('clitoral_hood', 'clitoris'):
                    glColor4ub(min(255, _skin_r + 22), max(0, _skin_g - 28), max(0, _skin_b - 25), _sb_alpha)
                elif _mt == 'anus':
                    glColor4ub(max(0, _skin_r - 30), max(0, _skin_g - 35), max(0, _skin_b - 32), _sb_alpha)
                else:
                    glColor4ub(min(255, _skin_r + 12), max(0, _skin_g - 5), max(0, _skin_b - 8), _sb_alpha)
                _draw_cached_sphere_abs(_mr, max(8, _sb_slices // 2))
                glPopMatrix()
            # Face detail features with proper skin/feature coloring
            _lc = _sb.lip_color
            _ic = _sb.iris_color
            _bwc = _sb.brow_color
            _fhc = _sb.facial_hair_color
            for _fx, _fy, _fz, _fr, _ft in _sb_face:
                glPushMatrix()
                glTranslatef(_fx, _fy, _fz)
                if _ft == 'pupil':
                    glColor4ub(10, 10, 15, _sb_alpha)
                elif _ft == 'iris':
                    glColor4ub(_ic[0], _ic[1], _ic[2], _sb_alpha)
                elif _ft == 'eye':
                    glColor4ub(215, 218, 225, _sb_alpha)
                elif _ft == 'eye_socket':
                    glColor4ub(max(0, _skin_r - 20), max(0, _skin_g - 18), max(0, _skin_b - 15), _sb_alpha)
                elif _ft in ('upper_lip', 'lower_lip', 'mouth_corner'):
                    glColor4ub(_lc[0], _lc[1], _lc[2], _sb_alpha)
                elif _ft == 'eyebrow':
                    glColor4ub(_bwc[0], _bwc[1], _bwc[2], _sb_alpha)
                elif _ft in ('brow_ridge', 'forehead'):
                    glColor4ub(min(255, _skin_r + 3), _skin_g, _skin_b, _sb_alpha)
                elif _ft in ('nose_bridge', 'nose_tip', 'philtrum'):
                    glColor4ub(min(255, _skin_r + 6), min(255, _skin_g + 2), _skin_b, _sb_alpha)
                elif _ft == 'nostril':
                    glColor4ub(max(0, _skin_r - 30), max(0, _skin_g - 25), max(0, _skin_b - 22), _sb_alpha)
                elif _ft == 'cheekbone':
                    glColor4ub(min(255, _skin_r + 10), min(255, _skin_g + 3), _skin_b, _sb_alpha)
                elif _ft in ('chin', 'jaw'):
                    glColor4ub(_skin_r, max(0, _skin_g - 3), max(0, _skin_b - 5), _sb_alpha)
                elif _ft in ('ear', 'earlobe'):
                    glColor4ub(min(255, _skin_r + 12), min(255, _skin_g + 4), _skin_b, _sb_alpha)
                elif _ft in ('goatee', 'stubble'):
                    glColor4ub(_fhc[0], _fhc[1], _fhc[2], _sb_alpha)
                elif _ft == 'adams_apple':
                    glColor4ub(_skin_r, _skin_g, _skin_b, _sb_alpha)
                elif _ft == 'eyelash':
                    glColor4ub(15, 12, 10, _sb_alpha)
                else:
                    glColor4ub(_skin_r, _skin_g, _skin_b, _sb_alpha)
                _draw_cached_sphere_abs(_fr, max(6, _sb_slices // 2))
                glPopMatrix()
            # Hair rendering — the dominant per-body cost (long female hair = 120
            # strands × 2 segments + cap = ~240 capsules; even short male hair is
            # 48). Only render on the focused body. Non-focused bodies still
            # have visible "hair volume" via the bald head sphere with the
            # `hair_color` tint already applied above, and the user can see
            # full flowing hair on whichever body they focus on with `\`.
            if not _render_expensive_detail:
                _sb_hair_render = []  # skip entire hair loop
            else:
                _sb_hair_render = _sb_hair
            _hrc = _sb.hair_color
            _phrc = (max(0, _hrc[0] // 2), max(0, _hrc[1] // 2), max(0, _hrc[2] // 2))  # pubic hair: darker
            for _hx1, _hy1, _hz1, _hx2, _hy2, _hz2, _hrr, _hrt in _sb_hair_render:
                _hdx = _hx2 - _hx1
                _hdy = _hy2 - _hy1
                _hdz = _hz2 - _hz1
                _hlen = math.sqrt(_hdx * _hdx + _hdy * _hdy + _hdz * _hdz)
                if _hlen < 0.001:
                    continue
                glPushMatrix()
                glTranslatef(_hx1, _hy1, _hz1)
                if _hrt == 'pubic_hair':
                    glColor4ub(_phrc[0], _phrc[1], _phrc[2], _sb_alpha)
                else:
                    glColor4ub(_hrc[0], _hrc[1], _hrc[2], _sb_alpha)
                _hndx, _hndy, _hndz = _hdx / _hlen, _hdy / _hlen, _hdz / _hlen
                _hang = math.degrees(math.acos(max(-1, min(1, _hndz))))
                if abs(_hndx) > 1e-6 or abs(_hndy) > 1e-6:
                    glRotatef(_hang, -_hndy, _hndx, 0)
                _draw_cached_cylinder(_hrr, _hlen, 8, 0.6)
                _draw_cached_sphere_abs(_hrr, 8)
                glPopMatrix()
            # Aura removed — was causing flashing circles around AI bodies
            # (Neural network rendering moved above the busy/focus LOD gate so
            #  brain neurons are visible on every body at all times.)
            glDepthMask(GL_TRUE)
            glPopMatrix()
        # Focus ghost rendering — translucent marker at each AI's analytical focus
        for _sb in _shadow_bodies:
            # ... (rest of the code remains the same)
            _fgp = _sb.focus_ghost_pos
            if _fgp is None or not np.all(np.isfinite(_fgp)):
                continue
            _fg_rel = rotate_vector(_fgp - camera.pos, camera.rot)
            if not np.all(np.isfinite(_fg_rel)):
                continue
            _fg_dist = math.sqrt(float(_fg_rel[0]*_fg_rel[0] + _fg_rel[1]*_fg_rel[1] + _fg_rel[2]*_fg_rel[2]))
            if _fg_dist > 1e6 or _fg_dist < 0.01:
                continue
            _fg_r = max(0.8, min(5.0, _fg_dist * 0.012))
            _fg_a = max(0, min(120, int(120 * _sb.teleport_alpha)))
            if _fg_a < 3:
                continue
            glPushMatrix()
            glTranslatef(float(_fg_rel[0]), float(_fg_rel[1]), float(_fg_rel[2]))
            glBlendFunc(GL_SRC_ALPHA, GL_ONE)
            # Outer glow
            glColor4ub(_sb.color[0], _sb.color[1], _sb.color[2], _fg_a // 3)
            _draw_cached_sphere_abs(_fg_r * 2.5, 8)
            # Inner core
            glColor4ub(_sb.color[0], _sb.color[1], _sb.color[2], _fg_a)
            _draw_cached_sphere_abs(_fg_r, 8)
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
            glPopMatrix()
        glDisable(GL_BLEND)
        glEnable(GL_LIGHTING)

    # Switch to 2D for labels and UI
    glMatrixMode(GL_PROJECTION)
    glLoadIdentity()
    glOrtho(0, WIDTH, 0, HEIGHT, -1, 1)
    glMatrixMode(GL_MODELVIEW)
    glLoadIdentity()
    glDisable(GL_LIGHTING)
    glDisable(GL_DEPTH_TEST)
    glEnable(GL_BLEND)
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)

    # Shadow body 2D tags and speech bubbles
    if _sb_tag_infos:
        _sb_lbl = getattr(on_draw, '_sb_lbl', None)
        if _sb_lbl is None:
            _sb_lbl = _get_pooled_label(9, 'center', 'bottom')
            _sb_lbl.color = (255, 255, 255, 255)
            on_draw._sb_lbl = _sb_lbl
        for _sx, _sy, _sid, _sc, _sa, _stalk, _sgender in _sb_tag_infos:
            if _sx < 0 or _sx > WIDTH or _sy < 0 or _sy > HEIGHT:
                continue
            _gender_tag = "Male" if _sgender == 'male' else "Female"
            _state_txt = f" [{_sa}]" if _sa != 'idle' else ""
            _sb_lbl.text = f"{_sid} ({_gender_tag}){_state_txt}"
            _sb_lbl.color = (_sc[0], _sc[1], _sc[2], 220)
            _sb_lbl.x = int(_sx)
            _sb_lbl.y = int(_sy) + 8
            _sb_lbl.draw()
            if _stalk:
                _sb_lbl.color = (255, 255, 255, 180)
                _sb_lbl.font_size = 8
                # Word-wrap long text into lines of ~60 chars so full message displays
                _talk_lines = []
                _tw_line = ''
                for _tw_word in _stalk.split():
                    if len(_tw_line) + len(_tw_word) + 1 > 60:
                        _talk_lines.append(_tw_line)
                        _tw_line = _tw_word
                    else:
                        _tw_line = (_tw_line + ' ' + _tw_word).strip()
                if _tw_line:
                    _talk_lines.append(_tw_line)
                for _tli, _tl_text in enumerate(_talk_lines):
                    _sb_lbl.text = _tl_text
                    _sb_lbl.y = int(_sy) + 22 + _tli * 12
                    _sb_lbl.draw()
                _sb_lbl.font_size = 9

    # ── Photon Wavelength Visualization Overlay (Shift+W) ──
    if _show_photon_wavelengths and _photon_wave_infos:
        _pw_lbl = getattr(on_draw, '_pw_lbl', None)
        if _pw_lbl is None:
            _pw_lbl = _get_pooled_label(8, 'left', 'bottom')
            _pw_lbl.color = (255, 255, 255, 255)
            on_draw._pw_lbl = _pw_lbl
        # Wave trail parameters
        _pw_trail_len = 40  # pixels of sinusoidal trail behind each photon
        _pw_wave_segs = 20  # segments in the wave trail
        _pw_time = simulation_time * 8.0  # animation phase
        for _pwx, _pwy, _pw_nm, _pw_freq, _pw_rgb, _pw_n, _pw_gv, _pw_p in _photon_wave_infos:
            # Draw sinusoidal wave trail behind the photon
            _pw_vel = getattr(_pw_p, 'vel', None)
            if _pw_vel is not None:
                _vn = math.sqrt(float(_pw_vel[0]*_pw_vel[0] + _pw_vel[1]*_pw_vel[1] + _pw_vel[2]*_pw_vel[2]))
                if _vn > 1e-10:
                    # Project velocity direction to screen space for trail direction
                    _vdir_3d = rotate_vector(_pw_vel / _vn, camera.rot)
                    # Use x,y components of projected velocity for 2D trail direction
                    _vdx = float(_vdir_3d[0])
                    _vdy = float(-_vdir_3d[1])  # screen Y is inverted
                    _vd_mag = math.sqrt(_vdx*_vdx + _vdy*_vdy)
                    if _vd_mag > 0.01:
                        _vdx /= _vd_mag
                        _vdy /= _vd_mag
                    else:
                        _vdx, _vdy = 1.0, 0.0
                    # Perpendicular direction for wave oscillation
                    _vpx, _vpy = -_vdy, _vdx
                    # Wave amplitude scales with wavelength (longer = bigger oscillation)
                    _pw_amp = min(12.0, max(3.0, _pw_nm / 80.0))
                    # Oscillation spatial frequency: shorter wavelength = more cycles
                    _pw_k = max(0.3, min(2.5, 600.0 / max(_pw_nm, 50.0)))
                    glColor4ub(_pw_rgb[0], _pw_rgb[1], _pw_rgb[2], 180)
                    glLineWidth(1.5)
                    glBegin(GL_LINE_STRIP)
                    for _wi in range(_pw_wave_segs + 1):
                        _wfrac = _wi / float(_pw_wave_segs)
                        _wx_off = -_pw_trail_len * _wfrac  # behind the photon
                        _wy_osc = _pw_amp * math.sin(_pw_k * _wfrac * 2.0 * math.pi + _pw_time)
                        _fade = 1.0 - _wfrac * 0.7  # fade out toward tail
                        _sx = _pwx + _wx_off * _vdx + _wy_osc * _vpx
                        _sy = _pwy + _wx_off * _vdy + _wy_osc * _vpy
                        glColor4ub(_pw_rgb[0], _pw_rgb[1], _pw_rgb[2], int(180 * _fade))
                        glVertex2f(_sx, _sy)
                    glEnd()
                    glLineWidth(1.0)
            # Per-photon label: wavelength + frequency + medium info
            _pw_freq_str = f"{_pw_freq:.2e} Hz" if _pw_freq > 0 else "?"
            if _pw_nm < 380:
                _band = "UV"
            elif _pw_nm < 450:
                _band = "Violet"
            elif _pw_nm < 495:
                _band = "Blue"
            elif _pw_nm < 570:
                _band = "Green"
            elif _pw_nm < 590:
                _band = "Yellow"
            elif _pw_nm < 620:
                _band = "Orange"
            elif _pw_nm < 750:
                _band = "Red"
            elif _pw_nm < 1e6:
                _band = "IR"
            elif _pw_nm < 1e9:
                _band = "μWave"
            else:
                _band = "Radio"
            _pw_info = f"{_pw_nm:.1f}nm ({_band})"
            if _pw_n > 1.001:
                _pw_info += f" n={_pw_n:.2f}"
            _pw_lbl.text = _pw_info
            _pw_lbl.color = (_pw_rgb[0], _pw_rgb[1], _pw_rgb[2], 220)
            _pw_lbl.x = int(_pwx) + 6
            _pw_lbl.y = int(_pwy) + 4
            _pw_lbl.draw()
        # HUD legend: small panel showing toggle is active
        _pw_hud_x = 10
        _pw_hud_y = 10
        _pw_hud_w = 210
        _pw_hud_h = 22
        glColor4ub(12, 12, 18, 180)
        glBegin(GL_QUADS)
        glVertex2f(_pw_hud_x, _pw_hud_y)
        glVertex2f(_pw_hud_x + _pw_hud_w, _pw_hud_y)
        glVertex2f(_pw_hud_x + _pw_hud_w, _pw_hud_y + _pw_hud_h)
        glVertex2f(_pw_hud_x, _pw_hud_y + _pw_hud_h)
        glEnd()
        _pw_lbl.text = f"Photon Wavelengths ON  [{len(_photon_wave_infos)} visible]"
        _pw_lbl.color = (120, 220, 200, 255)
        _pw_lbl.x = _pw_hud_x + 6
        _pw_lbl.y = _pw_hud_y + 4
        _pw_lbl.draw()

    # ── Focused Shadow Body 3D Overlay (compact bottom-right display, rotates) ──
    if _shadow_bodies_visible and _shadow_focus_idx >= 0 and _shadow_focus_idx < len(_shadow_bodies):
        _fb = _shadow_bodies[_shadow_focus_idx]
        _fh = 180  # fixed world-space skeleton height
        # Tall panel: 20% width, 52% height (1.5x previous), bottom-right
        _fb_panel_w = max(140, int(WIDTH * 0.20))
        _fb_panel_h = max(300, int(HEIGHT * 0.52))
        _fb_panel_x = WIDTH - _fb_panel_w - 10  # 10px margin from right edge
        _fb_panel_y = 10  # 10px margin from bottom
        _foc = (255, 255, 255) if _shadow_outline_white else _fb.color
        # Semi-transparent background panel
        glDisable(GL_DEPTH_TEST)
        glEnable(GL_BLEND)
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        glColor4ub(12, 12, 18, 180)
        glBegin(GL_QUADS)
        glVertex2f(_fb_panel_x, _fb_panel_y)
        glVertex2f(_fb_panel_x + _fb_panel_w, _fb_panel_y)
        glVertex2f(_fb_panel_x + _fb_panel_w, _fb_panel_y + _fb_panel_h)
        glVertex2f(_fb_panel_x, _fb_panel_y + _fb_panel_h)
        glEnd()
        # Colored border
        glColor4ub(_foc[0], _foc[1], _foc[2], 120)
        glBegin(GL_LINE_LOOP)
        glVertex2f(_fb_panel_x, _fb_panel_y)
        glVertex2f(_fb_panel_x + _fb_panel_w, _fb_panel_y)
        glVertex2f(_fb_panel_x + _fb_panel_w, _fb_panel_y + _fb_panel_h)
        glVertex2f(_fb_panel_x, _fb_panel_y + _fb_panel_h)
        glEnd()
        # Restrict 3D rendering to the panel viewport
        glViewport(_fb_panel_x, _fb_panel_y, _fb_panel_w, _fb_panel_h)
        glEnable(GL_SCISSOR_TEST)
        glScissor(_fb_panel_x, _fb_panel_y, _fb_panel_w, _fb_panel_h)
        # Switch to 3D perspective for the body overlay
        glMatrixMode(GL_PROJECTION)
        glPushMatrix()
        glLoadIdentity()
        _fb_aspect = _fb_panel_w / max(_fb_panel_h, 1)
        gluPerspective(25.0, _fb_aspect, 1.0, 5000.0)
        glMatrixMode(GL_MODELVIEW)
        glPushMatrix()
        glLoadIdentity()
        # Position camera looking at the body center — pulled back for head/foot padding
        _fb_cam_dist = _fh * 2.8
        _fb_cy = _fh * 0.48
        gluLookAt(0, _fb_cy, _fb_cam_dist, 0, _fb_cy, 0, 0, 1, 0)
        # Y-axis rotation: manual orbit (arrow keys / middle-click) + slow auto-spin
        _fb_rot_angle = _shadow_focus_orbit + _fb.anim_time * 12.0
        glRotatef(_fb_rot_angle, 0, 1, 0)
        # X-axis tilt: UP/DOWN arrow keys
        if _shadow_focus_tilt != 0.0:
            glRotatef(_shadow_focus_tilt, 1, 0, 0)
        glEnable(GL_DEPTH_TEST)
        glDepthMask(GL_TRUE)
        glClear(GL_DEPTH_BUFFER_BIT)
        glEnable(GL_BLEND)
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        # Ground plane at feet level (Y=0)
        _gnd_ext = _fh * 0.6
        glColor4ub(25, 30, 42, 160)
        glBegin(GL_QUADS)
        glVertex3f(-_gnd_ext, 0, -_gnd_ext)
        glVertex3f( _gnd_ext, 0, -_gnd_ext)
        glVertex3f( _gnd_ext, 0,  _gnd_ext)
        glVertex3f(-_gnd_ext, 0,  _gnd_ext)
        glEnd()
        # Ground grid lines
        glColor4ub(_foc[0], _foc[1], _foc[2], 30)
        glBegin(GL_LINES)
        _gnd_step = _fh * 0.12
        _gnd_i = -_gnd_ext
        while _gnd_i <= _gnd_ext:
            glVertex3f(_gnd_i, 0.1, -_gnd_ext); glVertex3f(_gnd_i, 0.1, _gnd_ext)
            glVertex3f(-_gnd_ext, 0.1, _gnd_i); glVertex3f(_gnd_ext, 0.1, _gnd_i)
            _gnd_i += _gnd_step
        glEnd()
        # Cache geometry for preview panel (separate cache — different height than main 3D)
        _fc = frame_count
        if (_fb._preview_cache is None or
            _fc - _fb._preview_cache_frame >= 3 or
            abs(_fb._preview_cache_h - _fh) > 0.5):
            _fb._preview_cache = _fb.get_3d_limbs(_fh)
            _fb._preview_cache_frame = _fc
            _fb._preview_cache_h = _fh
        capsules, head_info, _fb_face, _fb_muscles, _fb_hair = _fb._preview_cache
        _fb_slices = 32
        # Skin tone body fill — fixed brightness (no aura pulsing)
        _fb_sk = _fb.skin_tone
        _fb_ai = 0.75
        _fb_skin_bright = 0.78 if _fb.gender == 'female' else 0.65
        _fb_sr = max(45, int(_fb_sk[0] * _fb_skin_bright * _fb_ai))
        _fb_sg = max(38, int(_fb_sk[1] * _fb_skin_bright * _fb_ai))
        _fb_sb = max(32, int(_fb_sk[2] * _fb_skin_bright * _fb_ai))
        glColor4ub(_fb_sr, _fb_sg, _fb_sb, 220)
        for _cx1, _cy1, _cx2, _cy2, _cr, _ck in capsules:
            _cdx = _cx2 - _cx1
            _cdy = _cy2 - _cy1
            _clen = math.sqrt(_cdx * _cdx + _cdy * _cdy)
            if _clen < 0.001:
                continue
            # Per-limb taper — same table the main ShadowBody render uses,
            # so the focus-preview avatar matches the in-scene avatar.
            _ctp = _LIMB_TAPER.get(_ck, 0.85)
            glPushMatrix()
            glTranslatef(_cx1, _cy1, 0)
            _cang = math.degrees(math.atan2(_cdy, _cdx))
            glRotatef(_cang, 0, 0, 1)
            glRotatef(90, 0, 1, 0)
            _draw_cached_cylinder(_cr, _clen, 32, _ctp)
            _draw_cached_sphere_abs(_cr, 32)
            glTranslatef(0, 0, _clen)
            _draw_cached_sphere_abs(_cr * _ctp, 32)
            glPopMatrix()
        # Head sphere (semi-transparent for neural vis)
        if head_info is not None:
            _hcx, _hcy, _hr = head_info
            glPushMatrix()
            glTranslatef(_hcx, _hcy, 0)
            glColor4ub(_fb_sr, _fb_sg, _fb_sb, 185)
            _draw_cached_sphere_abs(_hr, 32)
            glPopMatrix()
        # Muscle rendering — flesh-toned bulges with anatomical coloring
        for _mx, _my, _mz, _mr, _mt in _fb_muscles:
            if _mr < 0.001:
                continue
            glPushMatrix()
            glTranslatef(_mx, _my, _mz)
            if _mt == 'breast':
                glColor4ub(min(255, _fb_sr + 8), min(255, _fb_sg + 5), min(255, _fb_sb + 5), 220)
            elif _mt == 'areola':
                glColor4ub(max(0, _fb_sr - 25), max(0, _fb_sg - 40), max(0, _fb_sb - 40), 220)
            elif _mt == 'nipple':
                glColor4ub(max(0, _fb_sr - 35), max(0, _fb_sg - 50), max(0, _fb_sb - 48), 220)
            elif _mt == 'navel':
                glColor4ub(max(0, _fb_sr - 18), max(0, _fb_sg - 15), max(0, _fb_sb - 12), 220)
            elif _mt in ('pubic_mound', 'perineum'):
                glColor4ub(_fb_sr, max(0, _fb_sg - 8), max(0, _fb_sb - 10), 220)
            elif _mt == 'penis_shaft':
                glColor4ub(max(0, _fb_sr - 10), max(0, _fb_sg - 15), max(0, _fb_sb - 18), 220)
            elif _mt == 'glans':
                glColor4ub(min(255, _fb_sr + 20), max(0, _fb_sg - 25), max(0, _fb_sb - 30), 220)
            elif _mt == 'scrotum':
                glColor4ub(max(0, _fb_sr - 15), max(0, _fb_sg - 20), max(0, _fb_sb - 22), 220)
            elif _mt in ('labia_majora', 'labia_minora'):
                glColor4ub(min(255, _fb_sr + 15), max(0, _fb_sg - 30), max(0, _fb_sb - 28), 220)
            elif _mt in ('clitoral_hood', 'clitoris'):
                glColor4ub(min(255, _fb_sr + 22), max(0, _fb_sg - 28), max(0, _fb_sb - 25), 220)
            elif _mt == 'anus':
                glColor4ub(max(0, _fb_sr - 30), max(0, _fb_sg - 35), max(0, _fb_sb - 32), 220)
            else:
                glColor4ub(min(255, _fb_sr + 12), max(0, _fb_sg - 5), max(0, _fb_sb - 8), 220)
            _draw_cached_sphere_abs(_mr, 24)
            glPopMatrix()
        # Face detail features with proper skin/feature coloring
        _fb_lc = _fb.lip_color
        _fb_ic = _fb.iris_color
        _fb_bwc = _fb.brow_color
        _fb_fhc = _fb.facial_hair_color
        for _fx, _fy, _fz, _fr, _ft in _fb_face:
            glPushMatrix()
            glTranslatef(_fx, _fy, _fz)
            if _ft == 'pupil':
                glColor4ub(10, 10, 15, 220)
            elif _ft == 'iris':
                glColor4ub(_fb_ic[0], _fb_ic[1], _fb_ic[2], 220)
            elif _ft == 'eye':
                glColor4ub(215, 218, 225, 220)
            elif _ft == 'eye_socket':
                glColor4ub(max(0, _fb_sr - 20), max(0, _fb_sg - 18), max(0, _fb_sb - 15), 220)
            elif _ft in ('upper_lip', 'lower_lip', 'mouth_corner'):
                glColor4ub(_fb_lc[0], _fb_lc[1], _fb_lc[2], 220)
            elif _ft == 'eyebrow':
                glColor4ub(_fb_bwc[0], _fb_bwc[1], _fb_bwc[2], 220)
            elif _ft in ('brow_ridge', 'forehead'):
                glColor4ub(min(255, _fb_sr + 3), _fb_sg, _fb_sb, 220)
            elif _ft in ('nose_bridge', 'nose_tip', 'philtrum'):
                glColor4ub(min(255, _fb_sr + 6), min(255, _fb_sg + 2), _fb_sb, 220)
            elif _ft == 'nostril':
                glColor4ub(max(0, _fb_sr - 30), max(0, _fb_sg - 25), max(0, _fb_sb - 22), 220)
            elif _ft == 'cheekbone':
                glColor4ub(min(255, _fb_sr + 10), min(255, _fb_sg + 3), _fb_sb, 220)
            elif _ft in ('chin', 'jaw'):
                glColor4ub(_fb_sr, max(0, _fb_sg - 3), max(0, _fb_sb - 5), 220)
            elif _ft in ('ear', 'earlobe'):
                glColor4ub(min(255, _fb_sr + 12), min(255, _fb_sg + 4), _fb_sb, 220)
            elif _ft in ('goatee', 'stubble'):
                glColor4ub(_fb_fhc[0], _fb_fhc[1], _fb_fhc[2], 220)
            elif _ft == 'adams_apple':
                glColor4ub(_fb_sr, _fb_sg, _fb_sb, 220)
            elif _ft == 'eyelash':
                glColor4ub(15, 12, 10, 220)
            else:
                glColor4ub(_fb_sr, _fb_sg, _fb_sb, 220)
            _draw_cached_sphere_abs(_fr, 24)
            glPopMatrix()
        # Hair rendering
        _fb_hrc = _fb.hair_color
        _fb_phrc = (max(0, _fb_hrc[0] // 2), max(0, _fb_hrc[1] // 2), max(0, _fb_hrc[2] // 2))  # pubic hair: darker
        for _hx1, _hy1, _hz1, _hx2, _hy2, _hz2, _hrr, _hrt in _fb_hair:
            _hdx = _hx2 - _hx1
            _hdy = _hy2 - _hy1
            _hdz = _hz2 - _hz1
            _hlen = math.sqrt(_hdx * _hdx + _hdy * _hdy + _hdz * _hdz)
            if _hlen < 0.001:
                continue
            glPushMatrix()
            glTranslatef(_hx1, _hy1, _hz1)
            if _hrt == 'pubic_hair':
                glColor4ub(_fb_phrc[0], _fb_phrc[1], _fb_phrc[2], 220)
            else:
                glColor4ub(_fb_hrc[0], _fb_hrc[1], _fb_hrc[2], 220)
            _hndx, _hndy, _hndz = _hdx / _hlen, _hdy / _hlen, _hdz / _hlen
            _hang = math.degrees(math.acos(max(-1, min(1, _hndz))))
            if abs(_hndx) > 1e-6 or abs(_hndy) > 1e-6:
                glRotatef(_hang, -_hndy, _hndx, 0)
            _draw_cached_cylinder(_hrr, _hlen, 24, 0.6)
            _draw_cached_sphere_abs(_hrr, 24)
            glPopMatrix()
        # Neural network visualization inside head (preview panel)
        if head_info is not None and _fb._neural_nodes:
            _hcx, _hcy, _hr = head_info
            _nn_scale = _hr * 0.8
            glBlendFunc(GL_SRC_ALPHA, GL_ONE)
            glBegin(GL_LINES)
            for _ne_a, _ne_b in _fb._neural_edges:
                if _ne_a < len(_fb._neural_nodes) and _ne_b < len(_fb._neural_nodes):
                    _na = _fb._neural_nodes[_ne_a]
                    _nb = _fb._neural_nodes[_ne_b]
                    _act_a = min(2.0, abs(_fb.neural_activations[min(_ne_a, 63)])) if _ne_a < 64 else 0.2
                    _edge_a = max(20, min(150, int(_act_a * 220)))
                    glColor4ub(80, 180, 255, _edge_a)
                    glVertex3f(_hcx + _na[0] * _nn_scale, _hcy + _na[1] * _nn_scale, _na[2] * _nn_scale)
                    glVertex3f(_hcx + _nb[0] * _nn_scale, _hcy + _nb[1] * _nn_scale, _nb[2] * _nn_scale)
            glEnd()
            for _ni, _nn in enumerate(_fb._neural_nodes):
                _act = min(2.0, abs(_fb.neural_activations[min(_ni, 63)])) if _ni < 64 else 0.1
                _nr = _hr * 0.05 * (0.5 + _act)
                _na_alpha = max(25, min(220, int(_act * 280)))
                glPushMatrix()
                glTranslatef(_hcx + _nn[0] * _nn_scale, _hcy + _nn[1] * _nn_scale, _nn[2] * _nn_scale)
                glColor4ub(100, 200, 255, _na_alpha)
                _draw_cached_sphere_abs(_nr, 24)
                glPopMatrix()
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)
        # Restore full viewport and 2D projection
        glDisable(GL_SCISSOR_TEST)
        glViewport(0, 0, WIDTH, HEIGHT)
        glDisable(GL_DEPTH_TEST)
        # ... rest of the code remains the same ...
        glMatrixMode(GL_MODELVIEW)
        glPopMatrix()
        glMatrixMode(GL_PROJECTION)
        glPopMatrix()
        glMatrixMode(GL_MODELVIEW)
        # Restore 2D ortho for label
        glMatrixMode(GL_PROJECTION)
        glPushMatrix()
        glLoadIdentity()
        glOrtho(0, WIDTH, 0, HEIGHT, -1, 1)
        glMatrixMode(GL_MODELVIEW)
        glPushMatrix()
        glLoadIdentity()
        # Label below panel (in 2D screen coords)
        _fb_lbl = getattr(on_draw, '_fb_lbl', None)
        if _fb_lbl is None:
            _fb_lbl = _get_pooled_label(10, 'center', 'top')
            _fb_lbl.color = (255, 255, 255, 255)
            on_draw._fb_lbl = _fb_lbl
        _fb_pos_str = f"({_fb.pos[0]:.0f}, {_fb.pos[1]:.0f}, {_fb.pos[2]:.0f})" if np.all(np.isfinite(_fb.pos)) else "(---)"
        _fb_gender_str = "Male" if _fb.gender == 'male' else "Female"
        _fb_lbl.text = f"{_fb.obs_id} ({_fb_gender_str})  [{_fb.anim_state}]  {_fb_pos_str}"
        _fb_lbl.color = (_foc[0], _foc[1], _foc[2], 220)
        _fb_lbl.x = _fb_panel_x + _fb_panel_w // 2
        _fb_lbl.y = _fb_panel_y - 4
        _fb_lbl.draw()
        # Arrow key hint
        _fb_lbl.text = "[]=Rotate  \\=Focus"
        _fb_lbl.color = (_foc[0], _foc[1], _foc[2], 140)
        _fb_lbl.font_size = 8
        _fb_lbl.y = _fb_panel_y - 18
        _fb_lbl.draw()
        _fb_lbl.font_size = 10
        glMatrixMode(GL_MODELVIEW)
        glPopMatrix()
        glMatrixMode(GL_PROJECTION)
        glPopMatrix()
        glMatrixMode(GL_MODELVIEW)

    # Place labels (reuse single Label to avoid per-frame allocation)
    if True:
        if label_infos:
            label_infos.sort(key=lambda t: t[1])  # sort by winy ascending
            # Performance governor: cap labels to prevent O(N²) collision overhead
            _max_lbls = _perf.max_render_labels
            if len(label_infos) > _max_lbls:
                label_infos = label_infos[:_max_lbls]
            _reuse_lbl = getattr(on_draw, '_reuse_lbl', None)
            if _reuse_lbl is None:
                _reuse_lbl = _get_pooled_label(10, 'center', 'bottom')
                _reuse_lbl.color = (255, 255, 255, 255)
                on_draw._reuse_lbl = _reuse_lbl
            placed_rects = []  # (x, y, w, h) tuples instead of full Label objects
            for px, py, text, r, is_sub in label_infos:
                _reuse_lbl.text = text
                target_y = py + r + 5
                lbl_w = _reuse_lbl.content_width
                lbl_h = _reuse_lbl.content_height + 5
                adjusted = False
                while not adjusted:
                    adjusted = True
                    for pl_x, pl_y, pl_w, pl_h in placed_rects:
                        if abs(px - pl_x) < (lbl_w + pl_w) / 2 and abs(target_y - pl_y) < (lbl_h + pl_h) / 2:
                            target_y = pl_y + pl_h / 2 + lbl_h / 2 + 2
                            adjusted = False
                            break
                _reuse_lbl.x = px
                _reuse_lbl.y = target_y
                if toggle_yellow_lines and abs(target_y - (py + r + 5)) > 5:
                    PygletLine(px, py + r, px, target_y, color=(255, 255, 0, 255)).draw()
                elif toggle_atom_names_macro and not is_sub:
                    PygletLine(px, py, px, target_y, color=(255, 255, 0, 180)).draw()
                _reuse_lbl.draw()
                placed_rects.append((px, target_y, lbl_w, lbl_h))

    # Draw grid labels in 2D (capped count, reuse single Label)
    if toggle_grid:
        _grid_lbl = getattr(on_draw, '_grid_lbl', None)
        if _grid_lbl is None:
            _grid_lbl = _get_pooled_label(9, 'center', 'center')
            _grid_lbl.color = (120, 180, 255, 200)
            on_draw._grid_lbl = _grid_lbl
        label_step = max(1, int(step * 5))
        label_count = int(2 * effective_grid_size / label_step) if label_step > 0 else 0
        if label_count > 30:
            label_step = max(1, int(2 * effective_grid_size / 30))
        _eg = int(effective_grid_size)
        _gnd = as_loc_decimals()  # AS sub-cell decimals for grid labels (grows with space)
        # X-axis labels along Z=0 plane edge
        for i in range(-_eg, _eg + 1, label_step):
            winx, winy, winz = gluProject(float(i), 0.0, 0.0, model, proj, view)
            if 0 < winx < WIDTH and 0 < winy < HEIGHT and winz <= 1.0:
                _rx = i * GRID_SPACING + camera.pos[0]
                _si_f = world_pos_to_as_loc_f(_rx, 0.0, 0.0)
                _grid_lbl.text = f"X:{i} ({_rx:.0f}) S:{_si_f:,.{_gnd}f} {as_cell_str_f(_si_f, _gnd)}"
                _grid_lbl.x = winx
                _grid_lbl.y = winy - 12
                _grid_lbl.color = (100, 200, 255, 200)
                _grid_lbl.draw()
        # Y-axis labels along Z=0 plane edge
        for i in range(-_eg, _eg + 1, label_step):
            winx, winy, winz = gluProject(0.0, float(i), 0.0, model, proj, view)
            if 0 < winx < WIDTH and 0 < winy < HEIGHT and winz <= 1.0:
                _ry = i * GRID_SPACING + camera.pos[1]
                _si_f = world_pos_to_as_loc_f(0.0, _ry, 0.0)
                _grid_lbl.text = f"Y:{i} ({_ry:.0f}) S:{_si_f:,.{_gnd}f} {as_cell_str_f(_si_f, _gnd)}"
                _grid_lbl.x = winx - 14
                _grid_lbl.y = winy
                _grid_lbl.color = (100, 255, 150, 200)
                _grid_lbl.draw()
        # Z-axis labels along Y=0 plane edge
        for i in range(-_eg, _eg + 1, label_step):
            winx, winy, winz = gluProject(0.0, 0.0, float(i), model, proj, view)
            if 0 < winx < WIDTH and 0 < winy < HEIGHT and winz <= 1.0:
                _rz = i * GRID_SPACING + camera.pos[2]
                _si_f = world_pos_to_as_loc_f(0.0, 0.0, _rz)
                _grid_lbl.text = f"Z:{i} ({_rz:.0f}) S:{_si_f:,.{_gnd}f} {as_cell_str_f(_si_f, _gnd)}"
                _grid_lbl.x = winx
                _grid_lbl.y = winy + 12
                _grid_lbl.color = (255, 180, 100, 200)
                _grid_lbl.draw()
        # Cross-section intersection labels (every label_step*2 on XY plane)
        _cross_step = label_step * 2
        _cross_max = 8
        _cross_count = 0
        for ix in range(-_eg, _eg + 1, _cross_step):
            if _cross_count >= _cross_max * _cross_max:
                break
            for iy in range(-_eg, _eg + 1, _cross_step):
                if ix == 0 and iy == 0:
                    continue
                winx, winy, winz = gluProject(float(ix), float(iy), 0.0, model, proj, view)
                if 0 < winx < WIDTH and 0 < winy < HEIGHT and winz <= 1.0:
                    # Grid index + real world position + sphere map location
                    _real_x = ix * GRID_SPACING + camera.pos[0]
                    _real_y = iy * GRID_SPACING + camera.pos[1]
                    _sph_idx_f = world_pos_to_as_loc_f(_real_x, _real_y, 0.0)
                    _grid_lbl.text = f"[{ix},{iy}] ({_real_x:.0f},{_real_y:.0f}) S:{_sph_idx_f:,.{_gnd}f} {as_cell_str_f(_sph_idx_f, _gnd)}"
                    _grid_lbl.x = winx
                    _grid_lbl.y = winy
                    _grid_lbl.color = (80, 140, 220, 180)
                    _grid_lbl.draw()
                    _cross_count += 1

    # === Mandelbrot Grid 2D labels (key 0) â€” uses cached data from 3D wireframe above ===
    if toggle_mandelbrot_grid and _mandelbrot_3d_cache is not None:
        _mb_data, _mb_rmin, _mb_rmax, _mb_imin, _mb_imax = _mandelbrot_3d_cache
        _mb_res = _mandelbrot_grid_res
        _mb_gs = effective_grid_size
        _mb_z_scale = _mb_gs * 0.3 / max(_mandelbrot_max_iter, 1)
        _mb_step_x = (2.0 * _mb_gs) / max(_mb_res - 1, 1)
        _mb_step_y = (2.0 * _mb_gs) / max(_mb_res - 1, 1)
        _mb_lbl = getattr(on_draw, '_mb_lbl', None)
        if _mb_lbl is None:
            _mb_lbl = _get_pooled_label(8, 'center', 'center')
            _mb_lbl.color = (200, 160, 255, 220)
            on_draw._mb_lbl = _mb_lbl
        _mb_label_step = max(1, _mb_res // 8)
        _mb_label_count = 0
        for _miy in range(0, _mb_res, _mb_label_step):
            for _mix in range(0, _mb_res, _mb_label_step):
                if _mb_label_count >= 64:
                    break
                _n_val = int(_mb_data[_miy, _mix])
                _gx = -_mb_gs + _mix * _mb_step_x
                _gy = -_mb_gs + _miy * _mb_step_y
                _gz = _n_val * _mb_z_scale
                winx, winy, winz = gluProject(float(_gx), float(_gy), float(_gz), model, proj, view)
                if 0 < winx < WIDTH and 0 < winy < HEIGHT and winz <= 1.0:
                    _cr = _mb_rmin + (_mix / max(_mb_res - 1, 1)) * (_mb_rmax - _mb_rmin)
                    _ci = _mb_imin + (_miy / max(_mb_res - 1, 1)) * (_mb_imax - _mb_imin)
                    _mloc_f = infinity_map_mandelbrot_to_loc_f(_cr, _ci)
                    _mb_lbl.text = f"M:{_mloc_f:,.{as_loc_decimals()}f} i{_n_val} ({_cr:.2f},{_ci:.2f}i)"
                    _mb_lbl.x = winx
                    _mb_lbl.y = winy + 10
                    _mb_lbl.draw()
                    _mb_label_count += 1
            if _mb_label_count >= 64:
                break

    # Draw UI â€” dynamic TOP HUD with ALL hotkeys (responsive to window size)
    _s = ui_scale
    # Panels below read _UI_BAR_H even when the bar is hidden (F9); pre-bind a
    # local default so they don't hit UnboundLocalError. Recomputed inside
    # `if show_ui:` when the bar is actually drawn.
    _UI_BAR_H = 96
    if show_ui:
        _pad = 12  # horizontal padding
        _mid_x = WIDTH // 2
        _right_x = WIDTH - _pad
        _bar_top = HEIGHT  # top edge of screen

        _hint_fs = max(6, int(9 * _s))
        _btn_h = _hint_fs + 6
        _btn_gap = 3
        _char_w = max(5, _hint_fs * 0.72)
        _line_px = _hint_fs + 5

        # Build hotkey button items.
        # cs_viewer / life_generator / lifeform_focus are labelled "Click=…" because
        # their default keys (SCROLLLOCK / PAUSE / NUM_2) are unreliable on many
        # Windows keyboards — the click is the guaranteed invocation path. The
        # underlying keys remain bound (and rebindable via the controls panel).
        _hud_hotkey_rects.clear()
        _hk_items = []
        _hk = _hotkey_display
        _CLICK_ONLY = {'cs_viewer', 'life_generator', 'lifeform_focus', 'formula_view'}
        # Visual group separators — a dim non-clickable marker is inserted before
        # these action ids so the flat button strip reads as sections
        # (Core / Toggles / Fields / Views / AI / Subprograms+Click) instead of
        # one undifferentiated wall of ~70 buttons.
        _HK_SEP_BEFORE = {'toggle_lines', 'f1_info', 'grav_potential', 'observer',
                          'gna_launch', 'cs_viewer'}
        _hk_items.append((None, 'ESC=Menu'))
        for _aid, _dname, _dkey in _HOTKEY_ACTIONS:
            if _aid in _HK_SEP_BEFORE:
                _hk_items.append((None, ' ┃ '))
            if _aid in _CLICK_ONLY:
                _hk_items.append((_aid, f"Click={_dname}"))
            else:
                _hk_items.append((_aid, f"{_hk(_aid)}={_dname}"))
        _hk_items.append((None, 'WASD=Cam'))
        _hk_items.append((None, 'Q/E=Roll'))
        _hk_items.append((None, 'Scroll=Zoom'))

        # Pre-compute actual button row count (matches real wrapping logic below)
        _bx_test = _pad
        _btn_rows = 1
        for _aid, _dtxt in _hk_items:
            _btn_w = int(len(_dtxt) * _char_w) + 8
            if _bx_test + _btn_w > WIDTH - _pad and _bx_test > _pad:
                _bx_test = _pad
                _btn_rows += 1
            _bx_test += _btn_w + _btn_gap

        # Dynamic row positions from top down (based on actual button rows)
        _row1_y = _bar_top - _line_px
        _buttons_total_h = _btn_rows * (_btn_h + 2)
        _row3_y = _row1_y - _buttons_total_h - 4
        _row4_y = _row3_y - 20                             # time slider row
        _row4b_y = _row4_y - 18                            # V% slider + counts
        _UI_BAR_H = max(96, _bar_top - _row4b_y + 8)

        # --- Top bar background ---
        _bar_bot = HEIGHT - _UI_BAR_H
        ui_background.x = 0
        ui_background.y = _bar_bot
        ui_background.width = WIDTH
        ui_background.height = _UI_BAR_H
        ui_background.draw()

        # === ROW 1 & 2: Clickable hotkey buttons (hover-highlight, click to activate) ===
        _bx_cur = _pad
        _by_cur = _row1_y
        _hk_lbl = getattr(on_draw, '_hk_lbl', None)
        if _hk_lbl is None:
            _hk_lbl = _get_pooled_label(_hint_fs)
            _hk_lbl.color = _TH_TEXT_DIM
            on_draw._hk_lbl = _hk_lbl
        _hk_lbl.font_size = _hint_fs
        for _aid, _dtxt in _hk_items:
            _btn_w = int(len(_dtxt) * _char_w) + 8
            if _bx_cur + _btn_w > WIDTH - _pad and _bx_cur > _pad:
                _bx_cur = _pad
                _by_cur -= _btn_h + 2
            if _aid is not None and _aid == _hud_hover_action:
                Rectangle(_bx_cur, _by_cur - 2, _btn_w, _btn_h,
                          color=(80, 200, 160, 60)).draw()
                _hk_lbl.color = _TH_TEXT_ACC
            elif _aid is not None:
                _hk_lbl.color = _TH_TEXT_DIM
            else:
                _hk_lbl.color = (180, 180, 200, 160)
            if _aid is not None:
                _hud_hotkey_rects.append((_bx_cur, _by_cur - 2, _btn_w, _btn_h, _aid, _dtxt))
            _hk_lbl.text = _dtxt
            _hk_lbl.x = _bx_cur + 4
            _hk_lbl.y = _by_cur
            _hk_lbl.draw()
            _bx_cur += _btn_w + _btn_gap

        # === ROW 3: placement | plaquette | V_total | toggle indicators ===
