        _fp_gr_w = _fp_w - 28
        Rectangle(_fp_gr_x, _fp_gr_y, _fp_gr_w, _fp_gr_h, color=(25, 30, 42, 230)).draw()
        glColor4ub(50, 70, 90, 180)
        glBegin(GL_LINE_LOOP)
        glVertex2f(_fp_gr_x, _fp_gr_y)
        glVertex2f(_fp_gr_x + _fp_gr_w, _fp_gr_y)
        glVertex2f(_fp_gr_x + _fp_gr_w, _fp_gr_y + _fp_gr_h)
        glVertex2f(_fp_gr_x, _fp_gr_y + _fp_gr_h)
        glEnd()
