            _fh_rng = max(1e-9, max(_fh_lv) - _fh_min)
            glColor4ub(80, 220, 180, 210)
            glBegin(GL_LINE_STRIP)
            for _fi, _lv in enumerate(_fh_lv):
                _fx = _fp_gr_x + int(_fi / max(1, _fh_n - 1) * _fp_gr_w)
                _fy = _fp_gr_y + 2 + int((_lv - _fh_min) / _fh_rng * (_fp_gr_h - 4))
                glVertex2f(_fx, _fy)
            glEnd()
            # Current-value marker (right edge) with pulse
            _cv_y = _fp_gr_y + 2 + int((_fh_lv[-1] - _fh_min) / _fh_rng * (_fp_gr_h - 4))
            _cv_a = int(160 + 90 * math.sin(simulation_time * 5.0))
