        glVertex2f(_gna_tx + _gna_tw, _gna_ty + _gna_th); glVertex2f(_gna_tx, _gna_ty + _gna_th)
        glEnd()
        _gna_status = 'RUNNING' if _gna_running else 'STOPPED'
        _gna_sc = (80, 255, 120, 255) if _gna_running else (255, 80, 80, 255)
