        with _gna_output_lock:
            _gna_lines = list(_gna_output)
        _gna_line_h = 13
        _gna_max_vis = max(1, (_gna_th - 36) // _gna_line_h)
        _gna_vis = _gna_lines[-_gna_max_vis:] if len(_gna_lines) > _gna_max_vis else _gna_lines
        _gna_olbl = getattr(on_draw, '_gna_olbl', None)
